import { DwgElement } from '../dwg_element';
import { clickButton } from '../../scripts/util';
import { emoticons } from '../../data/emoji_data';

import html from './chatbox.html';
import './chatbox.scss';

/** Data describing a chat message */
export declare interface ChatMessage {
  message: string;
  sender?: string;
  color?: string;
}

/** Sender name reserved for server chats */
export const SERVER_CHAT_NAME = '!!server!!';

export class DwgChatbox extends DwgElement {
  private chat_container!: HTMLDivElement;
  private chat_input!: HTMLInputElement;
  private send_chat!: HTMLButtonElement;
  private new_messages_button!: HTMLButtonElement;
  private new_messages_number!: HTMLSpanElement;

  convert_emoticons = true;

  constructor() {
    super();
    this.html_string = html;
    this.configureElements('chat_container', 'chat_input', 'send_chat', 'new_messages_button', 'new_messages_number');
  }

  protected override parsedCallback(): void {
    clickButton(this.send_chat, () => {
      this.sendChat();
    });
    this.chat_input.addEventListener('keyup', (e) => {
      if (e.key === 'Enter') {
        this.sendChat();
      }
    });
    this.new_messages_button.addEventListener('click', () => {
      this.adjustScroll();
    });
    this.chat_container.addEventListener('scroll', () => {
      if (!this.scrolledUp()) {
        this.scrolledToBottom();
      }
    });
  }

  scrolledUp(): boolean {
    const scroll_height = this.chat_container.scrollHeight - this.chat_container.offsetHeight;
    return scroll_height - this.chat_container.scrollTop > DwgChatbox.adjust_scroll_limit;
  }

  adjustScroll() {
    this.chat_container.scrollTop = this.chat_container.scrollHeight - this.chat_container.offsetHeight;
    this.scrolledToBottom();
  }

  scrolledToBottom() {
    this.last_new_messages_button_count = 0;
    this.new_messages_button.classList.remove('show');
  }

  private static adjust_scroll_limit = 5;
  private last_new_messages_button_timer?: number;
  private last_new_messages_button_count = 0;

  addChat(message: ChatMessage, you_sent = false) {
    const scrolled_up = this.scrolledUp();
    const sender = !!message.sender && message.sender !== SERVER_CHAT_NAME ? `${message.sender}: ` : '';
    const new_element = document.createElement('div');
    if (message.sender === SERVER_CHAT_NAME || message.color === 'gray') {
      new_element.classList.add('color-gray');
    }
    const sender_el = document.createElement('b');
    sender_el.innerText = sender;
    new_element.appendChild(sender_el);
    new_element.appendChild(document.createTextNode(message.message));
    this.chat_container.appendChild(new_element);
    new_element.classList.add('new-message');
    window.setTimeout(() => new_element.classList.remove('new-message'), 1500);
    this.classList.add('new-message');
    if (this.last_new_messages_button_timer) {
      clearTimeout(this.last_new_messages_button_timer);
    }
    if (you_sent || !scrolled_up || (this.classList.contains('transparent-fade') && !this.classList.contains('show'))) {
      this.adjustScroll();
    } else {
      this.new_messages_button.classList.add('show');
      this.new_messages_button.classList.add('new-message');
      this.last_new_messages_button_count++;
      this.new_messages_number.innerText = this.last_new_messages_button_count.toString();
    }
    this.last_new_messages_button_timer = window.setTimeout(() => {
      this.new_messages_button.classList.remove('new-message');
      this.classList.remove('new-message');
      this.last_new_messages_button_timer = undefined;
    }, 1500);
  }

  sendChat() {
    if (this.inputEmpty()) {
      return;
    }
    const chat_input = this.getInput();
    if (this.convert_emoticons) {
      for (const [emoticon, emoji] of emoticons) {
        chat_input.message = chat_input.message.replace(emoticon, emoji);
      }
    }
    const chat_event = new CustomEvent('chat_sent', { detail: chat_input });
    this.dispatchEvent(chat_event);
  }

  setPlaceholder(placeholder: string) {
    this.chat_input.placeholder = placeholder;
  }

  focus() {
    this.chat_input.focus();
  }

  override disconnectedCallback(): void {
    super.disconnectedCallback();
    if (this.last_new_messages_button_timer) {
      clearTimeout(this.last_new_messages_button_timer);
      this.last_new_messages_button_timer = undefined;
    }
  }

  clear() {
    if (this.last_new_messages_button_timer) {
      clearTimeout(this.last_new_messages_button_timer);
      this.last_new_messages_button_timer = undefined;
    }
    this.chat_input.value = '';
    this.chat_container.innerHTML = '';
    this.classList.remove('new-message');
    this.new_messages_button.classList.remove('new-message');
  }

  private inputEmpty(): boolean {
    return !this.chat_input.value;
  }

  private getInput(): ChatMessage {
    const message: ChatMessage = {
      message: this.chat_input.value,
    };
    this.chat_input.value = '';
    return message;
  }
}

customElements.define('dwg-chatbox', DwgChatbox);

declare global {
  interface HTMLElementTagNameMap {
    'dwg-chatbox': DwgChatbox;
  }
}

import { DwgDialogBox, DialogSize } from '../dialog_box';

import html from './confirm_dialog.html';

import './confirm_dialog.scss';

/** Input data for a message dialog */
interface ConfirmDialogData {
  question: string;
  yes_text?: string;
  no_text?: string;
  size?: DialogSize;
}

/** Will emit a 'confirmed' event if confirmed is clicked */
export class DwgConfirmDialog extends DwgDialogBox<ConfirmDialogData> {
  private message_container!: HTMLDivElement;
  private yes_button!: HTMLButtonElement;
  private no_button!: HTMLButtonElement;

  constructor() {
    super();
    this.configureElements('message_container', 'yes_button', 'no_button');
  }

  override getHTML(): string {
    return html;
  }

  getData(): ConfirmDialogData {
    return {
      question: this.getAttribute('question') ?? '',
      yes_text: this.getAttribute('yes_text') ?? 'yes',
      no_text: this.getAttribute('no_text') ?? 'no',
      size: (this.getAttribute('size') as DialogSize) ?? DialogSize.MEDIUM,
    };
  }

  setData(data: ConfirmDialogData, parsed?: boolean) {
    this.setAttribute('question', data.question);
    this.setAttribute('size', data.size ?? DialogSize.MEDIUM);
    this.classList.add(`size-${data.size ?? DialogSize.MEDIUM}`);
    if (!parsed && !this.fully_parsed) {
      return;
    }
    this.message_container.innerText = data.question;
    if (data.yes_text) {
      this.yes_button.innerText = data.yes_text;
    }
    if (data.no_text) {
      this.no_button.innerText = data.no_text;
    }
    this.yes_button.addEventListener('click', () => {
      this.dispatchEvent(new Event('confirmed'));
      this.closeDialog();
    });
    this.no_button.addEventListener('click', () => {
      this.closeDialog();
    });
  }
}

customElements.define('dwg-confirm-dialog', DwgConfirmDialog);

declare global {
  interface HTMLElementTagNameMap {
    'dwg-confirm-dialog': DwgConfirmDialog;
  }
}

import { DwgElement } from '../dwg_element';

import html from './dialog_box.html';

import './dialog_box.scss';

/** Shared sizing option for any dialog; maps to a `size-*` class on the dialog element */
export enum DialogSize {
  SMALL = 'small',
  MEDIUM = 'medium',
  LARGE = 'large',
  XLARGE = 'xlarge',
  XXLARGE = 'xxlarge',
}

export interface DialogHotkey {
  key?: string;
  ctrl?: boolean;
  shift?: boolean;
  alt?: boolean;
}

export abstract class DwgDialogBox<T> extends DwgElement {
  protected close_hotkey?: DialogHotkey;

  override async connectedCallback() {
    this.html_string = html.replace('id="content-container">', `id="content-container">${this.getHTML()}`);
    this.classList.add('dwg-dialog-box');
    await super.connectedCallback();
    window.addEventListener('keydown', this.handleCloseHotkey);
  }

  override disconnectedCallback() {
    window.removeEventListener('keydown', this.handleCloseHotkey);
    super.disconnectedCallback();
  }

  private handleCloseHotkey = (event: KeyboardEvent): void => {
    const hotkey = this.close_hotkey;
    const matches_close_hotkey =
      hotkey?.key === event.key.toLowerCase() &&
      hotkey.ctrl === event.ctrlKey &&
      hotkey.shift === event.shiftKey &&
      hotkey.alt === event.altKey;
    if (!event.repeat && (event.key === 'Escape' || matches_close_hotkey)) {
      event.preventDefault();
      this.closeDialog();
    }
  };

  protected override parsedCallback(): void {
    this.setData(this.getData(), true);
  }

  closeDialog() {
    this.remove();
  }

  abstract getHTML(): string;
  abstract getData(): T; // usually from attributes
  abstract setData(data: T, parsed?: boolean): void;
}

import { DwgDialogBox, DialogSize } from '../dialog_box';

import html from './message_dialog.html';

import './message_dialog.scss';

/** Input data for a message dialog */
export declare interface MessageDialogData {
  message: string;
  button_text?: string;
  size?: DialogSize;
}

export class DwgMessageDialog extends DwgDialogBox<MessageDialogData> {
  private message_container!: HTMLDivElement;
  private ok_button!: HTMLButtonElement;

  constructor() {
    super();
    this.configureElements('message_container', 'ok_button');
  }

  override getHTML(): string {
    return html;
  }

  getData(): MessageDialogData {
    return {
      message: this.getAttribute('message') ?? '',
      button_text: this.getAttribute('button_text') ?? undefined,
      size: (this.getAttribute('size') as DialogSize) ?? DialogSize.MEDIUM,
    };
  }

  setData(data: MessageDialogData, parsed?: boolean) {
    this.setAttribute('message', data.message);
    this.setAttribute('size', data.size ?? DialogSize.MEDIUM);
    this.classList.add(`size-${data.size ?? DialogSize.MEDIUM}`);
    if (data.button_text) {
      this.setAttribute('button_text', data.button_text);
    }
    if (!parsed && !this.fully_parsed) {
      return;
    }
    this.message_container.innerText = data.message;
    if (data.button_text) {
      this.ok_button.innerText = data.button_text;
    }
    this.ok_button.addEventListener('click', () => {
      this.closeDialog();
    });
  }
}

customElements.define('dwg-message-dialog', DwgMessageDialog);

declare global {
  interface HTMLElementTagNameMap {
    'dwg-message-dialog': DwgMessageDialog;
  }
}

import { DwgDialogBox, DialogSize } from '../dialog_box';
import { GameType } from '../../lobby/data_models';

import html from './settings_dialog.html';

import './settings_dialog.scss';
import '../../game/games/fiddlesticks/fiddlesticks_settings/fiddlesticks_settings';
import '../../game/games/risq/dialogs/risq_settings/risq_settings';

export declare interface SettingsDialogData {
  game_type: GameType;
}

export class DwgSettingsDialog extends DwgDialogBox<SettingsDialogData> {
  private settings_body!: HTMLDivElement;
  private close_button!: HTMLButtonElement;

  private data: SettingsDialogData = { game_type: GameType.UNSPECIFIED };

  constructor() {
    super();
    this.configureElements('settings_body', 'close_button');
  }

  override getHTML(): string {
    return html;
  }

  getData(): SettingsDialogData {
    return this.data;
  }

  setData(data: SettingsDialogData, parsed?: boolean) {
    this.data = data;
    const size = this.resolveSize(data);
    this.classList.add(`size-${size}`);
    if (!parsed && !this.fully_parsed) {
      return;
    }
    switch (data.game_type) {
      case GameType.FIDDLESTICKS:
        this.settings_body.replaceChildren(document.createElement('dwg-fiddlesticks-settings'));
        break;
      case GameType.RISQ:
        this.settings_body.replaceChildren(document.createElement('dwg-risq-settings'));
        break;
      default:
        this.settings_body.innerText = 'No settings for this game';
        break;
    }
    this.close_button.addEventListener('click', () => {
      this.closeDialog();
    });
  }

  private resolveSize(data: SettingsDialogData): DialogSize {
    switch (data.game_type) {
      case GameType.FIDDLESTICKS:
      case GameType.RISQ:
        return DialogSize.XLARGE;
      default:
        return DialogSize.SMALL;
    }
  }
}

customElements.define('dwg-settings-dialog', DwgSettingsDialog);

declare global {
  interface HTMLElementTagNameMap {
    'dwg-settings-dialog': DwgSettingsDialog;
  }
}

import { until } from '../scripts/util';

import './dwg_element.scss';

/** Describes an html element used by DwgElements */
interface ElementMetadata {
  element_id: string;
  name: string;
  found_element: boolean;
}

export abstract class DwgElement extends HTMLElement {
  protected html_string: string = '';
  fully_parsed = false;
  private els_metadata: ElementMetadata[] = [];
  private parsing_controller?: AbortController;

  async connectedCallback(): Promise<void> {
    this.parsing_controller?.abort();
    const controller = new AbortController();
    this.parsing_controller = controller;
    this.classList.add('dwg-element');
    this.innerHTML = this.html_string;
    await until(this.elementsParsed.bind(this), 50, controller.signal);
    if (controller.signal.aborted) {
      return;
    }
    this.parsedCallback();
    this.classList.add('parsed');
    this.fully_parsed = true;
  }

  disconnectedCallback() {
    this.parsing_controller?.abort();
    this.fully_parsed = false;
    for (const el_metadata of this.els_metadata) {
      el_metadata.found_element = false;
    }
  }

  private elementsParsed(): boolean {
    let parsed = true;
    for (const el_metadata of this.els_metadata) {
      // @ts-ignore -> check value in subclass
      let el: HTMLElement | null = el_metadata.found_element ? this[el_metadata.name] : null;
      if (!el_metadata.found_element) {
        el = this.querySelector(`#${el_metadata.element_id}`);
        if (!!el) {
          // @ts-ignore -> set value in subclass
          this[el_metadata.name] = el;
          el_metadata.found_element = true;
        }
      }
      if (!el_metadata.found_element) {
        parsed = false;
        continue;
      }
      if (el instanceof DwgElement) {
        if (!el.fully_parsed) {
          parsed = false;
        }
      }
    }
    return parsed;
  }

  protected parsedCallback() {}

  protected configureElement(name: string, element_id?: string) {
    if (!element_id) {
      element_id = name.replace(/_/g, '-');
    }
    this.els_metadata.push({ element_id, name } as ElementMetadata);
  }

  protected configureElements(...names: string[]) {
    for (const name of names) {
      this.configureElement(name);
    }
  }
}

import { DwgElement } from '../dwg_element';
import type { ServerMessage, LobbyRoom, ConnectionMetadata } from '../lobby/data_models';
