  [RisqHotkeyScope.GLOBAL]: 'Global',
  [RisqHotkeyScope.UNITS]: 'Units',
  [RisqHotkeyScope.UNGARRISONED_UNITS]: 'Ungarrisoned Units',
  [RisqHotkeyScope.GARRISONED_UNITS_OR_BUILDINGS]: 'Garrisoned Units & Buildings',
  [RisqHotkeyScope.VILLAGERS]: 'Villagers',
  [RisqHotkeyScope.MILITARY]: 'Military',
  [RisqHotkeyScope.BUILDINGS]: 'Buildings',
};

export function actionScope(action: RisqHotkeyAction): RisqHotkeyScope {
  switch (action) {
    case RisqHotkeyAction.MOVE:
    case RisqHotkeyAction.ATTACK:
    case RisqHotkeyAction.STOP:
      return RisqHotkeyScope.UNITS;
    case RisqHotkeyAction.GARRISON:
      return RisqHotkeyScope.UNGARRISONED_UNITS;
    case RisqHotkeyAction.UNGARRISON:
      return RisqHotkeyScope.GARRISONED_UNITS_OR_BUILDINGS;
    case RisqHotkeyAction.GATHER:
    case RisqHotkeyAction.REPAIR:
    case RisqHotkeyAction.RENEW:
      return RisqHotkeyScope.VILLAGERS;
    case RisqHotkeyAction.STANCE_AGGRESSIVE:
    case RisqHotkeyAction.STANCE_DEFENSIVE:
    case RisqHotkeyAction.STANCE_STAND_GROUND:
    case RisqHotkeyAction.STANCE_PASSIVE:
    case RisqHotkeyAction.TOGGLE_INTERRUPT_CURRENT:
    case RisqHotkeyAction.TOGGLE_ATTACK_BACK:
      return RisqHotkeyScope.MILITARY;
    case RisqHotkeyAction.BUILDING_ATTACK:
    case RisqHotkeyAction.BUILDING_GATHER_POINT:
    case RisqHotkeyAction.BUILDING_CLEAR_GATHER_POINT:
    case RisqHotkeyAction.BUILDING_DELETE:
      return RisqHotkeyScope.BUILDINGS;
    default:
      return RisqHotkeyScope.GLOBAL;
  }
}

function scopeApplies(scope: RisqHotkeyScope, s: HotkeySelection): boolean {
  switch (scope) {
    case RisqHotkeyScope.UNITS:
      return s.kind === 'units';
    case RisqHotkeyScope.UNGARRISONED_UNITS:
      return s.kind === 'units' && !s.garrisoned;
    case RisqHotkeyScope.GARRISONED_UNITS_OR_BUILDINGS:
      return s.kind === 'building' || s.garrisoned;
    case RisqHotkeyScope.VILLAGERS:
      return s.kind === 'units' && s.composition === 'villagers';
    case RisqHotkeyScope.MILITARY:
      return s.kind === 'units' && s.composition === 'military';
    case RisqHotkeyScope.BUILDINGS:
      return s.kind === 'building';
    case RisqHotkeyScope.GLOBAL:
      return true;
  }
}

/** Whether the hotkey acts on the given selection */
export function hotkeyApplies(entry: RisqHotkeyLookupEntry, s: HotkeySelection): boolean {
  switch (entry.kind) {
    case 'action':
      return scopeApplies(actionScope(entry.action), s);
    case 'create_unit':
      return s.kind === 'building' && s.unit_ids.includes(entry.id);
    case 'research_tech':
      return s.kind === 'building' && s.tech_ids.includes(entry.id);
    case 'build_building':
      return scopeApplies(RisqHotkeyScope.VILLAGERS, s);
    default:
      return true;
  }
}

/** Two hotkeys conflict when any of the given selections makes both apply */
export function hotkeysConflict(
  a: RisqHotkeyLookupEntry,
  b: RisqHotkeyLookupEntry,
  selections: HotkeySelection[]
): boolean {
  return selections.some((s) => hotkeyApplies(a, s) && hotkeyApplies(b, s));
}

import type { Point2D } from '../../../../util/objects2d';
import { equalsPoint2D, roundAxialCoordinate } from '../../../../util/objects2d';
import type { RisqRegion, RisqSpace, RisqZone } from '../../model/types';
import type { RisqViewport } from '../../rendering/board/viewport';
import { RisqViewMode } from '../../rendering/terrain';
import { resolveHoveredZones, unhoverRisqZone } from '../../rendering/zones/hit_testing';
import type { RisqSession } from '../session';

/** The mouse's last board position and the space/zone under it, including their hover and click flags */
export class RisqHover {
  private mouse_canvas: Point2D = { x: 0, y: 0 };
  private mouse_screen: Point2D = { x: 0, y: 0 };
  private hovered_space?: RisqSpace;
  private hovered_zone?: RisqZone;

  constructor(
    private session: RisqSession,
    private viewport: RisqViewport
  ) {}

  space(): RisqSpace | undefined {
    return this.hovered_space;
  }

  zone(): RisqZone | undefined {
    return this.hovered_zone;
  }

  mouseCanvas(): Point2D {
    return this.mouse_canvas;
  }

  mouseScreen(): Point2D {
    return this.mouse_screen;
  }

  setMouse(canvas: Point2D, screen: Point2D) {
    this.mouse_canvas = canvas;
    this.mouse_screen = screen;
  }

  hoveredRegion(): RisqRegion | undefined {
    if (!this.viewport.regionInteractionEnabled() || !this.hovered_space) {
      return undefined;
    }
    return this.session.getRegionForSpace(this.hovered_space.coordinate_key);
  }

  /** Drops references into a snapshot that's about to be replaced */
  forget() {
    this.hovered_space = undefined;
    this.hovered_zone = undefined;
  }

  /** Resolves the hovered space and zone under the mouse; returns whether the board itself is hovered */
  update(over_other_component: boolean): boolean {
    const game = this.session.getGame();
    if (!game) {
      return false;
    }
    if (!!this.hovered_space) {
      this.hovered_space.center = this.viewport.coordinateToCanvas(this.hovered_space.coordinate);
    }
    const mouse_coordinate = this.viewport.canvasToCoordinate(this.mouse_canvas, game.board_size);
    const new_hovered_space = this.session.spaceAt(roundAxialCoordinate(mouse_coordinate));
    if (over_other_component || !new_hovered_space) {
      this.removeHoveredFlags();
      if (!!this.hovered_space) {
        this.hovered_space.clicked = false;
        this.hovered_space = undefined;
        this.unhoverZone();
      }
      return false;
    }
    if (equalsPoint2D(new_hovered_space.coordinate, this.hovered_space?.coordinate)) {
      this.updateHoveredFlags();
      this.resolveZone();
      return true;
    }
    this.removeHoveredFlags();
    if (!!this.hovered_space) {
      this.hovered_space.clicked = false;
      this.unhoverZone();
    }
    this.hovered_space = new_hovered_space;
    this.resolveZone();
    this.updateHoveredFlags();
    return true;
  }

  private resolveZone() {
    if (this.viewport.zoneView() && this.viewport.viewMode() !== RisqViewMode.REGION) {
      const new_hovered_zone = resolveHoveredZones(this.mouse_canvas, this.hovered_space, this.viewport.hexR());
      if (!!this.hovered_zone && !equalsPoint2D(new_hovered_zone?.coordinate, this.hovered_zone?.coordinate)) {
        this.unhoverZone();
      }
      this.hovered_zone = new_hovered_zone;
    } else {
      this.unhoverZone();
    }
  }

  private unhoverZone() {
    if (!!this.hovered_zone) {
      unhoverRisqZone(this.hovered_zone);
      this.hovered_zone = undefined;
    }
  }

  /** Cancels any click pending on the hovered space/zone, e.g. once a press turns into a drag */
  clearClicks() {
    if (!!this.hovered_space) {
      this.hovered_space.clicked = false;
    }
    if (!!this.hovered_zone) {
      this.hovered_zone.clicked = false;
      for (const part of this.hovered_zone.hovered_data) {
        part.clicked = false;
      }
    }
  }

  /** Board pan has started: drop highlight flags and pending clicks */
  dragging() {
    this.removeHoveredFlags();
    this.clearClicks();
  }

  leave() {
    this.unhoverZone();
    if (!!this.hovered_space) {
      this.hovered_space.hovered = false;
      this.hovered_space.clicked = false;
      this.hovered_space = undefined;
    }
  }

  private removeHoveredFlags() {
    if (!this.hovered_space) {
      return;
    }
    this.hovered_space.hovered = false;
    for (const neighbor of this.session.boardNeighbors(this.hovered_space)) {
      neighbor.hovered_neighbor = false;
    }
    for (const row of this.session.boardRows(this.hovered_space)) {
      row.hovered_row = false;
    }
  }

  private updateHoveredFlags() {
    if (!this.hovered_space) {
      return;
    }
    this.hovered_space.hovered = true;
    for (const neighbor of this.session.boardNeighbors(this.hovered_space)) {
      neighbor.hovered_neighbor = true;
    }
    for (const row of this.session.boardRows(this.hovered_space)) {
      row.hovered_row = true;
    }
  }
}

import type { BoardTransformData, DwgCanvasBoard, ModifierKeys } from '../../../../util/canvas_board/canvas_board';
import type { CanvasComponent } from '../../../../util/canvas_components/canvas_component';
import type { Point2D } from '../../../../util/objects2d';
import { normalizeRect } from '../../../../util/objects2d';
import type { RisqLeftPanel } from '../../canvas_components/left_panel/left_panel';
import { LeftPanelDataType } from '../../canvas_components/left_panel/left_panel_data';
import type { RisqSpace, RisqZone } from '../../model/types';
import { RisqOrderType } from '../../model/types';
import type { RisqViewport } from '../../rendering/board/viewport';
import { isEmptyPlot } from '../../rendering/zones/draw';
import type { OrderSubject, RisqOrderDispatch } from '../orders/dispatch';
import type { RisqOrderPlanning } from '../orders/planning';
import type { RisqBoardClicks } from '../selection/board_clicks';
import type { RisqSession } from '../session';
import type { RisqArmedState } from './armed_state';
import type { RisqCursorController } from './cursor_controller';
import type { RisqHover } from './hover';

const DRAG_SELECT_THRESHOLD = 3;

/** Routes board mouse events between the overlay components, hover, order dispatch, and click/drag selection */
export class RisqPointer {
  private dragging_selection = false;
  private drag_additive = false;
  private drag_start: Point2D = { x: 0, y: 0 };
  private drag_current: Point2D = { x: 0, y: 0 };

  constructor(
    private board: () => DwgCanvasBoard | undefined,
    private components: CanvasComponent[],
    private panels_hovered: () => boolean,
    private session: RisqSession,
    private viewport: RisqViewport,
    private hover: RisqHover,
    private armed: RisqArmedState,
    private cursor: RisqCursorController,
    private left_panel: RisqLeftPanel,
    private planning: RisqOrderPlanning,
    private dispatch: RisqOrderDispatch,
    private board_clicks: RisqBoardClicks
  ) {}

  /** Screen-space rectangle of an in-progress drag selection */
  dragRect(): { min: Point2D; max: Point2D } | undefined {
    return this.dragging_selection ? normalizeRect(this.drag_start, this.drag_current) : undefined;
  }

  private dragged(): boolean {
    return (
      Math.hypot(this.drag_current.x - this.drag_start.x, this.drag_current.y - this.drag_start.y) >
      DRAG_SELECT_THRESHOLD
    );
  }

  /** Re-resolves hover at the last mouse position, e.g. after panels or data change underneath it */
  recalculate() {
    const board = this.board();
    if (!board || !board.isInitialized()) {
      return;
    }
    this.mousemove(
      this.hover.mouseCanvas(),
      this.hover.mouseScreen(),
      this.viewport.lastTransform(),
      board.getModifiers()
    );
  }

  // scroll() signature already used by HTMLElement
  scroll(dy: number, mode: number): boolean {
    for (const component of this.components) {
      if (component.isHovering()) {
        component.scroll?.(dy, mode);
        return true;
      }
    }
    return false;
  }

  mousemove(m: Point2D, screen: Point2D, transform: BoardTransformData, modifiers: ModifierKeys) {
    const board = this.board();
    if (!this.session.getGame() || !board) {
      return;
    }
    this.viewport.updateDrawDetail(transform.scale, board.getMaxScale());
    this.hover.setMouse(m, screen);
    if (this.dragging_selection) {
      this.drag_current = screen;
      if (this.dragged()) {
        this.hover.clearClicks();
      }
      return;
    }
    const hovered_other_component = this.components.map((c) => c.mousemove(m, screen, transform)).some(Boolean);
    board.setPanSuppressed(false, this.panels_hovered());
    if (this.hover.update(hovered_other_component)) {
      this.cursor.update(modifiers.ctrl);
    } else {
      this.cursor.setDefault();
    }
  }

  draggingCallback() {
    this.hover.dragging();
  }

  cancelInput(): void {
    this.dragging_selection = false;
    this.hover.clearClicks();
    this.hover.leave();
    for (const component of this.components) {
      component.setClicking(false);
      component.setHovering(false);
    }
    this.cursor.setDefault();
  }

  mouseleave(): void {
    this.cancelInput();
  }

  // returns false if mousedown event should initiate dragging
  mousedown(e: MouseEvent): boolean {
    if (this.components.map((c) => c.mousedown(e)).some(Boolean)) {
      return true;
    }
    if (e.button === 0) {
      this.pressBoard();
    } else if (e.button === 2 && this.armed.getArmedOrder() === RisqOrderType.OrderType_BuyMercenary) {
      this.dispatch.placeMercenary(e.ctrlKey);
      return true;
    } else if (e.button === 2 && this.left_panel.isOrderable() && this.session.canGiveOrders()) {
      this.orderSelection(e.ctrlKey);
      return true;
    }
    const armed = this.armed.anythingArmed();
    if (this.viewport.zoneView() && e.button === 0 && !e.shiftKey && !armed) {
      this.dragging_selection = true;
      this.drag_additive = e.ctrlKey;
      this.drag_start = { ...this.hover.mouseScreen() };
      this.drag_current = this.drag_start;
      return true;
    }
    return (e.button === 2 && armed) || (e.button !== 0 && e.button !== 2);
  }

  /** Marks the pressed space, zone, or zone part as clicked so mouseup can act on it if still hovered */
  private pressBoard() {
    const space = this.hover.space();
    const zone = this.hover.zone();
    if (!space || space.visibility <= 0) {
      return;
    }
    space.clicked = true;
    if (!this.viewport.zoneView() || !zone) {
      return;
    }
    space.clicked = false;
    zone.clicked = true;
    for (const [i, part] of zone.hovered_data.entries()) {
      if (part.hovered && !(i === 0 && isEmptyPlot(this.planning, zone))) {
        part.clicked = true;
        zone.clicked = false;
        break;
      }
    }
  }

  private orderSelection(ctrl_held: boolean) {
    const data = this.left_panel.getData();
    switch (data?.data_type) {
      case LeftPanelDataType.UNIT:
        this.dispatch.unitOrder([data.data], ctrl_held);
        break;
      case LeftPanelDataType.UNITS_BY_TYPE:
      case LeftPanelDataType.ECONOMIC_UNITS:
      case LeftPanelDataType.MILITARY_UNITS: {
        const units: OrderSubject[] = data.data.units.flatMap((u) =>
          [...u.units].map((internal_id) => ({ unit_type: u.unit_type, internal_id }))
        );
        this.dispatch.unitOrder(units, ctrl_held);
        break;
      }
      case LeftPanelDataType.BUILDING:
        this.dispatch.buildingOrder(data.data, ctrl_held);
        break;
      default:
        break;
    }
  }

  mouseup(e: MouseEvent) {
    const armed_before = this.armed.snapshot();
    for (const component of this.components) {
      component.mouseup(e);
    }
    if (this.dragging_selection) {
      this.dragging_selection = false;
      if (this.dragged()) {
        this.board_clicks.dragSelect(this.drag_start, this.drag_current, this.drag_additive);
        return;
      }
    }
    const space = this.hover.space();
    const zone = this.hover.zone();
    if (!!space && space.visibility > 0 && armed_before.order === RisqOrderType.NONE) {
      this.releaseBoard(space, zone, e);
    } else if (e.button === 0 && armed_before.order === RisqOrderType.NONE && !this.panels_hovered()) {
      this.left_panel.close();
    }
    const keep_mercenary_armed = e.ctrlKey && armed_before.order === RisqOrderType.OrderType_BuyMercenary;
    if (armed_before.order !== RisqOrderType.NONE && this.armed.unchangedSince(armed_before) && !keep_mercenary_armed) {
      this.armed.disarmOrder();
    }
  }

  private releaseBoard(space: RisqSpace, zone: RisqZone | undefined, e: MouseEvent) {
    if (!!zone) {
      if (this.viewport.zoneView()) {
        this.board_clicks.zoneClick(space, zone, e);
      }
      zone.clicked = false;
      for (const part of zone.hovered_data) {
        part.clicked = false;
      }
    } else {
      this.board_clicks.spaceClick(space);
    }
    space.clicked = false;
  }
}

import type { ColorRGB } from '../../../../../../scripts/color_rgb';
import { RISQ_MESSAGE_WARNING_COLOR } from '../../canvas_components/message_queue';
import { cantorPair } from '../../model/coordinates';
import type { RisqBuilding, RisqFrontendOrder, RisqGatherPoint } from '../../model/types';
import {
  RisqGatherObjectType,
  RisqGatherPointLocationKind,
  RisqOrderType,
  RisqUnitType,
  canAffordCost,
  canHaveGatherPoint,
} from '../../model/types';
import type { RisqViewport } from '../../rendering/board/viewport';
import { hoveredZoneObject } from '../../rendering/zones/hit_testing';
import type { RisqCommands } from '../commands';
import type { RisqArmedState } from '../input/armed_state';
import type { RisqHover } from '../input/hover';
import type { RisqSession } from '../session';
import type { RisqOrdersModel } from './orders_model';
import type { RisqOrderPlanning } from './planning';
import { unitCanBuild } from './eligibility';
import type { RisqOrderTargeting } from './targeting';

/** A selected unit as order dispatch needs it */
export declare interface OrderSubject {
  internal_id: number;
  unit_type: RisqUnitType;
}

/** Turns a right-click on the hovered target into orders for the selected units or building */
export class RisqOrderDispatch {
  constructor(
    private session: RisqSession,
    private viewport: RisqViewport,
    private hover: RisqHover,
    private armed: RisqArmedState,
    private targeting: RisqOrderTargeting,
    private planning: RisqOrderPlanning,
    private orders_model: RisqOrdersModel,
    private commands: RisqCommands,
    private show_message: (text: string, color: ColorRGB) => void
  ) {}

  unitOrder(units: OrderSubject[], ctrl_held: boolean): void {
    const space = this.hover.space();
    const zone = this.hover.zone();
    if (!space) {
      this.armed.disarmOrder();
      return;
    }
    const ids = (filter: (u: OrderSubject) => boolean = () => true) => units.filter(filter).map((u) => u.internal_id);
    const economic = (u: OrderSubject) => u.unit_type === RisqUnitType.ECONOMIC;
    const attackers = () => ids((u) => this.armed.getArmedOrder() !== RisqOrderType.NONE || !economic(u));
    const add = (order_type: RisqOrderType, subjects: number[], target_id: number) =>
      this.addUnitOrder(order_type, subjects, target_id, ctrl_held);
    const order_type = this.targeting.resolveActiveOrderType(ctrl_held);
    switch (order_type) {
      case RisqOrderType.OrderType_UnitMoveSpace:
        add(
          order_type,
          ids((u) => !this.targeting.isUnitAtHoverTarget(u.internal_id, false, ctrl_held)),
          space.coordinate_key
        );
        break;
      case RisqOrderType.OrderType_UnitMoveZone:
        if (!zone) {
          return;
        }
        add(
          order_type,
          ids((u) => !this.targeting.isUnitAtHoverTarget(u.internal_id, true, ctrl_held)),
          zone.coordinate_key
        );
        break;
      case RisqOrderType.OrderType_UnitAttackBuilding:
      case RisqOrderType.OrderType_UnitGarrison: {
        const target = zone?.building;
        if (!target) {
          return;
        }
        add(order_type, order_type === RisqOrderType.OrderType_UnitGarrison ? ids() : attackers(), target.internal_id);
        break;
      }
      case RisqOrderType.OrderType_UnitAttackUnit: {
        const target_id = this.targeting.hoveredEnemyUnitId();
        if (target_id === undefined) {
          return;
        }
        add(order_type, attackers(), target_id);
        break;
      }
      case RisqOrderType.OrderType_UnitAttackSpace:
        add(order_type, ids(), space.coordinate_key);
        break;
      case RisqOrderType.OrderType_UnitAttackZone:
        if (!zone) {
          return;
        }
        add(order_type, ids(), zone.coordinate_key);
        break;
      case RisqOrderType.OrderType_UnitGather: {
        if (!zone) {
          return;
        }
        const target = zone.building ?? zone.resource;
        const fitted = this.planning.fitGatherCapacity(target, ids(economic));
        if (fitted.at_capacity) {
          this.show_message(`${target!.display_name} is at worker capacity`, RISQ_MESSAGE_WARNING_COLOR);
        }
        add(order_type, fitted.subjects, zone.coordinate_key);
        break;
      }
      case RisqOrderType.OrderType_UnitBuild:
        if (!zone) {
          return;
        }
        if (this.armed.getArmedBuilding()) {
          this.newFoundation(ids(economic), zone.coordinate_key, ctrl_held);
        } else {
          this.assistBuildOrder(units, zone.coordinate_key, ctrl_held);
        }
        break;
      case RisqOrderType.OrderType_UnitRepair:
      case RisqOrderType.OrderType_UnitRenew:
        if (!zone?.building) {
          return;
        }
        add(order_type, ids(economic), zone.building.internal_id);
        break;
      default:
        this.armed.disarmOrder();
        return;
    }
    this.armed.disarmOrder();
  }

  private addUnitOrder(order_type: RisqOrderType, subjects: number[], target_id: number, ctrl_held: boolean): void {
    if (subjects.length === 0) {
      return;
    }
    if (order_type === RisqOrderType.OrderType_UnitRenew) {
      const player = this.session.getPlayer();
      const cost = this.planning.unpaidRenewalCost(target_id);
      const reserved = this.orders_model
        .pendingOrders()
        .some(
          (order: RisqFrontendOrder): boolean =>
            order.order_type === RisqOrderType.OrderType_UnitRenew && order.target_id === target_id
        );
      if (player && cost && !reserved && !canAffordCost(player, cost)) {
        this.show_message('Not enough resources', RISQ_MESSAGE_WARNING_COLOR);
        return;
      }
    }
    this.orders_model.add({
      player_id: this.session.getPlayerId(),
      order_type,
      subjects,
      target_id,
      clear_previous_orders: !ctrl_held,
    });
  }

  private existingBuildTarget(zone_key: number): number | undefined {
    const building = this.hover.zone()?.building;
    const owned_unfinished = building?.player_id === this.session.getPlayerId() && building?.under_construction;
    return (
      this.planning.getLocalFoundation(zone_key)?.building_id ??
      (owned_unfinished ? building?.building_id : undefined) ??
      this.session.getPlayer()?.planned_foundations.get(zone_key)?.building_id
    );
  }

  private assistBuildOrder(units: OrderSubject[], zone_key: number, ctrl_held: boolean): void {
    const player = this.session.getPlayer();
    const building_id = this.existingBuildTarget(zone_key);
    if (!player || building_id === undefined) {
      return;
    }
    const subjects = units
      .filter((subject: OrderSubject): boolean => {
        const unit = player.units.get(subject.internal_id);
        return !!unit && unitCanBuild(player, unit, building_id);
      })
      .map((subject: OrderSubject): number => subject.internal_id);
    if (subjects.length > 0) {
      this.orders_model.add(this.buildOrder(building_id, subjects, zone_key, ctrl_held));
    }
  }

  /** Queues a build order for the armed building and records it as a local foundation */
  private newFoundation(subjects: number[], zone_key: number, ctrl_held: boolean) {
    const building = this.armed.getArmedBuilding()!;
    const order = this.buildOrder(building.id, subjects, zone_key, ctrl_held);
    this.orders_model.add(order);
    this.planning.setLocalFoundation({
      coordinate_key: zone_key,
      building_id: building.id,
      display_name: building.display_name,
      stamina_cost: building.stamina_cost,
      order,
    });
  }

  private buildOrder(building_id: number, subjects: number[], zone_key: number, ctrl_held: boolean): RisqFrontendOrder {
    return {
      player_id: this.session.getPlayerId(),
      order_type: RisqOrderType.OrderType_UnitBuild,
      subjects,
      target_id: cantorPair(building_id, zone_key),
      clear_previous_orders: !ctrl_held,
    };
  }

  /** Right-click with an owned building selected: attack the hovered enemy, else set the gather point there */
  buildingOrder(building: RisqBuilding, ctrl_held: boolean) {
    const target = this.targeting.buildingAttackTarget(building);
    if (target) {
      this.orders_model.add({
        player_id: this.session.getPlayerId(),
        order_type:
          target.kind === 'unit'
            ? RisqOrderType.OrderType_BuildingAttackUnit
            : RisqOrderType.OrderType_BuildingAttackBuilding,
        subjects: [building.internal_id],
        target_id: target.internal_id,
        clear_previous_orders: !ctrl_held,
      });
    } else {
      this.gatherPointOrder(building);
    }
    this.armed.disarmGatherPoint();
    this.armed.disarmBuildingAttack();
  }

  private gatherPointOrder(building: RisqBuilding) {
    if (!canHaveGatherPoint(building)) {
      return;
    }
    const zone = this.hover.zone();
    const space = this.hover.space();
    let point: RisqGatherPoint;
    if (this.viewport.zoneView() && zone) {
      point = {
        location_kind: RisqGatherPointLocationKind.ZONE,
        location_id: zone.coordinate_key,
        object_type: RisqGatherObjectType.NONE,
        object_id: 0,
      };
      const hovered = hoveredZoneObject(zone, this.viewport.viewMode());
      if (hovered?.kind === 'resource' && zone.resource) {
        point.object_type = RisqGatherObjectType.RESOURCE;
        point.object_id = zone.resource.internal_id;
      } else if (hovered?.kind === 'building' && zone.building) {
        point.object_type = RisqGatherObjectType.BUILDING;
        point.object_id = zone.building.internal_id;
      } else if (hovered?.kind === 'unit') {
        const unit_id = [...hovered.groups[0].units][0];
        if (unit_id !== undefined) {
          point.object_type = RisqGatherObjectType.UNIT;
          point.object_id = unit_id;
        }
      }
    } else if (space) {
      point = {
        location_kind: RisqGatherPointLocationKind.SPACE,
        location_id: space.coordinate_key,
        object_type: RisqGatherObjectType.NONE,
        object_id: 0,
      };
    } else {
      return;
    }
    this.commands.setGatherPoint(building.internal_id, point);
  }

  placeMercenary(keep_armed: boolean) {
    const zone = this.targeting.mercenaryTargetZone();
    const invalid_reason = this.targeting.mercenaryPlacementInvalidReason(zone);
    const mercenary = this.armed.getArmedMercenary();
    if (invalid_reason || !zone || !mercenary) {
      this.show_message(invalid_reason ?? 'No valid location', RISQ_MESSAGE_WARNING_COLOR);
      return;
    }
    this.orders_model.add({
      player_id: this.session.getPlayerId(),
      order_type: RisqOrderType.OrderType_BuyMercenary,
      subjects: [],
      target_id: cantorPair(mercenary.id, zone.coordinate_key),
      clear_previous_orders: false,
    });
    if (!keep_armed) {
      this.armed.disarmOrder();
    }
  }
}

import type { RisqFrontendOrder, RisqOrder } from '../../model/types';
import { RisqOrderType } from '../../model/types';

/** Returns whether the order is for units */
export function isUnitOrder(order: RisqOrderType): boolean {
  return order >= RisqOrderType.OrderType_UnitMoveSpace && order <= RisqOrderType.OrderType_UnitDelete;
}

/** Returns whether the order is for buildings */
export function isBuildingOrder(order: RisqOrderType): boolean {
  return order >= RisqOrderType.OrderType_BuildingCreate && order <= RisqOrderType.OrderType_BuildingAutoAttackBuilding;
}

/** Returns whether the order survives a clear_previous_orders order on the same subject, mirroring the backend */
export function isClearImmune(order: RisqOrderType): boolean {
  return order === RisqOrderType.OrderType_BuildingCreate || order === RisqOrderType.OrderType_BuildingResearch;
}

/** Returns whether the order is a subject-less, player-level order */
export function isPlayerOrder(order: RisqOrderType): boolean {
  return order >= RisqOrderType.OrderType_CancelOrder && order <= RisqOrderType.OrderType_BuyMercenary;
}

/** Returns the arrow color used to draw the order on the map */
export function orderArrowColor(order_type: RisqOrderType): string {
  switch (order_type) {
    case RisqOrderType.OrderType_UnitGather:
      return 'rgba(255, 150, 0, 0.9)';
    case RisqOrderType.OrderType_UnitAttackSpace:
    case RisqOrderType.OrderType_UnitAttackZone:
    case RisqOrderType.OrderType_UnitAttackUnit:
    case RisqOrderType.OrderType_UnitAttackBuilding:
    case RisqOrderType.OrderType_UnitAutoAttackUnit:
    case RisqOrderType.OrderType_UnitAutoAttackBuilding:
    case RisqOrderType.OrderType_BuildingAttackUnit:
    case RisqOrderType.OrderType_BuildingAttackBuilding:
    case RisqOrderType.OrderType_BuildingAutoAttackUnit:
    case RisqOrderType.OrderType_BuildingAutoAttackBuilding:
      return 'rgba(220, 30, 30, 0.9)';
    case RisqOrderType.OrderType_UnitBuild:
      return 'rgba(40, 110, 230, 0.9)';
    case RisqOrderType.OrderType_UnitRepair:
      return 'rgba(100, 170, 250, 0.9)';
    case RisqOrderType.OrderType_UnitRenew:
      return 'rgba(190, 200, 40, 0.9)';
    case RisqOrderType.OrderType_UnitGarrison:
      return 'rgba(255, 225, 0, 0.9)';
    case RisqOrderType.OrderType_UnitMoveSpace:
    case RisqOrderType.OrderType_UnitMoveZone:
    default:
      return 'rgba(20, 20, 20, 0.9)';
  }
}

/** One ledger row's worth of orders: a representative order plus any same-producible orders collapsed behind it */
export declare interface RisqOrderRowEntry {
  order: RisqFrontendOrder;
  collapsed_orders?: RisqFrontendOrder[];
}

/** Groups same-subject, same-target BuildingCreate orders together, keeping the first behind */
export function collapseBuildingCreateOrders(orders: RisqFrontendOrder[]): RisqOrderRowEntry[] {
  const clusters = new Map<string, RisqFrontendOrder[]>();
  for (const order of orders) {
    if (order.order_type !== RisqOrderType.OrderType_BuildingCreate) {
      continue;
    }
    const key = `${order.subjects[0]}:${order.target_id}`;
    const cluster = clusters.get(key);
    if (cluster) {
      cluster.push(order);
    } else {
      clusters.set(key, [order]);
    }
  }
  const consumed = new Set<RisqFrontendOrder>();
  const entries: RisqOrderRowEntry[] = [];
  for (const order of orders) {
    if (consumed.has(order)) {
      continue;
    }
    if (order.order_type !== RisqOrderType.OrderType_BuildingCreate) {
      consumed.add(order);
      entries.push({ order });
      continue;
    }
    const cluster = clusters.get(`${order.subjects[0]}:${order.target_id}`)!;
    consumed.add(cluster[0]);
    entries.push({ order: cluster[0] });
    if (cluster.length > 1) {
      for (const queued of cluster.slice(1)) {
        consumed.add(queued);
      }
      entries.push({ order: cluster[1], collapsed_orders: cluster.slice(2) });
    }
  }
  return entries;
}

/** Owns this player's orders for the current turn: the server's already-active ones plus any queued locally */
export class RisqOrdersModel {
  private submitted: RisqFrontendOrder[] = [];
  private pending: RisqFrontendOrder[] = [];
  private on_change: () => void;

  constructor(on_change: () => void) {
    this.on_change = on_change;
  }

  triggerChange() {
    this.on_change();
  }

  setSubmitted(orders: RisqOrder[]) {
    this.submitted = [...orders];
  }

  revertSubmittedToPending() {
    this.pending.push(...this.submitted.filter((order) => order.internal_id === undefined));
    this.submitted = [];
    this.on_change();
  }

  all(): RisqFrontendOrder[] {
    return [...this.submitted, ...this.pending];
  }

  pendingOrders(): RisqFrontendOrder[] {
    return [...this.pending];
  }

  private stripPendingSubject(order: RisqFrontendOrder, subject_internal_id: number): boolean {
    order.subjects = order.subjects.filter((id) => id !== subject_internal_id);
    return order.subjects.length > 0;
  }

  add(order: RisqFrontendOrder) {
    if (order.clear_previous_orders) {
      this.pending = this.pending.filter((o) => {
        if (
          !(
            (isUnitOrder(order.order_type) && isUnitOrder(o.order_type)) ||
            (isBuildingOrder(order.order_type) && isBuildingOrder(o.order_type))
          )
        ) {
          return true;
        }
        if (isClearImmune(o.order_type)) {
          return true;
        }
        let has_subjects = true;
        for (const new_id of order.subjects) {
          has_subjects = this.stripPendingSubject(o, new_id);
        }
        return has_subjects;
      });
    }
    this.pending.push(order);
    this.on_change();
  }

  isExplicitlyCancelling(order: RisqFrontendOrder, subject_internal_ids?: number[]): boolean {
    if (order.internal_id === undefined) return false;
    const explicit = this.pending.find(
      (o) => o.order_type === RisqOrderType.OrderType_CancelOrder && o.target_id === order.internal_id
    );
    if (!explicit) return false;
    if (explicit.subjects.length === 0) return true;
    const subs = subject_internal_ids ? order.subjects.filter((s) => subject_internal_ids.includes(s)) : order.subjects;
    return subs.length > 0 && subs.every((s) => explicit.subjects.includes(s));
  }

  isCancelling(order: RisqFrontendOrder, subject_internal_ids?: number[]): boolean {
    if (this.isExplicitlyCancelling(order, subject_internal_ids)) {
      return true;
    }
    if (order.internal_id === undefined || isClearImmune(order.order_type)) {
      return false;
    }
    const subs = subject_internal_ids ? order.subjects.filter((s) => subject_internal_ids.includes(s)) : order.subjects;
    const is_unit = isUnitOrder(order.order_type);
    const is_bldg = isBuildingOrder(order.order_type);
    return (
      subs.length > 0 &&
      subs.every((s) =>
        this.pending.some(
          (p) =>
            p.clear_previous_orders &&
            ((is_unit && isUnitOrder(p.order_type)) || (is_bldg && isBuildingOrder(p.order_type))) &&
            p.subjects.includes(s)
        )
      )
    );
  }

  cancel(order: RisqFrontendOrder) {
    if (order.internal_id === undefined) {
      this.pending = this.pending.filter((o) => o !== order);
      this.on_change();
      return;
    }
    if (this.isExplicitlyCancelling(order)) {
      this.pending = this.pending.filter(
        (o) => !(o.order_type === RisqOrderType.OrderType_CancelOrder && o.target_id === order.internal_id)
      );
      this.on_change();
      return;
    }
    if (this.isCancelling(order)) {
      return;
    }
    this.add({
      player_id: order.player_id,
      order_type: RisqOrderType.OrderType_CancelOrder,
      subjects: [],
      target_id: order.internal_id,
      clear_previous_orders: false,
    });
  }

  cancelSubject(order: RisqFrontendOrder, subject_internal_id: number) {
    if (order.internal_id === undefined) return;
    const existing = this.pending.find(
      (o) => o.order_type === RisqOrderType.OrderType_CancelOrder && o.target_id === order.internal_id
    );
    if (existing) {
      if (existing.subjects.length > 0 && !existing.subjects.includes(subject_internal_id)) {
        existing.subjects.push(subject_internal_id);
        this.on_change();
      }
      return;
    }
    this.add({
      player_id: order.player_id,
      order_type: RisqOrderType.OrderType_CancelOrder,
      subjects: [subject_internal_id],
      target_id: order.internal_id,
      clear_previous_orders: false,
    });
  }

  cancelForSubject(subject_internal_id: number, kind: 'unit' | 'building' = 'unit') {
    for (const order of this.all()) {
      if (kind === 'unit' && !isUnitOrder(order.order_type)) {
        continue;
      }
      if (kind === 'building' && !isBuildingOrder(order.order_type)) {
        continue;
      }
      if (!order.subjects.includes(subject_internal_id)) {
        continue;
      }
      if (order.internal_id === undefined) {
        if (!this.stripPendingSubject(order, subject_internal_id)) {
          this.pending = this.pending.filter((o) => o !== order);
        }
        this.on_change();
        continue;
      }
      this.cancelSubject(order, subject_internal_id);
    }
  }

  clearPending() {
    this.pending = [];
    this.on_change();
  }

  effectiveForSubject(subject_internal_id: number, kind: 'unit' | 'building'): RisqFrontendOrder[] {
    const all = this.all();
    const cancel_orders = all.filter((o) => o.order_type === RisqOrderType.OrderType_CancelOrder);
    const kind_matches = kind === 'unit' ? isUnitOrder : isBuildingOrder;
    let effective: RisqFrontendOrder[] = [];
    for (const order of all) {
      if (!kind_matches(order.order_type) || !order.subjects.includes(subject_internal_id)) {
        continue;
      }
      if (
        order.internal_id !== undefined &&
        cancel_orders.some(
          (c) =>
            c.target_id === order.internal_id && (c.subjects.length === 0 || c.subjects.includes(subject_internal_id))
        )
      ) {
        continue;
      }
      if (order.clear_previous_orders) {
        effective = effective.filter((o) => isClearImmune(o.order_type));
      }
      effective.push(order);
    }
    return effective;
  }
}

import { equalsPoint2D } from '../../../../util/objects2d';
import { cantorPair, invertBuildKey, invertPair } from '../../model/coordinates';
import type {
  RisqBuilding,
  RisqCost,
  RisqFrontendOrder,
  RisqPlayer,
  RisqProducible,
  RisqResource,
  RisqUnit,
  RisqUnitType,
  RisqZone,
} from '../../model/types';
import { RisqOrderType, RisqProducibleKind, RisqResourceType, canAffordCost } from '../../model/types';
import type { RisqSession } from '../session';
import type { RisqOrdersModel } from './orders_model';

export declare interface LocalRisqFoundation {
  coordinate_key: number;
  building_id: number;
  display_name: string;
  stamina_cost?: number;
  order: RisqFrontendOrder;
}

/** Predictions derived from the snapshot plus pending orders: local foundations, spending, gather capacity, idleness */
export class RisqOrderPlanning {
  private local_foundations = new Map<number, LocalRisqFoundation>();
  private idle_units: RisqUnit[] = [];
  private last_idle_selected?: number;

  constructor(
    private session: RisqSession,
    private orders_model: RisqOrdersModel
  ) {}

  getLocalFoundation(key: number): LocalRisqFoundation | undefined {
    return this.local_foundations.get(key);
  }

  setLocalFoundation(foundation: LocalRisqFoundation) {
    this.local_foundations.set(foundation.coordinate_key, foundation);
  }

  unpaidRenewalCost(target_id: number): RisqCost | undefined {
    const building = this.session.findBuildingById(target_id);
    return building?.renewing ? undefined : building?.renew_cost;
  }

  hasPlannedFoundation(zone: RisqZone | undefined): boolean {
    if (!zone) {
      return false;
    }
    const has_local = this.local_foundations.has(zone.coordinate_key);
    const is_cancelled = this.orders_model
      .pendingOrders()
      .some((o) => o.order_type === RisqOrderType.OrderType_CancelFoundation && o.target_id === zone.coordinate_key);
    const has_server = !is_cancelled && !!this.session.getPlayer()?.planned_foundations?.has(zone.coordinate_key);
    return has_local || has_server;
  }

  /** Recomputes everything derived from the orders model; call after any order or snapshot change */
  refresh() {
    this.syncLocalFoundations();
    this.updateResourceSpending();
    this.recomputeIdleUnits();
  }

  private activeBuildOrders(): Map<number, RisqFrontendOrder> {
    const map = new Map<number, RisqFrontendOrder>();
    for (const order of this.orders_model.all()) {
      if (order.order_type === RisqOrderType.OrderType_UnitBuild && !this.orders_model.isCancelling(order)) {
        map.set(invertPair(order.target_id).y, order);
      }
    }
    return map;
  }

  private registerLocalFoundation(player: RisqPlayer, key: number, order: RisqFrontendOrder) {
    const { building_id, space, zone } = invertBuildKey(order.target_id);
    const site = this.session
      .spaceAt(space)
      ?.zones?.flat()
      .find((z) => equalsPoint2D(z.coordinate, zone));
    if (site?.building) {
      return;
    }
    const producible = this.findProducible(player, building_id, order.subjects);
    this.local_foundations.set(key, {
      coordinate_key: key,
      building_id,
      display_name: producible?.display_name ?? 'Building',
      stamina_cost: producible?.stamina_cost,
      order,
    });
  }

  private syncLocalFoundations() {
    const active = this.activeBuildOrders();
    const player = this.session.getPlayer();
    const is_cancelled = (key: number) =>
      this.orders_model
        .pendingOrders()
        .some((o) => o.order_type === RisqOrderType.OrderType_CancelFoundation && o.target_id === key);
    for (const [key, f] of this.local_foundations.entries()) {
      const order = active.get(key);
      if (!order || (!is_cancelled(key) && player?.planned_foundations?.has(key))) {
        this.local_foundations.delete(key);
      } else {
        f.order = order;
      }
    }
    for (const [key, order] of active.entries()) {
      const has_active_server = !is_cancelled(key) && !!player?.planned_foundations?.has(key);
      if (!this.local_foundations.has(key) && !has_active_server && player) {
        this.registerLocalFoundation(player, key, order);
      }
    }
  }

  private recomputeIdleUnits() {
    const player = this.session.getPlayer();
    if (!player) {
      this.idle_units = [];
      return;
    }
    this.idle_units = [...player.units.values()]
      .filter((u) => this.orders_model.effectiveForSubject(u.internal_id, 'unit').length === 0)
      .sort((a, b) => a.internal_id - b.internal_id);
  }

  idleUnitCount(unit_type?: RisqUnitType): number {
    return unit_type === undefined
      ? this.idle_units.length
      : this.idle_units.filter((unit) => unit.unit_type === unit_type).length;
  }

  idleBuildingCount(): number {
    const player = this.session.getPlayer();
    if (!player) {
      return 0;
    }
    return [...player.buildings.values()].filter(
      (b) =>
        !b.under_construction &&
        b.produces.length > 0 &&
        this.orders_model.effectiveForSubject(b.internal_id, 'building').length === 0
    ).length;
  }

  /** Cycles through idle units in internal-id order, continuing after the last one returned */
  nextIdleUnit(): RisqUnit | undefined {
    if (!this.session.getGame() || this.idle_units.length === 0) {
      return undefined;
    }
    let idx = 0;
    if (this.last_idle_selected !== undefined) {
      const found = this.idle_units.findIndex((u) => u.internal_id > this.last_idle_selected!);
      idx = found === -1 ? 0 : found;
    }
    const unit = this.idle_units[idx];
    this.last_idle_selected = unit.internal_id;
    return unit;
  }

  pendingMercenaryOrders(): RisqFrontendOrder[] {
    return this.orders_model.all().filter((o) => o.order_type === RisqOrderType.OrderType_BuyMercenary);
  }

  pendingMercenaryCount(): number {
    return this.pendingMercenaryOrders().length;
  }

  mercenaryUnavailableReason(mercenary: RisqProducible): string | undefined {
    const player = this.session.getPlayer();
    if (!player || !this.session.canGiveOrders()) {
      return 'Cannot give orders now';
    }
    if (!canAffordCost(player, mercenary.cost)) {
      return 'Not enough resources';
    }
    if (player.units.size + this.pendingMercenaryCount() >= player.population_limit) {
      return 'Population capped';
    }
    return undefined;
  }

  hasNegativeResources(): boolean {
    const player = this.session.getPlayer();
    return !!player && [...player.resources.values()].some((pr) => pr.amount - pr.spending < 0);
  }

  /** Own units gathering at the target per the server, and the set gathering there once pending orders apply */
  gatherers(target: RisqBuilding | RisqResource): { current: number; predicted: Set<number> } {
    const zone_key = cantorPair(
      cantorPair(target.space_coordinate.x, target.space_coordinate.y),
      cantorPair(target.zone_coordinate.x, target.zone_coordinate.y)
    );
    const gathers = (orders: RisqFrontendOrder[]) =>
      orders.some((o) => o.order_type === RisqOrderType.OrderType_UnitGather && o.target_id === zone_key);
    let current = 0;
    const predicted = new Set<number>();
    for (const unit of this.session.getPlayer()?.units.values() ?? []) {
      current += gathers(unit.active_orders) ? 1 : 0;
      if (gathers(this.orders_model.effectiveForSubject(unit.internal_id, 'unit'))) {
        predicted.add(unit.internal_id);
      }
    }
    return { current, predicted };
  }

  /** Keeps already-assigned gatherers plus as many new ones as the target has room for */
  fitGatherCapacity(
    target: RisqBuilding | RisqResource | undefined,
    subjects: number[]
  ): { subjects: number[]; at_capacity: boolean } {
    if (!target || target.gather_capacity === undefined) {
      return { subjects, at_capacity: false };
    }
    const { predicted } = this.gatherers(target);
    const joining = subjects.filter((id) => !predicted.has(id));
    const free = Math.max(0, target.gather_capacity - predicted.size);
    return {
      subjects: [...subjects.filter((id) => predicted.has(id)), ...joining.slice(0, free)],
      at_capacity: joining.length > free,
    };
  }

  private updateResourceSpending() {
    const player = this.session.getPlayer();
    if (!player) {
      return;
    }
    for (const pr of player.resources.values()) {
      pr.spending = 0;
    }
    for (const order of this.orders_model.pendingOrders()) {
      let kind: RisqProducibleKind;
      if (order.order_type === RisqOrderType.OrderType_BuildingCreate) {
        kind = RisqProducibleKind.UNIT;
      } else if (order.order_type === RisqOrderType.OrderType_BuildingResearch) {
        kind = RisqProducibleKind.TECH;
      } else {
        continue;
      }
      for (const subject_id of order.subjects) {
        this.addSpending(
          player,
          player.buildings.get(subject_id)?.produces.find((p) => p.kind === kind && p.id === order.target_id)?.cost
        );
      }
    }
    const build_zones = new Set<number>();
    for (const order of this.orders_model.pendingOrders()) {
      if (order.order_type !== RisqOrderType.OrderType_UnitBuild) {
        continue;
      }
      const zone_key = invertPair(order.target_id).y;
      const is_cancelled = this.orders_model
        .pendingOrders()
        .some((o) => o.order_type === RisqOrderType.OrderType_CancelFoundation && o.target_id === zone_key);
      if (build_zones.has(zone_key) || (!is_cancelled && player.planned_foundations?.has(zone_key))) {
        continue;
      }
      build_zones.add(zone_key);
      const { building_id, space, zone } = invertBuildKey(order.target_id);
      const site = this.session
        .spaceAt(space)
        ?.zones?.flat()
        .find((z) => equalsPoint2D(z.coordinate, zone));
      if (site?.building) {
        continue;
      }
      this.addSpending(player, this.findProducible(player, building_id, order.subjects)?.cost);
    }
    for (const order of this.orders_model.pendingOrders()) {
      if (order.order_type === RisqOrderType.OrderType_BuyMercenary) {
        const unit_id = invertPair(order.target_id).x;
        this.addSpending(player, player.available_mercenaries.find((m) => m.id === unit_id)?.cost);
      } else if (order.order_type === RisqOrderType.OrderType_CancelOrder) {
        this.addSpending(player, this.paidProductionCost(player, order.target_id), -1);
      } else if (order.order_type === RisqOrderType.OrderType_CancelFoundation) {
        const foundation = player.planned_foundations?.get(order.target_id);
        const cost = foundation?.cost ?? this.findProducible(player, foundation?.building_id ?? 0, [])?.cost;
        this.addSpending(player, cost, -1);
      }
    }
    const renew_targets = new Set(
      this.orders_model
        .pendingOrders()
        .filter((o) => o.order_type === RisqOrderType.OrderType_UnitRenew)
        .map((o) => o.target_id)
    );
    for (const target_id of renew_targets) {
      this.addSpending(player, this.unpaidRenewalCost(target_id));
    }
  }

  /** Cost the server already charged for a production order still in a building's queue, refunded if it's cancelled */
  private paidProductionCost(player: RisqPlayer, order_internal_id: number): RisqCost | undefined {
    for (const building of player.buildings.values()) {
      const item = building.production_queue.find((i) => i.order_internal_id === order_internal_id);
      if (item) {
        return building.produces.find((p) => p.kind === item.kind && p.id === item.item_id)?.cost;
      }
    }
    return undefined;
  }

  private findProducible(player: RisqPlayer, building_id: number, subjects: number[]): RisqProducible | undefined {
    for (const subject_id of subjects) {
      const p = player.units.get(subject_id)?.builds.find((b) => b.id === building_id);
      if (p) {
        return p;
      }
    }
    for (const unit of player.units.values()) {
      const p = unit.builds.find((b) => b.id === building_id);
      if (p) {
        return p;
      }
    }
    return undefined;
  }

  private addSpending(player: RisqPlayer, cost: RisqCost | undefined, multiplier = 1) {
    if (!cost) {
      return;
    }
    player.resources.get(RisqResourceType.FOOD)!.spending += multiplier * cost.food;
    player.resources.get(RisqResourceType.WOOD)!.spending += multiplier * cost.wood;
    player.resources.get(RisqResourceType.STONE)!.spending += multiplier * cost.stone;
    player.resources.get(RisqResourceType.GOLD)!.spending += multiplier * cost.gold;
  }
}

import { DialogSize } from '../../../../../dialog_box/dialog_box';
import { createMessage } from '../../../../../lobby/data_models';
import type { RisqRightPanel } from '../../canvas_components/right_panel/right_panel';
import type { RisqSession } from '../session';
import type { RisqOrdersModel } from './orders_model';
import type { RisqOrderPlanning } from './planning';
import { RisqUnitType } from '../../model/types';

import '../../../../../dialog_box/confirm_dialog/confirm_dialog';

/** Submitting and unsubmitting this turn's pending orders, with one request in flight at a time */
export class RisqOrderSubmission {
  private get toggling(): boolean {
    return this.session.isToggling();
  }
  private set toggling(value: boolean) {
    this.session.setToggling(value);
  }
  private submitted_times = 0;

  constructor(
    private host: HTMLElement,
    private session: RisqSession,
    private orders_model: RisqOrdersModel,
    private planning: RisqOrderPlanning,
    private right_panel: RisqRightPanel
  ) {}

  submittedTimes(): number {
    return this.submitted_times;
  }

  turnStarted(): void {
    this.toggling = false;
    if (this.session.getPlayerId() > -1) {
      this.submitted_times = 0;
    }
  }

  submitted() {
    this.toggling = false;
    this.orders_model.clearPending();
  }

  unsubmitted() {
    this.toggling = false;
    this.orders_model.revertSubmittedToPending();
  }

  /** Submits directly, or first confirms when units/buildings are idle or resources would go negative */
  confirmSubmit() {
    if (!this.session.canGiveOrders()) {
      return;
    }
    const n_villagers = this.planning.idleUnitCount(RisqUnitType.ECONOMIC);
    const n_military = this.planning.idleUnitCount() - n_villagers;
    const n_buildings = this.planning.idleBuildingCount();
    const n = n_villagers + n_military + n_buildings;
    const over_budget = this.planning.hasNegativeResources();
    if (n === 0 && !over_budget) {
      this.toggle();
      return;
    }
    const warnings: string[] = [];
    if (n > 0) {
      const idle_counts = [
        `${n_villagers} idle villager${n_villagers === 1 ? '' : 's'}`,
        `${n_military} idle military unit${n_military === 1 ? '' : 's'}`,
        `${n_buildings} idle building${n_buildings === 1 ? '' : 's'}`,
      ];
      warnings.push(`You have ${idle_counts.join(', ')}.`);
    }
    if (over_budget) {
      warnings.push('One or more resources will go negative.');
    }
    const dialog = document.createElement('dwg-confirm-dialog');
    dialog.setData({
      question: `Are you sure you want to submit orders? ${warnings.join(' ')}`,
      size: DialogSize.SMALL,
    });
    dialog.addEventListener('confirmed', () => this.toggle());
    this.host.appendChild(dialog);
  }

  toggle(): void {
    const player = this.session.getPlayer();
    if (this.toggling || !this.session.givingOrders() || !player) {
      return;
    }
    this.toggling = true;
    const sender = `player-${this.session.getPlayerId()}`;
    if (player.orders_submitted) {
      this.right_panel.unsubmittingOrders();
      this.dispatch(createMessage(sender, 'game-update', '', 'unsubmit-orders'));
    } else {
      this.right_panel.submittingOrders();
      const content = JSON.stringify({ orders: this.orders_model.pendingOrders() });
      this.dispatch(createMessage(sender, 'game-update', content, 'submit-orders'));
      this.submitted_times++;
    }
  }

  private dispatch(game_update: string) {
    this.host.dispatchEvent(new CustomEvent('game_update', { detail: game_update, bubbles: true }));
  }
}

import { canvasToScreen } from '../../../../util/canvas_board/canvas_board';
import type { Point2D } from '../../../../util/objects2d';
import { pointInRect } from '../../../../util/objects2d';
import type { RisqLeftPanel } from '../../canvas_components/left_panel/left_panel';
import { LeftPanelDataType } from '../../canvas_components/left_panel/left_panel_data';
import type { RisqSpace, RisqZone, UnitByTypeData } from '../../model/types';
import type { RisqViewport } from '../../rendering/board/viewport';
import { RisqViewMode } from '../../rendering/terrain';
import { UNIT_SLOT_CIRCLE_RADIUS_MULTIPLIER } from '../../rendering/zones/geometry';
import { unitVisibleInViewMode } from '../../rendering/zones/draw';
import { visibleZoneUnitSlot } from '../../rendering/zones/hit_testing';
import type { RisqOrderPlanning } from '../orders/planning';
import type { RisqSession } from '../session';
import type { RisqSelection } from './selection';

function groupByPlayer(groups: Iterable<UnitByTypeData>): Map<number, UnitByTypeData[]> {
  const units_by_player = new Map<number, UnitByTypeData[]>();
  for (const g of groups) {
    if (!units_by_player.has(g.player_id)) {
      units_by_player.set(g.player_id, []);
    }
    units_by_player.get(g.player_id)!.push(g);
  }
  return units_by_player;
}

/** Selection changes from clicking or drag-selecting on the board itself (the left panel has its own gestures) */
export class RisqBoardClicks {
  constructor(
    private session: RisqSession,
    private viewport: RisqViewport,
    private selection: RisqSelection,
    private left_panel: RisqLeftPanel,
    private planning: RisqOrderPlanning
  ) {}

  /** A released click on the zone: acts on whichever pressed part is still hovered, else opens the zone itself */
  zoneClick(space: RisqSpace, zone: RisqZone, e: MouseEvent) {
    for (const [i, part] of zone.hovered_data.entries()) {
      if (!part.clicked || !part.hovered) {
        continue;
      }
      if (i > 0 && visibleZoneUnitSlot(zone, i - 1, this.viewport.viewMode()).length === 0) {
        continue;
      }
      if (i === 0) {
        this.buildingSlotClick(space, zone);
      } else if (e.detail >= 2) {
        this.unitSlotMultiClick(space, zone, i - 1, e.detail >= 3);
      } else if (e.ctrlKey) {
        this.toggleUnitSlot(space, visibleZoneUnitSlot(zone, i - 1, this.viewport.viewMode()));
      } else {
        this.unitSlotClick(space, visibleZoneUnitSlot(zone, i - 1, this.viewport.viewMode()));
      }
      return;
    }
    if (zone.clicked) {
      this.left_panel.openPanel({ data_type: LeftPanelDataType.ZONE, data: { space, zone } }, space.visibility);
    }
  }

  /** Toggles the resource/building/foundation in the zone's building slot */
  private buildingSlotClick(space: RisqSpace, zone: RisqZone) {
    const target_id = zone.resource?.internal_id ?? zone.building?.internal_id;
    const current = this.selection.current();
    if (
      target_id !== undefined &&
      current &&
      (current.kind === 'building' || current.kind === 'resource') &&
      current.id === target_id
    ) {
      this.left_panel.close();
    } else if (!!zone.resource) {
      this.left_panel.openPanel({ data_type: LeftPanelDataType.RESOURCE, data: zone.resource }, space.visibility);
    } else if (!!zone.building) {
      this.left_panel.openPanel({ data_type: LeftPanelDataType.BUILDING, data: zone.building }, space.visibility);
    } else {
      this.foundationClick(space, zone);
    }
  }

  private foundationClick(space: RisqSpace, zone: RisqZone) {
    const local_foundation = this.planning.getLocalFoundation(zone.coordinate_key);
    const foundation = local_foundation ?? this.session.getPlayer()?.planned_foundations?.get(zone.coordinate_key);
    if (!foundation) {
      return;
    }
    const current = this.selection.current();
    if (current && current.kind === 'foundation' && current.id === zone.coordinate_key) {
      this.left_panel.close();
      return;
    }
    this.left_panel.openPanel(
      {
        data_type: LeftPanelDataType.FOUNDATION,
        data: {
          coordinate_key: zone.coordinate_key,
          building_id: foundation.building_id,
          player_id: this.session.getPlayerId(),
          is_local: !!local_foundation,
          display_name: `Planned ${foundation.display_name}`,
          zone,
        },
      },
      space.visibility
    );
  }

  /** Double click selects the slot's lead unit type within the zone; triple click, across the screen */
  private unitSlotMultiClick(space: RisqSpace, zone: RisqZone, slot_index: number, on_screen: boolean) {
    const target = visibleZoneUnitSlot(zone, slot_index, this.viewport.viewMode())[0];
    if (!target) {
      return;
    }
    const ids = on_screen
      ? this.unitsOnScreenOfType(target.player_id, target.unit_id)
      : [...zone.units.values()]
          .filter((u) => u.player_id === target.player_id && u.unit_id === target.unit_id)
          .map((u) => u.internal_id);
    this.selection.selectUnitsOfPlayer(target.player_id, ids, on_screen ? undefined : space, space.visibility);
  }

  /** Ctrl-click adds the whole slot to the selection, or removes it if every unit in it is already selected */
  private toggleUnitSlot(space: RisqSpace, slot_groups: UnitByTypeData[]) {
    const slot_unit_ids = slot_groups.flatMap((t) => [...t.units]);
    const selected = this.selection.selectedUnitIds();
    const deselect = slot_unit_ids.length > 0 && slot_unit_ids.every((id) => selected.has(id));
    const groups = new Map<string, UnitByTypeData>();
    for (const g of this.selection.unitTypeGroups()) {
      groups.set(`${g.player_id}:${g.unit_id}`, { ...g, units: new Set(g.units) });
    }
    for (const g of slot_groups) {
      const key = `${g.player_id}:${g.unit_id}`;
      const target = groups.get(key) ?? { ...g, units: new Set<number>() };
      for (const id of g.units) {
        if (deselect) {
          target.units.delete(id);
        } else {
          target.units.add(id);
        }
      }
      if (target.units.size > 0) {
        groups.set(key, target);
      } else {
        groups.delete(key);
      }
    }
    this.left_panel.openPanel(
      { data_type: LeftPanelDataType.UNITS, data: { space, units_by_player: groupByPlayer(groups.values()) } },
      space.visibility
    );
  }

  /** Selects the slot's units, or deselects when the slot is exactly the one already-selected unit */
  private unitSlotClick(space: RisqSpace, slot_groups: UnitByTypeData[]) {
    const slot_unit_ids = slot_groups.flatMap((t) => [...t.units]);
    const current = this.selection.current();
    if (slot_unit_ids.length === 1 && current?.kind === 'unit' && current.id === slot_unit_ids[0]) {
      this.left_panel.close();
      return;
    }
    this.left_panel.openPanel(
      { data_type: LeftPanelDataType.UNITS, data: { space, units_by_player: groupByPlayer(slot_groups) } },
      space.visibility
    );
  }

  /** A released click on a space when zones aren't interactive: opens its region if regions are, else the space */
  spaceClick(space: RisqSpace) {
    if (!space.clicked || space.visibility <= 0) {
      return;
    }
    if (this.viewport.zoneView() && this.viewport.viewMode() !== RisqViewMode.REGION) {
      return;
    }
    const region = this.viewport.regionInteractionEnabled()
      ? this.session.getRegionForSpace(space.coordinate_key)
      : undefined;
    if (region) {
      this.left_panel.openPanel({ data_type: LeftPanelDataType.REGION, data: region }, space.visibility);
    } else {
      this.left_panel.openPanel({ data_type: LeftPanelDataType.SPACE, data: space }, space.visibility);
    }
  }

  /** Selects own ungarrisoned units whose on-screen anchor lies in the dragged rectangle */
  dragSelect(start: Point2D, end: Point2D, additive: boolean) {
    const player = this.session.getPlayer();
    if (!player) {
      return;
    }
    const zone_view = this.viewport.zoneView();
    const found_ids: number[] = [];
    for (const unit of player.units.values()) {
      if (unit.garrisoned_in !== undefined || !unitVisibleInViewMode(unit.unit_type, this.viewport.viewMode())) {
        continue;
      }
      const anchor = canvasToScreen(
        this.viewport.orderPoint(unit.space_coordinate, this.viewport.unitAnchorOffset(unit), zone_view),
        this.viewport.lastTransform()
      );
      if (pointInRect(anchor, start, end)) {
        found_ids.push(unit.internal_id);
      }
    }
    if (found_ids.length === 0) {
      if (!additive) {
        this.left_panel.close();
      }
      return;
    }
    const selected_ids = additive ? new Set([...this.selection.selectedUnitIds(), ...found_ids]) : new Set(found_ids);
    this.selection.selectOwnUnits([...selected_ids]);
  }

  // space-level bounding-box check first (cheap pre-filter), then whether the unit's own rendered circle overlaps the viewport
  private unitsOnScreenOfType(player_id: number, unit_id: number): number[] {
    const ids: number[] = [];
    const bounds = this.viewport.visibleCanvasBounds();
    const radius = UNIT_SLOT_CIRCLE_RADIUS_MULTIPLIER * this.viewport.hexR();
    for (const row of this.session.getGame()?.spaces ?? []) {
      for (const space of row) {
        if (!space || !this.viewport.isSpaceOnScreen(space, bounds)) {
          continue;
        }
        for (const zone of space.zones?.flat() ?? []) {
          for (const unit of zone.units.values()) {
            if (unit.player_id !== player_id || unit.unit_id !== unit_id) {
              continue;
            }
            const canvas_pos = this.viewport.orderPoint(
              unit.space_coordinate,
              this.viewport.unitAnchorOffset(unit),
              true
            );
            if (this.viewport.isCircleOnScreen(canvas_pos, radius, bounds)) {
              ids.push(unit.internal_id);
            }
          }
        }
      }
    }
    return ids;
  }
}

import type { RisqLeftPanel } from '../../canvas_components/left_panel/left_panel';
import type { Point2D } from '../../../../util/objects2d';
import { LeftPanelDataType } from '../../canvas_components/left_panel/left_panel_data';
import type { RisqSession } from '../session';
import type { RisqSelection } from './selection';

interface ControlGroup {
  kind: 'unit' | 'building';
  ids: number[];
}

/** Control groups 1-10 ('0' is group 10), pruned of dead members when recalled */
export class RisqControlGroups {
  private groups = new Map<number, ControlGroup>();

  constructor(
    private session: RisqSession,
    private left_panel: RisqLeftPanel,
    private selection: RisqSelection
  ) {}

  assign(group: number) {
    if (!this.left_panel.isOrderable()) {
      return;
    }
    const data = this.left_panel.getData();
    switch (data?.data_type) {
      case LeftPanelDataType.UNIT:
        this.groups.set(group, { kind: 'unit', ids: [data.data.internal_id] });
        break;
      case LeftPanelDataType.BUILDING:
        this.groups.set(group, { kind: 'building', ids: [data.data.internal_id] });
        break;
      case LeftPanelDataType.UNITS_BY_TYPE:
      case LeftPanelDataType.ECONOMIC_UNITS:
      case LeftPanelDataType.MILITARY_UNITS:
        this.groups.set(group, { kind: 'unit', ids: data.data.units.flatMap((u) => [...u.units]) });
        break;
      default:
        break;
    }
  }

  recall(group: number): Point2D | undefined {
    const group_data = this.groups.get(group);
    const player = this.session.getPlayer();
    if (!group_data || !player) {
      return;
    }
    if (group_data.kind === 'building') {
      const building = player.buildings.get(group_data.ids[0]);
      if (!building) {
        this.groups.delete(group);
        return;
      }
      this.selection.selectBuilding(building);
      return building.space_coordinate;
    }
    const alive_ids = group_data.ids.filter((id) => player.units.has(id));
    if (alive_ids.length === 0) {
      this.groups.delete(group);
      return;
    }
    group_data.ids = alive_ids;
    this.selection.selectOwnUnits(alive_ids);
    const coordinates = alive_ids.flatMap((id) => {
      const location = this.session.unitLocation(player.units.get(id)!);
      return location ? [location.space_coordinate] : [];
    });
    if (coordinates.length === 0) {
      return;
    }
    return {
      x: coordinates.reduce((sum, coordinate) => sum + coordinate.x, 0) / coordinates.length,
      y: coordinates.reduce((sum, coordinate) => sum + coordinate.y, 0) / coordinates.length,
    };
  }
}

import type { RisqLeftPanel } from '../../canvas_components/left_panel/left_panel';
import type { Point2D } from '../../../../util/objects2d';
import { invertPair, invertZoneKey } from '../../model/coordinates';
import { LeftPanelDataType } from '../../canvas_components/left_panel/left_panel_data';
import type {
  RisqBuilding,
  RisqFrontendOrder,
  RisqRegion,
  RisqSpace,
  RisqUnit,
  UnitByTypeData,
} from '../../model/types';
import { RisqProducibleKind, RisqVisibilityLevel } from '../../model/types';
import { groupUnitsByType } from '../../model/unit_groups';
import type { HotkeySelection } from '../input/hotkeys';
import { isBuildingOrder, isUnitOrder } from '../orders/orders_model';
import type { RisqSession } from '../session';

export type SingleSelectionKind = 'unit' | 'building' | 'resource' | 'foundation';

/** Neutral queries and changes over the current selection, which the left panel's data currently stores */
export class RisqSelection {
  constructor(
    private session: RisqSession,
    private left_panel: RisqLeftPanel
  ) {}

  selectedUnitIds(): Set<number> {
    const data = this.left_panel.getData();
    switch (data?.data_type) {
      case LeftPanelDataType.UNIT:
        return new Set([data.data.internal_id]);
      case LeftPanelDataType.UNITS_BY_TYPE:
      case LeftPanelDataType.ECONOMIC_UNITS:
      case LeftPanelDataType.MILITARY_UNITS:
        return new Set(data.data.units.flatMap((u) => [...u.units]));
      case LeftPanelDataType.MULTIPLE_PLAYERS_UNITS:
        return new Set(data.data.units_by_player.flatMap(([, units]) => units.flatMap((u) => [...u.units])));
      default:
        return new Set();
    }
  }

  /** Selected unit ids when the selection is a single player's units, as hotkeys and commands act on */
  subjectUnitIds(): number[] {
    const data = this.left_panel.getData();
    switch (data?.data_type) {
      case LeftPanelDataType.UNIT:
        return [data.data.internal_id];
      case LeftPanelDataType.UNITS_BY_TYPE:
      case LeftPanelDataType.ECONOMIC_UNITS:
      case LeftPanelDataType.MILITARY_UNITS:
        return data.data.units.flatMap((u) => [...u.units]);
      default:
        return [];
    }
  }

  selectedBuilding(): RisqBuilding | undefined {
    const data = this.left_panel.getData();
    return data?.data_type === LeftPanelDataType.BUILDING ? data.data : undefined;
  }

  coordinate(): Point2D | undefined {
    const data = this.left_panel.getData();
    if (!data) {
      return;
    }
    if (data.data_type === LeftPanelDataType.UNIT) {
      return this.session.unitLocation(data.data)?.space_coordinate;
    }
    if ('space_coordinate' in data.data) {
      return data.data.space_coordinate;
    }
    if (data.data_type === LeftPanelDataType.SPACE) {
      return data.data.coordinate;
    }
    if (data.data_type === LeftPanelDataType.FOUNDATION) {
      return invertZoneKey(data.data.coordinate_key).space;
    }
    if ('space' in data.data && data.data.space) {
      return data.data.space.coordinate;
    }
    const coordinates =
      data.data_type === LeftPanelDataType.REGION
        ? data.data.spaces.map(invertPair)
        : [...this.selectedUnitIds()].flatMap((id) => {
            const unit = this.session.findUnitById(id);
            const location = unit ? this.session.unitLocation(unit) : undefined;
            return location ? [location.space_coordinate] : [];
          });
    if (coordinates.length === 0) {
      return;
    }
    return {
      x: coordinates.reduce((sum, coordinate) => sum + coordinate.x, 0) / coordinates.length,
      y: coordinates.reduce((sum, coordinate) => sum + coordinate.y, 0) / coordinates.length,
    };
  }

  current(): { kind: SingleSelectionKind; id: number } | undefined {
    const data = this.left_panel.getData();
    switch (data?.data_type) {
      case LeftPanelDataType.UNIT:
        return { kind: 'unit', id: data.data.internal_id };
      case LeftPanelDataType.BUILDING:
        return { kind: 'building', id: data.data.internal_id };
      case LeftPanelDataType.RESOURCE:
        return { kind: 'resource', id: data.data.internal_id };
      case LeftPanelDataType.FOUNDATION:
        return { kind: 'foundation', id: data.data.coordinate_key };
      case LeftPanelDataType.UNITS_BY_TYPE:
      case LeftPanelDataType.ECONOMIC_UNITS:
      case LeftPanelDataType.MILITARY_UNITS: {
        const ids = this.selectedUnitIds();
        return ids.size === 1 ? { kind: 'unit', id: [...ids][0] } : undefined;
      }
      default:
        return undefined;
    }
  }

  unitTypeGroups(): UnitByTypeData[] {
    const data = this.left_panel.getData();
    switch (data?.data_type) {
      case LeftPanelDataType.UNIT:
        return [
          {
            player_id: data.data.player_id,
            unit_id: data.data.unit_id,
            unit_type: data.data.unit_type,
            units: new Set([data.data.internal_id]),
          },
        ];
      case LeftPanelDataType.UNITS_BY_TYPE:
      case LeftPanelDataType.ECONOMIC_UNITS:
      case LeftPanelDataType.MILITARY_UNITS:
        return data.data.units;
      case LeftPanelDataType.MULTIPLE_PLAYERS_UNITS:
        return data.data.units_by_player.flatMap(([, units]) => units);
      default:
        return [];
    }
  }

  isUnitSelected(internal_id: number): boolean {
    return this.selectedUnitIds().has(internal_id);
  }

  isBuildingSelected(internal_id: number): boolean {
    return this.selectedBuilding()?.internal_id === internal_id;
  }

  isOrderSubjectSelected(order: RisqFrontendOrder): boolean {
    if (isUnitOrder(order.order_type)) {
      return order.subjects.some((id) => this.selectedUnitIds().has(id));
    }
    const building = this.selectedBuilding();
    return isBuildingOrder(order.order_type) && building !== undefined && order.subjects.includes(building.internal_id);
  }

  isResourceSelected(internal_id: number): boolean {
    const data = this.left_panel.getData();
    return data?.data_type === LeftPanelDataType.RESOURCE && data.data.internal_id === internal_id;
  }

  isRegionSelected(region: RisqRegion): boolean {
    const data = this.left_panel.getData();
    return data?.data_type === LeftPanelDataType.REGION && data.data.name === region.name;
  }

  /** The selection's shape as hotkey scoping sees it, or undefined when nothing hotkey-relevant is selected */
  hotkeySelection(): HotkeySelection | undefined {
    const building = this.selectedBuilding();
    if (building) {
      const ids = (kind: RisqProducibleKind) => building.produces.filter((p) => p.kind === kind).map((p) => p.id);
      return { kind: 'building', unit_ids: ids(RisqProducibleKind.UNIT), tech_ids: ids(RisqProducibleKind.TECH) };
    }
    if (this.subjectUnitIds().length === 0) {
      return undefined;
    }
    const lp = this.left_panel;
    const composition = lp.isOnlyVillagers() ? 'villagers' : lp.isOnlyMilitary() ? 'military' : 'mixed';
    return { kind: 'units', composition, garrisoned: lp.isOnlyGarrisoned() };
  }

  selectBuilding(building: RisqBuilding) {
    this.left_panel.openPanel({ data_type: LeftPanelDataType.BUILDING, data: building }, RisqVisibilityLevel.SPY);
  }

  selectUnit(unit: RisqUnit) {
    this.left_panel.openPanel({ data_type: LeftPanelDataType.UNIT, data: unit }, RisqVisibilityLevel.SPY);
  }

  /** Selects the given units of the local player, grouped by type, regardless of where they are */
  selectOwnUnits(internal_ids: number[]) {
    const player = this.session.getPlayer();
    if (!player) {
      return;
    }
    this.left_panel.openPanel(
      { data_type: LeftPanelDataType.UNITS_BY_TYPE, data: { units: groupUnitsByType(player.units, internal_ids) } },
      RisqVisibilityLevel.SPY
    );
  }

  /** Selects one player's units of the given ids, optionally tied to the space they were picked from */
  selectUnitsOfPlayer(player_id: number, internal_ids: number[], space: RisqSpace | undefined, visibility: number) {
    if (internal_ids.length === 0) {
      return;
    }
    const units_map =
      this.session.getGame()?.players.find((p) => p.player.player_id === player_id)?.units ??
      new Map<number, RisqUnit>();
    const units = groupUnitsByType(units_map, internal_ids);
    this.left_panel.openPanel({ data_type: LeftPanelDataType.UNITS_BY_TYPE, data: { space, units } }, visibility);
  }

  selectOrderSubjects(order: RisqFrontendOrder) {
    const player = this.session.getPlayer();
    if (!player || !this.session.getGame()) {
      return;
    }
    if (isBuildingOrder(order.order_type)) {
      const building = player.buildings.get(order.subjects[0]);
      if (building) {
        this.selectBuilding(building);
      }
      return;
    }
    if (!isUnitOrder(order.order_type)) {
      return;
    }
    const units_by_type = groupUnitsByType(player.units, order.subjects);
    const first = order.subjects.map((id) => player.units.get(id)).find((u) => !!u);
    const location = first ? this.session.unitLocation(first) : undefined;
    if (units_by_type.length === 0 || !location) {
      return;
    }
    const space = this.session.spaceAt(location.space_coordinate);
    if (!space) {
      return;
    }
    this.left_panel.openPanel(
      {
        data_type: LeftPanelDataType.UNITS,
        data: { space, units_by_player: new Map([[player.player.player_id, units_by_type]]) },
      },
      RisqVisibilityLevel.SPY
    );
  }

  /** Selects the next completed building of this type after the currently selected one, returning it */
  cycleBuildingOfType(building_id: number): RisqBuilding | undefined {
    const player = this.session.getPlayer();
    if (!player) {
      return undefined;
    }
    const buildings = [...player.buildings.values()]
      .filter((b) => b.building_id === building_id && !b.under_construction)
      .sort((a, b) => a.internal_id - b.internal_id);
    if (buildings.length === 0) {
      return undefined;
    }
    const current_index = buildings.findIndex((b) => b.internal_id === this.selectedBuilding()?.internal_id);
    const next = buildings[(current_index + 1) % buildings.length];
    this.selectBuilding(next);
    return next;
  }
}

import type { Point2D } from '../../../util/objects2d';
import { hexagonalBoardNeighbors, hexagonalBoardRows } from '../../../util/objects2d';
import { coordinateToIndex, getSpace } from '../model/coordinates';
import type {
  GameRisq,
  RisqBuilding,
  RisqPlayer,
  RisqRegion,
  RisqResourceConfig,
  RisqSpace,
  RisqUnit,
} from '../model/types';
import type { GameRisqFromServer } from '../transport/snapshot_types';
import { serverToGameRisq } from '../transport/snapshot_conversion';
import type { RisqTurnReport } from '../transport/turn_report';

/** Maps each explored space's coordinate key to the region it belongs to */
function buildRegionLookup(regions: RisqRegion[]): Map<number, RisqRegion> {
  const lookup = new Map<number, RisqRegion>();
  for (const region of regions) {
    for (const key of region.spaces) {
      lookup.set(key, region);
    }
  }
  return lookup;
}

/** Owns the current game snapshot and the local player's identity within it */
export class RisqSession {
  private game?: GameRisq;
  private region_by_space = new Map<number, RisqRegion>();
  private player_id = -1;
  private last_turn_report?: RisqTurnReport;
  private resource_configs = new Map<number, RisqResourceConfig>();
  private toggling = false;

  isToggling(): boolean {
    return this.toggling;
  }

  setToggling(toggling: boolean): void {
    this.toggling = toggling;
  }

  setResourceConfigs(configs: RisqResourceConfig[]): void {
    this.resource_configs = new Map(configs.map((config) => [config.resource_id, config]));
  }

  getResourceConfigs(): ReadonlyMap<number, RisqResourceConfig> {
    return this.resource_configs;
  }

  setPlayerId(player_id: number) {
    this.player_id = player_id;
  }

  getPlayerId(): number {
    return this.player_id;
  }

  getGame(): GameRisq | undefined {
    return this.game;
  }

  getPlayer(): RisqPlayer | undefined {
    if (!this.game) {
      return undefined;
    }
    return this.player_id > -1 ? this.game.players[this.player_id] : undefined;
  }

  replaceSnapshot(new_game: GameRisqFromServer) {
    this.game = serverToGameRisq(new_game);
    this.region_by_space = buildRegionLookup(this.game?.regions ?? []);
  }

  getLastTurnReport(): RisqTurnReport | undefined {
    return this.last_turn_report;
  }

  setLastTurnReport(report: RisqTurnReport | undefined) {
    this.last_turn_report = report;
  }

  givingOrders(): boolean {
    return !!this.game?.giving_orders && !this.game.game_base.game_ended && !this.getPlayer()?.eliminated;
  }

  canGiveOrders(): boolean {
    const player = this.getPlayer();
    const game = this.getGame();
    if (!player || !game) {
      return false;
    }
    if (this.toggling || player.orders_submitted) {
      return false;
    }
    if (!this.givingOrders()) {
      return false;
    }
    return true;
  }

  getRegionForSpace(coordinate_key: number): RisqRegion | undefined {
    return this.region_by_space.get(coordinate_key);
  }

  getRegionLookup(): Map<number, RisqRegion> {
    return this.region_by_space;
  }

  findBuildingById(internal_id: number): RisqBuilding | undefined {
    for (const player of this.game?.players ?? []) {
      const building = player.buildings.get(internal_id);
      if (building) {
        return building;
      }
    }
    return undefined;
  }

  findUnitById(internal_id: number): RisqUnit | undefined {
    for (const player of this.game?.players ?? []) {
      const unit = player.units.get(internal_id);
      if (unit) {
        return unit;
      }
    }
    return undefined;
  }

  /** A garrisoned unit has no coordinates of its own, so it's located at its building */
  unitLocation(unit: RisqUnit): { space_coordinate: Point2D; zone_coordinate: Point2D } | undefined {
    return unit.garrisoned_in === undefined ? unit : this.findBuildingById(unit.garrisoned_in);
  }

  spaceAt(coordinate: Point2D): RisqSpace | undefined {
    if (!this.game) {
      return undefined;
    }
    return getSpace(this.game, coordinateToIndex(this.game.board_size, coordinate));
  }

  boardNeighbors(space: RisqSpace): RisqSpace[] {
    if (!this.game) {
      return [];
    }
    return hexagonalBoardNeighbors(space.coordinate, this.game.board_size)
      .map((c) => this.spaceAt(c))
      .filter((s): s is RisqSpace => !!s);
  }

  boardRows(space: RisqSpace): RisqSpace[] {
    if (!this.game) {
      return [];
    }
    return hexagonalBoardRows(space.coordinate, this.game.board_size)
      .map((c) => this.spaceAt(c))
      .filter((s): s is RisqSpace => !!s);
  }
}

import type { BoardTransformData } from '../../../../util/canvas_board/canvas_board';
import { screenToCanvas } from '../../../../util/canvas_board/canvas_board';
import type { CanvasComponent } from '../../../../util/canvas_components/canvas_component';
import { configDraw } from '../../../../util/canvas_components/canvas_component';
import type { RectScrollbarConfig } from '../../../../util/canvas_components/scrollbar/rect_scrollbar';
import { DwgRectScrollbar } from '../../../../util/canvas_components/scrollbar/rect_scrollbar';
import { drawLine, drawRect } from '../../../../util/canvas_util';
import type { Point2D } from '../../../../util/objects2d';
import type { DwgRisq } from '../../risq';

/** A bottom-panel item must be independently positionable so the panel can lay it out in a column */
export declare interface BottomPanelItem extends CanvasComponent {
  setPosition(p: Point2D): void;
  dataRefreshed?(): void;
  drawTooltip?(ctx: CanvasRenderingContext2D, transform: BoardTransformData, risq: DwgRisq, dt: number): void;
}

/** A group of items stacked in a column; groups are laid out left-to-right with a separator between them */
export type BottomPanelGroup = BottomPanelItem[];

export declare interface BottomPanelConfig {
  background: string;
  left_panel_w: number;
  right_panel_w: number;
}

class RisqBottomPanelScrollbar extends DwgRectScrollbar {
  scrollCallback(_value: number): void {}
}

/** Centered, content-sized bottom bar that stays clear of the left/right panels, scrolling horizontally on overflow */
export class RisqBottomPanel implements CanvasComponent {
  private static PADDING = 8;
  private static GAP = 8;
  private static BOTTOM_MARGIN = 12;
  private static SCROLLBAR_SIZE = 8;

  private risq: DwgRisq;
  private config: BottomPanelConfig;
  private groups: BottomPanelGroup[];
  private items: BottomPanelItem[];
  private group_widths: number[] = [];
  private separator_xs: number[] = [];
  private scrollbar: RisqBottomPanelScrollbar;
  private hovering = false;
  private mouse_screen: Point2D = { x: -1, y: -1 };
  private p: Point2D = { x: 0, y: 0 };
  private panel_w = 0;
  private panel_h = 0;
  private content_w = 0;
  private content_h = 0;
  private overflowing = false;

  constructor(risq: DwgRisq, config: BottomPanelConfig, groups: BottomPanelGroup[]) {
    this.risq = risq;
    this.config = config;
    this.groups = groups;
    this.items = groups.flat();
    this.scrollbar = new RisqBottomPanelScrollbar({
      scrollbar_config: { value: { value: 0, value_min: 0, value_max: 0 }, step_size: 30, scroll_pixel_constant: 1 },
      p: { x: 0, y: 0 },
      w: 0,
      h: 0,
      scrollbar_size: RisqBottomPanel.SCROLLBAR_SIZE,
      min_bar_size: 1.5 * RisqBottomPanel.SCROLLBAR_SIZE,
      bar_dif_size: 1,
      vertical: false,
      draw_config: {
        fill_style: 'rgba(255, 255, 255, 0.4)',
        stroke_width: 0,
        hover_fill_style: 'rgba(255, 255, 255, 0.6)',
        click_fill_style: 'rgba(255, 255, 255, 0.8)',
        fixed_position: true,
      },
      space_draw_config: {
        fill_style: 'rgba(0, 0, 0, 0.15)',
        stroke_width: 0,
        hover_fill_style: 'rgba(0, 0, 0, 0.25)',
        click_fill_style: 'rgba(0, 0, 0, 0.35)',
        fixed_position: true,
        stroke_matches_fill_style: true,
      },
      background_color: 'rgba(0, 0, 0, 0.1)',
      arrow_scroll_amount: 30,
      space_scroll_amount: 100,
    } satisfies RectScrollbarConfig);
  }

  isHovering(): boolean {
    return this.hovering;
  }
  setHovering(hovering: boolean): void {
    this.hovering = hovering;
  }
  isClicking(): boolean {
    return this.scrollbar.isClicking();
  }
  setClicking(clicking: boolean): void {
    this.scrollbar.setClicking(clicking);
    if (!clicking) {
      this.scrollbar.setHovering(false);
      for (const item of this.items) {
        item.setClicking(false);
        item.setHovering(false);
      }
    }
  }

  private groupHeight(group: BottomPanelGroup): number {
    return group.reduce((sum, item) => sum + item.h(), 0) + RisqBottomPanel.GAP * Math.max(group.length - 1, 0);
  }

  private recomputeLayout() {
    const groups = this.groups.filter((group) => group.some((item) => item.w() > 0));
    this.group_widths = groups.map((group) => Math.max(0, ...group.map((item) => item.w())));
    this.content_h = Math.max(0, ...groups.map((group) => this.groupHeight(group)));
    this.content_w =
      this.group_widths.reduce((sum, w) => sum + w, 0) + RisqBottomPanel.GAP * Math.max(groups.length - 1, 0);
    const canvas_w = this.risq.viewport.canvasSize().width;
    const max_side_panel_w = Math.max(this.config.left_panel_w, this.config.right_panel_w);
    const available_w = Math.max(canvas_w - 2 * (max_side_panel_w + RisqBottomPanel.PADDING), 0);
    this.overflowing = this.content_w + 2 * RisqBottomPanel.PADDING > available_w;
    this.panel_w = Math.min(this.content_w + 2 * RisqBottomPanel.PADDING, available_w);
    this.panel_h =
      this.content_h +
      2 * RisqBottomPanel.PADDING +
      (this.overflowing ? RisqBottomPanel.SCROLLBAR_SIZE + RisqBottomPanel.PADDING : 0);
    this.p = {
      x: 0.5 * (canvas_w - this.panel_w),
      y: this.risq.viewport.canvasSize().height - this.panel_h - RisqBottomPanel.BOTTOM_MARGIN,
    };
    const max_scroll = this.overflowing ? this.content_w - (this.panel_w - 2 * RisqBottomPanel.PADDING) : 0;
    this.scrollbar.setValue({
      value: Math.min(this.scrollbar.value(), max_scroll),
      value_min: 0,
      value_max: max_scroll,
    });
    if (this.overflowing) {
      this.scrollbar.setAllSizes(
        RisqBottomPanel.SCROLLBAR_SIZE,
        {
          x: this.xi() + RisqBottomPanel.PADDING,
          y: this.yi(),
        },
        this.panel_w - 2 * RisqBottomPanel.PADDING,
        this.panel_h - RisqBottomPanel.PADDING
      );
    }
    this.separator_xs = [];
    let x = this.xi() + RisqBottomPanel.PADDING - this.scrollbar.value();
    for (const [i, group] of groups.entries()) {
      const group_w = this.group_widths[i];
      const group_h = this.groupHeight(group);
      let y = this.yi() + RisqBottomPanel.PADDING + 0.5 * (this.content_h - group_h);
      for (const item of group) {
        item.setPosition({ x: x + 0.5 * (group_w - item.w()), y });
        y += item.h() + RisqBottomPanel.GAP;
      }
      x += group_w + RisqBottomPanel.GAP;
      if (i < groups.length - 1) {
        this.separator_xs.push(x - 0.5 * RisqBottomPanel.GAP);
      }
    }
  }

  draw(ctx: CanvasRenderingContext2D, transform: BoardTransformData, dt: number): void {
    for (const item of this.items) {
      item.dataRefreshed?.();
    }
    this.recomputeLayout();
    if (this.panel_w <= 0 || this.panel_h <= 0) {
      return;
    }
    configDraw(
      ctx,
      transform,
      {
        fill_style: this.config.background,
        stroke_style: 'rgba(255, 255, 255, 0.2)',
        stroke_width: 1,
        fixed_position: true,
      },
      false,
      false,
      () => {
        drawRect(ctx, { x: this.xi(), y: this.yi() }, this.panel_w, this.panel_h, 0.5 * Math.min(this.panel_h, 32));
      }
    );
    // clip in screen space (via screenToCanvas) since ctx is currently in world space, not inside a fixed_position block
    const clip_rect = {
      x: this.xi() + RisqBottomPanel.PADDING,
      y: this.yi() + RisqBottomPanel.PADDING,
      w: this.panel_w - 2 * RisqBottomPanel.PADDING,
      h: this.content_h,
    };
    ctx.save();
    const corners = [
      { x: clip_rect.x, y: clip_rect.y },
      { x: clip_rect.x + clip_rect.w, y: clip_rect.y },
      { x: clip_rect.x + clip_rect.w, y: clip_rect.y + clip_rect.h },
      { x: clip_rect.x, y: clip_rect.y + clip_rect.h },
    ].map((corner) => screenToCanvas(corner, transform));
    ctx.beginPath();
    corners.forEach((corner, i) => (i === 0 ? ctx.moveTo(corner.x, corner.y) : ctx.lineTo(corner.x, corner.y)));
    ctx.closePath();
    ctx.clip();
    configDraw(
      ctx,
      transform,
      { fill_style: 'transparent', stroke_style: 'rgba(60, 60, 60, 0.7)', stroke_width: 1, fixed_position: true },
      false,
      false,
      () => {
        for (const separator_x of this.separator_xs) {
          drawLine(ctx, { x: separator_x, y: clip_rect.y }, { x: separator_x, y: clip_rect.y + clip_rect.h });
        }
      }
    );
    for (const item of this.items) {
      if (!this.itemContains(item, this.mouse_screen)) {
        item.setHovering(false);
        item.setClicking(false);
      }
      item.draw(ctx, transform, dt);
    }
    ctx.restore();
    if (this.overflowing) {
      this.scrollbar.draw(ctx, transform, dt);
    }
    for (const item of this.items) {
      if (this.itemContains(item, this.mouse_screen) && item.isHovering()) {
        item.drawTooltip?.(ctx, transform, this.risq, dt);
      }
    }
  }

  scroll(dy: number, mode: number): boolean {
    if (!this.overflowing) {
      return false;
    }
    return this.scrollbar.scroll(dy, mode);
  }

  private contentContains(screen: Point2D): boolean {
    const padding = RisqBottomPanel.PADDING;
    return (
      screen.x >= this.xi() + padding &&
      screen.x <= this.xf() - padding &&
      screen.y >= this.yi() + padding &&
      screen.y <= this.yi() + padding + this.content_h
    );
  }

  private itemContains(item: BottomPanelItem, screen: Point2D): boolean {
    return (
      this.contentContains(screen) &&
      screen.x >= item.xi() &&
      screen.x <= item.xf() &&
      screen.y >= item.yi() &&
      screen.y <= item.yf()
    );
  }

  mousemove(canvas: Point2D, screen: Point2D, transform: BoardTransformData): boolean {
    this.mouse_screen = screen;
    const scrollbar_hovering = this.overflowing && this.scrollbar.mousemove(canvas, screen, transform);
    const item_hovering = this.items
      .map((item) => {
        if (this.itemContains(item, screen)) {
          return item.mousemove(canvas, screen, transform);
        }
        item.setHovering(false);
        item.setClicking(false);
        return false;
      })
      .some(Boolean);
    this.hovering =
      scrollbar_hovering ||
      item_hovering ||
      (screen.x >= this.xi() && screen.y >= this.yi() && screen.x <= this.xf() && screen.y <= this.yf());
    return this.hovering;
  }

  mousedown(e: MouseEvent): boolean {
    if (this.overflowing && this.scrollbar.mousedown(e)) {
      return true;
    }
    return this.items.map((item) => this.itemContains(item, this.mouse_screen) && item.mousedown(e)).some(Boolean);
  }

  mouseup(e: MouseEvent): void {
    this.scrollbar.mouseup(e);
    for (const item of this.items) {
      item.mouseup(e);
    }
  }

  xi(): number {
    return this.p.x;
  }
  yi(): number {
    return this.p.y;
  }
  xf(): number {
    return this.xi() + this.panel_w;
  }
  yf(): number {
    return this.yi() + this.panel_h;
  }
  w(): number {
    return this.panel_w;
  }
  h(): number {
    return this.panel_h;
  }
}

import type { BoardTransformData } from '../../../../../util/canvas_board/canvas_board';
import { DwgSquareButton } from '../../../../../util/canvas_components/button/square_button';
import { configDraw } from '../../../../../util/canvas_components/canvas_component';
import { drawRect } from '../../../../../util/canvas_util';
import type { DwgRisq } from '../../../risq';
import type { RisqTooltipData } from '../../risq_tooltip';
import { RisqButtonTooltip } from '../../risq_tooltip';
import type { HotkeyCombo, RisqHotkeyAction } from '../../../application/input/hotkeys';
import { hotkeyDisplayString } from '../../../application/input/hotkeys';

export declare interface RisqActionButtonConfig {
  row: number;
  col: number;
  image_path: string;
  description: string;
}

export abstract class RisqActionButton extends DwgSquareButton {
  readonly row: number;
  readonly col: number;
  readonly description: string;
  private tooltip = new RisqButtonTooltip(() => this.getTooltipData());
  protected dimmed = false;
  private hotkey_combo?: HotkeyCombo;

  constructor(config: RisqActionButtonConfig, s: number) {
    super({
      button_config: { allow_nonleft_clicks: true },
      p: { x: 0, y: 0 },
      s,
      draw_config: {
        fill_style: 'transparent',
        stroke_style: 'rgb(60, 40, 20)',
        stroke_width: 1,
        hover_fill_style: 'rgba(210, 180, 130, 0.5)',
        click_fill_style: 'rgba(235, 210, 165, 0.7)',
        draw_clicked_when_unhovered: true,
        fixed_position: true,
      },
      image_path: config.image_path,
    });
    this.row = config.row;
    this.col = config.col;
    this.description = config.description;
  }

  override mousedown(e: MouseEvent): boolean {
    return (e.button === 0 || e.button === 2) && super.mousedown(e);
  }

  protected hovered(): void {}
  protected unhovered(): void {}
  protected clicked(): void {}

  execute(_ctrl_held?: boolean): void {}

  matchesAction(_action: RisqHotkeyAction): boolean {
    return false;
  }

  matchesProducible(_kind: string, _id: number): boolean {
    return false;
  }

  protected released(): void {
    if (this.isHovering()) {
      this.execute();
    }
  }

  dataRefreshed(): void {}

  override draw(ctx: CanvasRenderingContext2D, transform: BoardTransformData, dt: number): void {
    super.draw(ctx, transform, dt);
    if (this.isDisabled() || this.dimmed) {
      configDraw(
        ctx,
        transform,
        { fill_style: 'rgba(40, 30, 20, 0.55)', stroke_width: 0, fixed_position: true },
        false,
        false,
        () => drawRect(ctx, { x: this.xi(), y: this.yi() }, this.w(), this.h())
      );
    }
  }

  setHotkeyCombo(combo: HotkeyCombo | undefined) {
    this.hotkey_combo = combo;
  }

  protected getTooltipData(): RisqTooltipData {
    return { title: this.description, hotkey: this.hotkey_combo ? hotkeyDisplayString(this.hotkey_combo) : undefined };
  }

  drawTooltip(ctx: CanvasRenderingContext2D, transform: BoardTransformData, risq: DwgRisq, dt: number) {
    this.tooltip.draw(ctx, transform, risq, dt, this.isHovering(), this.isPressed());
  }
}

import { drawText } from '../../../../../util/canvas_util';
import type { RisqBuilding, RisqResource } from '../../../model/types';
import { buildingImage } from '../../../rendering/assets/buildings';
import { resourceIcon, resourceTypeImage } from '../../../rendering/assets/resources';
import type { FoundationDrawData } from '../left_panel_data';
import type { PanelDrawContext } from './primitives';
import { drawHeaderImage, drawName, drawOwnerSeparators, drawSeparator } from './primitives';
import { workersText } from './stats_view';
import { drawGarrisonedUnits } from './unit_views';

export function drawResource(pc: PanelDrawContext, resource: RisqResource) {
  const { ctx, frame, risq } = pc;
  let yi = frame.yi() + drawName(pc, resource.display_name);
  yi += drawHeaderImage(pc, yi, resourceIcon(risq, resource));
  drawSeparator(pc, yi);
  yi += 8;
  ctx.beginPath();
  ctx.drawImage(risq.getIcon(resourceTypeImage(resource)), frame.xi() + 0.1 * frame.w(), yi, 40, 40);
  drawText(ctx, resource.resources_left.toFixed(1), {
    p: { x: frame.xi() + 0.1 * frame.w() + 48, y: yi + 20 },
    w: 0.9 * frame.w() - 48,
    fill_style: 'black',
    baseline: 'middle',
    font: '36px serif',
  });
  yi += 50;
  drawText(ctx, `Base gather speed: ${resource.base_gather_speed}`, {
    p: { x: frame.xi() + 0.1 * frame.w(), y: yi + 12 },
    w: 0.9 * frame.w(),
    fill_style: 'black',
    baseline: 'middle',
    font: '18px serif',
  });
  const full = risq.planning.gatherers(resource).predicted.size >= resource.gather_capacity;
  drawText(ctx, `Workers: ${workersText(risq, resource, resource.gather_capacity)}`, {
    p: { x: frame.xi() + 0.1 * frame.w(), y: yi + 36 },
    w: 0.9 * frame.w(),
    fill_style: full ? 'rgb(200, 30, 30)' : 'black',
    baseline: 'middle',
    font: '18px serif',
  });
}

export function drawBuilding(pc: PanelDrawContext, building: RisqBuilding) {
  const { ctx, frame, risq } = pc;
  let yi = frame.yi() + drawName(pc, building?.display_name ?? 'Empty Plot');
  yi += drawHeaderImage(
    pc,
    yi,
    buildingImage(building?.building_id, building?.under_construction),
    building ? risq.getGame()?.players[building.player_id]?.color : undefined
  );
  drawSeparator(pc, yi);
  if (!building) {
    yi += 12;
    drawText(ctx, 'An empty lot that can be built on', {
      p: { x: frame.xi() + 0.1 * frame.w(), y: yi },
      w: 0.9 * frame.w(),
      fill_style: 'black',
      align: 'left',
      font: `14px serif`,
    });
    return;
  }
  pc.stats.draw(pc, frame.yi() + 0.25 * frame.h() + 6, building, building);
  if (drawOwnerSeparators(pc, building.player_id) && pc.layout.garrison_rows > 0) {
    drawGarrisonedUnits(pc, building);
  }
}

export function drawFoundation(pc: PanelDrawContext, foundation: FoundationDrawData) {
  const { ctx, frame, risq } = pc;
  let yi = frame.yi() + drawName(pc, foundation.display_name);
  yi += drawHeaderImage(pc, yi, 'risq/buildings/construction', risq.getGame()?.players[foundation.player_id]?.color);
  drawSeparator(pc, yi);
  yi += 12;
  drawText(ctx, 'A planned foundation awaiting construction units', {
    p: { x: frame.xi() + 0.1 * frame.w(), y: yi },
    w: 0.9 * frame.w(),
    fill_style: 'black',
    align: 'left',
    font: `14px serif`,
  });
  const stamina =
    risq.planning.getLocalFoundation(foundation.coordinate_key)?.stamina_cost ??
    risq.getPlayer()?.planned_foundations.get(foundation.coordinate_key)?.stamina_cost;
  if (stamina !== undefined) {
    drawText(ctx, `Construction progress: 0 / ${stamina}`, {
      p: { x: frame.xi() + 0.1 * frame.w(), y: yi + 36 },
      w: 0.9 * frame.w(),
      fill_style: 'black',
      baseline: 'middle',
      font: '18px serif',
    });
  }
}

import type { ColorRGB } from '../../../../../../../scripts/color_rgb';
import { drawLine, drawText } from '../../../../../util/canvas_util';
import type { DwgRisq } from '../../../risq';
import type { LeftPanelLayout, PanelFrame } from '../layout';
import type { RisqStatsView } from './stats_view';

/** Everything a left-panel content renderer needs for one draw */
export declare interface PanelDrawContext {
  ctx: CanvasRenderingContext2D;
  risq: DwgRisq;
  frame: PanelFrame;
  layout: LeftPanelLayout;
  visibility: number;
  stats: RisqStatsView;
}

/** Draws the centered title; returns its height */
export function drawName(pc: PanelDrawContext, name: string): number {
  const text_size = Math.min(40, (1 / 12) * pc.frame.h());
  drawText(pc.ctx, name, {
    p: { x: pc.frame.xc(), y: pc.frame.yi() + 3 },
    w: pc.frame.w(),
    fill_style: 'black',
    align: 'center',
    font: `bold ${0.85 * text_size}px serif`,
  });
  return text_size + 3;
}

/** Draws a centered subtitle at yi; returns its height */
export function drawSubtitle(pc: PanelDrawContext, text: string, yi: number): number {
  drawText(pc.ctx, text, {
    p: { x: pc.frame.xc(), y: yi },
    w: pc.frame.w(),
    fill_style: 'black',
    align: 'center',
    font: '18px serif',
  });
  return 26;
}

/** Draws the header image filling the rest of the panel's top quarter; returns the height it reserved */
export function drawHeaderImage(
  pc: PanelDrawContext,
  yi: number,
  img: string | CanvasImageSource,
  color?: ColorRGB
): number {
  pc.ctx.beginPath();
  const max_img_height = 0.25 * pc.frame.h() - yi + pc.frame.yi();
  const img_height = Math.min(max_img_height - 6, 0.8 * pc.frame.w());
  const icon = typeof img !== 'string' ? img : color ? pc.risq.getPlayerColoredIcon(img, color) : pc.risq.getIcon(img);
  pc.ctx.drawImage(icon, 0.5 * (pc.frame.w() - img_height), yi, img_height, img_height);
  return max_img_height;
}

export function drawSeparator(pc: PanelDrawContext, yi: number) {
  pc.ctx.strokeStyle = 'rgba(60, 60, 60, 0.7)';
  pc.ctx.lineWidth = 2;
  drawLine(pc.ctx, { x: pc.frame.xi() + 0.1 * pc.frame.w(), y: yi }, { x: pc.frame.xf() - 0.1 * pc.frame.w(), y: yi });
}

/** Separators framing the garrison and action-grid bands, drawn only for the local player's selections */
export function drawOwnerSeparators(pc: PanelDrawContext, owner_player_id: number | undefined): boolean {
  if (owner_player_id === undefined || pc.risq.getPlayer()?.player.player_id !== owner_player_id) {
    return false;
  }
  drawSeparator(pc, pc.layout.separator_below_stats);
  if (pc.layout.garrison_rows > 0) {
    drawSeparator(pc, pc.layout.garrison_separator);
  }
  drawSeparator(pc, pc.layout.grid_bottom_separator);
  return true;
}

import type { BoardTransformData } from '../../../../../util/canvas_board/canvas_board';
import { createTooltipState, drawTooltip, shouldShowTooltip } from '../../../../../util/canvas_components/tooltip';
import { drawHexagon } from '../../../../../util/canvas_util';
import type { Point2D } from '../../../../../util/objects2d';
import { equalsPoint2D } from '../../../../../util/objects2d';
import type { RectHoverData, RisqSpace, RisqZone } from '../../../model/types';
import { RisqVisibilityLevel } from '../../../model/types';
import { buildingImage } from '../../../rendering/assets/buildings';
import { resourceIcon } from '../../../rendering/assets/resources';
import { borderStrokeStyle, drawHexImage } from '../../../rendering/space';
import { RisqViewMode, spaceOwnerColor, terrainImage } from '../../../rendering/terrain';
import { getZoneFill } from '../../../rendering/zones/draw';
import { INNER_ZONE_MULTIPLIER, OUTER_ZONE_INDICES } from '../../../rendering/zones/geometry';
import { resolveHoveredZones, unhoverRisqZone } from '../../../rendering/zones/hit_testing';
import type { DwgRisq } from '../../../risq';
import { rectHovered } from './stats_view';
import type { PanelDrawContext } from './primitives';

/** The zoomed hex preview shown for a space or zone, with its hoverable zones and visibility badge */
export class RisqSpaceHexagon {
  private r = 0;
  private c: Point2D = { x: 0, y: 0 };
  private eye_badge_hover: RectHoverData = { ps: { x: 0, y: 0 }, pe: { x: 0, y: 0 } };
  private eye_badge_tooltip = createTooltipState();
  private hovered_zone?: RisqZone;

  hoveredZone(): RisqZone | undefined {
    return this.hovered_zone;
  }

  clearHoveredZone() {
    if (!!this.hovered_zone) {
      unhoverRisqZone(this.hovered_zone);
      this.hovered_zone = undefined;
    }
  }

  /** Draws the hex below yi, highlighting curr_zone (given in zone index coordinates); returns the height used */
  draw(
    pc: PanelDrawContext,
    space: RisqSpace,
    separator_distance: number,
    yi: number,
    curr_zone: Point2D = { x: -1, y: -1 }
  ): number {
    const { ctx, frame, risq } = pc;
    const hexagon_height = Math.min(frame.w(), frame.yi() + 0.4 * frame.h() - yi - separator_distance);
    const owner_color = spaceOwnerColor(space.ownership, risq.getGame()?.players ?? []);
    ctx.strokeStyle = borderStrokeStyle(owner_color, 1);
    ctx.lineWidth = 2;
    const r = 0.5 * hexagon_height;
    this.r = r;
    const inner_r = INNER_ZONE_MULTIPLIER * r;
    const c = { x: frame.xc(), y: yi + r };
    this.c = c;
    drawHexImage(ctx, risq.getIcon(terrainImage(space.terrain_id)), c, r);
    ctx.fillStyle = 'transparent';
    drawHexagon(ctx, c, r);
    this.drawEyeBadge(pc, space, yi, hexagon_height);
    if (pc.visibility < RisqVisibilityLevel.FOG || !space.zones) {
      return hexagon_height + separator_distance;
    }
    ctx.strokeStyle = borderStrokeStyle(owner_color, 0.7);
    ctx.lineWidth = 0.5;
    let zone = space.zones[1][1];
    const zone_fill = getZoneFill(zone, RisqViewMode.ALL, undefined, true, 4);
    if (curr_zone.x === 1 && curr_zone.y === 1) {
      zone_fill.addColor(255, 255, 255, 0.2);
    }
    ctx.fillStyle = zone_fill.getString();
    drawHexagon(ctx, c, inner_r);
    this.drawZoneIcon(ctx, risq, zone, c, 0.4 * inner_r);
    const a = Math.PI / 3;
    const mid_r = 0.5 * (inner_r + r);
    const icon_r = 0.32 * (r - inner_r);
    for (let i = 0; i < 6; i++) {
      const direction_vector = OUTER_ZONE_INDICES[i];
      zone = space.zones[direction_vector.x][direction_vector.y];
      const outer_fill = getZoneFill(zone, RisqViewMode.ALL, undefined, true, 4);
      if (curr_zone.x === direction_vector.x && curr_zone.y === direction_vector.y) {
        outer_fill.addColor(255, 255, 255, 0.2);
      }
      ctx.fillStyle = outer_fill.getString();
      ctx.beginPath();
      ctx.lineTo(c.x + inner_r * Math.cos(a * i + Math.PI / 6), c.y + inner_r * Math.sin(a * i + Math.PI / 6));
      ctx.lineTo(c.x + inner_r * Math.cos(a * i + Math.PI / 2), c.y + inner_r * Math.sin(a * i + Math.PI / 2));
      ctx.lineTo(c.x + r * Math.cos(a * i + Math.PI / 2), c.y + r * Math.sin(a * i + Math.PI / 2));
      ctx.lineTo(c.x + r * Math.cos(a * i + Math.PI / 6), c.y + r * Math.sin(a * i + Math.PI / 6));
      ctx.closePath();
      ctx.stroke();
      ctx.fill();
      const angle_mid = a * i + Math.PI / 3;
      this.drawZoneIcon(
        ctx,
        risq,
        zone,
        { x: c.x + mid_r * Math.cos(angle_mid), y: c.y + mid_r * Math.sin(angle_mid) },
        icon_r
      );
    }
    return hexagon_height + separator_distance;
  }

  private drawEyeBadge(pc: PanelDrawContext, space: RisqSpace, yi: number, hexagon_height: number) {
    if (space.visibility !== RisqVisibilityLevel.SPY && space.visibility !== RisqVisibilityLevel.POOR) {
      this.eye_badge_hover.hovered = false;
      return;
    }
    const { frame } = pc;
    const badge_size = 0.15 * hexagon_height;
    const badge_p =
      space.visibility === RisqVisibilityLevel.POOR
        ? { x: frame.xi() + 0.05 * frame.w(), y: yi }
        : { x: frame.xi() + 0.1 * frame.w(), y: yi + 0.05 * hexagon_height };
    pc.ctx.drawImage(
      pc.risq.getIcon(`icons/${space.visibility === RisqVisibilityLevel.SPY ? 'eye' : 'no_eye'}64`),
      badge_p.x,
      badge_p.y,
      badge_size,
      badge_size
    );
    this.eye_badge_hover.ps = badge_p;
    this.eye_badge_hover.pe = { x: badge_p.x + badge_size, y: badge_p.y + badge_size };
  }

  private drawZoneIcon(ctx: CanvasRenderingContext2D, risq: DwgRisq, zone: RisqZone, p: Point2D, icon_r: number) {
    let icon: HTMLImageElement | HTMLCanvasElement | undefined;
    if (zone.resource) {
      icon = resourceIcon(risq, zone.resource);
    } else if (zone.building) {
      const building_color = risq.getGame()?.players[zone.building.player_id]?.color;
      const building_image = buildingImage(zone.building.building_id, zone.building.under_construction);
      icon = building_color ? risq.getPlayerColoredIcon(building_image, building_color) : risq.getIcon(building_image);
    }
    if (icon) {
      ctx.drawImage(icon, p.x - icon_r, p.y - icon_r, 2 * icon_r, 2 * icon_r);
    }
  }

  drawTooltip(
    ctx: CanvasRenderingContext2D,
    transform: BoardTransformData,
    risq: DwgRisq,
    dt: number,
    space: RisqSpace
  ) {
    if (
      !shouldShowTooltip(this.eye_badge_tooltip, !!this.eye_badge_hover.hovered, !!this.eye_badge_hover.clicked, dt)
    ) {
      return;
    }
    drawTooltip(
      this.eye_badge_tooltip,
      ctx,
      transform,
      risq.viewport.canvasSize(),
      space.visibility === RisqVisibilityLevel.POOR
        ? 'Poor visibility on this space; overall unit count seen but no specific units or zone-level unit information'
        : ''
    );
  }

  mousemove(m: Point2D, space: RisqSpace) {
    rectHovered(m, this.eye_badge_hover);
    const new_hovered_zone = resolveHoveredZones(m, space, this.r, this.c, true);
    if (!!this.hovered_zone && !equalsPoint2D(this.hovered_zone.coordinate, new_hovered_zone?.coordinate)) {
      this.hovered_zone.hovered = false;
      this.hovered_zone.clicked = false;
    }
    this.hovered_zone = new_hovered_zone;
  }
}

import type { BoardTransformData } from '../../../../../util/canvas_board/canvas_board';
import { drawRect, drawText } from '../../../../../util/canvas_util';
import type { Point2D } from '../../../../../util/objects2d';
import type { RectHoverData, RisqRegion, RisqSpace } from '../../../model/types';
import { RisqResourceType, RisqVisibilityLevel } from '../../../model/types';
import { resourceTypeImage } from '../../../rendering/assets/resources';
import { COMBO_UNIT_ICON_SIZE, comboUnitIconKey, drawComboUnitIcon } from '../../../rendering/assets/unit';
import { spaceOwnerColor, terrainTypeLabel } from '../../../rendering/terrain';
import { RisqSpaceUnitsRowButton } from '../controls/space_units_row_button';
import type { PanelDrawContext } from './primitives';
import { drawName, drawSeparator, drawSubtitle } from './primitives';
import type { RisqSpaceHexagon } from './space_hexagon';

/** Draws a combo villager+military icon, used where only a total unit count is visible */
export function comboUnitIcon(pc: PanelDrawContext): HTMLCanvasElement | undefined {
  const villager_img = pc.risq.getIcon('icons/villager64');
  const unit_img = pc.risq.getIcon('icons/unit64');
  return pc.risq
    .getImageCache()
    .getImage(comboUnitIconKey(false), COMBO_UNIT_ICON_SIZE, [villager_img, unit_img], (combo_ctx) =>
      drawComboUnitIcon(combo_ctx, villager_img, unit_img)
    );
}

/** Space content: hex preview, then buildings, gold, owner, unit counts (clickable rows), and resource types */
export class RisqSpaceView {
  private villager_row_button?: RisqSpaceUnitsRowButton;
  private military_row_button?: RisqSpaceUnitsRowButton;

  constructor(private open_units_row: (economic: boolean) => void) {}

  private rowButtons(): RisqSpaceUnitsRowButton[] {
    return [this.villager_row_button, this.military_row_button].filter((b): b is RisqSpaceUnitsRowButton => !!b);
  }

  draw(pc: PanelDrawContext, space: RisqSpace, hexagon: RisqSpaceHexagon) {
    const { ctx, frame, risq } = pc;
    let yi = frame.yi() + drawName(pc, space.display_name);
    yi += drawSubtitle(pc, `${terrainTypeLabel(space.terrain_type)} space`, yi);
    const separator_distance = 8;
    yi += hexagon.draw(pc, space, separator_distance, yi);
    drawSeparator(pc, yi);
    yi += separator_distance;
    if (pc.visibility < RisqVisibilityLevel.POOR) {
      return;
    }
    const rows = 6;
    const image_size = Math.min(
      36,
      (1 / rows) * (0.6 * frame.h() - separator_distance - (rows - 1) * separator_distance)
    );
    const row_x = frame.xi() + 0.1 * frame.w();
    const row_w = 0.8 * frame.w();
    ctx.fillStyle = 'black';
    const draw_row_text = (x: number, text: string, max_w: number) => {
      const row_yc = yi + 0.5 * image_size;
      const font = `bold ${image_size}px serif`;
      ctx.font = font;
      const colon_w = ctx.measureText(': ').width;
      drawText(ctx, ': ', {
        p: { x, y: row_yc },
        w: colon_w,
        fill_style: 'black',
        align: 'left',
        baseline: 'middle',
        font,
      });
      drawText(ctx, text, {
        p: { x: x + colon_w, y: row_yc },
        w: max_w - colon_w,
        fill_style: 'black',
        align: 'left',
        baseline: 'middle',
        font,
      });
    };
    const draw_row = (img: CanvasImageSource, text: string, hover_data?: RectHoverData) => {
      const ps = { x: row_x, y: yi };
      const pe = { x: ps.x + row_w, y: ps.y + image_size };
      if (hover_data?.hovered) {
        ctx.strokeStyle = 'transparent';
        ctx.fillStyle = hover_data.clicked ? 'rgba(250, 250, 250, 0.4)' : 'rgba(210, 210, 210, 0.25)';
        drawRect(ctx, ps, pe.x - ps.x, pe.y - ps.y);
        ctx.fillStyle = 'black';
      }
      ctx.drawImage(img, ps.x, yi, image_size, image_size);
      draw_row_text(ps.x + image_size + 2, text, row_w - image_size - 2);
      if (!!hover_data) {
        hover_data.ps = ps;
        hover_data.pe = pe;
      }
      yi += image_size + separator_distance;
    };
    draw_row(risq.getIcon('icons/building64'), space.buildings?.size.toString() ?? '??');
    draw_row(risq.getIcon(resourceTypeImage(RisqResourceType.GOLD)), `${(space.gold_income ?? 0).toFixed(1)}/turn`);
    const owner_color = spaceOwnerColor(space.ownership, risq.getGame()?.players ?? []);
    const owner_name = owner_color
      ? (risq.getGame()?.players[space.ownership ?? -1]?.player.nickname ?? 'Unknown')
      : '--Unclaimed--';
    ctx.fillStyle = owner_color ? owner_color.getString() : 'rgba(255, 255, 255, 0.3)';
    ctx.strokeStyle = 'black';
    ctx.lineWidth = 1;
    drawRect(ctx, { x: row_x, y: yi }, image_size, image_size);
    draw_row_text(row_x + image_size + 2, owner_name, row_w - image_size - 2);
    yi += image_size + separator_distance;
    if (pc.visibility === RisqVisibilityLevel.POOR) {
      const combo_icon = comboUnitIcon(pc);
      if (combo_icon) {
        draw_row(combo_icon, space.unit_count?.toString() ?? '??');
      }
    } else {
      const row_step = image_size + separator_distance;
      this.villager_row_button = this.layoutRowButton(
        this.villager_row_button,
        pc.risq.getIcon('icons/villager64'),
        space.num_villager_units?.toString() ?? '??',
        true,
        { x: row_x, y: yi },
        row_w,
        image_size
      );
      yi += row_step;
      this.military_row_button = this.layoutRowButton(
        this.military_row_button,
        pc.risq.getIcon('icons/unit64'),
        space.num_military_units?.toString() ?? '??',
        false,
        { x: row_x, y: yi },
        row_w,
        image_size
      );
      yi += row_step;
    }
    this.drawResourceTypes(pc, space, yi, image_size);
  }

  private drawResourceTypes(pc: PanelDrawContext, space: RisqSpace, yi: number, image_size: number) {
    const { ctx, frame, risq } = pc;
    const resources = [...(space.total_resources?.entries() ?? [])]
      .filter((r) => r[1] > 0)
      .map((r) => r[0])
      .sort((a, b) => a - b);
    const num_resources = resources.length + 0.3 * (resources.length - 1); // account for slashes
    const resource_image_size = Math.min(image_size, (1.0 / num_resources) * 0.8 * frame.w());
    for (const [i, r] of resources.entries()) {
      if (i > 0) {
        drawText(ctx, '/', {
          p: { x: frame.xi() + 0.1 * frame.w() + (i * 1.3 - 0.15) * resource_image_size, y: yi },
          w: 0.3 * resource_image_size,
          fill_style: 'black',
          align: 'center',
          font: `bold ${resource_image_size}px serif`,
        });
      }
      ctx.drawImage(
        risq.getIcon(resourceTypeImage(r)),
        frame.xi() + 0.1 * frame.w() + i * 1.3 * resource_image_size,
        yi,
        resource_image_size,
        resource_image_size
      );
    }
  }

  /** Creates the row button on first use, then repositions it and refreshes its count */
  private layoutRowButton(
    button: RisqSpaceUnitsRowButton | undefined,
    icon: HTMLImageElement,
    count: string,
    economic: boolean,
    p: Point2D,
    w: number,
    h: number
  ): RisqSpaceUnitsRowButton {
    const row_button =
      button ?? new RisqSpaceUnitsRowButton({ p, w, h, icon, onOpen: () => this.open_units_row(economic) });
    row_button.setPosition(p);
    row_button.setSize(w, h);
    row_button.setRowText(`: ${count}`);
    return row_button;
  }

  drawRowButtons(ctx: CanvasRenderingContext2D, transform: BoardTransformData, dt: number) {
    for (const button of this.rowButtons()) {
      button.draw(ctx, transform, dt);
    }
  }

  mousemove(canvas: Point2D, screen: Point2D, transform: BoardTransformData) {
    for (const button of this.rowButtons()) {
      button.mousemove(canvas, screen, transform);
    }
  }

  cancelInput(): void {
    for (const button of this.rowButtons()) {
      button.setClicking(false);
      button.setHovering(false);
    }
  }

  mousedown(e: MouseEvent) {
    for (const button of this.rowButtons()) {
      button.mousedown(e);
    }
  }

  mouseup(e: MouseEvent) {
    for (const button of this.rowButtons()) {
      button.mouseup(e);
    }
  }
}

export function drawRegion(pc: PanelDrawContext, region: RisqRegion) {
  const { ctx, frame, risq } = pc;
  let yi = frame.yi() + drawName(pc, region.name);
  yi += 12;
  const image_size = 40;
  const owner_color = region.owner >= 0 ? risq.getGame()?.players[region.owner]?.color : undefined;
  const owner_name = owner_color
    ? (risq.getGame()?.players[region.owner]?.player.nickname ?? 'Unknown')
    : '--Unclaimed--';
  ctx.fillStyle = owner_color ? owner_color.getString() : 'rgba(255, 255, 255, 0.3)';
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 1;
  drawRect(ctx, { x: frame.xi() + 0.1 * frame.w(), y: yi }, image_size, image_size);
  drawText(ctx, owner_name, {
    p: { x: frame.xi() + 0.1 * frame.w() + image_size + 8, y: yi + 0.5 * image_size },
    w: 0.8 * frame.w() - image_size - 8,
    fill_style: 'black',
    align: 'left',
    baseline: 'middle',
    font: '20px serif',
  });
  yi += image_size + 12;
  drawSeparator(pc, yi);
  yi += 12;
  ctx.drawImage(risq.getIcon(resourceTypeImage(RisqResourceType.GOLD)), frame.xi() + 0.1 * frame.w(), yi, 32, 32);
  drawText(ctx, `${region.gold_bonus} gold / turn`, {
    p: { x: frame.xi() + 0.1 * frame.w() + 40, y: yi + 16 },
    w: 0.8 * frame.w() - 40,
    fill_style: 'black',
    align: 'left',
    baseline: 'middle',
    font: '20px serif',
  });
  yi += 40;
  drawText(ctx, `${region.spaces.length} space${region.spaces.length === 1 ? '' : 's'} explored`, {
    p: { x: frame.xi() + 0.1 * frame.w(), y: yi },
    w: 0.8 * frame.w(),
    fill_style: 'black',
    align: 'left',
    font: '16px serif',
  });
}

import type { BoardTransformData } from '../../../../../util/canvas_board/canvas_board';
import { createTooltipState, drawTooltip, shouldShowTooltip } from '../../../../../util/canvas_components/tooltip';
import { drawRect, drawText } from '../../../../../util/canvas_util';
import type { Point2D } from '../../../../../util/objects2d';
import type { RectHoverData, RisqBuilding, RisqCombatStats, RisqResource, RisqUnit } from '../../../model/types';
import { RisqAttackType, RisqRange, RisqResourceType } from '../../../model/types';
import { resourceTypeImage } from '../../../rendering/assets/resources';
import { UNIT_HEALTHBAR_COLOR_BACKGROUND, UNIT_HEALTHBAR_COLOR_HEALTH } from '../../../rendering/assets/unit';
import type { DwgRisq } from '../../../risq';
import { PANEL_PADDING } from '../layout';
import type { PanelDrawContext } from './primitives';

type StatCell = [icon: string, value: number | string, label: string];

const HEALTH_ROW_H = 14;
const STAT_ROW_H = 20;

/** "current+delta/capacity" workers at a gatherable target, counting pending gather orders */
export function workersText(risq: DwgRisq, target: RisqBuilding | RisqResource, capacity: number): string {
  const { current, predicted } = risq.planning.gatherers(target);
  const delta = predicted.size - current;
  return `${current}${delta > 0 ? `+${delta}` : delta < 0 ? `-${-delta}` : ''}/${capacity}`;
}

function attackTypeIncludes(attack_type: RisqAttackType, component: 0 | 1 | 2): boolean {
  switch (attack_type) {
    case RisqAttackType.BLUNT:
      return component === 0;
    case RisqAttackType.PIERCING:
      return component === 1;
    case RisqAttackType.MAGIC:
      return component === 2;
    case RisqAttackType.BLUNT_PIERCING:
      return component === 0 || component === 1;
    case RisqAttackType.PIERCING_MAGIC:
      return component === 1 || component === 2;
    case RisqAttackType.MAGIC_BLUNT:
      return component === 2 || component === 0;
    case RisqAttackType.BLUNT_PIERCING_MAGIC:
      return true;
    default:
      return false;
  }
}

// Returns the attack's space radius (0/1/2), or null if this isn't a ranged attack (RisqRange_ZONE)
function rangeDistance(range: RisqRange): number | null {
  switch (range) {
    case RisqRange.SPACE:
      return 0;
    case RisqRange.ADJACENT:
      return 1;
    case RisqRange.SECONDARY:
      return 2;
    default:
      return null;
  }
}

function combatStatsGroups(cs: RisqCombatStats, attack_range: RisqRange): (StatCell | null)[][] {
  const has_attack = cs.attack_type !== RisqAttackType.NONE;
  const includes = (component: 0 | 1 | 2) => attackTypeIncludes(cs.attack_type, component);
  const range = rangeDistance(attack_range);
  const attack: (StatCell | null)[] = has_attack
    ? [
        includes(0) ? ['risq/icons/attack_blunt', cs.attack_blunt, 'Blunt attack'] : null,
        includes(1) ? ['risq/icons/attack_piercing', cs.attack_piercing, 'Piercing attack'] : null,
        includes(2) ? ['risq/icons/attack_magic', cs.attack_magic, 'Magic attack'] : null,
        range !== null ? ['risq/icons/attack_range', range, 'Attack range'] : null,
      ]
    : [null, null, null, null];
  const penetration: (StatCell | null)[] = has_attack
    ? [
        cs.penetration_blunt ? ['risq/icons/penetration_blunt', cs.penetration_blunt, 'Blunt penetration'] : null,
        cs.penetration_piercing
          ? ['risq/icons/penetration_piercing', cs.penetration_piercing, 'Piercing penetration']
          : null,
        cs.penetration_magic ? ['risq/icons/penetration_magic', cs.penetration_magic, 'Magic penetration'] : null,
        null,
      ]
    : [null, null, null, null];
  const defense: (StatCell | null)[] = [
    cs.defense_blunt ? ['risq/icons/defense_blunt', cs.defense_blunt, 'Blunt defense'] : null,
    cs.defense_piercing ? ['risq/icons/defense_piercing', cs.defense_piercing, 'Piercing defense'] : null,
    cs.defense_magic ? ['risq/icons/defense_magic', cs.defense_magic, 'Magic defense'] : null,
    null,
  ];
  return [attack, defense, penetration];
}

/** Resources left / gather rate / workers for a completed gatherable building */
function gatherStatsRow(risq: DwgRisq, building: RisqBuilding): StatCell[] | undefined {
  if (building.under_construction || building.gather_capacity === undefined) {
    return undefined;
  }
  return [
    [
      resourceTypeImage(building.resource_category ?? RisqResourceType.ERROR),
      Math.round(building.resources_left ?? 0),
      'Resources left',
    ],
    ['icons/gather32', building.base_gather_speed ?? 0, 'Gather rate'],
    ['icons/villager64', workersText(risq, building, building.gather_capacity), 'Workers'],
  ];
}

/** Health bar, stamina, and per-damage-type stat rows for a unit or building, with their hover tooltips */
export class RisqStatsView {
  private healthbar_row: RectHoverData = { ps: { x: 0, y: 0 }, pe: { x: 0, y: 0 } };
  private stamina_row: RectHoverData = { ps: { x: 0, y: 0 }, pe: { x: 0, y: 0 } };
  private stat_cells: { rect: RectHoverData; text: string }[] = [];
  private hovered_stat_cell = -1;
  private healthbar_tooltip = createTooltipState();
  private stamina_tooltip = createTooltipState();
  private stat_tooltip = createTooltipState();

  /** Height of the stats section, including gathering, construction, and renewal details */
  static height(risq: DwgRisq, building?: RisqBuilding): number {
    let stat_rows = 3 + (building && (building.under_construction || gatherStatsRow(risq, building)) ? 1 : 0);
    stat_rows += building?.renewing ? 1 : 0;
    const rows = 2 + stat_rows;
    return 2 * HEALTH_ROW_H + stat_rows * STAT_ROW_H + (rows - 1) * PANEL_PADDING;
  }

  clearHover() {
    this.healthbar_row.hovered = false;
    this.stamina_row.hovered = false;
  }

  draw(pc: PanelDrawContext, start_yi: number, subject: RisqUnit | RisqBuilding, building?: RisqBuilding) {
    const { ctx, frame } = pc;
    const cs = subject.combat_stats;
    const health_h = HEALTH_ROW_H;
    const gap = PANEL_PADDING;
    const xi = frame.xi() + 0.1 * frame.w();
    let y = start_yi;

    ctx.strokeStyle = UNIT_HEALTHBAR_COLOR_BACKGROUND;
    ctx.lineWidth = 0.4;
    ctx.fillStyle = UNIT_HEALTHBAR_COLOR_BACKGROUND;
    drawRect(ctx, { x: xi, y }, 0.8 * frame.w(), health_h);
    if (cs.max_health > 0 && cs.health > 0) {
      ctx.fillStyle = UNIT_HEALTHBAR_COLOR_HEALTH;
      drawRect(ctx, { x: xi, y }, (cs.health / cs.max_health) * 0.8 * frame.w(), health_h);
    }
    this.healthbar_row.ps = { x: xi, y };
    this.healthbar_row.pe = { x: xi + 0.8 * frame.w(), y: y + health_h };
    y += health_h + gap;

    const text_y = y + 0.5 * health_h;
    drawText(ctx, `${Math.round(cs.health)} / ${cs.max_health}`, {
      p: { x: xi, y: text_y },
      w: 0.8 * frame.w(),
      fill_style: 'black',
      align: 'left',
      baseline: 'middle',
      font: `${health_h}px serif`,
    });
    const row_right = xi + 0.8 * frame.w();
    const stamina_text = `${subject.current_stamina}`;
    ctx.font = `${health_h}px serif`;
    const stamina_text_width = ctx.measureText(stamina_text).width;
    const stamina_icon_x = row_right - stamina_text_width - health_h - 4;
    ctx.drawImage(pc.risq.getIcon('risq/icons/stamina'), stamina_icon_x, y, health_h, health_h);
    this.stamina_row.ps = { x: stamina_icon_x, y };
    this.stamina_row.pe = { x: row_right, y: y + health_h };
    drawText(ctx, stamina_text, {
      p: { x: row_right, y: text_y },
      w: stamina_text_width,
      fill_style: 'black',
      align: 'right',
      baseline: 'middle',
      font: `${health_h}px serif`,
    });
    y += health_h + gap;

    this.stat_cells = [];
    for (const group of combatStatsGroups(cs, subject.attack_range)) {
      this.drawStatRow(pc, group, y, (0.8 * frame.w()) / 4);
      y += STAT_ROW_H + gap;
    }
    const gather_row = building ? gatherStatsRow(pc.risq, building) : undefined;
    if (gather_row) {
      this.drawStatRow(pc, gather_row, y, (0.8 * frame.w()) / gather_row.length);
      y += STAT_ROW_H + gap;
    }
    if (building?.renewing && building.resource_capacity && building.renew_stamina !== undefined) {
      const completed = ((building.resources_left ?? 0) / building.resource_capacity) * building.renew_stamina;
      drawText(ctx, `Renewal progress: ${completed.toFixed(1)} / ${building.renew_stamina}`, {
        p: { x: xi, y: y + 0.5 * STAT_ROW_H },
        w: 0.9 * frame.w(),
        fill_style: 'black',
        baseline: 'middle',
        font: '18px serif',
      });
    }
    if (building?.under_construction) {
      const completed = building.construction_stamina_total - building.stamina_remaining;
      drawText(ctx, `Construction progress: ${completed} / ${building.construction_stamina_total}`, {
        p: { x: xi, y: y + 0.5 * STAT_ROW_H },
        w: 0.9 * frame.w(),
        fill_style: 'black',
        baseline: 'middle',
        font: '18px serif',
      });
    }
  }

  private drawStatRow(pc: PanelDrawContext, row: (StatCell | null)[], y: number, dx: number) {
    const image_size = STAT_ROW_H;
    for (const [col, entry] of row.entries()) {
      if (!entry) {
        continue;
      }
      const sx = pc.frame.xi() + 0.1 * pc.frame.w() + col * dx;
      this.stat_cells.push({
        rect: { ps: { x: sx, y }, pe: { x: sx + dx, y: y + image_size } },
        text: `${entry[2]}: ${entry[1]}`,
      });
      pc.ctx.drawImage(pc.risq.getIcon(entry[0]), sx, y, image_size, image_size);
      drawText(pc.ctx, entry[1].toString(), {
        p: { x: sx + image_size + 0.1 * dx, y: y + 0.5 * image_size },
        w: dx - image_size,
        fill_style: 'black',
        align: 'left',
        baseline: 'middle',
        font: `${0.9 * image_size}px serif`,
      });
    }
  }

  /** Tooltips for whichever stats row is hovered; subject is undefined when no stats are showing */
  drawTooltips(
    ctx: CanvasRenderingContext2D,
    transform: BoardTransformData,
    risq: DwgRisq,
    dt: number,
    subject: RisqUnit | RisqBuilding | undefined
  ) {
    const canvas_size = risq.viewport.canvasSize();
    if (
      subject &&
      shouldShowTooltip(this.healthbar_tooltip, !!this.healthbar_row.hovered, !!this.healthbar_row.clicked, dt)
    ) {
      const cs = subject.combat_stats;
      drawTooltip(
        this.healthbar_tooltip,
        ctx,
        transform,
        canvas_size,
        `Health: ${cs.health.toFixed(1)} / ${cs.max_health}`
      );
    }
    if (
      subject &&
      shouldShowTooltip(this.stamina_tooltip, !!this.stamina_row.hovered, !!this.stamina_row.clicked, dt)
    ) {
      drawTooltip(this.stamina_tooltip, ctx, transform, canvas_size, `Stamina: +${subject.turn_stamina} / turn`);
    }
    const stat_cell = subject ? this.stat_cells[this.hovered_stat_cell] : undefined;
    if (shouldShowTooltip(this.stat_tooltip, !!stat_cell, false, dt) && stat_cell) {
      drawTooltip(this.stat_tooltip, ctx, transform, canvas_size, stat_cell.text);
    }
  }

  mousemove(m: Point2D) {
    rectHovered(m, this.healthbar_row);
    rectHovered(m, this.stamina_row);
    this.hovered_stat_cell = this.stat_cells.findIndex((cell) => rectHovered(m, cell.rect));
  }
}

/** Sets and returns whether m lies inside the rect */
export function rectHovered(m: Point2D, hover_data: RectHoverData): boolean {
  if (m.x < hover_data.ps.x || m.y < hover_data.ps.y || m.x > hover_data.pe.x || m.y > hover_data.pe.y) {
    hover_data.hovered = false;
    return false;
  }
  hover_data.hovered = true;
  return true;
}

import { capitalize } from '../../../../../../../scripts/util';
import { drawRect, drawText } from '../../../../../util/canvas_util';
import type { Point2D } from '../../../../../util/objects2d';
import type { RisqBuilding, RisqUnit, UnitByTypeData } from '../../../model/types';
import { RisqUnitType } from '../../../model/types';
import {
  UNIT_HEALTHBAR_COLOR_BACKGROUND,
  UNIT_HEALTHBAR_COLOR_HEALTH,
  unitCountLabel,
  unitImage,
} from '../../../rendering/assets/unit';
import type { DwgRisq } from '../../../risq';
import { ACTION_GRID_COLS, PANEL_PADDING } from '../layout';
import { unitResolver } from '../selection_queries';
import type { PanelDrawContext } from './primitives';
import { drawHeaderImage, drawName, drawOwnerSeparators, drawSeparator, drawSubtitle } from './primitives';

/** Draws a unit's icon and health bar, and records its rect as the unit's hover target */
export function drawUnitImage(pc: PanelDrawContext, unit: RisqUnit, p: Point2D, s: number) {
  const { ctx, risq } = pc;
  const color = risq.getGame()?.players[unit.player_id]?.color;
  const icon = color
    ? risq.getPlayerColoredIcon(unitImage(unit.unit_id), color)
    : risq.getIcon(unitImage(unit.unit_id));
  ctx.drawImage(icon, p.x, p.y, s, s);
  ctx.strokeStyle = UNIT_HEALTHBAR_COLOR_BACKGROUND;
  ctx.lineWidth = 0.4;
  ctx.fillStyle = UNIT_HEALTHBAR_COLOR_BACKGROUND;
  drawRect(ctx, { x: p.x, y: p.y + 0.8 * s }, s, 0.18 * s);
  if (unit.combat_stats.max_health > 0 && unit.combat_stats.health > 0) {
    ctx.fillStyle = UNIT_HEALTHBAR_COLOR_HEALTH;
    drawRect(ctx, { x: p.x, y: p.y + 0.8 * s }, (unit.combat_stats.health / unit.combat_stats.max_health) * s, 0.2 * s);
  }
  if (unit.hover_data.hovered) {
    ctx.fillStyle = unit.hover_data.clicked ? 'rgba(250, 250, 250, 0.4)' : 'rgba(220, 220, 220, 0.2)';
    ctx.strokeStyle = 'transparent';
    drawRect(ctx, p, s, s);
  }
  unit.hover_data.ps = p;
  unit.hover_data.pe = { x: p.x + s, y: p.y + s };
}

export function garrisonedUnits(risq: DwgRisq, building: RisqBuilding): RisqUnit[] {
  const resolve = unitResolver(risq);
  return (building.garrisoned_units ?? [])
    .map((internal_id) => resolve(building.player_id, internal_id))
    .filter((u): u is RisqUnit => !!u);
}

/** Garrisoned units fill the garrison band's grid cells in order, with empty outlined cells for the rest */
export function drawGarrisonedUnits(pc: PanelDrawContext, building: RisqBuilding) {
  const s = pc.layout.grid_s;
  const P = PANEL_PADDING;
  const top = pc.layout.separator_below_stats + P;
  const units = garrisonedUnits(pc.risq, building);
  const slot_p = (i: number): Point2D => ({
    x: pc.layout.grid_x0 + (i % ACTION_GRID_COLS) * (s + P),
    y: top + Math.floor(i / ACTION_GRID_COLS) * (s + P),
  });
  for (const [i, unit] of units.entries()) {
    drawUnitImage(pc, unit, slot_p(i), s);
  }
  pc.ctx.fillStyle = 'transparent';
  pc.ctx.strokeStyle = 'black';
  pc.ctx.lineWidth = 1;
  for (let i = units.length; i < building.garrison_capacity; i++) {
    drawRect(pc.ctx, slot_p(i), s, s);
  }
}

function drawUnitCountBadge(ctx: CanvasRenderingContext2D, count: number, p: Point2D, s: number) {
  const text = `×${count}`;
  const font_size = Math.max(10, 0.22 * s);
  ctx.font = `bold ${font_size}px serif`;
  const badge_w = ctx.measureText(text).width + 6;
  const badge_h = font_size + 4;
  const badge_p = { x: p.x + s - badge_w, y: p.y + s - badge_h };
  ctx.fillStyle = 'rgba(0, 0, 0, 0.75)';
  ctx.strokeStyle = 'transparent';
  drawRect(ctx, badge_p, badge_w, badge_h, 3);
  drawText(ctx, text, {
    p: { x: badge_p.x + 0.5 * badge_w, y: badge_p.y + 0.5 * badge_h },
    w: badge_w,
    fill_style: 'white',
    align: 'center',
    baseline: 'middle',
    font: `bold ${font_size}px serif`,
  });
}

function drawUnitCountBlock(
  pc: PanelDrawContext,
  player_id: number,
  unit_id: number,
  count: number,
  p: Point2D,
  s: number
) {
  const color = pc.risq.getGame()?.players[player_id]?.color;
  const icon = color ? pc.risq.getPlayerColoredIcon(unitImage(unit_id), color) : pc.risq.getIcon(unitImage(unit_id));
  pc.ctx.drawImage(icon, p.x, p.y, s, s);
  drawUnitCountBadge(pc.ctx, count, p, s);
}

function chunkBlocks<T>(items: T[], size: number): T[][] {
  const rows: T[][] = [];
  for (let i = 0; i < items.length; i += size) {
    rows.push(items.slice(i, i + size));
  }
  return rows;
}

function unitGroupTitle(risq: DwgRisq, groups: [number, UnitByTypeData[]][], total: number): string {
  const types = groups.flatMap(([, units]) => units).filter((t) => t.units.size > 0);
  if (new Set(types.map((t) => t.unit_id)).size === 1) {
    const sample = unitResolver(risq)(types[0].player_id, [...types[0].units][0]);
    return unitCountLabel(sample?.display_name ?? 'Unit', total);
  }
  const unit_types = new Set(types.map((t) => t.unit_type));
  const units_word = total === 1 ? 'Unit' : 'Units';
  if (unit_types.size === 1) {
    return `${total} ${capitalize(RisqUnitType[types[0].unit_type].replace(/_/g, ' '))} ${units_word}`;
  }
  return unit_types.has(RisqUnitType.ECONOMIC) ? `${total} ${units_word}` : `${total} Military ${units_word}`;
}

function unitGroupSubtitle(risq: DwgRisq, groups: [number, UnitByTypeData[]][]): string | undefined {
  const player_ids = groups.filter(([, units]) => units.some((u) => u.units.size > 0)).map(([id]) => id);
  if (player_ids.length > 1) {
    return `Units from ${player_ids.length} players`;
  }
  if (player_ids[0] === undefined || player_ids[0] === risq.getPlayer()?.player.player_id) {
    return undefined;
  }
  return `Owned by ${risq.getGame()?.players[player_ids[0]]?.player.nickname ?? 'another player'}`;
}

interface UnitRef {
  player_id: number;
  internal_id: number;
}

/** Draws a unit selection, coarsening from individual units to per-type, per-category, then per-player blocks until it fits */
export function drawUnitsGeneric(pc: PanelDrawContext, groups: [number, UnitByTypeData[]][]) {
  const multi_player = groups.length > 1;
  const single_owner_player_id = multi_player ? undefined : groups[0]?.[0];
  const total_units = groups.reduce((sum, [, units]) => sum + units.reduce((s, u) => s + u.units.size, 0), 0);
  let content_yi = pc.frame.yi() + drawName(pc, unitGroupTitle(pc.risq, groups, total_units));
  const subtitle = unitGroupSubtitle(pc.risq, groups);
  if (subtitle) {
    content_yi += drawSubtitle(pc, subtitle, content_yi);
  }
  const gap = PANEL_PADDING;
  const block_size = pc.layout.grid_s;
  const grid_bottom = pc.layout.separator_below_stats;
  const max_rows = Math.floor((grid_bottom - gap - content_yi) / (block_size + gap));
  const separators = () => drawOwnerSeparators(pc, single_owner_player_id);
  const per_player_refs: [number, UnitRef[]][] = groups
    .map(([player_id, units]): [number, UnitRef[]] => [
      player_id,
      units.flatMap((u) => [...u.units].map((internal_id) => ({ player_id, internal_id }))),
    ])
    .filter(([, refs]) => refs.length > 0);
  const tier1_row_groups = per_player_refs.map(([, refs]) => chunkBlocks(refs, ACTION_GRID_COLS));
  const tier1_rows = tier1_row_groups.reduce((sum, rows) => sum + rows.length, 0);
  if (tier1_rows > 0 && tier1_rows <= max_rows) {
    drawPerPlayerUnitRows(pc, per_player_refs, tier1_row_groups, tier1_rows, multi_player);
    separators();
    return;
  }
  const tier2_row_groups = chunkBlocks(
    per_player_refs.flatMap(([, refs]) => refs),
    ACTION_GRID_COLS
  );
  if (tier2_row_groups.length > 0 && tier2_row_groups.length <= max_rows) {
    layoutRows(pc, tier2_row_groups, (ref, p) => drawUnitRef(pc, ref, p));
    separators();
    return;
  }
  const id_blocks = groups.flatMap(([player_id, units]) =>
    units.filter((u) => u.units.size > 0).map((u) => ({ player_id, unit_id: u.unit_id, count: u.units.size }))
  );
  const tier3_row_groups = chunkBlocks(id_blocks, ACTION_GRID_COLS);
  if (tier3_row_groups.length > 0 && tier3_row_groups.length <= max_rows) {
    layoutRows(pc, tier3_row_groups, (b, p) => drawUnitCountBlock(pc, b.player_id, b.unit_id, b.count, p, block_size));
    separators();
    return;
  }
  const type_blocks = unitTypeBlocks(pc.risq, groups);
  const tier4_row_groups = chunkBlocks(type_blocks, ACTION_GRID_COLS);
  if (type_blocks.length > 0 && (tier4_row_groups.length <= max_rows || !multi_player)) {
    layoutRows(pc, tier4_row_groups, (b, p) =>
      drawUnitCountBlock(pc, b.player_id, b.representative_unit_id, b.count, p, block_size)
    );
    separators();
    return;
  }
  // only reachable for a multi-player selection
  const player_blocks = groups
    .map(([player_id, units]) => ({ player_id, count: units.reduce((s, u) => s + u.units.size, 0) }))
    .filter((b) => b.count > 0);
  layoutRows(pc, chunkBlocks(player_blocks, ACTION_GRID_COLS), (block, p) => {
    const color = pc.risq.getGame()?.players[block.player_id]?.color;
    pc.ctx.fillStyle = color ? color.getString() : 'rgba(255, 255, 255, 0.3)';
    pc.ctx.strokeStyle = 'black';
    pc.ctx.lineWidth = 1;
    drawRect(pc.ctx, p, block_size, block_size);
    drawUnitCountBadge(pc.ctx, block.count, p, block_size);
  });
  separators();
}

/** Rows are stacked upward from the stats separator, so the last row sits right above it */
function layoutRows<T>(pc: PanelDrawContext, row_groups: T[][], draw_item: (item: T, p: Point2D) => void) {
  const gap = PANEL_PADDING;
  const block_size = pc.layout.grid_s;
  let by = pc.layout.separator_below_stats - row_groups.length * (block_size + gap);
  for (const row of [...row_groups].reverse()) {
    let bx = pc.layout.grid_x0;
    for (const item of row) {
      draw_item(item, { x: bx, y: by });
      bx += block_size + gap;
    }
    by += block_size + gap;
  }
}

function drawUnitRef(pc: PanelDrawContext, ref: UnitRef, p: Point2D) {
  const unit = unitResolver(pc.risq)(ref.player_id, ref.internal_id);
  if (unit) {
    drawUnitImage(pc, unit, p, pc.layout.grid_s);
  }
}

/** Individual units with one row-run per player, tinted per player when more than one player is shown */
function drawPerPlayerUnitRows(
  pc: PanelDrawContext,
  per_player_refs: [number, UnitRef[]][],
  row_groups: UnitRef[][][],
  total_rows: number,
  multi_player: boolean
) {
  const gap = PANEL_PADDING;
  const block_size = pc.layout.grid_s;
  const content_w = ACTION_GRID_COLS * block_size + (ACTION_GRID_COLS - 1) * gap;
  let by = pc.layout.separator_below_stats - total_rows * (block_size + gap);
  for (const [i, [player_id]] of [...per_player_refs.entries()].reverse()) {
    const rows = row_groups[i];
    if (multi_player) {
      const color = pc.risq.getGame()?.players[player_id]?.color;
      pc.ctx.fillStyle = color
        ? `rgba(${color.getR()}, ${color.getG()}, ${color.getB()}, 0.12)`
        : 'rgba(255, 255, 255, 0.06)';
      pc.ctx.strokeStyle = 'transparent';
      drawRect(
        pc.ctx,
        { x: pc.layout.grid_x0 - 0.5 * gap, y: by - 0.5 * gap },
        content_w + gap,
        rows.length * (block_size + gap)
      );
    }
    for (const row of [...rows].reverse()) {
      let bx = pc.layout.grid_x0;
      for (const ref of row) {
        drawUnitRef(pc, ref, { x: bx, y: by });
        bx += block_size + gap;
      }
      by += block_size + gap;
    }
  }
}

interface TypeBlock {
  player_id: number;
  unit_type: RisqUnitType;
  representative_unit_id: number;
  count: number;
}

/** One block per (player, unit_type), merging unit_ids that share a type */
function unitTypeBlocks(risq: DwgRisq, groups: [number, UnitByTypeData[]][]): TypeBlock[] {
  const resolve = unitResolver(risq);
  const type_blocks_by_key = new Map<string, TypeBlock>();
  for (const [player_id, units] of groups) {
    for (const u of units) {
      if (u.units.size < 1) {
        continue;
      }
      const unit_type = resolve(player_id, [...u.units][0])?.unit_type ?? RisqUnitType.NONE;
      const key = `${player_id}:${unit_type}`;
      const existing = type_blocks_by_key.get(key);
      if (existing) {
        existing.count += u.units.size;
      } else {
        type_blocks_by_key.set(key, { player_id, unit_type, representative_unit_id: u.unit_id, count: u.units.size });
      }
    }
  }
  return [...type_blocks_by_key.values()];
}

export function drawUnit(pc: PanelDrawContext, unit: RisqUnit) {
  let yi = pc.frame.yi() + drawName(pc, unit.display_name);
  yi += drawHeaderImage(pc, yi, unitImage(unit.unit_id), pc.risq.getGame()?.players[unit.player_id]?.color);
  drawSeparator(pc, yi);
  pc.stats.draw(pc, pc.frame.yi() + 0.25 * pc.frame.h() + 6, unit);
  drawOwnerSeparators(pc, unit.player_id);
}

import { drawRect, drawText } from '../../../../../util/canvas_util';
import type { RectHoverData, RisqSpace, RisqZone } from '../../../model/types';
import { RisqVisibilityLevel } from '../../../model/types';
import { coordinateToIndex } from '../../../model/coordinates';
import { buildingImage } from '../../../rendering/assets/buildings';
import { resourceIcon } from '../../../rendering/assets/resources';
import { spaceOwnerColor, terrainTypeLabel } from '../../../rendering/terrain';
import type { PanelDrawContext } from './primitives';
import { drawName, drawSeparator, drawSubtitle } from './primitives';
import type { RisqSpaceHexagon } from './space_hexagon';
import { comboUnitIcon } from './space_view';
import { drawUnitImage } from './unit_views';

const MAX_IMAGE_SIZE = 36;
const UNIT_IMAGE_MULTIPLIER = 1.3;

/** Zone content: hex preview with this zone highlighted, its building/resource, owner, and individual units */
export function drawZone(pc: PanelDrawContext, data: { space: RisqSpace; zone: RisqZone }, hexagon: RisqSpaceHexagon) {
  const { ctx, frame, risq } = pc;
  const { space, zone } = data;
  let yi = frame.yi() + drawName(pc, space.display_name);
  const zone_label = zone.terrain_override_display_name ?? terrainTypeLabel(space.terrain_type);
  yi += drawSubtitle(pc, `${zone_label} zone`, yi);
  const separator_distance = 8;
  yi += hexagon.draw(pc, space, separator_distance, yi, coordinateToIndex(1, zone.coordinate));
  drawSeparator(pc, yi);
  yi += separator_distance;
  const units_per_row = Math.floor((0.8 * frame.w() - 1.6 * MAX_IMAGE_SIZE) / (UNIT_IMAGE_MULTIPLIER * MAX_IMAGE_SIZE));
  const economic_rows = Math.ceil(zone.economic_units.length / units_per_row);
  const military_rows = Math.ceil(zone.military_units.length / units_per_row);
  const unit_count_rows = pc.visibility === RisqVisibilityLevel.POOR && !!zone.unit_count ? 1 : 0;
  const rows = 2 + unit_count_rows + economic_rows + military_rows;
  const image_size = Math.min(
    MAX_IMAGE_SIZE,
    (1 / rows) * (0.6 * frame.h() - separator_distance - (rows - 1) * separator_distance)
  );
  ctx.fillStyle = 'black';
  const draw_row = (img: CanvasImageSource, text: string, hover_data?: RectHoverData) => {
    const ps = { x: frame.xi() + 0.1 * frame.w(), y: yi };
    const pe = { x: ps.x + 0.8 * frame.w(), y: ps.y + image_size };
    if (hover_data?.hovered) {
      ctx.strokeStyle = 'transparent';
      ctx.fillStyle = hover_data?.clicked ? 'rgba(250, 250, 250, 0.4)' : 'rgba(210, 210, 210, 0.25)';
      drawRect(ctx, ps, pe.x - ps.x, pe.y - ps.y);
    }
    ctx.drawImage(img, ps.x, ps.y, image_size, image_size);
    drawText(ctx, `: ${text}`, {
      p: { x: ps.x + image_size + 2, y: yi + 0.5 * image_size },
      w: 0.8 * frame.w() - image_size - 2,
      fill_style: 'black',
      align: 'left',
      baseline: 'middle',
      font: `bold ${image_size}px serif`,
    });
    if (!!hover_data) {
      hover_data.ps = ps;
      hover_data.pe = pe;
    }
  };
  if (!!zone.resource) {
    draw_row(resourceIcon(risq, zone.resource), zone.resource.display_name, zone.resource.hover_data);
  } else {
    const building_image = buildingImage(zone.building?.building_id, zone.building?.under_construction);
    const building_color = zone.building ? risq.getGame()?.players[zone.building.player_id]?.color : undefined;
    draw_row(
      building_color ? risq.getPlayerColoredIcon(building_image, building_color) : risq.getIcon(building_image),
      zone.building?.display_name ?? 'Empty Plot',
      zone.building?.hover_data
    );
  }
  yi += image_size + separator_distance;
  const owner_color = spaceOwnerColor(zone.ownership, risq.getGame()?.players ?? []);
  const owner_name =
    owner_color && zone.ownership !== undefined
      ? (risq.getGame()?.players[zone.ownership]?.player.nickname ?? 'Unknown')
      : '--Unclaimed--';
  const owner_ps = { x: frame.xi() + 0.1 * frame.w(), y: yi };
  ctx.fillStyle = owner_color ? owner_color.getString() : 'rgba(255, 255, 255, 0.3)';
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 1;
  drawRect(ctx, owner_ps, image_size, image_size);
  drawText(ctx, `: ${owner_name}`, {
    p: { x: owner_ps.x + image_size + 2, y: yi + 0.5 * image_size },
    w: 0.8 * frame.w() - image_size - 2,
    fill_style: 'black',
    align: 'left',
    baseline: 'middle',
    font: `bold ${image_size}px serif`,
  });
  yi += image_size + separator_distance;
  if (unit_count_rows > 0) {
    const combo_icon = comboUnitIcon(pc);
    if (combo_icon) {
      draw_row(combo_icon, zone.unit_count!.toString());
    }
    yi += image_size + separator_distance;
  }
  const unit_grid = (header_icon: string, unit_ids: number[], grid_rows: number) => {
    if (unit_ids.length === 0) {
      return;
    }
    draw_row(risq.getIcon(header_icon), '');
    const xi = frame.xi() + 0.1 * frame.w() + 0.6 * image_size;
    let i = 1;
    let j = 0;
    for (const u of unit_ids) {
      const unit = zone.units.get(u);
      if (!unit) {
        continue;
      }
      const p = { x: xi + i * UNIT_IMAGE_MULTIPLIER * image_size, y: yi + j * UNIT_IMAGE_MULTIPLIER * image_size };
      drawUnitImage(pc, unit, p, image_size);
      i++;
      if (i > units_per_row) {
        i = 1;
        j++;
      }
    }
    yi += grid_rows * UNIT_IMAGE_MULTIPLIER * image_size + separator_distance;
  };
  unit_grid('icons/villager64', zone.economic_units, economic_rows);
  unit_grid('icons/unit64', zone.military_units, military_rows);
}

import type { BoardTransformData } from '../../../../../util/canvas_board/canvas_board';
import { configDraw } from '../../../../../util/canvas_components/canvas_component';
import { drawRect } from '../../../../../util/canvas_util';
import type { Point2D } from '../../../../../util/objects2d';
import type { DwgRisq } from '../../../risq';
import { RisqTargetCategory } from '../../../model/types';

const POOL_CATEGORIES = [RisqTargetCategory.ECONOMIC, RisqTargetCategory.MILITARY, RisqTargetCategory.BUILDING];
const PADDING = 4;
const CONTAINER_GAP = 8;
const DRAG_THRESHOLD = 4;

function categoryIcon(category: RisqTargetCategory): string {
  switch (category) {
    case RisqTargetCategory.ECONOMIC:
      return 'icons/villager64';
    case RisqTargetCategory.MILITARY:
      return 'icons/unit64';
    case RisqTargetCategory.BUILDING:
      return 'icons/building64';
    default:
      return '';
  }
}

interface CategoryRect {
  category: RisqTargetCategory;
  x: number;
  y: number;
  w: number;
  h: number;
}

interface ControlLayout {
  pool: CategoryRect[];
  container: { x: number; y: number; w: number; h: number };
  chips: CategoryRect[];
}

/** Lets the player rank target categories: click a pool square to prioritize it, click a chip to unprioritize it, drag a chip to reorder */
export class RisqTargetPriorityControl {
  private risq: DwgRisq;
  private unit_internal_ids: number[];
  private p: Point2D = { x: 0, y: 0 };
  private control_w = 0;
  private square_size = 0;
  private priority: RisqTargetCategory[] = [];
  private last_mouse: Point2D = { x: 0, y: 0 };
  private hovering_category?: RisqTargetCategory;
  private pressed_pool_category?: RisqTargetCategory;
  private dragging_category?: RisqTargetCategory;
  private drag_order?: RisqTargetCategory[];
  private drag_start_x = 0;
  private drag_offset_x = 0;
  private dragged = false;

  constructor(risq: DwgRisq, unit_internal_ids: number[]) {
    this.risq = risq;
    this.unit_internal_ids = unit_internal_ids;
  }

  setUnitIds(unit_internal_ids: number[]) {
    this.unit_internal_ids = unit_internal_ids;
  }

  setPosition(p: Point2D) {
    this.p = p;
  }

  setSize(w: number, h: number) {
    this.control_w = w;
    this.square_size = h - 2 * PADDING;
  }

  dataRefreshed() {
    if (this.dragging_category !== undefined) {
      return;
    }
    const player = this.risq.getPlayer();
    this.priority = player?.units.get(this.unit_internal_ids[0])?.target_priority ?? [];
  }

  private poolCategories(): RisqTargetCategory[] {
    return POOL_CATEGORIES.filter((c) => !this.priority.includes(c));
  }

  private computeLayout(): ControlLayout {
    const s = this.square_size;
    const chip_y = this.p.y + PADDING;
    const pool_categories = this.poolCategories();
    const pool: CategoryRect[] = pool_categories.map((category, i) => ({
      category,
      x: this.p.x + i * (s + PADDING),
      y: chip_y,
      w: s,
      h: s,
    }));
    const pool_w = pool_categories.length > 0 ? pool_categories.length * (s + PADDING) - PADDING : 0;
    const container_x = this.p.x + pool_w + (pool_categories.length > 0 ? CONTAINER_GAP : 0);
    const chip_categories = this.dragging_category !== undefined && this.drag_order ? this.drag_order : this.priority;
    const container_w =
      2 * PADDING + (chip_categories.length > 0 ? chip_categories.length * (s + PADDING) - PADDING : 0);
    const chips: CategoryRect[] = chip_categories.map((category, i) => ({
      category,
      x: container_x + PADDING + i * (s + PADDING),
      y: chip_y,
      w: s,
      h: s,
    }));
    return { pool, container: { x: container_x, y: this.p.y, w: container_w, h: s + 2 * PADDING }, chips };
  }

  private pointIn(m: Point2D, r: CategoryRect): boolean {
    return m.x >= r.x && m.x <= r.x + r.w && m.y >= r.y && m.y <= r.y + r.h;
  }

  private updateDragOrder() {
    if (this.dragging_category === undefined || !this.drag_order) {
      return;
    }
    const layout = this.computeLayout();
    const dragged_center = this.clampedDragX(layout.container) + this.square_size / 2;
    const step = this.square_size + PADDING;
    const slot_center = (i: number) => layout.container.x + PADDING + i * step + this.square_size / 2;
    const current_index = this.drag_order.indexOf(this.dragging_category);
    const own_center = slot_center(current_index);
    let new_index = current_index;
    if (
      current_index < this.drag_order.length - 1 &&
      dragged_center > (own_center + slot_center(current_index + 1)) / 2
    ) {
      new_index = current_index + 1;
    } else if (current_index > 0 && dragged_center < (own_center + slot_center(current_index - 1)) / 2) {
      new_index = current_index - 1;
    }
    if (new_index !== current_index) {
      const others = this.drag_order.filter((c) => c !== this.dragging_category);
      others.splice(new_index, 0, this.dragging_category);
      this.drag_order = others;
    }
  }

  private sendPriority(priority: RisqTargetCategory[]) {
    this.risq.commands.setUnitTargetPriority(this.unit_internal_ids, priority);
  }

  draw(ctx: CanvasRenderingContext2D, transform: BoardTransformData) {
    configDraw(
      ctx,
      transform,
      { fill_style: 'transparent', stroke_width: 0, fixed_position: true },
      false,
      false,
      () => {
        const layout = this.computeLayout();
        for (const rect of layout.pool) {
          this.drawSquare(ctx, rect);
        }
        ctx.fillStyle = 'transparent';
        ctx.strokeStyle = 'rgba(60, 40, 20, 0.8)';
        ctx.lineWidth = 1;
        drawRect(
          ctx,
          { x: layout.container.x, y: layout.container.y },
          layout.container.w,
          layout.container.h,
          0.3 * layout.container.h
        );
        for (const rect of layout.chips) {
          const dragging_this = this.dragged && rect.category === this.dragging_category;
          this.drawSquare(ctx, dragging_this ? { ...rect, x: this.clampedDragX(layout.container) } : rect);
        }
      }
    );
  }

  private clampedDragX(container: { x: number; w: number }): number {
    const min_x = container.x + PADDING;
    const max_x = container.x + container.w - PADDING - this.square_size;
    return Math.max(min_x, Math.min(max_x, this.last_mouse.x - this.drag_offset_x));
  }

  private drawSquare(ctx: CanvasRenderingContext2D, rect: CategoryRect) {
    const dragging = rect.category === this.dragging_category && this.dragged;
    const hovered = rect.category === this.hovering_category;
    ctx.fillStyle = dragging
      ? 'rgba(210, 180, 130, 0.9)'
      : hovered
        ? 'rgba(210, 180, 130, 0.5)'
        : 'rgba(60, 40, 20, 0.15)';
    ctx.strokeStyle = 'rgba(60, 40, 20, 0.6)';
    ctx.lineWidth = 1;
    drawRect(ctx, { x: rect.x, y: rect.y }, rect.w, rect.h, 3);
    ctx.drawImage(this.risq.getIcon(categoryIcon(rect.category)), rect.x + 2, rect.y + 2, rect.w - 4, rect.h - 4);
  }

  mousemove(m: Point2D): boolean {
    this.last_mouse = m;
    if (this.dragging_category !== undefined) {
      if (!this.dragged && Math.abs(m.x - this.drag_start_x) > DRAG_THRESHOLD) {
        this.dragged = true;
      }
      if (this.dragged) {
        this.updateDragOrder();
      }
      return true;
    }
    const layout = this.computeLayout();
    const hit = [...layout.pool, ...layout.chips].find((r) => this.pointIn(m, r));
    this.hovering_category = hit?.category;
    return !!hit;
  }

  mousedown(_e: MouseEvent): boolean {
    const layout = this.computeLayout();
    const chip = layout.chips.find((r) => this.pointIn(this.last_mouse, r));
    if (chip) {
      this.dragging_category = chip.category;
      this.drag_order = [...this.priority];
      this.drag_start_x = this.last_mouse.x;
      this.drag_offset_x = this.last_mouse.x - chip.x;
      this.dragged = false;
      return true;
    }
    const pool = layout.pool.find((r) => this.pointIn(this.last_mouse, r));
    if (pool) {
      this.pressed_pool_category = pool.category;
      return true;
    }
    return false;
  }

  cancelInput(): void {
    this.hovering_category = undefined;
    this.pressed_pool_category = undefined;
    this.dragging_category = undefined;
    this.drag_order = undefined;
    this.dragged = false;
  }

  mouseup(_e: MouseEvent): void {
    if (this.dragging_category !== undefined) {
      if (this.dragged && this.drag_order) {
        this.priority = this.drag_order;
        this.sendPriority(this.drag_order);
      } else {
        this.sendPriority(this.priority.filter((c) => c !== this.dragging_category));
      }
      this.dragging_category = undefined;
      this.drag_order = undefined;
      this.dragged = false;
      return;
    }
    if (this.pressed_pool_category !== undefined) {
      const layout = this.computeLayout();
      const still_hovering = layout.pool.some(
        (r) => r.category === this.pressed_pool_category && this.pointIn(this.last_mouse, r)
      );
      if (still_hovering) {
        this.sendPriority([...this.priority, this.pressed_pool_category]);
      }
      this.pressed_pool_category = undefined;
    }
  }
}

