      false
    );
    this.input = new RisqLeftPanelInput(risq, this, this.hexagon, this.space_view, this.stats);
    this.resolveSize();
  }

  private shownData(): LeftPanelData | undefined {
    return this.showing ? this.data : undefined;
  }

  private refreshActionButtons() {
    this.buttons = [];
    this.target_priority_control = undefined;
    this.refreshOrderRows();
    if (!this.isOrderable()) {
      this.resolveSize();
      return;
    }
    const actions = buildPanelActions(this.risq, this.data);
    this.buttons = actions.buttons;
    this.target_priority_control = this.risq.session.givingOrders() ? actions.target_priority_control : undefined;
    this.resolveSize();
    for (const button of this.buttons) {
      button.dataRefreshed();
      if (!this.risq.session.givingOrders()) {
        button.disable();
      }
    }
    this.target_priority_control?.dataRefreshed();
  }

  private showOrderRows(): boolean {
    return orderListSubjects(this.data, this.risq.getPlayer()?.player.player_id).kind !== undefined;
  }

  private refreshOrderRows() {
    // an empty list never matches a real internal_id, so an unowned/non-orderable selection just shows an empty list
    const subjects = orderListSubjects(this.data, this.risq.getPlayer()?.player.player_id);
    this.order_rows_list.setSubject(subjects.ids, subjects.kind);
    this.order_rows_list.refresh();
    const player = this.risq.getPlayer();
    if (this.risq.session.givingOrders() && !!player && !player.orders_submitted) {
      this.order_rows_list.enable();
    } else {
      this.order_rows_list.disable();
    }
  }

  private statsSectionEnd(): number {
    const building = this.data?.data_type === LeftPanelDataType.BUILDING ? this.data.data : undefined;
    const has_stats = this.data?.data_type === LeftPanelDataType.UNIT || !!building;
    if (!has_stats && !this.isUnit()) {
      return this.yi() + 0.5 * this.size.y - PANEL_PADDING;
    }
    return this.yi() + 0.25 * this.size.y + 6 + RisqStatsView.height(this.risq, building);
  }

  resolveSize() {
    const h = Math.min(4 * this.config.w, this.risq.viewport.canvasSize().height);
    this.size = { x: h / 3, y: h };
    this.close_button.setPosition({ x: this.size.x, y: this.yi() + 0.5 * this.close_button.h() });
    const action_rows = this.isUnit() ? UNIT_ACTION_GRID_ROWS : BUILDING_ACTION_GRID_ROWS;
    const garrison_capacity =
      this.isBuilding() && this.data?.data_type === LeftPanelDataType.BUILDING ? this.data.data.garrison_capacity : 0;
    const P = PANEL_PADDING;
    const min_orders_height =
      ORDER_FILTER_BAR_H + 2 * this.order_rows_list.getPadding() + 2 * ORDER_ROW_H + this.order_rows_list.getGap();
    this.layout = computeLayout(this, this.statsSectionEnd(), action_rows, garrison_capacity, min_orders_height);
    const s = this.layout.grid_s;
    for (const button of this.buttons) {
      button.setSize(s, s);
      button.setPosition(gridCell(this.layout, button.row, button.col));
    }
    this.target_priority_control?.setSize(3 * s + 2 * PANEL_PADDING, s);
    this.target_priority_control?.setPosition(gridCell(this.layout, 2, 2));
    const orders_y0 = this.layout.grid_bottom_separator + P;
    this.order_rows_list.setAllSizes(
      Math.min(0.1 * this.w(), 16),
      { x: this.xi() + P, y: orders_y0 },
      this.w() - 2 * P,
      Math.max(min_orders_height, this.yi() + this.size.y - orders_y0 - P)
    );
  }

  isHovering(): boolean {
    return this.hovering;
  }

  setHovering(hovering: boolean): void {
    this.hovering = hovering;
  }

  isClicking(): boolean {
    return false;
  }

  setClicking(clicking: boolean): void {
    if (!clicking) {
      for (const component of [this.close_button, this.order_rows_list, ...this.buttons]) {
        component.setClicking(false);
        component.setHovering(false);
      }
      this.target_priority_control?.cancelInput();
      this.input.cancelInput();
    }
  }

  isShowing(): boolean {
    return this.showing;
  }

  getData(): LeftPanelData | undefined {
    return this.data;
  }

  refreshData() {
    if (!this.showing || !this.data) {
      this.refreshActionButtons();
      return;
    }
    const resolved = resolveSelectionData(this.data, this.risq.session);
    if (!resolved) {
      this.close();
      return;
    }
    this.data = resolved.data;
    this.visibility = resolved.visibility;
    this.refreshActionButtons();
    this.resolveSize();
  }

  dataRefreshed() {
    this.refreshData();
  }

  triggerAction(action: RisqHotkeyAction): boolean {
    if (!this.isShowing() || !this.isOrderable() || !this.risq.session.canGiveOrders()) {
      return false;
    }
    const button = this.buttons.find((b) => b.matchesAction(action) && !b.isDisabled());
    if (button) {
      button.execute();
      return true;
    }
    return false;
  }

  triggerProducible(kind: string, id: number, ctrl_held = false): boolean {
    if (!this.isShowing() || !this.isOrderable() || !this.risq.session.canGiveOrders()) {
      return false;
    }
    const button = this.buttons.find((b) => b.matchesProducible(kind, id) && !b.isDisabled());
    if (button) {
      button.execute(ctrl_held);
      return true;
    }
    return false;
  }

  isOrderable(): boolean {
    return isOrderable(this.shownData(), this.visibility, this.risq.getPlayer()?.player.player_id ?? -1);
  }

  isUnit(): boolean {
    return isUnitSelection(this.shownData());
  }

  hasVillager(): boolean {
    return hasVillager(this.shownData());
  }

  hasMilitary(): boolean {
    return hasMilitary(this.shownData());
  }

  isOnlyVillagers(): boolean {
    return isOnlyVillagers(this.shownData());
  }

  isOnlyMilitary(): boolean {
    return isOnlyMilitary(this.shownData());
  }

  isOnlyGarrisoned(): boolean {
    return isOnlyGarrisoned(this.shownData(), unitResolver(this.risq));
  }

  isBuilding(): boolean {
    return this.shownData()?.data_type === LeftPanelDataType.BUILDING;
  }

  close() {
    this.showing = false;
    this.visibility = undefined;
    this.data = undefined;
    this.hexagon.clearHoveredZone();
    this.stats.clearHover();
    this.buttons = [];
  }

  openPanel(open_data: LeftPanelData, visibility: number) {
    if (visibility < RisqVisibilityLevel.FOG) {
      return; // not explored
    }
    if (visibility < RisqVisibilityLevel.GOOD && UNIT_DATA_TYPES.includes(open_data.data_type)) {
      return; // units not individually identifiable yet
    }
    this.risq.armed.disarmAll();
    this.input.reset();
    this.hover_stale = true;
    this.visibility = visibility;
    this.data = open_data;
    this.showing = true;
    const normalized = normalizeSelection(open_data, unitResolver(this.risq));
    if (normalized) {
      this.data = normalized;
    } else {
      this.close();
    }
    this.refreshActionButtons();
    this.risq.pointer.recalculate();
  }

  /** Opens the shown space's villagers or military units as a unit selection */
  private openSpaceUnitsRow(economic: boolean): void {
    if (this.data?.data_type !== LeftPanelDataType.SPACE) {
      return;
    }
    const space = this.data.data;
    this.openPanel(
      {
        data_type: LeftPanelDataType.UNITS,
        data: { space, units_by_player: unitsByPlayerFiltered(space.units ?? new Map(), economic) },
      },
      this.visibility ?? 0
    );
  }

  draw(ctx: CanvasRenderingContext2D, transform: BoardTransformData, dt: number) {
    if (!this.isShowing()) {
      return;
    }
    const pc: PanelDrawContext = {
      ctx,
      risq: this.risq,
      frame: this,
      layout: this.layout,
      visibility: this.visibility ?? 0,
      stats: this.stats,
    };
    configDraw(
      ctx,
      transform,
      { fill_style: this.config.background, stroke_style: 'transparent', stroke_width: 0, fixed_position: true },
      false,
      false,
      () => {
        drawRect(ctx, { x: this.xi(), y: this.yi() }, this.w(), this.h());
        ctx.save();
        ctx.beginPath();
        ctx.rect(this.xi(), this.yi(), this.w(), this.h());
        ctx.clip();
        this.drawContent(pc);
        ctx.restore();
      }
    );
    const data = this.data;
    const stats_subject =
      data?.data_type === LeftPanelDataType.UNIT || data?.data_type === LeftPanelDataType.BUILDING
        ? data.data
        : undefined;
    this.stats.drawTooltips(ctx, transform, this.risq, dt, stats_subject);
    if (data?.data_type === LeftPanelDataType.SPACE || data?.data_type === LeftPanelDataType.ZONE) {
      const space = data.data_type === LeftPanelDataType.SPACE ? data.data : data.data.space;
      this.hexagon.drawTooltip(ctx, transform, this.risq, dt, space);
    }
    ctx.beginPath();
    for (const button of this.buttons) {
      button.draw(ctx, transform, dt);
      button.drawTooltip(ctx, transform, this.risq, dt);
    }
    this.target_priority_control?.draw(ctx, transform);
    if (data?.data_type === LeftPanelDataType.SPACE && (this.visibility ?? 0) > RisqVisibilityLevel.POOR) {
      this.space_view.drawRowButtons(ctx, transform, dt);
    }
    if (this.showOrderRows()) {
      this.order_rows_list.draw(ctx, transform, dt);
    }
    ctx.beginPath();
    this.close_button.draw(ctx, transform, dt);
    if (this.hover_stale) {
      this.hover_stale = false;
      this.risq.pointer.recalculate();
    }
  }

  private drawContent(pc: PanelDrawContext) {
    switch (this.data?.data_type) {
      case LeftPanelDataType.RESOURCE:
        drawResource(pc, this.data.data);
        break;
      case LeftPanelDataType.BUILDING:
        drawBuilding(pc, this.data.data);
        break;
      case LeftPanelDataType.SPACE:
        this.space_view.draw(pc, this.data.data, this.hexagon);
        break;
      case LeftPanelDataType.REGION:
        drawRegion(pc, this.data.data);
        break;
      case LeftPanelDataType.ZONE:
        drawZone(pc, this.data.data, this.hexagon);
        break;
      case LeftPanelDataType.MULTIPLE_PLAYERS_UNITS:
        drawUnitsGeneric(pc, this.data.data.units_by_player);
        break;
      case LeftPanelDataType.UNITS_BY_TYPE:
      case LeftPanelDataType.ECONOMIC_UNITS:
      case LeftPanelDataType.MILITARY_UNITS:
        if (this.data.data.units.length > 0) {
          drawUnitsGeneric(pc, [[this.data.data.units[0].player_id, this.data.data.units]]);
        }
        break;
      case LeftPanelDataType.UNITS:
        err('LeftPanelDataType.UNITS should have been converted by normalizeSelection', this.data);
        break;
      case LeftPanelDataType.UNIT:
        drawUnit(pc, this.data.data);
        break;
      case LeftPanelDataType.FOUNDATION:
        drawFoundation(pc, this.data.data);
        break;
      default:
        err('Unknown data type for left panel', this.data);
        break;
    }
  }

  scroll(dy: number, mode: number): boolean {
    if (this.showOrderRows() && this.order_rows_list.isHovering()) {
      return this.order_rows_list.scroll(dy, mode);
    }
    return false;
  }

  mousemove(canvas: Point2D, screen: Point2D, transform: BoardTransformData): boolean {
    if (this.close_button.mousemove(canvas, screen, transform)) {
      return true;
    }
    this.hovering = screen.x > this.xi() && screen.y > this.yi() && screen.x < this.xf() && screen.y < this.yf();
    for (const button of this.buttons) {
      button.mousemove(canvas, screen, transform);
    }
    this.target_priority_control?.mousemove(screen);
    if (this.showOrderRows()) {
      this.order_rows_list.mousemove(canvas, screen, transform);
    }
    this.input.mousemove(this.data, canvas, screen, transform);
    return this.isHovering();
  }

  mousedown(e: MouseEvent): boolean {
    if (this.close_button.mousedown(e)) {
      return true;
    }
    this.input.mousedown(this.data, e);
    for (const button of this.buttons) {
      button.mousedown(e);
    }
    this.target_priority_control?.mousedown(e);
    if (this.showOrderRows()) {
      this.order_rows_list.mousedown(e);
    }
    return this.isHovering();
  }

  mouseup(e: MouseEvent) {
    this.close_button.mouseup(e);
    if (this.showOrderRows()) {
      this.order_rows_list.mouseup(e);
    }
    this.input.mouseup(this.data, this.visibility ?? 0, e);
    for (const button of this.buttons) {
      button.mouseup(e);
    }
    this.target_priority_control?.mouseup(e);
  }

  xi(): number {
    return 0;
  }
  yi(): number {
    return 0.5 * (this.risq.viewport.canvasSize().height - this.size.y);
  }
  xf(): number {
    return this.showing ? this.xi() + this.w() : 0;
  }
  yf(): number {
    return this.showing ? this.yi() + this.h() : 0;
  }
  xc(): number {
    return this.xi() + 0.5 * this.w();
  }
  yc(): number {
    return this.yi() + 0.5 * this.h();
  }
  w(): number {
    return this.size.x;
  }
  h(): number {
    return this.size.y;
  }
}

import type { BoardTransformData } from '../../../../util/canvas_board/canvas_board';
import type { Point2D } from '../../../../util/objects2d';
import type { RisqBuilding, RisqSpace, RisqUnit, UnitByTypeData } from '../../model/types';
import { groupUnitsByType } from '../../model/unit_groups';
import type { DwgRisq } from '../../risq';
import type { RisqSpaceHexagon } from './content/space_hexagon';
import type { RisqSpaceView } from './content/space_view';
import type { RisqStatsView } from './content/stats_view';
import { garrisonedUnits } from './content/unit_views';
import type { RisqLeftPanel } from './left_panel';
import type { HoveredObject, LeftPanelData } from './left_panel_data';
import { HoverableObjectType, LeftPanelDataType } from './left_panel_data';
import { unitResolver } from './selection_queries';

/** Hover and click handling for the panel's content: hex zones, unit tiles, zone rows, and stats rows */
export class RisqLeftPanelInput {
  private hovered_object?: HoveredObject;

  constructor(
    private risq: DwgRisq,
    private panel: RisqLeftPanel,
    private hexagon: RisqSpaceHexagon,
    private space_view: RisqSpaceView,
    private stats: RisqStatsView
  ) {}

  /** Clears the hovered object's flags; the next draw lays out fresh hover rects */
  reset() {
    if (this.hovered_object) {
      this.hovered_object.object.hover_data.hovered = false;
      this.hovered_object.object.hover_data.clicked = false;
    }
    this.hovered_object = undefined;
  }

  cancelInput(): void {
    this.reset();
    this.hexagon.clearHoveredZone();
    this.space_view.cancelInput();
  }

  private objectHoverLogic(m: Point2D, hovered: HoveredObject) {
    const object = hovered.object;
    if (
      m.x < object.hover_data.ps.x ||
      m.y < object.hover_data.ps.y ||
      m.x > object.hover_data.pe.x ||
      m.y > object.hover_data.pe.y
    ) {
      object.hover_data.hovered = false;
      return;
    }
    const previous = this.hovered_object;
    if (!!previous && (previous.object.internal_id !== object.internal_id || previous.type !== hovered.type)) {
      previous.object.hover_data.hovered = false;
      previous.object.hover_data.clicked = false;
    }
    object.hover_data.hovered = true;
    this.hovered_object = hovered;
  }

  private hoverUnits(m: Point2D, player_id_units: [number, Iterable<number>][]) {
    const resolve = unitResolver(this.risq);
    for (const [player_id, unit_ids] of player_id_units) {
      for (const unit_id of unit_ids) {
        const unit = resolve(player_id, unit_id);
        if (unit) {
          this.objectHoverLogic(m, { type: HoverableObjectType.UNIT, object: unit });
        }
      }
    }
  }

  mousemove(data: LeftPanelData | undefined, canvas: Point2D, screen: Point2D, transform: BoardTransformData) {
    const m = screen;
    switch (data?.data_type) {
      case LeftPanelDataType.SPACE:
        this.hexagon.mousemove(m, data.data);
        this.space_view.mousemove(canvas, screen, transform);
        break;
      case LeftPanelDataType.ZONE: {
        this.hexagon.mousemove(m, data.data.space);
        const zone = data.data.zone;
        for (const unit_id of [...zone.economic_units, ...zone.military_units]) {
          const unit = zone.units.get(unit_id);
          if (unit) {
            this.objectHoverLogic(m, { type: HoverableObjectType.UNIT, object: unit });
          }
        }
        if (zone.resource) {
          this.objectHoverLogic(m, { type: HoverableObjectType.RESOURCE, object: zone.resource });
        }
        if (zone.building) {
          this.objectHoverLogic(m, { type: HoverableObjectType.BUILDING, object: zone.building });
        }
        break;
      }
      case LeftPanelDataType.MULTIPLE_PLAYERS_UNITS:
        this.hoverUnits(
          m,
          data.data.units_by_player.flatMap(([, units]) =>
            units.map((u): [number, Set<number>] => [u.player_id, u.units])
          )
        );
        break;
      case LeftPanelDataType.UNITS_BY_TYPE:
      case LeftPanelDataType.ECONOMIC_UNITS:
      case LeftPanelDataType.MILITARY_UNITS:
        this.hoverUnits(
          m,
          data.data.units.map((u): [number, Set<number>] => [u.player_id, u.units])
        );
        break;
      case LeftPanelDataType.UNIT:
        this.stats.mousemove(m);
        break;
      case LeftPanelDataType.BUILDING:
        this.stats.mousemove(m);
        for (const unit of garrisonedUnits(this.risq, data.data)) {
          this.objectHoverLogic(m, { type: HoverableObjectType.UNIT, object: unit });
        }
        break;
      default:
        break;
    }
  }

  mousedown(data: LeftPanelData | undefined, e: MouseEvent) {
    const hovered_zone = this.hexagon.hoveredZone();
    switch (data?.data_type) {
      case LeftPanelDataType.SPACE:
      case LeftPanelDataType.ZONE:
        if (!!hovered_zone) {
          hovered_zone.clicked = true;
        } else if (!!this.hovered_object) {
          this.hovered_object.object.hover_data.clicked = true;
        } else if (data.data_type === LeftPanelDataType.SPACE) {
          this.space_view.mousedown(e);
        }
        break;
      case LeftPanelDataType.UNITS:
      case LeftPanelDataType.MULTIPLE_PLAYERS_UNITS:
      case LeftPanelDataType.UNITS_BY_TYPE:
      case LeftPanelDataType.ECONOMIC_UNITS:
      case LeftPanelDataType.MILITARY_UNITS:
      case LeftPanelDataType.BUILDING:
        if (!!this.hovered_object) {
          this.hovered_object.object.hover_data.clicked = true;
        }
        break;
      default:
        break;
    }
  }

  mouseup(data: LeftPanelData | undefined, visibility: number, e: MouseEvent) {
    switch (data?.data_type) {
      case LeftPanelDataType.SPACE:
      case LeftPanelDataType.ZONE:
        this.worldMouseup(data, visibility, e);
        break;
      case LeftPanelDataType.MULTIPLE_PLAYERS_UNITS: {
        const unit = this.releasedUnit();
        if (unit) {
          this.unitGridClick(data.data.space, data.data.units_by_player, unit, visibility, e);
        }
        break;
      }
      case LeftPanelDataType.UNITS_BY_TYPE:
      case LeftPanelDataType.ECONOMIC_UNITS:
      case LeftPanelDataType.MILITARY_UNITS: {
        const unit = this.releasedUnit();
        if (unit) {
          this.unitGridClick(data.data.space, [[unit.player_id, data.data.units]], unit, visibility, e);
        }
        break;
      }
      case LeftPanelDataType.BUILDING: {
        const unit = this.releasedUnit();
        if (unit) {
          this.garrisonedUnitClick(data.data, unit, visibility, e);
        }
        break;
      }
      default:
        break;
    }
  }

  /** The pressed unit tile if it was released while still hovered; always clears its pressed state */
  private releasedUnit(): RisqUnit | undefined {
    if (this.hovered_object?.type !== HoverableObjectType.UNIT || !this.hovered_object.object.hover_data.clicked) {
      return undefined;
    }
    const unit = this.hovered_object.object;
    unit.hover_data.clicked = false;
    return unit.hover_data.hovered ? unit : undefined;
  }

  /** Clicking a zone in the hex opens it (or its space if it's the zone already shown); clicking a zone row object opens it */
  private worldMouseup(
    data: Extract<LeftPanelData, { data_type: LeftPanelDataType.SPACE | LeftPanelDataType.ZONE }>,
    visibility: number,
    e: MouseEvent
  ) {
    const space: RisqSpace = data.data_type === LeftPanelDataType.SPACE ? data.data : data.data.space;
    const hovered_zone = this.hexagon.hoveredZone();
    if (!!hovered_zone && hovered_zone.clicked) {
      hovered_zone.clicked = false;
      if (!hovered_zone.hovered) {
        return;
      }
      if (data.data_type === LeftPanelDataType.ZONE && hovered_zone.coordinate_key === data.data.zone.coordinate_key) {
        this.panel.openPanel({ data_type: LeftPanelDataType.SPACE, data: space }, visibility);
      } else {
        this.panel.openPanel({ data_type: LeftPanelDataType.ZONE, data: { space, zone: hovered_zone } }, visibility);
      }
    } else if (!!this.hovered_object && this.hovered_object.object.hover_data.clicked) {
      const hovered = this.hovered_object;
      hovered.object.hover_data.clicked = false;
      if (hovered.object.hover_data.hovered) {
        this.zoneObjectClick(data, space, hovered, visibility, e);
      }
    } else if (data.data_type === LeftPanelDataType.SPACE) {
      this.space_view.mouseup(e);
    }
  }

  private zoneObjectClick(
    data: LeftPanelData,
    space: RisqSpace,
    hovered: HoveredObject,
    visibility: number,
    e: MouseEvent
  ) {
    switch (hovered.type) {
      case HoverableObjectType.UNIT:
        if (e.shiftKey && data.data_type === LeftPanelDataType.ZONE) {
          const units_by_type = data.data.zone.units_by_type.get(hovered.object.player_id);
          if (!!units_by_type) {
            const units = [...units_by_type.values()].filter((u) => u.unit_id === hovered.object.unit_id);
            this.panel.openPanel({ data_type: LeftPanelDataType.UNITS_BY_TYPE, data: { space, units } }, visibility);
          }
        } else {
          this.panel.openPanel({ data_type: LeftPanelDataType.UNIT, data: hovered.object }, visibility);
        }
        break;
      case HoverableObjectType.BUILDING:
        this.panel.openPanel({ data_type: LeftPanelDataType.BUILDING, data: hovered.object }, visibility);
        break;
      case HoverableObjectType.RESOURCE:
        this.panel.openPanel({ data_type: LeftPanelDataType.RESOURCE, data: hovered.object }, visibility);
        break;
      default:
        break;
    }
  }

  /** Shift narrows the garrison selection to the clicked unit's type; otherwise selects just the clicked unit */
  private garrisonedUnitClick(building: RisqBuilding, hovered_unit: RisqUnit, visibility: number, e: MouseEvent) {
    if (e.shiftKey) {
      const units_map = this.risq.getGame()?.players[building.player_id]?.units ?? new Map<number, RisqUnit>();
      const units = groupUnitsByType(units_map, building.garrisoned_units ?? []).filter(
        (u) => u.unit_id === hovered_unit.unit_id
      );
      this.panel.openPanel({ data_type: LeftPanelDataType.UNITS_BY_TYPE, data: { units } }, visibility);
    } else {
      this.panel.openPanel({ data_type: LeftPanelDataType.UNIT, data: hovered_unit }, visibility);
    }
  }

  /** Shift keeps only the clicked unit's type; Ctrl removes the clicked unit; a plain click selects just that unit */
  private unitGridClick(
    space: RisqSpace | undefined,
    groups: [number, UnitByTypeData[]][],
    hovered_unit: RisqUnit,
    visibility: number,
    e: MouseEvent
  ) {
    if (e.shiftKey) {
      const player_units = groups.find(([player_id]) => player_id === hovered_unit.player_id)?.[1] ?? [];
      const units_by_player = new Map<number, UnitByTypeData[]>([
        [hovered_unit.player_id, player_units.filter((u) => u.unit_id === hovered_unit.unit_id)],
      ]);
      this.openUnitGroups(space, units_by_player, visibility);
    } else if (e.ctrlKey) {
      const units_by_player = new Map<number, UnitByTypeData[]>();
      for (const [player_id, units] of groups) {
        const new_units = units
          .map((u) => ({ ...u, units: new Set([...u.units].filter((id) => id !== hovered_unit.internal_id)) }))
          .filter((u) => u.units.size > 0);
        if (new_units.length > 0) {
          units_by_player.set(player_id, new_units);
        }
      }
      this.openUnitGroups(space, units_by_player, visibility);
    } else {
      this.panel.openPanel({ data_type: LeftPanelDataType.UNIT, data: hovered_unit }, visibility);
    }
  }

  private openUnitGroups(
    space: RisqSpace | undefined,
    units_by_player: Map<number, UnitByTypeData[]>,
    visibility: number
  ) {
    if (space) {
      this.panel.openPanel({ data_type: LeftPanelDataType.UNITS, data: { space, units_by_player } }, visibility);
    } else {
      const units = [...units_by_player.values()].flat();
      this.panel.openPanel({ data_type: LeftPanelDataType.UNITS_BY_TYPE, data: { units } }, visibility);
    }
  }
}

import { equalsPoint2D } from '../../../../util/objects2d';
import type { RisqSession } from '../../application/session';
import { invertPair } from '../../model/coordinates';
import type { RisqUnit, UnitByTypeData } from '../../model/types';
import { RisqUnitType, RisqVisibilityLevel } from '../../model/types';
import { groupUnitsByType } from '../../model/unit_groups';
import type { DwgRisq } from '../../risq';
import type { LeftPanelData, PlayerUnitsDrawData, UnitsDrawData } from './left_panel_data';
import { LeftPanelDataType } from './left_panel_data';

export type UnitResolver = (player_id: number, internal_id: number) => RisqUnit | undefined;

export function unitResolver(risq: DwgRisq): UnitResolver {
  return (player_id, internal_id) => risq.getGame()?.players[player_id]?.units.get(internal_id);
}

/** Whether the selection belongs to the local player and is visible enough to take orders */
export function isOrderable(
  data: LeftPanelData | undefined,
  visibility: number | undefined,
  player_id: number
): boolean {
  if (!data || !visibility || visibility < RisqVisibilityLevel.GOOD || player_id < 0) {
    return false;
  }
  switch (data.data_type) {
    case LeftPanelDataType.BUILDING:
    case LeftPanelDataType.UNIT:
    case LeftPanelDataType.FOUNDATION:
      return data.data.player_id === player_id;
    case LeftPanelDataType.UNITS_BY_TYPE:
    case LeftPanelDataType.ECONOMIC_UNITS:
    case LeftPanelDataType.MILITARY_UNITS:
      return data.data.units.length > 0 && data.data.units[0].player_id === player_id;
    default:
      return false;
  }
}

export function isUnitSelection(data: LeftPanelData | undefined): boolean {
  switch (data?.data_type) {
    case LeftPanelDataType.MULTIPLE_PLAYERS_UNITS:
    case LeftPanelDataType.UNITS:
    case LeftPanelDataType.UNITS_BY_TYPE:
    case LeftPanelDataType.ECONOMIC_UNITS:
    case LeftPanelDataType.MILITARY_UNITS:
    case LeftPanelDataType.UNIT:
      return true;
    default:
      return false;
  }
}

function isEconomic(t: { unit_type: RisqUnitType }): boolean {
  return t.unit_type === RisqUnitType.ECONOMIC;
}

/** Whether any selected unit (for some=true) or every selected unit (some=false) matches; multi-player selections only count for some */
function unitTypesMatch(
  data: LeftPanelData | undefined,
  matches: (t: { unit_type: RisqUnitType }) => boolean,
  some: boolean
): boolean {
  switch (data?.data_type) {
    case LeftPanelDataType.UNIT:
      return matches(data.data);
    case LeftPanelDataType.MULTIPLE_PLAYERS_UNITS:
      return some && data.data.units_by_player.some(([, units]) => units.some(matches));
    case LeftPanelDataType.UNITS_BY_TYPE:
    case LeftPanelDataType.ECONOMIC_UNITS:
    case LeftPanelDataType.MILITARY_UNITS:
      return some ? data.data.units.some(matches) : data.data.units.every(matches);
    default:
      return false;
  }
}

export function hasVillager(data: LeftPanelData | undefined): boolean {
  return unitTypesMatch(data, isEconomic, true);
}

export function hasMilitary(data: LeftPanelData | undefined): boolean {
  return unitTypesMatch(data, (t) => !isEconomic(t), true);
}

export function isOnlyVillagers(data: LeftPanelData | undefined): boolean {
  return unitTypesMatch(data, isEconomic, false);
}

export function isOnlyMilitary(data: LeftPanelData | undefined): boolean {
  return unitTypesMatch(data, (t) => !isEconomic(t), false);
}

export function isOnlyGarrisoned(data: LeftPanelData | undefined, resolve: UnitResolver): boolean {
  const all_garrisoned = (player_id: number, t: UnitByTypeData): boolean =>
    [...t.units].every((id) => resolve(player_id, id)?.garrisoned_in !== undefined);
  switch (data?.data_type) {
    case LeftPanelDataType.UNIT:
      return data.data.garrisoned_in !== undefined;
    case LeftPanelDataType.MULTIPLE_PLAYERS_UNITS:
      return data.data.units_by_player.every(([player_id, units]) => units.every((t) => all_garrisoned(player_id, t)));
    case LeftPanelDataType.UNITS_BY_TYPE:
    case LeftPanelDataType.ECONOMIC_UNITS:
    case LeftPanelDataType.MILITARY_UNITS:
      return data.data.units.every((t) => all_garrisoned(t.player_id, t));
    default:
      return false;
  }
}

/** The subjects whose orders the panel's order list shows; empty when the selection has none of the local player's */
export function orderListSubjects(
  data: LeftPanelData | undefined,
  own_player_id: number | undefined
): { ids: number[]; kind?: 'unit' | 'building' } {
  switch (data?.data_type) {
    case LeftPanelDataType.UNIT:
    case LeftPanelDataType.BUILDING:
      if (data.data.player_id !== own_player_id) {
        return { ids: [] };
      }
      return { ids: [data.data.internal_id], kind: data.data_type === LeftPanelDataType.UNIT ? 'unit' : 'building' };
    case LeftPanelDataType.UNITS_BY_TYPE:
    case LeftPanelDataType.ECONOMIC_UNITS:
    case LeftPanelDataType.MILITARY_UNITS:
      if (!data.data.units.some((u) => u.player_id === own_player_id)) {
        return { ids: [] };
      }
      return { ids: data.data.units.flatMap((u) => [...u.units]), kind: 'unit' };
    default:
      return { ids: [] };
  }
}

/** Collapses a UNITS selection into its most specific data type; undefined when nothing selectable remains */
export function normalizeSelection(data: LeftPanelData, resolve: UnitResolver): LeftPanelData | undefined {
  switch (data.data_type) {
    case LeftPanelDataType.UNITS_BY_TYPE:
    case LeftPanelDataType.ECONOMIC_UNITS:
    case LeftPanelDataType.MILITARY_UNITS:
      return normalizePlayerUnits(data.data, resolve);
    case LeftPanelDataType.UNITS:
      return normalizeUnits(data.data, resolve);
    default:
      return data;
  }
}

function normalizeUnits(data: UnitsDrawData, resolve: UnitResolver): LeftPanelData | undefined {
  if (!data || !data.space || !data.units_by_player || data.units_by_player.size < 1) {
    return undefined;
  }
  const new_data: [number, UnitByTypeData[]][] = [];
  for (const [player_id, units_by_type] of data.units_by_player.entries()) {
    if (player_id < 0 || units_by_type.length < 1) {
      continue;
    }
    new_data.push([player_id, units_by_type.filter((u) => u.units.size > 0)]);
  }
  if (new_data.length < 1) {
    return undefined;
  }
  if (new_data.length > 1) {
    return {
      data_type: LeftPanelDataType.MULTIPLE_PLAYERS_UNITS,
      data: { space: data.space, units_by_player: new_data },
    };
  }
  return normalizePlayerUnits({ space: data.space, units: new_data[0][1] }, resolve);
}

/** A single unit becomes UNIT; otherwise the type reflects whether the units are economic, military, or mixed */
function normalizePlayerUnits(data: PlayerUnitsDrawData, resolve: UnitResolver): LeftPanelData | undefined {
  if (data.units.length === 1 && data.units[0].units.size === 1) {
    const unit = resolve(data.units[0].player_id, [...data.units[0].units.values()][0]);
    return unit ? { data_type: LeftPanelDataType.UNIT, data: unit } : undefined;
  }
  const new_data = { space: data.space, units: data.units };
  const has_economic_units = data.units.some(isEconomic);
  const has_military_units = data.units.some((u) => !isEconomic(u));
  if (has_economic_units && has_military_units) {
    return { data_type: LeftPanelDataType.UNITS_BY_TYPE, data: new_data };
  } else if (has_economic_units) {
    return { data_type: LeftPanelDataType.ECONOMIC_UNITS, data: new_data };
  } else if (has_military_units) {
    return { data_type: LeftPanelDataType.MILITARY_UNITS, data: new_data };
  }
  return undefined;
}

export function resolveSelectionData(
  data: LeftPanelData,
  session: RisqSession
): { data: LeftPanelData; visibility: number } | undefined {
  switch (data.data_type) {
    case LeftPanelDataType.UNIT: {
      const unit = session.findUnitById(data.data.internal_id);
      if (!unit) return undefined;
      const loc = session.unitLocation(unit);
      const space = loc ? session.spaceAt(loc.space_coordinate) : undefined;
      const vis = unit.player_id === session.getPlayerId() ? RisqVisibilityLevel.GOOD : (space?.visibility ?? 0);
      return vis >= RisqVisibilityLevel.GOOD
        ? { data: { data_type: LeftPanelDataType.UNIT, data: unit }, visibility: vis }
        : undefined;
    }
    case LeftPanelDataType.BUILDING: {
      const building = session.findBuildingById(data.data.internal_id);
      if (!building) return undefined;
      const space = session.spaceAt(building.space_coordinate);
      const vis = building.player_id === session.getPlayerId() ? RisqVisibilityLevel.GOOD : (space?.visibility ?? 0);
      return vis >= RisqVisibilityLevel.GOOD
        ? { data: { data_type: LeftPanelDataType.BUILDING, data: building }, visibility: vis }
        : undefined;
    }
    case LeftPanelDataType.SPACE: {
      const space = session.spaceAt(data.data.coordinate);
      const vis = space?.visibility ?? 0;
      return space && vis >= RisqVisibilityLevel.FOG
        ? { data: { data_type: LeftPanelDataType.SPACE, data: space }, visibility: vis }
        : undefined;
    }
    case LeftPanelDataType.ZONE: {
      const space = session.spaceAt(data.data.space.coordinate);
      const zone = space?.zones?.flat().find((z) => equalsPoint2D(z.coordinate, data.data.zone.coordinate));
      const vis = space?.visibility ?? 0;
      return space && zone && vis >= RisqVisibilityLevel.FOG
        ? { data: { data_type: LeftPanelDataType.ZONE, data: { space, zone } }, visibility: vis }
        : undefined;
    }
    case LeftPanelDataType.RESOURCE: {
      const space = session.spaceAt(data.data.space_coordinate);
      const zone = space?.zones?.flat().find((z) => equalsPoint2D(z.coordinate, data.data.zone_coordinate));
      const vis = space?.visibility ?? 0;
      return zone?.resource && vis >= RisqVisibilityLevel.FOG
        ? { data: { data_type: LeftPanelDataType.RESOURCE, data: zone.resource }, visibility: vis }
        : undefined;
    }
    case LeftPanelDataType.REGION: {
      const region = session.getGame()?.regions.find((r) => r.name === data.data.name);
      return region
        ? { data: { data_type: LeftPanelDataType.REGION, data: region }, visibility: RisqVisibilityLevel.GOOD }
        : undefined;
    }
    case LeftPanelDataType.FOUNDATION: {
      const player = session.getPlayer();
      const coord_key = data.data.coordinate_key;
      const planned = player?.planned_foundations.get(coord_key);
      const space_coord = invertPair(coord_key);
      const space = session.spaceAt(space_coord);
      const zone = space?.zones?.flat().find((z) => z.coordinate_key === coord_key);
      if (planned && space && zone) {
        return {
          data: {
            data_type: LeftPanelDataType.FOUNDATION,
            data: {
              coordinate_key: coord_key,
              building_id: planned.building_id,
              player_id: session.getPlayerId(),
              is_local: data.data.is_local,
              display_name: `Planned ${planned.display_name}`,
              zone,
            },
          },
          visibility: space.visibility,
        };
      }
      if (zone?.building) {
        return {
          data: { data_type: LeftPanelDataType.BUILDING, data: zone.building },
          visibility: space?.visibility ?? RisqVisibilityLevel.GOOD,
        };
      }
      return undefined;
    }
    case LeftPanelDataType.UNITS_BY_TYPE:
    case LeftPanelDataType.ECONOMIC_UNITS:
    case LeftPanelDataType.MILITARY_UNITS: {
      const all_ids = data.data.units.flatMap((u) => [...u.units.values()]);
      const surviving = all_ids.map((id) => session.findUnitById(id)).filter((u): u is RisqUnit => !!u);
      if (surviving.length === 0) return undefined;
      const first = surviving[0];
      const space = data.data.space ? session.spaceAt(data.data.space.coordinate) : undefined;
      const owner = session.getGame()?.players.find((p) => p.player.player_id === first.player_id);
      if (!owner) return undefined;
      const grouped = groupUnitsByType(
        owner.units,
        surviving.map((u) => u.internal_id)
      );
      const normalized = normalizePlayerUnits({ space, units: grouped }, (p, id) =>
        session.getGame()?.players[p]?.units.get(id)
      );
      if (!normalized) return undefined;
      const vis = first.player_id === session.getPlayerId() ? RisqVisibilityLevel.GOOD : (space?.visibility ?? 0);
      return vis >= RisqVisibilityLevel.GOOD ? { data: normalized, visibility: vis } : undefined;
    }
    case LeftPanelDataType.UNITS:
    case LeftPanelDataType.MULTIPLE_PLAYERS_UNITS: {
      const space = session.spaceAt(data.data.space.coordinate);
      if (!space || space.visibility < RisqVisibilityLevel.GOOD) return undefined;
      const surviving_map = new Map<number, UnitByTypeData[]>();
      const raw_entries: [number, UnitByTypeData[]][] =
        data.data_type === LeftPanelDataType.UNITS
          ? [...data.data.units_by_player.entries()]
          : data.data.units_by_player;
      for (const [pid, types] of raw_entries) {
        const ids = types.flatMap((t) => [...t.units.values()]);
        const surviving = ids.map((id) => session.findUnitById(id)).filter((u): u is RisqUnit => !!u);
        const owner = session.getGame()?.players.find((p) => p.player.player_id === pid);
        if (owner && surviving.length > 0) {
          surviving_map.set(
            pid,
            groupUnitsByType(
              owner.units,
              surviving.map((u) => u.internal_id)
            )
          );
        }
      }
      const normalized = normalizeUnits({ space, units_by_player: surviving_map }, (p, id) =>
        session.getGame()?.players[p]?.units.get(id)
      );
      return normalized ? { data: normalized, visibility: space.visibility } : undefined;
    }
    default:
      return undefined;
  }
}

import { ColorRGB } from '../../../../../scripts/color_rgb';
import type { BoardTransformData } from '../../../util/canvas_board/canvas_board';
import type { CanvasComponent } from '../../../util/canvas_components/canvas_component';
import { configDraw } from '../../../util/canvas_components/canvas_component';
import { drawRect, drawText } from '../../../util/canvas_util';
import type { Point2D } from '../../../util/objects2d';
import type { DwgRisq } from '../risq';

const FADE_MS = 300;
const BASE_HOLD_MS = 1200;
const HOLD_MS_PER_CHAR = 20;
const MAX_HOLD_EXTRA_MS = 4000;
const MAX_VISIBLE = 3;
const ROW_H = 30;
const ROW_GAP = 8;
const ROW_PADDING_X = 14;
const TOP_MARGIN = 12;
const FONT = 'bold 14px serif';

export const RISQ_MESSAGE_WARNING_COLOR = new ColorRGB(255, 200, 60);

interface RisqQueuedMessage {
  text: string;
  color: ColorRGB;
  activated_at?: number;
}

/** Transient top-of-screen system messages (e.g. "Not enough resources"), queued FIFO with a fixed number visible at once */
export class RisqMessageQueue implements CanvasComponent {
  private risq: DwgRisq;
  private queue: RisqQueuedMessage[] = [];
  private active: RisqQueuedMessage[] = [];
  private bounds: { w: number; h: number } = { w: 0, h: 0 };
  private clock = 0;

  constructor(risq: DwgRisq) {
    this.risq = risq;
  }

  isHovering(): boolean {
    return false;
  }
  setHovering(_hovering: boolean): void {}
  isClicking(): boolean {
    return false;
  }
  setClicking(_clicking: boolean): void {}
  mousemove(_canvas: Point2D, _screen: Point2D, _transform: BoardTransformData): boolean {
    return false;
  }
  mousedown(_e: MouseEvent): boolean {
    return false;
  }
  mouseup(_e: MouseEvent): void {}

  enqueue(text: string, color: ColorRGB) {
    this.queue.push({ text, color });
    this.promote();
  }

  private promote() {
    while (this.active.length < MAX_VISIBLE && this.queue.length > 0) {
      const msg = this.queue.shift()!;
      msg.activated_at = this.clock;
      this.active.unshift(msg);
    }
  }

  private holdDuration(text: string): number {
    return BASE_HOLD_MS + Math.min(text.length * HOLD_MS_PER_CHAR, MAX_HOLD_EXTRA_MS);
  }

  private ageOf(msg: RisqQueuedMessage): number {
    return this.clock - msg.activated_at!;
  }

  private alphaFor(msg: RisqQueuedMessage): number {
    const age = this.ageOf(msg);
    const hold = this.holdDuration(msg.text);
    if (age < FADE_MS) {
      return age / FADE_MS;
    }
    if (age < FADE_MS + hold) {
      return 1;
    }
    return Math.max(0, 1 - (age - FADE_MS - hold) / FADE_MS);
  }

  draw(ctx: CanvasRenderingContext2D, transform: BoardTransformData, dt: number) {
    this.clock += dt;
    this.active = this.active.filter((msg) => this.ageOf(msg) < 2 * FADE_MS + this.holdDuration(msg.text));
    this.promote();
    if (this.active.length === 0) {
      this.bounds = { w: 0, h: 0 };
      return;
    }
    const cx = 0.5 * this.risq.viewport.canvasSize().width;
    ctx.font = FONT;
    let max_w = 0;
    for (const [i, msg] of this.active.entries()) {
      const alpha = this.alphaFor(msg);
      if (alpha <= 0) {
        continue;
      }
      const w = ctx.measureText(msg.text).width + 2 * ROW_PADDING_X;
      max_w = Math.max(max_w, w);
      const y = TOP_MARGIN + i * (ROW_H + ROW_GAP);
      const bg_style = msg.color.getBrightness() > 0.5 ? 'rgba(0, 0, 0, 0.65)' : 'rgba(255, 255, 255, 0.65)';
      const prev_alpha = ctx.globalAlpha;
      ctx.globalAlpha = alpha;
      configDraw(
        ctx,
        transform,
        {
          fill_style: bg_style,
          stroke_width: 0,
          fixed_position: true,
        },
        false,
        false,
        () => {
          drawRect(ctx, { x: cx - 0.5 * w, y }, w, ROW_H, 5);
          drawText(ctx, msg.text, {
            p: { x: cx, y: y + 0.5 * ROW_H },
            w,
            fill_style: msg.color.getString(),
            align: 'center',
            baseline: 'middle',
            font: FONT,
          });
        }
      );
      ctx.globalAlpha = prev_alpha;
    }
    this.bounds = { w: max_w, h: this.active.length * ROW_H + (this.active.length - 1) * ROW_GAP };
  }

  xi(): number {
    return 0.5 * (this.risq.viewport.canvasSize().width - this.bounds.w);
  }
  xf(): number {
    return this.xi() + this.bounds.w;
  }
  yi(): number {
    return TOP_MARGIN;
  }
  yf(): number {
    return this.yi() + this.bounds.h;
  }
  w(): number {
    return this.bounds.w;
  }
  h(): number {
    return this.bounds.h;
  }
}

import type { BoardTransformData } from '../../../../util/canvas_board/canvas_board';
import { defaultTransform, screenToCanvas } from '../../../../util/canvas_board/canvas_board';
import type { CanvasComponent } from '../../../../util/canvas_components/canvas_component';
import { configDraw } from '../../../../util/canvas_components/canvas_component';
import { drawCircle, drawHexagon } from '../../../../util/canvas_util';
import type { Point2D } from '../../../../util/objects2d';
import { rotatePoint } from '../../../../util/objects2d';
import type { RisqSpace } from '../../model/types';
import { RisqVisibilityLevel } from '../../model/types';
import type { DwgRisq } from '../../risq';
import { drawRisqSpaceBorders } from '../../rendering/space_borders';
