import { RisqViewMode, spaceOwnerColor, terrainImage } from '../../rendering/terrain';

export declare interface MinimapConfig {
  target_w: number;
  background: string;
}

/** Clips a convex polygon against an axis-aligned box (Sutherland-Hodgman) */
function clipPolygonToBox(polygon: Point2D[], min: Point2D, max: Point2D): Point2D[] {
  const lerp = (a: Point2D, b: Point2D, t: number): Point2D => ({ x: a.x + t * (b.x - a.x), y: a.y + t * (b.y - a.y) });
  const clip_edge = (
    points: Point2D[],
    inside: (p: Point2D) => boolean,
    intersect: (a: Point2D, b: Point2D) => Point2D
  ): Point2D[] => {
    const out: Point2D[] = [];
    for (let i = 0; i < points.length; i++) {
      const curr = points[i];
      const prev = points[(i + points.length - 1) % points.length];
      if (inside(curr)) {
        if (!inside(prev)) {
          out.push(intersect(prev, curr));
        }
        out.push(curr);
      } else if (inside(prev)) {
        out.push(intersect(prev, curr));
      }
    }
    return out;
  };
  let result = polygon;
  result = clip_edge(
    result,
    (p) => p.x >= min.x,
    (a, b) => lerp(a, b, (min.x - a.x) / (b.x - a.x))
  );
  result = clip_edge(
    result,
    (p) => p.x <= max.x,
    (a, b) => lerp(a, b, (max.x - a.x) / (b.x - a.x))
  );
  result = clip_edge(
    result,
    (p) => p.y >= min.y,
    (a, b) => lerp(a, b, (min.y - a.y) / (b.y - a.y))
  );
  result = clip_edge(
    result,
    (p) => p.y <= max.y,
    (a, b) => lerp(a, b, (max.y - a.y) / (b.y - a.y))
  );
  return result;
}

export class RisqMinimap implements CanvasComponent {
  private static PADDING = 4;

  private risq: DwgRisq;
  private config: MinimapConfig;
  private hex_r = 0;
  private content_size: Point2D = { x: 0, y: 0 };
  private side = 0;
  private p: Point2D = { x: 0, y: 0 };
  private hovering = false;
  private clicking = false;
  private last_screen_m: Point2D = { x: 0, y: 0 };
  private last_transform: BoardTransformData = defaultTransform();

  constructor(risq: DwgRisq, config: MinimapConfig) {
    this.risq = risq;
    this.config = config;
  }

  resolveSize() {
    const board_size = this.risq.getGame()?.board_size;
    if (board_size === undefined) {
      return;
    }
    this.hex_r = this.config.target_w / (1.732 * (2 * board_size + 1));
    this.content_size = {
      x: 1.732 * this.hex_r * (2 * board_size + 1),
      y: 1.5 * this.hex_r * (2 * board_size + 1) + 0.5 * this.hex_r,
    };
    this.side = Math.max(this.content_size.x, this.content_size.y) + 2 * RisqMinimap.PADDING;
  }

  setPosition(p: Point2D): void {
    this.p = p;
  }

  private contentOrigin(): Point2D {
    return {
      x: this.xi() + 0.5 * (this.side - this.content_size.x),
      y: this.yi() + 0.5 * (this.side - this.content_size.y),
    };
  }

  isHovering(): boolean {
    return this.hovering;
  }
  setHovering(hovering: boolean): void {
    this.hovering = hovering;
  }
  isClicking(): boolean {
    return this.clicking;
  }
  setClicking(clicking: boolean): void {
    this.clicking = clicking;
  }

  private minimapCanvasToCoordinate(minimap_canvas: Point2D): Point2D {
    const board_size = this.risq.getGame()?.board_size ?? 0;
    const cy = (minimap_canvas.y - 0.25 * this.hex_r) / (1.5 * this.hex_r) - board_size - 0.5;
    return {
      x: minimap_canvas.x / (1.732 * this.hex_r) - 0.5 * cy - board_size - 0.5,
      y: cy,
    };
  }

  private coordinateToMinimapCanvas(coordinate: Point2D): Point2D {
    const board_size = this.risq.getGame()?.board_size ?? 0;
    return {
      x: 1.732 * (coordinate.x + 0.5 * coordinate.y + board_size + 0.5) * this.hex_r,
      y: 1.5 * (coordinate.y + board_size + 0.5) * this.hex_r + 0.25 * this.hex_r,
    };
  }

  draw(ctx: CanvasRenderingContext2D, transform: BoardTransformData, _dt: number): void {
    const game = this.risq.getGame();
    if (!game || this.hex_r <= 0) {
      return;
    }
    this.last_transform = transform;
    configDraw(
      ctx,
      transform,
      {
        fill_style: this.config.background,
        stroke_style: 'transparent',
        stroke_width: 0,
        fixed_position: true,
      },
      false,
      false,
      () => {
        drawCircle(ctx, { x: this.xc(), y: this.yc() }, 0.5 * this.side);
        ctx.save();
        ctx.beginPath();
        ctx.arc(this.xc(), this.yc(), 0.5 * this.side, 0, 2 * Math.PI);
        ctx.clip();
        const origin = this.contentOrigin();
        const content_center = { x: 0.5 * this.content_size.x, y: 0.5 * this.content_size.y };
        ctx.translate(origin.x + content_center.x, origin.y + content_center.y);
        ctx.rotate(transform.rotation);
        ctx.translate(-content_center.x, -content_center.y);
        const view_mode = this.risq.viewport.viewMode();
        const draw_r = this.hex_r + 1; // slight overlap so adjacent tiles' antialiasing doesn't leave seams
        ctx.strokeStyle = 'transparent';
        ctx.lineWidth = 0;
        for (const row of game.spaces) {
          for (const space of row) {
            if (!space) {
              continue;
            }
            const minimap_canvas = this.coordinateToMinimapCanvas(space.coordinate);
            const owner_color = spaceOwnerColor(space.ownership, game.players);
            const region_owned = (this.risq.session.getRegionForSpace(space.coordinate_key)?.owner ?? -1) >= 0;
            if (
              space.visibility === RisqVisibilityLevel.UNEXPLORED ||
              view_mode === RisqViewMode.OWNERSHIP ||
              view_mode === RisqViewMode.REGION
            ) {
              const fill = getSpaceFill(space, RisqViewMode.OWNERSHIP, owner_color, false);
              if (region_owned) {
                fill.dBrightness(-0.22);
              }
              ctx.fillStyle = `rgb(${fill.getR()}, ${fill.getG()}, ${fill.getB()})`;
              drawHexagon(ctx, minimap_canvas, draw_r);
            } else {
              drawHexImage(ctx, this.risq.getIcon(terrainImage(space.terrain_id)), minimap_canvas, draw_r);
              if (view_mode !== RisqViewMode.RESOURCE && !!owner_color) {
                fillHexOverlay(
                  ctx,
                  minimap_canvas,
                  this.hex_r,
                  `rgba(${owner_color.getR()}, ${owner_color.getG()}, ${owner_color.getB()}, ${region_owned ? 0.45 : 0.25})`
                );
              }
            }
          }
        }
        const all_spaces = game.spaces.flat().filter((s): s is RisqSpace => !!s);
        drawRisqSpaceBorders(
          ctx,
          this.risq,
          all_spaces,
          {
            hex_r: this.hex_r,
            draw_detail: DrawRisqSpaceDetail.OWNERSHIP,
            view_mode,
            regions_only: true,
            min_width: 1,
          },
          (s) => this.coordinateToMinimapCanvas(s.coordinate)
        );
        ctx.fillStyle = 'white';
        ctx.strokeStyle = 'transparent';
        for (const player of game.players) {
          for (const unit of player.units.values()) {
            if (unit.garrisoned_in === undefined && this.risq.selection.isUnitSelected(unit.internal_id)) {
              drawCircle(ctx, this.coordinateToMinimapCanvas(unit.space_coordinate), Math.max(1.5, 0.25 * this.hex_r));
            }
          }
        }
        ctx.translate(content_center.x, content_center.y);
        ctx.rotate(-transform.rotation);
        ctx.translate(-(origin.x + content_center.x), -(origin.y + content_center.y));
        const left_panel = this.risq.left_panel;
        const right_panel = this.risq.right_panel;
        const visible_x0 = left_panel.isShowing() ? left_panel.xf() : 0;
        const visible_x1 = right_panel.isOpen() ? right_panel.xi() : this.risq.viewport.canvasSize().width;
        const canvas_h = this.risq.viewport.canvasSize().height;
        const display_center = { x: origin.x + content_center.x, y: origin.y + content_center.y };
        const corners = [
          { x: visible_x0, y: 0 },
          { x: visible_x1, y: 0 },
          { x: visible_x1, y: canvas_h },
          { x: visible_x0, y: canvas_h },
        ].map((screen) => {
          const local = this.minimapCanvasFromCanvas(screenToCanvas(screen, transform));
          const rotated = rotatePoint(
            { x: local.x - content_center.x, y: local.y - content_center.y },
            transform.rotation
          );
          return { x: display_center.x + rotated.x, y: display_center.y + rotated.y };
        });
        const clipped = clipPolygonToBox(corners, { x: this.xi(), y: this.yi() }, { x: this.xf(), y: this.yf() });
        if (clipped.length >= 3) {
          ctx.fillStyle = 'transparent';
          ctx.strokeStyle = 'white';
          ctx.lineWidth = 1;
          ctx.beginPath();
          clipped.forEach((p, i) => (i === 0 ? ctx.moveTo(p.x, p.y) : ctx.lineTo(p.x, p.y)));
          ctx.closePath();
          ctx.stroke();
        }
        ctx.restore();
      }
    );
  }

  private minimapCanvasFromCanvas(canvas: Point2D): Point2D {
    const coordinate = this.risq.viewport.canvasToCoordinate(canvas, this.risq.getGame()?.board_size ?? 0);
    return this.coordinateToMinimapCanvas(coordinate);
  }

  scroll(): boolean {
    return false;
  }

  mousemove(_canvas: Point2D, screen: Point2D, _transform: BoardTransformData): boolean {
    this.last_screen_m = screen;
    this.hovering = Math.hypot(screen.x - this.xc(), screen.y - this.yc()) <= 0.5 * this.side;
    if (this.clicking && this.hovering) {
      this.jumpTo(this.last_screen_m);
    }
    return this.hovering;
  }

  mousedown(e: MouseEvent): boolean {
    if (!this.hovering || e.button !== 0) {
      return false;
    }
    this.clicking = true;
    this.jumpTo(this.last_screen_m);
    return true;
  }

  mouseup(): void {
    this.clicking = false;
  }

  private jumpTo(screen: Point2D) {
    const origin = this.contentOrigin();
    const content_center = { x: 0.5 * this.content_size.x, y: 0.5 * this.content_size.y };
    const display_center = { x: origin.x + content_center.x, y: origin.y + content_center.y };
    const local = rotatePoint(
      { x: screen.x - display_center.x, y: screen.y - display_center.y },
      -this.last_transform.rotation
    );
    const coordinate = this.minimapCanvasToCoordinate({
      x: local.x + content_center.x,
      y: local.y + content_center.y,
    });
    this.risq.goToCoordinate(coordinate);
  }

  xi(): number {
    return this.p.x;
  }
  yi(): number {
    return this.p.y;
  }
  xf(): number {
    return this.xi() + this.w();
  }
  yf(): number {
    return this.yi() + this.h();
  }
  xc(): number {
    return this.xi() + 0.5 * this.side;
  }
  yc(): number {
    return this.yi() + 0.5 * this.side;
  }
  w(): number {
    return this.side;
  }
  h(): number {
    return this.side;
  }
}

import type { BoardTransformData } from '../../../../util/canvas_board/canvas_board';
import type { CanvasComponent } from '../../../../util/canvas_components/canvas_component';
import { configDraw } from '../../../../util/canvas_components/canvas_component';
import { drawLine, drawRect, drawText } from '../../../../util/canvas_util';
import { createTooltipState, drawTooltip, shouldShowTooltip } from '../../../../util/canvas_components/tooltip';
import type { Point2D } from '../../../../util/objects2d';
import type { RisqFrontendOrder } from '../../model/types';
import { UNIT_CLUSTER_ICON_SIZE, drawUnitTypeCluster, unitClusterIconKey } from '../../rendering/zones/draw';
import { unitImage } from '../../rendering/assets/unit';
import type { DwgRisq } from '../../risq';
import { RisqOrderCancelButton } from './order_cancel_button';
import type { ResolvedRow } from './order_row_resolve';
import { resolveOrderRow } from './order_row_resolve';

export interface RisqOrderRowConfig {
  game: DwgRisq;
  w: number;
  /** Whether to draw the subject icon/count badge; true in the right panel, false in the left panel */
  show_subject: boolean;
  order: RisqFrontendOrder;
  /** Other same-producible BuildingCreate orders collapsed behind this one, not yet started */
  collapsed_orders?: RisqFrontendOrder[];
  /** Whether a cancel for this (already-submitted) order is pending, drawn as a strikethrough */
  cancelling?: boolean;
  explicit_cancel?: boolean;
  onCancel: (order: RisqFrontendOrder) => void;
  onCancelAll?: (orders: RisqFrontendOrder[]) => void;
  onSelect?: (order: RisqFrontendOrder) => void;
}

export const ROW_H = 30;
const COLLAPSED_STRIP_H = 14;
const ICON_S = 20;
const PADDING = 5;
const CANCEL_S = 14;
const CHIP_W = 30;

export class RisqOrderRow implements CanvasComponent {
  private config: RisqOrderRowConfig;
  private hovering = false;
  private clicking = false;
  private cancel_all_hover = false;
  private cancel_all_clicking = false;
  private resolved: ResolvedRow;
  private cancel_button: RisqOrderCancelButton;
  private progress_tooltip = createTooltipState();

  constructor(config: RisqOrderRowConfig) {
    this.config = config;
    this.resolved = resolveOrderRow(config);
    this.cancel_button = new RisqOrderCancelButton(
      CANCEL_S,
      () => {
        const collapsed = this.config.collapsed_orders;
        this.config.onCancel(collapsed?.length ? collapsed[collapsed.length - 1] : this.config.order);
      },
      config.explicit_cancel
    );
    this.positionButtons();
    if (config.cancelling && !config.explicit_cancel) {
      this.disableCancel();
    }
  }

  getOrder(): RisqFrontendOrder {
    return this.config.order;
  }

  /** All orders this row represents, including any collapsed behind it */
  getOrders(): RisqFrontendOrder[] {
    return [this.config.order, ...(this.config.collapsed_orders ?? [])];
  }

  disableCancel(): void {
    this.cancel_button.disable();
  }

  enableCancel(): void {
    if (!this.config.cancelling || this.config.explicit_cancel) {
      this.cancel_button.enable();
    }
  }

  private positionButtons(): void {
    this.cancel_button.setPosition({ x: this.xi() + this.w() - PADDING - CANCEL_S, y: this.yi() + PADDING });
  }

  isHovering(): boolean {
    return this.hovering;
  }
  setHovering(hovering: boolean): void {
    this.hovering = hovering;
    if (!hovering) {
      this.progress_tooltip.hover_ms = 0;
      this.cancel_all_hover = false;
      this.cancel_button.setHovering(false);
    }
  }
  isClicking(): boolean {
    return this.clicking;
  }
  setClicking(clicking: boolean): void {
    this.clicking = clicking;
    if (!clicking) {
      this.cancel_all_clicking = false;
      this.cancel_button.setClicking(false);
    }
  }

  setW(w: number): void {
    this.config.w = w;
    this.positionButtons();
  }

  private isCollapsed(): boolean {
    return !!this.config.collapsed_orders?.length;
  }

  private isSelected(): boolean {
    return this.config.show_subject && this.config.game.selection.isOrderSubjectSelected(this.config.order);
  }

  private drawSubject(ctx: CanvasRenderingContext2D, x: number, yc: number): void {
    const game = this.config.game;
    const units = this.resolved.subject_units;
    if (units) {
      const total = this.config.order.subjects.length;
      const s = UNIT_CLUSTER_ICON_SIZE;
      const cluster = game.getImageCache().getImage(
        unitClusterIconKey(units, total),
        s,
        units.map((t) => game.getIcon(unitImage(t.unit_id))),
        (cctx) => {
          cctx.translate(s / 2, s / 2);
          drawUnitTypeCluster(
            cctx,
            game,
            units,
            { x: s / 2, y: s / 2 },
            total,
            'rgb(59, 36, 19)',
            'rgba(59, 36, 19, 0.4)'
          );
        }
      );
      if (cluster) {
        ctx.drawImage(cluster, x, yc - ICON_S / 2, ICON_S, ICON_S);
      }
      return;
    }
    ctx.drawImage(game.getIcon(this.resolved.subject_icon!), x, yc - ICON_S / 2, ICON_S, ICON_S);
    const count = this.config.order.subjects.length;
    if (count > 1) {
      this.drawCountBadge(ctx, `×${count}`, x + ICON_S, yc + ICON_S / 2);
    }
  }

  private drawCountBadge(ctx: CanvasRenderingContext2D, label: string, right: number, bottom: number): void {
    ctx.font = 'bold 8px sans-serif';
    const bw = ctx.measureText(label).width + 5;
    const bh = 10;
    const bx = right - bw + 3;
    const by = bottom - bh + 4;
    ctx.fillStyle = 'rgba(59, 36, 19, 0.7)';
    ctx.strokeStyle = 'transparent';
    ctx.lineWidth = 0;
    drawRect(ctx, { x: bx, y: by }, bw, bh, 3);
    drawText(ctx, label, {
      p: { x: bx + bw / 2, y: by + bh / 2 + 1 },
      w: bw,
      fill_style: 'rgb(241, 226, 196)',
      align: 'center',
      baseline: 'middle',
      font: 'bold 8px sans-serif',
    });
  }

  draw(ctx: CanvasRenderingContext2D, transform: BoardTransformData, dt: number): void {
    const selected = this.isSelected();
    configDraw(
      ctx,
      transform,
      {
        fill_style: selected ? 'rgb(218, 198, 160)' : 'rgb(241, 226, 196)',
        stroke_style: 'rgb(59, 36, 19)',
        stroke_width: selected ? 1.8 : 0.6,
        hover_fill_style: selected ? 'rgb(226, 207, 172)' : 'rgb(247, 236, 212)',
        click_fill_style: selected ? 'rgb(234, 217, 184)' : 'rgb(252, 244, 224)',
      },
      this.isHovering(),
      this.isClicking(),
      () => {
        drawRect(ctx, { x: this.xi(), y: this.yi() }, this.w(), ROW_H, 3);
        let x = this.xi() + PADDING;
        const yc = this.yi() + ROW_H / 2;
        if (this.config.show_subject && (this.resolved.subject_units || this.resolved.subject_icon)) {
          this.drawSubject(ctx, x, yc);
          x += ICON_S + 4;
          ctx.strokeStyle = 'rgba(59, 36, 19, 0.4)';
          ctx.lineWidth = 1;
          drawLine(ctx, { x, y: yc - ICON_S / 2 }, { x, y: yc + ICON_S / 2 });
          x += 5;
        }
        ctx.drawImage(this.config.game.getIcon(this.resolved.icon), x, yc - ICON_S / 2, ICON_S, ICON_S);
        x += ICON_S + 5;
        const chips_w = this.chipsWidth();
        const text_w = this.w() - (x - this.xi()) - chips_w - PADDING - CANCEL_S;
        drawText(ctx, this.resolved.name, {
          p: { x, y: yc - 8 },
          w: text_w,
          fill_style: 'rgb(59, 36, 19)',
          align: 'left',
          font: 'bold 10.5px serif',
        });
        drawText(ctx, this.resolved.target, {
          p: { x, y: yc + 3 },
          w: text_w,
          fill_style: 'rgb(122, 92, 62)',
          align: 'left',
          font: '9.5px sans-serif',
        });
        this.drawChips(ctx, this.xi() + this.w() - PADDING - CANCEL_S - chips_w, yc);
        if (this.resolved.progress !== undefined) {
          this.drawProgress(ctx, this.resolved.progress);
        }
        if (!this.cancel_button.isDisabled()) {
          this.cancel_button.draw(ctx, transform, dt);
          if (this.isCollapsed()) {
            this.drawCancelAllStrip(ctx);
          }
        }
        if (this.config.cancelling) {
          ctx.strokeStyle = 'rgb(122, 46, 27)';
          ctx.lineWidth = 3;
          drawLine(ctx, { x: this.xi(), y: yc }, { x: this.xi() + this.w(), y: yc });
        }
      }
    );
    const hovering =
      !!this.resolved.progress_text && this.hovering && !this.cancel_button.isHovering() && !this.cancel_all_hover;
    const show_tooltip = shouldShowTooltip(this.progress_tooltip, hovering, this.clicking, dt);
    if (show_tooltip && this.resolved.progress_text) {
      drawTooltip(
        this.progress_tooltip,
        ctx,
        transform,
        this.config.game.viewport.canvasSize(),
        this.resolved.progress_text
      );
    }
  }

  private chipsWidth(): number {
    return this.resolved.cost.length * (CHIP_W + 3);
  }

  private drawChips(ctx: CanvasRenderingContext2D, x: number, yc: number) {
    for (const chip of this.resolved.cost) {
      ctx.drawImage(this.config.game.getIcon(chip.icon), x, yc - 7, 14, 14);
      drawText(ctx, chip.amount.toString(), {
        p: { x: x + 16, y: yc },
        w: CHIP_W - 16,
        fill_style: 'rgb(59, 36, 19)',
        align: 'left',
        baseline: 'middle',
        font: '10px sans-serif',
      });
      x += CHIP_W + 3;
    }
  }

  private drawProgress(ctx: CanvasRenderingContext2D, progress: number) {
    const y = this.yi() + ROW_H - 2;
    const clamped = Math.max(0, Math.min(1, progress));
    ctx.fillStyle = 'rgba(59, 36, 19, 0.12)';
    ctx.strokeStyle = 'transparent';
    drawRect(ctx, { x: this.xi(), y }, this.w(), 2);
    ctx.fillStyle = 'rgb(46, 125, 58)';
    drawRect(ctx, { x: this.xi(), y }, this.w() * clamped, 2);
  }

  private drawCancelAllStrip(ctx: CanvasRenderingContext2D) {
    const y = this.yi() + ROW_H;
    ctx.fillStyle = this.cancel_all_clicking
      ? 'rgba(80, 40, 25, 0.85)'
      : this.cancel_all_hover
        ? 'rgba(80, 40, 25, 0.7)'
        : 'rgba(80, 40, 25, 0.5)';
    ctx.strokeStyle = 'transparent';
    drawRect(ctx, { x: this.xi(), y }, this.w(), COLLAPSED_STRIP_H, 0);
    const count = 1 + (this.config.collapsed_orders?.length ?? 0);
    drawText(ctx, `Cancel all (×${count})`, {
      p: { x: this.xf() - PADDING, y: y + COLLAPSED_STRIP_H / 2 },
      w: this.w() - 2 * PADDING,
      fill_style: 'rgb(255, 255, 255)',
      align: 'right',
      baseline: 'middle',
      font: '9px sans-serif',
    });
  }

  scroll(_dy: number, _mode: number): boolean {
    return false;
  }

  mousemove(_canvas: Point2D, screen: Point2D, transform: BoardTransformData): boolean {
    this.hovering = !(screen.x < this.xi() || screen.y < this.yi() || screen.x > this.xf() || screen.y > this.yf());
    this.cancel_button.mousemove(screen, screen, transform);
    if (this.cancel_button.isDisabled()) {
      this.cancel_all_hover = false;
      return this.hovering;
    }
    if (this.isCollapsed()) {
      const sy = this.yi() + ROW_H;
      this.cancel_all_hover = this.hovering && screen.y >= sy && screen.y <= sy + COLLAPSED_STRIP_H;
    } else {
      this.cancel_all_hover = false;
    }
    return this.hovering;
  }

  mousedown(e: MouseEvent): boolean {
    if (this.cancel_button.mousedown(e)) {
      return true;
    }
    if (!this.cancel_button.isDisabled() && this.cancel_all_hover) {
      this.cancel_all_clicking = true;
      return true;
    }
    if (this.hovering) {
      this.clicking = true;
      return true;
    }
    return false;
  }

  mouseup(e: MouseEvent): void {
    this.cancel_button.mouseup(e);
    if (
      !this.cancel_button.isDisabled() &&
      this.cancel_all_clicking &&
      this.cancel_all_hover &&
      this.config.collapsed_orders
    ) {
      this.config.onCancelAll?.([this.config.order, ...this.config.collapsed_orders]);
    } else if (this.clicking && this.hovering) {
      this.config.onSelect?.(this.config.order);
    }
    this.cancel_all_clicking = false;
    this.clicking = false;
  }

  xi(): number {
    return 0;
  }
  yi(): number {
    return 0;
  }
  xf(): number {
    return this.w();
  }
  yf(): number {
    return this.h();
  }
  w(): number {
    return this.config.w;
  }
  h(): number {
    return this.isCollapsed() && !this.cancel_button.isDisabled() ? ROW_H + COLLAPSED_STRIP_H : ROW_H;
  }
}

import type { BoardTransformData } from '../../../../util/canvas_board/canvas_board';
import { DwgRectButton } from '../../../../util/canvas_components/button/rect_button';
import type { DwgRisq } from '../../risq';
import { RisqButtonTooltip } from '../risq_tooltip';
import { getSettings } from '../../../../../../scripts/settings_store';
import { RisqHotkeyAction, hotkeyDisplayString } from '../../application/input/hotkeys';

export class RisqNextIdleButton extends DwgRectButton {
  private risq: DwgRisq;
  private tooltip = new RisqButtonTooltip(() => ({
    title: 'Next Idle Unit',
    hotkey: hotkeyDisplayString(getSettings().risq_hotkeys.actions[RisqHotkeyAction.NEXT_IDLE]),
  }));

  constructor(risq: DwgRisq, h: number) {
    super({
      button_config: {
        allow_nonleft_clicks: false,
      },
      p: { x: 0, y: 0 },
      w: 0,
      h,
      draw_config: {
        fill_style: 'rgb(220, 190, 50)',
        stroke_style: 'rgb(150, 130, 20)',
        stroke_width: 0,
        hover_fill_style: 'rgb(240, 210, 80)',
        click_fill_style: 'rgb(255, 230, 110)',
        fixed_position: true,
      },
      r: 0.1 * h,
      text: {
        text: 'Next Idle',
        config: {
          align: 'center',
          baseline: 'ideographic',
          font: `${0.75 * h}px serif`,
          fill_style: 'rgb(0, 0, 0)',
        },
        padding: 0.1 * h,
      },
    });
    this.risq = risq;
  }

  protected hovered(): void {}
  protected unhovered(): void {}
  protected clicked(): void {}
  protected released(): void {
    if (this.isHovering()) {
      this.risq.selectNextIdleUnit();
    }
  }

  drawTooltip(ctx: CanvasRenderingContext2D, transform: BoardTransformData, risq: DwgRisq, dt: number) {
    this.tooltip.draw(ctx, transform, risq, dt, this.isHovering(), this.isPressed());
  }
}

import type { ColorRGB } from '../../../../../../scripts/color_rgb';
import type { BoardTransformData } from '../../../../util/canvas_board/canvas_board';
import type { DropdownBounds } from '../../../../util/canvas_components/dropdown/multi_select_dropdown';
import { DwgListbox } from '../../../../util/canvas_components/scrollbar/listbox';
import type { Point2D } from '../../../../util/objects2d';
import type { DwgRisq } from '../../risq';
import type { OrderFilterContext } from '../../application/orders/order_filter';
import { OrderSubjectClass } from '../../application/orders/order_filter';
import type { RisqOrdersModel, RisqOrderRowEntry } from '../../application/orders/orders_model';
import { collapseBuildingCreateOrders, isBuildingOrder, isUnitOrder } from '../../application/orders/orders_model';
import { RisqUnitType } from '../../model/types';
import { ORDER_FILTER_BAR_H, RisqOrderFilterBar } from '../order_filter_bar/order_filter_bar';
import { RisqOrderRow } from '../order_row/order_row';
import { RisqOrdersScrollbar } from './orders_scrollbar';

export class RisqOrdersList extends DwgListbox<RisqOrderRow, RisqOrdersScrollbar> {
  private game: DwgRisq;
  private orders: RisqOrdersModel;
  // when set, only orders targeting one of these subjects are shown (used by the left panel); undefined shows all
  private subject_internal_ids?: number[];
  // unit and building internal ids are separate counters and can collide, so the subject filter must also match order category
  private subject_kind?: 'unit' | 'building';
  private cancel_disabled = false;
  private filter_bar: RisqOrderFilterBar;

  constructor(risq: DwgRisq, w: number, background: ColorRGB, with_title = true, show_subject_filter: boolean = true) {
    super({
      list: [],
      scrollbar: new RisqOrdersScrollbar(risq, w, background.copy().dBrightness(-0.1)),
      draw_config: {
        fill_style: background.copy().dBrightness(-0.2).getString(),
        stroke_style: 'rgb(10, 10, 10)',
        stroke_width: 0.5,
        fixed_position: true,
      },
      padding: 2,
      gap: 2,
      title: with_title
        ? {
            text: 'Orders',
            size: 30,
            font_color: 'rgb(0, 0, 0)',
          }
        : undefined,
    });
    this.game = risq;
    this.orders = risq.orders_model;
    this.filter_bar = new RisqOrderFilterBar(
      risq,
      () => this.popoverBounds(),
      () => this.refresh(),
      show_subject_filter
    );
  }

  private popoverBounds(): DropdownBounds {
    return { x: this.xi(), y: this.yi(), w: this.w(), h: this.h() };
  }

  setSubject(subject_internal_ids: number[] | undefined, subject_kind: 'unit' | 'building' | undefined) {
    this.subject_internal_ids = subject_internal_ids;
    this.subject_kind = subject_kind;
  }

  // Overridden so disabling only blocks each row's cancel button; rows stay clickable/scrollable for viewing
  override disable(): void {
    this.cancel_disabled = true;
    for (const row of this.config.list) {
      row.disableCancel();
    }
  }

  override enable(): void {
    this.cancel_disabled = false;
    for (const row of this.config.list) {
      row.enableCancel();
    }
  }

  private newOrderRow(entry: RisqOrderRowEntry): RisqOrderRow {
    const row = new RisqOrderRow({
      w: this.config.scrollbar.w() - this.config.scrollbar.getScrollbarSize() - 2 * this.getPadding(),
      order: entry.order,
      collapsed_orders: entry.collapsed_orders,
      cancelling: this.orders.isCancelling(entry.order, this.subject_internal_ids),
      explicit_cancel: this.orders.isExplicitlyCancelling(entry.order, this.subject_internal_ids),
      game: this.game,
      show_subject: this.subject_internal_ids === undefined || this.subject_internal_ids.length !== 1,
      onCancel: (order) => this.orders.cancel(order),
      onCancelAll: (orders) => orders.forEach((order) => this.orders.cancel(order)),
      onSelect: (order) => this.game.selection.selectOrderSubjects(order),
    });
    if (this.cancel_disabled) {
      row.disableCancel();
    }
    return row;
  }

  refresh() {
    const subject_internal_ids = this.subject_internal_ids;
    const kind_matches = this.subject_kind === 'building' ? isBuildingOrder : isUnitOrder;
    const orders =
      subject_internal_ids === undefined
        ? this.orders.all()
        : this.orders
            .all()
            .filter((o) => kind_matches(o.order_type) && o.subjects.some((s) => subject_internal_ids.includes(s)));
    const context = this.filterContext();
    const shown = orders.filter((o) => this.filter_bar.filter.matches(o, context));
    this.setList(collapseBuildingCreateOrders(shown).map((entry) => this.newOrderRow(entry)));
  }

  private filterContext(): OrderFilterContext {
    const units = this.game.getPlayer()?.units;
    return {
      isCancelled: (order) => this.orders.isCancelling(order, this.subject_internal_ids),
      unitSubjectClass: (unit_internal_id) => {
        const unit = units?.get(unit_internal_id);
        if (!unit) {
          return undefined;
        }
        return unit.unit_type === RisqUnitType.ECONOMIC
          ? OrderSubjectClass.ECONOMIC_UNITS
          : OrderSubjectClass.MILITARY_UNITS;
      },
    };
  }

  override draw(ctx: CanvasRenderingContext2D, transform: BoardTransformData, dt: number): void {
    super.draw(ctx, transform, dt);
    this.filter_bar.draw(ctx, transform, dt);
  }

  override isHovering(): boolean {
    return this.filter_bar.isHovering() || super.isHovering();
  }

  override scroll(dy: number, mode: number, dx?: number): boolean {
    return this.filter_bar.scroll(dy) || super.scroll(dy, mode, dx);
  }

  override mousemove(canvas: Point2D, screen: Point2D, transform: BoardTransformData): boolean {
    if (!this.filter_bar.mousemove(canvas, screen, transform)) {
      return super.mousemove(canvas, screen, transform);
    }
    this.config.list.forEach((row) => row.setHovering(false));
    return true;
  }

  override mousedown(e: MouseEvent): boolean {
    return this.filter_bar.mousedown(e) || super.mousedown(e);
  }

  override mouseup(e: MouseEvent): void {
    this.filter_bar.mouseup(e);
    super.mouseup(e);
  }

  override setClicking(clicking: boolean): void {
    super.setClicking(clicking);
    if (!clicking) {
      this.filter_bar.setClicking(false);
      this.filter_bar.setHovering(false);
    }
  }

  override yi(): number {
    return super.yi() - ORDER_FILTER_BAR_H;
  }

  override h(): number {
    return super.h() + ORDER_FILTER_BAR_H;
  }

  override setAllSizes(size: number, p: Point2D, w: number, h: number): void {
    super.setAllSizes(size, { x: p.x, y: p.y + ORDER_FILTER_BAR_H }, w, h - ORDER_FILTER_BAR_H);
    this.filter_bar.setPosition({ x: p.x + this.getPadding(), y: this.config.scrollbar.yi() - ORDER_FILTER_BAR_H });
    this.filter_bar.setW(w - 2 * this.getPadding());
    for (const el of this.config.list) {
      el.setW(w - this.config.scrollbar.getScrollbarSize() - 2 * this.getPadding());
    }
  }
}

import type { ColorRGB } from '../../../../../../scripts/color_rgb';
import type { BoardTransformData } from '../../../../util/canvas_board/canvas_board';
import type { CanvasComponent, Rotation } from '../../../../util/canvas_components/canvas_component';
import { configDraw } from '../../../../util/canvas_components/canvas_component';
import { drawLine, drawRect, drawText } from '../../../../util/canvas_util';
import type { Point2D } from '../../../../util/objects2d';
import type { DwgRisq } from '../../risq';
import type { GameRisqScoreEntry, RisqPlayerResource, RisqResourceType } from '../../model/types';
import { resourceTypeImage } from '../../rendering/assets/resources';
import { RisqOrdersList } from './orders_list';
import { RisqNextIdleButton } from './next_idle_button';
import { RisqRightPanelButton } from './right_panel_button';
import { RisqSubmitOrdersButton } from './submit_orders_button';
import { RisqSubmitIconButton } from './submit_icon_button';

export declare interface RightPanelConfig {
  w: number;
  is_open: boolean;
  background: ColorRGB;
}

export class RisqRightPanel implements CanvasComponent {
  private static PADDING = 5;
  private static SUBMIT_SIZE = 30;

  private open_button: RisqRightPanelButton;
  private orders_list: RisqOrdersList;
  private submit_button: RisqSubmitOrdersButton;
  private submit_icon_button: RisqSubmitIconButton;
  private next_idle_button: RisqNextIdleButton;
  private need_to_set_position = true;
  private submit_row_y = 0;

  private risq: DwgRisq;
  private config: RightPanelConfig;
  private opening = false;
  private hovering = false;

  constructor(risq: DwgRisq, config: RightPanelConfig) {
    this.risq = risq;
    this.config = config;
    this.open_button = new RisqRightPanelButton(risq);
    this.orders_list = new RisqOrdersList(
      risq,
      config.w - 2 * RisqRightPanel.PADDING,
      config.background.copy().addColor(255, 0, 0, 0.2)
    );
    this.submit_button = new RisqSubmitOrdersButton(risq, RisqRightPanel.SUBMIT_SIZE);
    this.submit_icon_button = new RisqSubmitIconButton(risq, RisqRightPanel.SUBMIT_SIZE);
    this.next_idle_button = new RisqNextIdleButton(risq, RisqRightPanel.SUBMIT_SIZE);
    this.toggle(config.is_open, true);
  }

  dataRefreshed() {
    this.need_to_set_position = true;
    const player = this.risq.getPlayer();
    this.orders_list.refresh();
    if (!player || !this.risq.session.givingOrders()) {
      this.orders_list.disable();
      this.submit_button.disable();
      this.submit_icon_button.disable();
      this.next_idle_button.disable();
      return;
    }
    if (this.risq.session.givingOrders() && !player.orders_submitted) {
      this.orders_list.enable();
      this.submit_button.setText(this.risq.submission.submittedTimes() > 0 ? 'Resubmit Orders' : 'Submit Orders');
    } else {
      this.orders_list.disable();
      this.submit_button.setText('Unsubmit Orders');
    }
    this.next_idle_button.setText(`Next Idle (${this.risq.planning.idleUnitCount()})`);
    if (this.hasIdleUnits()) {
      this.submit_icon_button.enable();
      this.next_idle_button.enable();
      this.submit_button.disable();
    } else {
      this.submit_button.enable();
      this.submit_icon_button.disable();
      this.next_idle_button.disable();
    }
  }

  private hasIdleUnits(): boolean {
    const player = this.risq.getPlayer();
    return (
      !!player && this.risq.session.givingOrders() && !player.orders_submitted && this.risq.planning.idleUnitCount() > 0
    );
  }

  private layoutButtons() {
    const y = this.submit_row_y;
    const left = this.xi() + RisqRightPanel.PADDING;
    if (this.hasIdleUnits()) {
      const icon_w = RisqRightPanel.SUBMIT_SIZE;
      const idle_w = this.w() - 2 * RisqRightPanel.PADDING - icon_w - RisqRightPanel.PADDING;
      this.next_idle_button.setPosition({ x: left, y });
      this.next_idle_button.setW(idle_w);
      this.submit_icon_button.setPosition({ x: left + idle_w + RisqRightPanel.PADDING, y });
    } else {
      this.submit_button.setPosition({ x: left, y });
      this.submit_button.setW(this.w() - 2 * RisqRightPanel.PADDING);
    }
  }

  isHovering(): boolean {
    return this.hovering;
  }

  setHovering(hovering: boolean) {
    this.hovering = hovering;
  }

  isClicking(): boolean {
    return false;
  }

  setClicking(clicking: boolean): void {
    if (!clicking) {
      for (const component of [
        this.open_button,
        this.orders_list,
        this.submit_button,
        this.submit_icon_button,
        this.next_idle_button,
      ]) {
        component.setClicking(false);
        component.setHovering(false);
      }
    }
  }

  isOpen(): boolean {
    return this.config.is_open;
  }

  toggle(open?: boolean, initial?: boolean) {
    this.config.is_open = open ?? !this.config.is_open;
    const position: Point2D = {
      x: this.risq.viewport.canvasSize().width - this.open_button.w(),
      y: 0.5 * this.open_button.h(),
    };
    if (this.config.is_open) {
      position.x -= this.config.w;
    }
    this.opening = true;
    this.open_button.setPosition(
      position,
      () => {
        this.opening = false;
        const rotation: Rotation = {
          direction: this.config.is_open,
          angle: this.config.is_open ? 0.5 * Math.PI : -0.5 * Math.PI,
        };
        this.open_button.setRotation(rotation, undefined, initial);
        this.need_to_set_position = true;
      },
      initial
    );
  }

  submittingOrders() {
    this.orders_list.disable();
    this.submit_button.disable();
    this.submit_button.setText('Submitting Orders ...');
  }

  unsubmittingOrders() {
    this.orders_list.disable();
    this.submit_button.disable();
    this.submit_button.setText('Unsubmitting Orders ...');
  }

  draw(ctx: CanvasRenderingContext2D, transform: BoardTransformData, dt: number) {
    if (this.opening || this.config.is_open) {
      configDraw(
        ctx,
        transform,
        {
          fill_style: this.config.background.getString(),
          stroke_style: 'transparent',
          stroke_width: 0,
          fixed_position: true,
        },
        false,
        false,
        () => {
          drawRect(ctx, { x: this.xi(), y: this.yi() }, this.w(), this.h());
          if (this.opening) {
            return;
          }
          let yi = this.yi() + RisqRightPanel.PADDING;
          const player = this.risq.getPlayer();
          const game = this.risq.getGame();
          drawText(ctx, game?.game_base.game_ended ? 'Game Over' : `Turn ${game?.turn_number ?? '??'}`, {
            p: { x: this.xc(), y: yi },
            w: this.paddedW(),
            fill_style: 'black',
            align: 'center',
            font: 'bold 36px serif',
          });
          yi += 40;
          this.drawSeparator(ctx, yi);
          yi += RisqRightPanel.PADDING;
          ctx.save();
          ctx.beginPath();
          ctx.rect(this.xi(), yi, this.w(), this.yf() - yi);
          ctx.clip();
          if (!!player) {
            ctx.font = '24px serif';
            this.drawPopulation(
              ctx,
              yi,
              player.units.size,
              this.risq.planning.pendingMercenaryCount(),
              player.population_limit
            );
            yi += 30;
            for (const [rt, pr] of [...player.resources.entries()].sort((a, b) => a[0] - b[0])) {
              this.drawResource(ctx, yi, rt, pr);
              yi += 30;
            }
            yi += RisqRightPanel.PADDING;
            this.drawSeparator(ctx, yi);
            yi += RisqRightPanel.PADDING;
          }
          for (const score of game?.scores ?? []) {
            this.drawScore(ctx, yi, score);
            yi += 30;
          }
          ctx.restore();
          yi += RisqRightPanel.PADDING;
          this.drawSeparator(ctx, yi);
          yi += RisqRightPanel.PADDING;
          if (this.need_to_set_position) {
            const submit_height = game?.game_base.game_ended ? 0 : RisqRightPanel.SUBMIT_SIZE + RisqRightPanel.PADDING;
            const orders_list_height = this.yf() - yi - RisqRightPanel.PADDING - submit_height;
            this.orders_list.setAllSizes(
              Math.min(0.1 * this.paddedW(), 20),
              { x: this.xi() + RisqRightPanel.PADDING, y: yi },
              this.w() - 2 * RisqRightPanel.PADDING,
              orders_list_height
            );
            yi += orders_list_height + RisqRightPanel.PADDING;
            this.submit_row_y = yi;
            this.need_to_set_position = false;
          }
        }
      );
    }
    if (this.config.is_open && !this.opening) {
      this.orders_list.draw(ctx, transform, dt);
      this.layoutButtons();
      if (this.hasIdleUnits()) {
        this.next_idle_button.draw(ctx, transform, dt);
        this.next_idle_button.drawTooltip(ctx, transform, this.risq, dt);
        this.submit_icon_button.draw(ctx, transform, dt);
        this.submit_icon_button.drawTooltip(ctx, transform, this.risq, dt);
      } else if (!this.risq.getGame()?.game_base.game_ended) {
        this.submit_button.draw(ctx, transform, dt);
        this.submit_button.drawTooltip(ctx, transform, this.risq, dt);
      }
    }
    this.open_button.draw(ctx, transform, dt);
  }

  private drawSeparator(ctx: CanvasRenderingContext2D, yi: number) {
    ctx.strokeStyle = 'rgba(60, 60, 60, 0.6)';
    ctx.lineWidth = 2;
    drawLine(ctx, { x: this.xi() + 0.15 * this.w(), y: yi }, { x: this.xf() - 0.15 * this.w(), y: yi });
  }

  private drawPopulation(ctx: CanvasRenderingContext2D, yi: number, pop: number, pending: number, limit: number) {
    ctx.beginPath();
    ctx.drawImage(this.risq.getIcon('icons/person64'), this.xi() + 0.1 * this.w(), yi, 30, 30);
    drawText(ctx, pending > 0 ? `${pop}+${pending}/${limit}` : `${pop}/${limit}`, {
      p: { x: this.xi() + 0.1 * this.w() + 36, y: yi + 15 },
      w: 0.9 * this.w() - 36,
      fill_style: pop + pending >= limit ? 'rgb(200, 30, 30)' : 'black',
      baseline: 'middle',
    });
  }

  private drawResource(ctx: CanvasRenderingContext2D, yi: number, rt: RisqResourceType, pr: RisqPlayerResource) {
    ctx.beginPath();
    ctx.drawImage(this.risq.getIcon(resourceTypeImage(rt)), this.xi() + 0.1 * this.w(), yi, 30, 30);
    const net = pr.amount - pr.spending;
    const sign = pr.spending > 0 ? '-' : '+';
    const text = pr.spending !== 0 ? `${net.toFixed(1)} (${sign}${Math.abs(pr.spending).toFixed(1)})` : net.toFixed(1);
    drawText(ctx, text, {
      p: { x: this.xi() + 0.1 * this.w() + 36, y: yi + 15 },
      w: 0.9 * this.w() - 36,
      fill_style: net < 0 ? 'rgb(200, 30, 30)' : 'black',
      baseline: 'middle',
      font: '18px serif',
    });
  }

  private drawScore(ctx: CanvasRenderingContext2D, yi: number, score: GameRisqScoreEntry) {
    ctx.beginPath();
    const text = `${score.nickname}: ${score.score}`;
    drawText(ctx, text, {
      p: { x: this.xi() + 0.9 * this.w(), y: yi + 15 },
      w: 0.8 * this.w(),
      fill_style: score.color.getString(),
      baseline: 'middle',
      align: 'right',
      font: '18px serif',
    });
    if (score.eliminated) {
      const text_w = Math.min(ctx.measureText(text).width, 0.8 * this.w());
      ctx.strokeStyle = score.color.getString();
      ctx.lineWidth = 2;
      drawLine(
        ctx,
        { x: this.xi() + 0.9 * this.w() - text_w, y: yi + 15 },
        { x: this.xi() + 0.9 * this.w(), y: yi + 15 }
      );
    }
  }

  scroll(dy: number, mode: number): boolean {
    return this.orders_list.scroll(dy, mode);
  }

  mousemove(canvas: Point2D, screen: Point2D, transform: BoardTransformData): boolean {
    if (this.open_button.mousemove(canvas, screen, transform)) {
      return true;
    }
    this.orders_list.mousemove(canvas, screen, transform);
    if (this.hasIdleUnits()) {
      this.next_idle_button.mousemove(canvas, screen, transform);
      this.submit_icon_button.mousemove(canvas, screen, transform);
    } else if (!this.risq.getGame()?.game_base.game_ended) {
      this.submit_button.mousemove(canvas, screen, transform);
    }
    if (screen.x > this.xi() && screen.y > this.yi() && screen.x < this.xf() && screen.y < this.yf()) {
      this.hovering = true;
    } else {
      this.hovering = false;
    }
    return this.isHovering();
  }

  mousedown(e: MouseEvent): boolean {
    if (this.open_button.mousedown(e)) {
      return true;
    }
    this.orders_list.mousedown(e);
    if (this.hasIdleUnits()) {
      this.next_idle_button.mousedown(e);
      this.submit_icon_button.mousedown(e);
    } else if (!this.risq.getGame()?.game_base.game_ended) {
      this.submit_button.mousedown(e);
    }
    return this.isHovering();
  }

  mouseup(e: MouseEvent) {
    this.open_button.mouseup(e);
    this.orders_list.mouseup(e);
    if (this.hasIdleUnits()) {
      this.next_idle_button.mouseup(e);
      this.submit_icon_button.mouseup(e);
    } else if (!this.risq.getGame()?.game_base.game_ended) {
      this.submit_button.mouseup(e);
    }
  }

  xi(): number {
    return this.open_button.xf();
  }
  yi(): number {
    return 0;
  }
  xf(): number {
    return this.risq.viewport.canvasSize().width;
  }
  yf(): number {
    return this.risq.viewport.canvasSize().height;
  }
  xc(): number {
    return this.xi() + 0.5 * this.w();
  }
  yc(): number {
    return this.yi() + 0.5 * this.h();
  }
  w(): number {
    return this.xf() - this.xi();
  }
  paddedW(): number {
    return this.w() - 2 * RisqRightPanel.PADDING;
  }
  h(): number {
    return this.yf() - this.yi();
  }
}

