import type { BoardTransformData } from '../../../util/canvas_board/canvas_board';
import { drawRect, drawText } from '../../../util/canvas_util';
import type { Point2D } from '../../../util/objects2d';
import { configDraw } from '../../../util/canvas_components/canvas_component';
import {
  anchorTooltipBox,
  createTooltipState,
  drawTooltip,
  shouldShowTooltip,
} from '../../../util/canvas_components/tooltip';
import type { CanvasSize, TooltipState } from '../../../util/canvas_components/tooltip';
import type { DwgRisq } from '../risq';
import type { RisqCost } from '../model/types';
import { RisqResourceType } from '../model/types';
import { resourceTypeImage } from '../rendering/assets/resources';

export declare interface RisqTooltipData {
  title: string;
  description?: string;
  cost?: RisqCost;
  stamina_cost?: number;
  // icon path, value; stats of the thing being made/researched (e.g. health, attack)
  stats?: [string, number][];
  hotkey?: string; // always rendered as the bottom-most row
}

type RisqTooltipDrawData = RisqTooltipData & { risq: DwgRisq };

const PADDING = 4;
const ROW_HEIGHT = 16;
const ICON_SIZE = ROW_HEIGHT - 2;
const ICON_TEXT_GAP = 4;
const STAT_GAP = 6;
const TITLE_COST_GAP = 10;
const FONT = '12px serif';
const TITLE_FONT = 'bold 13px serif';
const HOTKEY_FONT = 'italic 11px serif';
const HOTKEY_COLOR = 'rgba(255, 255, 255, 0.6)';

function costStats(data: RisqTooltipData): [string, string][] {
  const entries: [string, number][] = [];
  if (!!data.cost) {
    entries.push(
      [resourceTypeImage(RisqResourceType.FOOD), data.cost.food],
      [resourceTypeImage(RisqResourceType.WOOD), data.cost.wood],
      [resourceTypeImage(RisqResourceType.STONE), data.cost.stone],
      [resourceTypeImage(RisqResourceType.GOLD), data.cost.gold]
    );
  }
  if (data.stamina_cost !== undefined) {
    entries.push(['risq/icons/stamina', data.stamina_cost]);
  }
  return entries.filter(([, value]) => !!value).map(([icon, value]) => [icon, value.toString()]);
}

function measureStatsRow(ctx: CanvasRenderingContext2D, stats: [string, string][]): number {
  if (!stats.length) {
    return 0;
  }
  return (
    stats.reduce((sum, [, text]) => sum + ICON_SIZE + ICON_TEXT_GAP + ctx.measureText(text).width, 0) +
    STAT_GAP * (stats.length - 1)
  );
}

function drawStatsRow(ctx: CanvasRenderingContext2D, risq: DwgRisq, stats: [string, string][], x: number, y: number) {
  let xi = x;
  for (const [icon, text] of stats) {
    ctx.drawImage(risq.getIcon(icon), xi, y, ICON_SIZE, ICON_SIZE);
    const text_x = xi + ICON_SIZE + ICON_TEXT_GAP;
    const text_w = ctx.measureText(text).width;
    drawText(ctx, text, {
      p: { x: text_x, y: y + 0.5 * ICON_SIZE },
      w: text_w + 2,
      fill_style: 'white',
      align: 'left',
      baseline: 'middle',
      font: FONT,
    });
    xi = text_x + text_w + STAT_GAP;
  }
}

function risqTooltipDraw(
  ctx: CanvasRenderingContext2D,
  transform: BoardTransformData,
  canvas_size: CanvasSize,
  p: Point2D,
  data: RisqTooltipDrawData
) {
  configDraw(ctx, transform, { fill_style: 'transparent', stroke_width: 0, fixed_position: true }, false, false, () => {
    ctx.font = FONT;
    const cost_stats = costStats(data);
    const stats = (data.stats ?? []).map(([icon, value]) => [icon, value.toString()] as [string, string]);
    ctx.font = TITLE_FONT;
    const title_w = ctx.measureText(data.title).width;
    ctx.font = FONT;
    const row1_w = title_w + (cost_stats.length ? TITLE_COST_GAP + measureStatsRow(ctx, cost_stats) : 0);
    const desc_w = data.description ? ctx.measureText(data.description).width : 0;
    const stats_w = measureStatsRow(ctx, stats);
    ctx.font = HOTKEY_FONT;
    const hotkey_text = data.hotkey ? `Hotkey: ${data.hotkey}` : undefined;
    const hotkey_w = hotkey_text ? ctx.measureText(hotkey_text).width : 0;
    ctx.font = FONT;
    const w = Math.max(row1_w, desc_w, stats_w, hotkey_w) + 2 * PADDING;
    const num_rows = 1 + (data.description ? 1 : 0) + (stats.length ? 1 : 0) + (hotkey_text ? 1 : 0);
    const h = num_rows * ROW_HEIGHT + 2 * PADDING;
    const box_p = anchorTooltipBox(p, w, h, canvas_size);
    ctx.fillStyle = 'rgba(0, 0, 0, 0.85)';
    ctx.strokeStyle = 'rgba(250, 250, 250, 0.9)';
    ctx.lineWidth = 1;
    drawRect(ctx, box_p, w, h, 3);
    let row_y = box_p.y + PADDING + 0.5 * ROW_HEIGHT;
    drawText(ctx, data.title, {
      p: { x: box_p.x + PADDING, y: row_y },
      w: title_w + 2,
      fill_style: 'white',
      align: 'left',
      baseline: 'middle',
      font: TITLE_FONT,
    });
    if (cost_stats.length) {
      const costs_w = measureStatsRow(ctx, cost_stats);
      drawStatsRow(ctx, data.risq, cost_stats, box_p.x + w - PADDING - costs_w, row_y - 0.5 * ICON_SIZE);
    }
    if (data.description) {
      row_y += ROW_HEIGHT;
      drawText(ctx, data.description, {
        p: { x: box_p.x + PADDING, y: row_y },
        w: w - 2 * PADDING,
        fill_style: 'white',
        align: 'left',
        baseline: 'middle',
        font: FONT,
      });
    }
    if (stats.length) {
      row_y += ROW_HEIGHT;
      drawStatsRow(ctx, data.risq, stats, box_p.x + PADDING, row_y - 0.5 * ICON_SIZE);
    }
    if (hotkey_text) {
      row_y += ROW_HEIGHT;
      drawText(ctx, hotkey_text, {
        p: { x: box_p.x + PADDING, y: row_y },
        w: w - 2 * PADDING,
        fill_style: HOTKEY_COLOR,
        align: 'left',
        baseline: 'middle',
        font: HOTKEY_FONT,
      });
    }
  });
}

export function createRisqTooltipState(delay_ms?: number): TooltipState<RisqTooltipDrawData> {
  return createTooltipState<RisqTooltipDrawData>({
    draw: risqTooltipDraw,
    ...(delay_ms !== undefined && { delay_ms }),
  });
}

export function drawRisqTooltip(
  ctx: CanvasRenderingContext2D,
  transform: BoardTransformData,
  risq: DwgRisq,
  dt: number,
  hovering: boolean,
  clicked: boolean,
  state: TooltipState<RisqTooltipDrawData>,
  data: RisqTooltipData
) {
  if (!shouldShowTooltip(state, hovering, clicked, dt)) {
    return;
  }
  drawTooltip(state, ctx, transform, risq.viewport.canvasSize(), { ...data, risq });
}

export class RisqButtonTooltip {
  private state = createRisqTooltipState();

  constructor(private getData: () => RisqTooltipData) {}

  draw(
    ctx: CanvasRenderingContext2D,
    transform: BoardTransformData,
    risq: DwgRisq,
    dt: number,
    hovering: boolean,
    clicked: boolean
  ) {
    drawRisqTooltip(ctx, transform, risq, dt, hovering, clicked, this.state, this.getData());
  }
}

import { DwgElement } from '../../../../../dwg_element';
import { apiGet } from '../../../../../../scripts/api';
import { getSettings, updateSettings } from '../../../../../../scripts/settings_store';
import { enumKeys } from '../../../../../../scripts/util';
import type {
  HotkeyCombo,
  HotkeySelection,
  RisqHotkeyBindings,
  RisqHotkeyLookupEntry,
} from '../../application/input/hotkeys';
import {
  RISQ_HOTKEY_ACTION_LABELS,
  RISQ_HOTKEY_SCOPE_LABELS,
  RisqHotkeyAction,
  RisqHotkeyScope,
  UNIT_HOTKEY_SELECTIONS,
  actionScope,
  comboFromKeyboardEvent,
  comboFromMouseEvent,
  comboToDisplayString,
  comboToString,
  hotkeysConflict,
  isUnbound,
} from '../../application/input/hotkeys';
import { RisqProducibleKind } from '../../model/types';

import html from './risq_settings.html';

import './risq_settings.scss';

interface ProducibleEntry {
  kind: RisqProducibleKind;
  id: number;
  display_name: string;
  unlocks_mercenaries?: { id: number; display_name: string }[];
}

interface BuildingTreeEntry {
  building_id: number;
  display_name: string;
  produces: ProducibleEntry[];
}

type IdBindingGroup = 'create_unit' | 'research_tech' | 'build_building' | 'cycle_building' | 'hire_mercenary';

type BindingSlot = { group: 'actions'; key: RisqHotkeyAction } | { group: IdBindingGroup; key: number };

interface HotkeyEntry {
  section: string;
  subsection?: string;
  label: string;
  slot: BindingSlot;
}

const GLOBAL_SECTION = RISQ_HOTKEY_SCOPE_LABELS[RisqHotkeyScope.GLOBAL];

type RisqSettingsTab = 'animations' | 'hotkeys';

export class DwgRisqSettings extends DwgElement {
  private tab_button_animations!: HTMLButtonElement;
  private tab_button_hotkeys!: HTMLButtonElement;
  private tab_content_animations!: HTMLDivElement;
  private tab_content_hotkeys!: HTMLDivElement;
  private status!: HTMLDivElement;
  private rows!: HTMLDivElement;
  private bindings: RisqHotkeyBindings = getSettings().risq_hotkeys;
  private entries: HotkeyEntry[] = [];
  // generic building covers building-only actions before (or if) the tech tree loads
  private selections: HotkeySelection[] = [...UNIT_HOTKEY_SELECTIONS, { kind: 'building', unit_ids: [], tech_ids: [] }];
  private listener_cleanup?: () => void;

  constructor() {
    super();
    this.html_string = html;
    this.configureElements(
      'tab_button_animations',
      'tab_button_hotkeys',
      'tab_content_animations',
      'tab_content_hotkeys',
      'status',
      'rows'
    );
  }

  protected override async parsedCallback(): Promise<void> {
    this.entries = [];
    this.tab_button_animations.addEventListener('click', () => this.showTab('animations'));
    this.tab_button_hotkeys.addEventListener('click', () => this.showTab('hotkeys'));
    for (const key of enumKeys(RisqHotkeyAction)) {
      const action = RisqHotkeyAction[key];
      this.entries.push({
        section: RISQ_HOTKEY_SCOPE_LABELS[actionScope(action)],
        subsection: action === RisqHotkeyAction.GO_TO_SELECTION ? 'Selection' : undefined,
        label: RISQ_HOTKEY_ACTION_LABELS[action],
        slot: { group: 'actions', key: action },
      });
    }
    this.renderAll();
    const response = await apiGet<BuildingTreeEntry[]>('risq/tech-tree');
    this.status.classList.add('hide');
    if (response.success) {
      this.addBuildingEntries(response.result);
      this.renderAll();
    }
  }

  override disconnectedCallback(): void {
    super.disconnectedCallback();
    this.listener_cleanup?.();
  }

  private showTab(tab: RisqSettingsTab) {
    this.tab_button_animations.classList.toggle('active', tab === 'animations');
    this.tab_button_hotkeys.classList.toggle('active', tab === 'hotkeys');
    this.tab_content_animations.classList.toggle('active', tab === 'animations');
    this.tab_content_hotkeys.classList.toggle('active', tab === 'hotkeys');
  }

  private addBuildingEntries(buildings: BuildingTreeEntry[]) {
    for (const building of buildings) {
      if (building.produces.length === 0) {
        continue;
      }
      const ids = (kind: RisqProducibleKind) => building.produces.filter((p) => p.kind === kind).map((p) => p.id);
      this.selections.push({
        kind: 'building',
        unit_ids: ids(RisqProducibleKind.UNIT),
        tech_ids: ids(RisqProducibleKind.TECH),
      });
      this.entries.push({
        section: GLOBAL_SECTION,
        label: `Select Building: ${building.display_name}`,
        subsection: 'Selection',
        slot: { group: 'cycle_building', key: building.building_id },
      });
      for (const producible of building.produces) {
        const [group, verb] = this.producibleGroup(producible.kind);
        const section =
          group === 'build_building' ? RISQ_HOTKEY_SCOPE_LABELS[RisqHotkeyScope.VILLAGERS] : building.display_name;
        this.entries.push({
          section,
          label: `${verb}: ${producible.display_name}`,
          slot: { group, key: producible.id },
        });
        for (const mercenary of producible.unlocks_mercenaries ?? []) {
          this.entries.push({
            section: GLOBAL_SECTION,
            label: `Hire: ${mercenary.display_name}`,
            slot: { group: 'hire_mercenary', key: mercenary.id },
          });
        }
      }
    }
  }

  private producibleGroup(kind: RisqProducibleKind): [IdBindingGroup, string] {
    switch (kind) {
      case RisqProducibleKind.UNIT:
        return ['create_unit', 'Create'];
      case RisqProducibleKind.TECH:
        return ['research_tech', 'Research'];
      default:
        return ['build_building', 'Build'];
    }
  }

  private slotCombo(slot: BindingSlot): HotkeyCombo {
    return slot.group === 'actions' ? this.bindings.actions[slot.key] : (this.bindings[slot.group][slot.key] ?? {});
  }

  private assign(slot: BindingSlot, combo: HotkeyCombo) {
    if (slot.group === 'actions') {
      this.bindings.actions[slot.key] = combo;
    } else {
      this.bindings[slot.group][slot.key] = combo;
    }
  }

  private slotEntry(slot: BindingSlot): RisqHotkeyLookupEntry {
    return slot.group === 'actions' ? { kind: 'action', action: slot.key } : { kind: slot.group, id: slot.key };
  }

  private setSlotCombo(slot: BindingSlot, combo: HotkeyCombo) {
    if (!isUnbound(combo)) {
      const target = comboToString(combo);
      const new_entry = this.slotEntry(slot);
      for (const entry of this.entries) {
        const same_combo = comboToString(this.slotCombo(entry.slot)) === target;
        if (same_combo && hotkeysConflict(this.slotEntry(entry.slot), new_entry, this.selections)) {
          this.assign(entry.slot, {});
        }
      }
    }
    this.assign(slot, combo);
    updateSettings({ risq_hotkeys: this.bindings });
  }

  private renderAll() {
    const sections = new Map<string, HotkeyEntry[]>();
    for (const entry of this.entries) {
      sections.set(entry.section, [...(sections.get(entry.section) ?? []), entry]);
    }
    this.rows.replaceChildren(
      ...[...sections.entries()].flatMap(([section, entries]) => {
        const header = document.createElement('div');
        header.classList.add('hotkey-section-header');
        header.innerText = section;
        return [header, ...this.buildSectionRows(entries)];
      })
    );
  }

  private buildSectionRows(entries: HotkeyEntry[]): HTMLDivElement[] {
    const subsections = new Map<string, HotkeyEntry[]>();
    const rows = entries.filter((entry) => !entry.subsection).map((entry) => this.buildRow(entry));
    for (const entry of entries) {
      if (entry.subsection) {
        subsections.set(entry.subsection, [...(subsections.get(entry.subsection) ?? []), entry]);
      }
    }
    for (const [subsection, subsection_entries] of subsections) {
      const header = document.createElement('div');
      header.classList.add('hotkey-subsection-header');
      header.innerText = subsection;
      rows.push(header, ...subsection_entries.map((entry) => this.buildRow(entry)));
    }
    return rows;
  }

  private buildRow(entry: HotkeyEntry): HTMLDivElement {
    const row = document.createElement('div');
    row.classList.add('hotkey-row');
    const label_el = document.createElement('span');
    label_el.classList.add('hotkey-label');
    label_el.innerText = entry.label;
    const value_button = document.createElement('button');
    value_button.classList.add('hotkey-value');
    value_button.innerText = this.valueText(entry.slot);
    value_button.addEventListener('click', () => this.beginListening(value_button, entry.slot));
    const clear_button = document.createElement('button');
    clear_button.classList.add('hotkey-clear');
    clear_button.innerText = 'x';
    clear_button.addEventListener('click', () => {
      this.setSlotCombo(entry.slot, {});
      this.renderAll();
    });
    row.append(label_el, value_button, clear_button);
    return row;
  }

  private valueText(slot: BindingSlot): string {
    const combo = this.slotCombo(slot);
    return isUnbound(combo) ? 'Unbound' : comboToDisplayString(combo);
  }

  private beginListening(button: HTMLButtonElement, slot: BindingSlot) {
    this.listener_cleanup?.();
    button.innerText = 'Press a key...';
    const on_keydown = (e: KeyboardEvent) => {
      e.preventDefault();
      if (e.key === 'Escape') {
        this.stopListening(button, slot);
        return;
      }
      if (/^[0-9]$/.test(e.key) || ['Control', 'Shift', 'Alt'].includes(e.key)) {
        return; // digits are reserved for control groups; a bare modifier isn't a complete combo
      }
      this.setSlotCombo(slot, comboFromKeyboardEvent(e));
      this.renderAll();
      this.listener_cleanup?.();
      this.listener_cleanup = undefined;
    };
    const on_mousedown = (e: MouseEvent) => {
      if (e.button < 3) {
        return; // 0/1/2 are reserved for game interaction
      }
      e.preventDefault();
      this.setSlotCombo(slot, comboFromMouseEvent(e));
      this.renderAll();
      this.listener_cleanup?.();
      this.listener_cleanup = undefined;
    };
    window.addEventListener('keydown', on_keydown, true);
    window.addEventListener('mousedown', on_mousedown, true);
    this.listener_cleanup = () => {
      window.removeEventListener('keydown', on_keydown, true);
      window.removeEventListener('mousedown', on_mousedown, true);
    };
  }

  private stopListening(button: HTMLButtonElement, slot: BindingSlot) {
    this.listener_cleanup?.();
    this.listener_cleanup = undefined;
    button.innerText = this.valueText(slot);
  }
}

customElements.define('dwg-risq-settings', DwgRisqSettings);

