import { DwgDialogBox, DialogSize } from '../../../../../dialog_box/dialog_box';
import type { TechTreeDialogData, TreeNode, RisqBuildingTreeEntry, HeaderNode, RisqUnitStatsEntry } from './tree_nodes';
import html from './tech_tree_dialog.html';
import { apiGet } from '../../../../../../scripts/api';
import { createImage } from '../../../../../../scripts/image';
import {
  COLUMN_W,
  NODE_GAP,
  NODE_S,
  PADDING,
  techStatus,
  HEADER_H,
  HEADER_TO_NODES_GAP,
  COLUMN_GAP,
  STATUS_FILL,
  STATUS_STROKE,
  nodeIcon,
  ICON_PADDING_NODE,
  ICON_S_HEADER,
  STATUS_TEXT,
  RANGE_DISTANCE,
} from './tree_nodes';
import { RisqProducibleKind, RisqResourceType, RisqUnitType } from '../../model/types';
import { buildingImage } from '../../rendering/assets/buildings';
import type { RisqCost } from '../../model/types';
import { resourceTypeImage } from '../../rendering/assets/resources';
import './tech_tree_dialog.scss';
export class DwgRisqTechTreeDialog extends DwgDialogBox<TechTreeDialogData> {
  private wrapper!: HTMLDivElement;
  private title_heading!: HTMLHeadingElement;
  private canvas_scroll!: HTMLDivElement;
  private canvas!: HTMLCanvasElement;
  private empty_message!: HTMLParagraphElement;
  private hover_tooltip!: HTMLDivElement;
  private close_button!: HTMLButtonElement;

  private data!: TechTreeDialogData;
  private nodes: TreeNode[] = [];
  private hovered_node?: TreeNode;
  private pending_icon_loads = new Set<HTMLImageElement>();

  constructor() {
    super();
    this.configureElement('title_heading', 'title');
    this.configureElements('wrapper', 'canvas_scroll', 'canvas', 'empty_message', 'hover_tooltip', 'close_button');
  }

  override getHTML(): string {
    return html;
  }

  getData(): TechTreeDialogData {
    return this.data;
  }

  setData(data: TechTreeDialogData, parsed?: boolean) {
    this.data = data;
    this.close_hotkey = data.close_hotkey;
    this.classList.add(`size-${DialogSize.XXLARGE}`);
    if (!parsed && !this.fully_parsed) {
      return;
    }
    this.close_button.addEventListener('click', () => {
      this.closeDialog();
    });
    this.canvas.addEventListener('mousemove', (e) => this.handleMousemove(e));
    this.canvas.addEventListener('mouseleave', () => this.hideTooltip());
    this.loadTree();
  }

  private async loadTree() {
    const response = await apiGet<RisqBuildingTreeEntry[]>('risq/tech-tree');
    if (!response.success || response.result.length === 0) {
      this.canvas.hidden = true;
      this.empty_message.hidden = false;
      return;
    }
    this.canvas.hidden = false;
    this.empty_message.hidden = true;
    this.renderTree(response.result);
  }

  private nodesPerRow(): number {
    return Math.max(1, Math.floor((COLUMN_W + NODE_GAP) / (NODE_S + NODE_GAP)));
  }

  private renderTree(buildings: RisqBuildingTreeEntry[]) {
    const researched_techs = this.data.risq.getPlayer()?.researched_techs;
    const nodes_per_row = this.nodesPerRow();
    this.nodes = [];
    let x = PADDING;
    let max_column_h = 0;
    for (const building of buildings) {
      const producibles = [...building.produces].sort((a, b) => a.row - b.row || a.id - b.id);
      const header_status = techStatus(building.required_tech_id, false, researched_techs);
      this.nodes.push({
        kind: 'header',
        x,
        y: PADDING,
        w: COLUMN_W,
        h: HEADER_H,
        status: header_status === 'researched' ? 'available' : header_status,
        building,
      });
      const rows = Math.ceil(producibles.length / nodes_per_row);
      const nodes_top = PADDING + HEADER_H + HEADER_TO_NODES_GAP;
      producibles.forEach((entry, i) => {
        const row = Math.floor(i / nodes_per_row);
        const col = i % nodes_per_row;
        const researched = entry.kind === RisqProducibleKind.TECH && !!researched_techs?.get(entry.id);
        this.nodes.push({
          kind: 'producible',
          x: x + col * (NODE_S + NODE_GAP),
          y: nodes_top + row * (NODE_S + NODE_GAP),
          w: NODE_S,
          h: NODE_S,
          status: techStatus(entry.required_tech_id, researched, researched_techs),
          entry,
        });
      });
      const column_h = rows > 0 ? nodes_top - PADDING + rows * NODE_S + (rows - 1) * NODE_GAP : HEADER_H;
      max_column_h = Math.max(max_column_h, column_h);
      x += COLUMN_W + COLUMN_GAP;
    }
    const content_w = x - COLUMN_GAP + PADDING;
    const content_h = max_column_h + 2 * PADDING;
    this.drawCanvas(content_w, content_h);
  }

  private drawCanvas(content_w: number, content_h: number) {
    const dpr = window.devicePixelRatio || 1;
    this.canvas.style.width = `${content_w}px`;
    this.canvas.style.height = `${content_h}px`;
    this.canvas.width = content_w * dpr;
    this.canvas.height = content_h * dpr;
    const ctx = this.canvas.getContext('2d');
    if (!ctx) {
      return;
    }
    ctx.scale(dpr, dpr);
    this.redraw(ctx, content_w, content_h);
  }

  private redraw(ctx: CanvasRenderingContext2D, content_w: number, content_h: number) {
    ctx.fillStyle = 'black';
    ctx.fillRect(0, 0, content_w, content_h);
    for (const node of this.nodes) {
      if (node.kind === 'header') {
        this.drawConnectors(ctx, node);
      }
    }
    for (const node of this.nodes) {
      this.drawNode(ctx, node);
    }
  }

  /** Draws a branch line from the header to each of its own producible nodes, so every node is visibly connected */
  private drawConnectors(ctx: CanvasRenderingContext2D, header: HeaderNode) {
    const from = { x: header.x + 0.5 * header.w, y: header.y + header.h };
    ctx.strokeStyle = 'rgba(200, 190, 175, 0.35)';
    ctx.lineWidth = 1.5;
    for (const node of this.nodes) {
      if (node.kind !== 'producible' || node.x < header.x || node.x >= header.x + header.w) {
        continue;
      }
      ctx.beginPath();
      ctx.moveTo(from.x, from.y);
      ctx.lineTo(node.x + 0.5 * node.w, node.y);
      ctx.stroke();
    }
  }

  /** Returns the cached icon, and schedules a redraw once it finishes loading if it isn't ready yet */
  private trackedIcon(path: string): HTMLImageElement {
    const icon = this.data.risq.getIcon(path);
    if (!icon.complete && !this.pending_icon_loads.has(icon)) {
      this.pending_icon_loads.add(icon);
      icon.addEventListener(
        'load',
        () => {
          this.pending_icon_loads.delete(icon);
          this.redrawFromCache();
        },
        { once: true }
      );
    }
    return icon;
  }

  private drawNode(ctx: CanvasRenderingContext2D, node: TreeNode) {
    ctx.fillStyle = STATUS_FILL[node.status];
    ctx.strokeStyle = node === this.hovered_node ? 'white' : STATUS_STROKE[node.status];
    ctx.lineWidth = node === this.hovered_node ? 2.5 : 1.5;
    ctx.beginPath();
    ctx.roundRect(node.x, node.y, node.w, node.h, 6);
    ctx.fill();
    ctx.stroke();

    if (node.kind === 'header') {
      this.drawHeaderContent(ctx, node);
    } else {
      const icon = this.trackedIcon(nodeIcon(node.entry));
      const icon_s = node.w - 2 * ICON_PADDING_NODE;
      ctx.drawImage(icon, node.x + ICON_PADDING_NODE, node.y + ICON_PADDING_NODE, icon_s, icon_s);
    }
  }

  private drawHeaderContent(ctx: CanvasRenderingContext2D, node: HeaderNode) {
    const icon = this.trackedIcon(buildingImage(node.building.building_id, false, true));
    ctx.drawImage(icon, node.x + 8, node.y + 0.5 * node.h - 0.5 * ICON_S_HEADER, ICON_S_HEADER, ICON_S_HEADER);

    ctx.fillStyle = STATUS_TEXT[node.status];
    ctx.textBaseline = 'top';
    ctx.font = 'bold 14px serif';
    const text_x = node.x + 12 + ICON_S_HEADER;
    const text_w = node.w - 20 - ICON_S_HEADER;
    ctx.fillText(this.truncateText(ctx, node.building.display_name, text_w), text_x, node.y + 10, text_w);

    ctx.font = '11px serif';
    ctx.fillStyle = 'rgba(200, 190, 175, 0.85)';
    const lines = this.wrapText(ctx, node.building.description, text_w, 2);
    lines.forEach((line, i) => ctx.fillText(line, text_x, node.y + 30 + i * 13, text_w));
  }

  private truncateText(ctx: CanvasRenderingContext2D, text: string, max_w: number): string {
    if (ctx.measureText(text).width <= max_w) {
      return text;
    }
    let truncated = text;
    while (truncated.length > 1 && ctx.measureText(`${truncated}…`).width > max_w) {
      truncated = truncated.slice(0, -1);
    }
    return `${truncated}…`;
  }

  private wrapText(ctx: CanvasRenderingContext2D, text: string, max_w: number, max_lines: number): string[] {
    const words = text.split(' ');
    const lines: string[] = [];
    let current = '';
    for (const word of words) {
      const attempt = current ? `${current} ${word}` : word;
      if (current && ctx.measureText(attempt).width > max_w) {
        lines.push(current);
        current = word;
        if (lines.length === max_lines - 1) {
          break;
        }
      } else {
        current = attempt;
      }
    }
    if (current && lines.length < max_lines) {
      lines.push(current);
    }
    if (lines.length === max_lines && ctx.measureText(lines[max_lines - 1]).width > max_w) {
      lines[max_lines - 1] = this.truncateText(ctx, lines[max_lines - 1], max_w);
    }
    return lines;
  }

  private handleMousemove(e: MouseEvent) {
    const rect = this.canvas.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    const found = this.nodes.find((node) => x >= node.x && x <= node.x + node.w && y >= node.y && y <= node.y + node.h);
    if (found === this.hovered_node) {
      if (found) {
        this.positionTooltip(e);
      }
      return;
    }
    this.hovered_node = found;
    this.redrawFromCache();
    if (found) {
      this.hover_tooltip.replaceChildren(this.buildTooltipContent(found));
      this.hover_tooltip.hidden = false;
      this.positionTooltip(e);
    } else {
      this.hideTooltip();
    }
  }

  private addLine(container: DocumentFragment, text: string, cls = 'tooltip-line') {
    const line = document.createElement('span');
    line.classList.add(cls);
    line.innerText = text;
    container.appendChild(line);
  }

  private addStatChip(container: HTMLElement, icon_path: string, value: number) {
    const chip = document.createElement('span');
    const img = createImage(`/images/${icon_path}.png`);
    img.alt = '';
    const text = document.createElement('span');
    text.innerText = value.toString();
    chip.append(img, text);
    container.appendChild(chip);
  }

  private addCostRow(fragment: DocumentFragment, cost: RisqCost) {
    const cost_row = document.createElement('div');
    cost_row.classList.add('tooltip-stats');
    const costs: [RisqResourceType, number][] = [
      [RisqResourceType.FOOD, cost.food],
      [RisqResourceType.WOOD, cost.wood],
      [RisqResourceType.STONE, cost.stone],
      [RisqResourceType.GOLD, cost.gold],
    ];
    for (const [resource_type, amount] of costs) {
      if (amount) {
        this.addStatChip(cost_row, resourceTypeImage(resource_type), amount);
      }
    }
    if (cost_row.children.length > 0) {
      fragment.appendChild(cost_row);
    }
  }

  private addStatsRows(fragment: DocumentFragment, stats: RisqUnitStatsEntry) {
    this.addLine(fragment, `Health: ${stats.health}`);
    const combat_row = document.createElement('div');
    combat_row.classList.add('tooltip-stats');
    if (stats.attack_blunt) {
      this.addStatChip(combat_row, 'risq/icons/attack_blunt', stats.attack_blunt);
    }
    if (stats.attack_piercing) {
      this.addStatChip(combat_row, 'risq/icons/attack_piercing', stats.attack_piercing);
    }
    const range_distance = RANGE_DISTANCE[stats.attack_range];
    if (range_distance !== undefined) {
      this.addStatChip(combat_row, 'risq/icons/attack_range', range_distance);
    }
    if (stats.defense_blunt) {
      this.addStatChip(combat_row, 'risq/icons/defense_blunt', stats.defense_blunt);
    }
    if (stats.defense_piercing) {
      this.addStatChip(combat_row, 'risq/icons/defense_piercing', stats.defense_piercing);
    }
    if (stats.penetration_blunt) {
      this.addStatChip(combat_row, 'risq/icons/penetration_blunt', stats.penetration_blunt);
    }
    if (stats.penetration_piercing) {
      this.addStatChip(combat_row, 'risq/icons/penetration_piercing', stats.penetration_piercing);
    }
    if (combat_row.children.length > 0) {
      fragment.appendChild(combat_row);
    }
  }

  private buildTooltipContent(node: TreeNode): DocumentFragment {
    const fragment = document.createDocumentFragment();
    if (node.kind === 'header') {
      const title = document.createElement('span');
      title.classList.add('tooltip-title');
      title.innerText = node.building.display_name;
      const description = document.createElement('span');
      description.classList.add('tooltip-description');
      description.innerText = node.building.description;
      fragment.append(title, description);
      this.addCostRow(fragment, node.building.cost);
      if (node.building.stats) {
        this.addStatsRows(fragment, node.building.stats);
      }
      return fragment;
    }
    const entry = node.entry;
    const title = document.createElement('span');
    title.classList.add('tooltip-title');
    title.innerText = entry.display_name;
    const description = document.createElement('span');
    description.classList.add('tooltip-description');
    description.innerText = entry.description;
    fragment.append(title, description);
    this.addCostRow(fragment, entry.cost);
    if (entry.stats) {
      this.addStatsRows(fragment, entry.stats);
    }
    if (entry.unlocks_mercenaries?.length) {
      this.addLine(fragment, `Unlocks mercenaries: ${entry.unlocks_mercenaries.map((m) => m.display_name).join(', ')}`);
    }

    if (entry.bonus) {
      const affected = (entry.affects_unit_types ?? []).map((t) => RisqUnitType[t]?.toLowerCase() ?? t.toString());
      if (affected.length > 0) {
        this.addLine(fragment, `Affects: ${affected.join(', ')}`);
      } else if ((entry.affects_unit_ids ?? []).length > 0) {
        this.addLine(fragment, `Affects: ${entry.affects_unit_ids!.length} unit(s)`);
      }
      if (entry.bonus.max_health) {
        this.addLine(fragment, `Bonus health: +${entry.bonus.max_health}`);
      }
      if (entry.bonus.turn_stamina) {
        this.addLine(fragment, `Bonus stamina/turn: +${entry.bonus.turn_stamina}`);
      }
      const bonus_row = document.createElement('div');
      bonus_row.classList.add('tooltip-stats');
      const bonus_chips: [string, number][] = [
        ['risq/icons/attack_blunt', entry.bonus.attack_blunt],
        ['risq/icons/attack_piercing', entry.bonus.attack_piercing],
        ['risq/icons/attack_magic', entry.bonus.attack_magic],
        ['risq/icons/defense_blunt', entry.bonus.defense_blunt],
        ['risq/icons/defense_piercing', entry.bonus.defense_piercing],
        ['risq/icons/defense_magic', entry.bonus.defense_magic],
        ['risq/icons/penetration_blunt', entry.bonus.penetration_blunt],
        ['risq/icons/penetration_piercing', entry.bonus.penetration_piercing],
        ['risq/icons/penetration_magic', entry.bonus.penetration_magic],
      ];
      for (const [icon_path, value] of bonus_chips) {
        if (value) {
          this.addStatChip(bonus_row, icon_path, value);
        }
      }
      if (bonus_row.children.length > 0) {
        fragment.appendChild(bonus_row);
      }
    }
    return fragment;
  }

  // flips left/right and up/down based on which half of the visible viewport the cursor is in, so the tooltip is never behind it
  private positionTooltip(e: MouseEvent) {
    const wrapper_rect = this.wrapper.getBoundingClientRect();
    const tooltip_rect = this.hover_tooltip.getBoundingClientRect();
    const gap = 16;
    const cursor_x = e.clientX - wrapper_rect.left - this.wrapper.clientLeft;
    const cursor_y = e.clientY - wrapper_rect.top - this.wrapper.clientTop;
    const x = cursor_x > this.wrapper.clientWidth / 2 ? cursor_x - tooltip_rect.width - gap : cursor_x + gap;
    const y = cursor_y > this.wrapper.clientHeight / 2 ? cursor_y - tooltip_rect.height - gap : cursor_y + gap;
    this.hover_tooltip.style.left = `${Math.max(0, Math.min(x, this.wrapper.clientWidth - tooltip_rect.width))}px`;
    this.hover_tooltip.style.top = `${Math.max(0, Math.min(y, this.wrapper.clientHeight - tooltip_rect.height))}px`;
  }

  private hideTooltip() {
    this.hovered_node = undefined;
    this.hover_tooltip.hidden = true;
    this.redrawFromCache();
  }

  private redrawFromCache() {
    const ctx = this.canvas.getContext('2d');
    if (!ctx) {
      return;
    }
    const dpr = window.devicePixelRatio || 1;
    this.redraw(ctx, this.canvas.width / dpr, this.canvas.height / dpr);
  }
}

customElements.define('dwg-risq-tech-tree-dialog', DwgRisqTechTreeDialog);

declare global {
  interface HTMLElementTagNameMap {
    'dwg-risq-tech-tree-dialog': DwgRisqTechTreeDialog;
  }
}

import { DialogSize, DwgDialogBox } from '../../../../../dialog_box/dialog_box';
import type { HotkeyCombo } from '../../application/input/hotkeys';
import { configureImageFallback, resolveImage } from '../../../../../../scripts/image';
import { shortLabel } from '../../canvas_components/order_row/order_row_resolve';
import { buildingImage, techImage } from '../../rendering/assets/buildings';
import type { RisqPlayer, RisqProducible, RisqOrderType } from '../../model/types';
import { RisqProducibleKind, RisqResourceType } from '../../model/types';
import { resourceTypeImage } from '../../rendering/assets/resources';
import { unitImage } from '../../rendering/assets/unit';
import type { RisqReportCombatEvent, RisqTurnReport } from '../../transport/turn_report';
import { RisqCombatEventKind } from '../../transport/turn_report';
import type { DwgRisq } from '../../risq';

import html from './turn_report_dialog.html';

import './turn_report_dialog.scss';

const RESOURCE_LABELS: Record<RisqResourceType, string> = {
  [RisqResourceType.ERROR]: 'Error',
  [RisqResourceType.FOOD]: 'Food',
  [RisqResourceType.WOOD]: 'Wood',
  [RisqResourceType.STONE]: 'Stone',
  [RisqResourceType.GOLD]: 'Gold',
};

interface TurnReportDialogData {
  risq: DwgRisq;
  player: RisqPlayer;
  report: RisqTurnReport;
  close_hotkey: HotkeyCombo;
}

function signed(n: number): string {
  if (n > 0) {
    return `+${n}`;
  }
  return n.toString();
}

/** Looks up a producible's display name from the player's current buildings/units, falling back to a generic label */
function producibleName(player: RisqPlayer, kind: RisqProducibleKind, id: number, fallback: string): string {
  const find = (producibles: RisqProducible[]) => producibles.find((p) => p.kind === kind && p.id === id);
  for (const building of player.buildings.values()) {
    const match = find(building.produces);
    if (match) {
      return match.display_name;
    }
  }
  for (const unit of player.units.values()) {
    const match = find(unit.builds);
    if (match) {
      return match.display_name;
    }
  }
  return fallback;
}

function combatEventText(e: RisqReportCombatEvent, viewer_player_id: number): string {
  const mine = e.self_player === viewer_player_id;
  switch (e.kind) {
    case RisqCombatEventKind.UNIT_KILLED:
      return mine ? 'Destroyed an enemy unit' : 'Lost a unit in combat';
    case RisqCombatEventKind.UNIT_LOST:
      return 'Lost a unit in combat';
    case RisqCombatEventKind.BUILDING_RAZED:
      return mine ? 'Razed an enemy building' : 'A building was razed';
    case RisqCombatEventKind.BUILDING_LOST:
      return 'Lost a building';
    default:
      return 'Combat occurred';
  }
}

export class DwgRisqTurnReportDialog extends DwgDialogBox<TurnReportDialogData> {
  private title_heading!: HTMLHeadingElement;
  private scores_body!: HTMLTableSectionElement;
  private land_tiles!: HTMLDivElement;
  private region_lines!: HTMLUListElement;
  private region_empty!: HTMLParagraphElement;
  private resources_body!: HTMLTableSectionElement;
  private pop_line!: HTMLDivElement;
  private production_lines!: HTMLUListElement;
  private production_empty!: HTMLParagraphElement;
  private combat_lines!: HTMLUListElement;
  private combat_empty!: HTMLParagraphElement;
  private order_summary!: HTMLDivElement;
  private order_failures!: HTMLUListElement;
  private close_button!: HTMLButtonElement;

  private data!: TurnReportDialogData;

  constructor() {
    super();
    this.configureElement('title_heading', 'title');
    this.configureElements(
      'scores_body',
      'land_tiles',
      'region_lines',
      'region_empty',
      'resources_body',
      'pop_line',
      'production_lines',
      'production_empty',
      'combat_lines',
      'combat_empty',
      'order_summary',
      'order_failures',
      'close_button'
    );
  }

  override getHTML(): string {
    return html;
  }

  getData(): TurnReportDialogData {
    return this.data;
  }

  setData(data: TurnReportDialogData, parsed?: boolean) {
    this.data = data;
    this.close_hotkey = data.close_hotkey;
    this.classList.add(`size-${DialogSize.XLARGE}`);
    if (!parsed && !this.fully_parsed) {
      return;
    }
    const { risq, player, report } = data;
    this.close_button.addEventListener('click', () => {
      this.closeDialog();
    });

    this.title_heading.innerText = `Turn ${report.turn} Report`;

    this.renderScores(risq, player, report);
    this.renderLand(report);
    this.renderRegions(report);
    this.renderResources(report);
    this.renderProduction(player, report);
    this.renderCombat(player, report);
    this.renderOrders(report);
    for (const image of this.querySelectorAll('img')) {
      configureImageFallback(image);
      resolveImage(image);
    }
  }

  private renderScores(risq: DwgRisq, player: RisqPlayer, report: RisqTurnReport) {
    const rank_of = (key: 'was' | 'now', player_id: number): number => {
      const sorted = [...report.scores].sort((a, b) => b[key] - a[key]);
      return sorted.findIndex((s) => s.player_id === player_id) + 1;
    };
    const rows = [...report.scores]
      .sort((a, b) => b.now - a.now)
      .map((line) => {
        const row = document.createElement('tr');
        const nickname = risq.getGame()?.players[line.player_id]?.player.nickname ?? `Player ${line.player_id}`;
        const color = risq.getGame()?.players[line.player_id]?.color;
        if (line.player_id === player.player.player_id) {
          row.classList.add('you');
        }
        const rank_was = rank_of('was', line.player_id);
        const rank_now = rank_of('now', line.player_id);
        const rank_diff = rank_was - rank_now;
        let rank_html: string;
        if (rank_diff > 0) {
          rank_html = `<span class="rk up">&#9650;&nbsp;+${rank_diff}</span>`;
        } else if (rank_diff < 0) {
          rank_html = `<span class="rk down">&#9660;&nbsp;&minus;${-rank_diff}</span>`;
        } else {
          rank_html = `<span class="rk same">&mdash;</span>`;
        }
        row.innerHTML = `
        <td><span class="swatch" style="background:${color?.getString() ?? 'gray'}"></span></td>
        <td>${line.was}</td>
        <td class="arr">&rarr;</td>
        <td class="now">${line.now}</td>
        <td>${rank_html}</td>
      `;
        row.firstElementChild?.appendChild(document.createTextNode(nickname));
        return row;
      });
    this.scores_body.replaceChildren(...rows);
  }

  private renderLand(report: RisqTurnReport) {
    const land = report.land;
    const tile = (num: string, cap: string, cls = ''): HTMLDivElement => {
      const el = document.createElement('div');
      el.innerHTML = `<span class="num ${cls}">${num}</span><span class="cap">${cap}</span>`;
      return el;
    };
    const net = land.gained - land.lost;
    this.land_tiles.replaceChildren(
      tile(land.held_start.toString(), 'Held at start'),
      tile(signed(net), net > 0 ? 'Gained' : net < 0 ? 'Lost' : 'Net change', net > 0 ? 'up' : net < 0 ? 'down' : ''),
      tile(land.held_end.toString(), 'Held now'),
      tile(signed(Math.round(land.gold_from_land)), 'Gold from land', 'gold-txt'),
      tile(signed(land.newly_explored), 'Newly explored', land.newly_explored > 0 ? 'up' : '')
    );
  }

  private renderRegions(report: RisqTurnReport) {
    const lines = report.regions.map((r) => {
      const li = document.createElement('li');
      const verb = r.held_start ? 'held' : 'claimed';
      const suffix = r.held_end ? ` ${verb} (+${Math.round(r.gold_bonus)} gold/turn)` : ' lost';
      li.innerHTML = r.held_end
        ? '<span class="tick make">+</span><span></span>'
        : '<span class="tick bad">×</span><span></span>';
      li.lastElementChild?.appendChild(document.createTextNode(`${r.name}${suffix}`));
      return li;
    });
    this.region_lines.replaceChildren(...lines);
    this.region_lines.hidden = lines.length === 0;
    this.region_empty.hidden = lines.length > 0;
  }

  private renderResources(report: RisqTurnReport) {
    const rows = report.resources.map((line) => {
      const row = document.createElement('tr');
      const label = RESOURCE_LABELS[line.resource_type];
      const icon = resourceTypeImage(line.resource_type);
      const spent_html = line.spent > 0 ? `&minus;${Math.round(line.spent)}` : '0';
      row.innerHTML = `
        <td><img src="/images/${icon}.png" alt="" width="16" height="16" />${label}</td>
        <td>${Math.round(line.start)}</td>
        <td class="${line.gathered > 0 ? 'plus' : 'zero'}">${line.gathered > 0 ? '+' : ''}${Math.round(line.gathered)}</td>
        <td class="${line.spent > 0 ? 'minus' : 'zero'}">${spent_html}</td>
        <td class="final">${Math.round(line.final)}</td>
      `;
      return row;
    });
    this.resources_body.replaceChildren(...rows);
  }

  private renderProduction(player: RisqPlayer, report: RisqTurnReport) {
    this.pop_line.innerHTML = `Population <b>${report.population.start} &rarr; ${report.population.end}</b> &nbsp;&middot;&nbsp; cap <b>${report.population.cap_start} &rarr; ${report.population.cap_end}</b>`;
    const lines: HTMLLIElement[] = [];
    const line = (tick_cls: string, tick: string, icon: string, text: string) => {
      const li = document.createElement('li');
      const img = icon ? `<img src="/images/${icon}.png" alt="" width="18" height="18" />` : '';
      li.innerHTML = `<span class="tick ${tick_cls}">${tick}</span>${img}<span>${text}</span>`;
      lines.push(li);
    };
    for (const u of report.production.units_created) {
      const name = producibleName(player, RisqProducibleKind.UNIT, u.unit_id, 'Unit');
      line('make', '+', unitImage(u.unit_id, true), `${u.count > 1 ? `${u.count}× ` : ''}${name} trained`);
    }
    for (const b of report.production.buildings_built) {
      const name = producibleName(player, RisqProducibleKind.BUILDING, b.building_id, 'Building');
      line('make', '+', buildingImage(b.building_id, false, true), `${name} built at (${b.space.x}, ${b.space.y})`);
    }
    for (const tech_id of report.production.techs_researched) {
      const name = producibleName(player, RisqProducibleKind.TECH, tech_id, 'Technology');
      line('tech', '✦', techImage(tech_id), `${name} researched`);
    }
    this.production_lines.replaceChildren(...lines);
    this.production_lines.hidden = lines.length === 0;
    this.production_empty.hidden = lines.length > 0;
  }

  private renderCombat(player: RisqPlayer, report: RisqTurnReport) {
    const lines = report.combat.map((e) => {
      const li = document.createElement('li');
      const mine = e.self_player === player.player.player_id;
      li.innerHTML = `<span class="tick ${mine ? 'make' : 'bad'}">${mine ? '+' : '×'}</span><span>${combatEventText(e, player.player.player_id)} <span class="where">at (${e.space.x}, ${e.space.y})</span></span>`;
      return li;
    });
    this.combat_lines.replaceChildren(...lines);
    this.combat_lines.hidden = lines.length === 0;
    this.combat_empty.hidden = lines.length > 0;
  }

  private renderOrders(report: RisqTurnReport) {
    const orders = report.orders;
    const chip = (n: number, label: string, warn = false): string =>
      `<span${warn && n > 0 ? ' class="warn"' : ''}><b>${n}</b>&nbsp;${label}</span>`;
    this.order_summary.innerHTML = [
      chip(orders.active, 'active'),
      chip(orders.added, 'added'),
      chip(orders.failed, 'failed', true),
      chip(orders.executed, 'executed'),
      chip(orders.cancelled, 'cancelled'),
    ].join('');
    const failures = orders.failures.map((f) => {
      const li = document.createElement('li');
      li.innerHTML = `<span class="tick bad">&times;</span><span>${shortLabel(f.order_type as RisqOrderType)} &mdash; <span class="reason">${f.reason}</span></span>`;
      return li;
    });
    this.order_failures.replaceChildren(...failures);
  }
}

