const GHOST_ALPHA = 0.6;

/** Collapses pending hires into at most `capacity` slots: one per hire, then one per unit type, then one for all */
function mercenaryGhostSlots(player_id: number, unit_ids: number[], capacity: number): UnitByTypeData[][] {
  const group = (unit_id: number, indices: number[]): UnitByTypeData => ({
    player_id,
    unit_id,
    unit_type: RisqUnitType.NONE,
    units: new Set(indices),
  });
  if (unit_ids.length <= capacity) {
    return unit_ids.map((unit_id, i) => [group(unit_id, [i])]);
  }
  const indices_by_type = new Map<number, number[]>();
  unit_ids.forEach((unit_id, i) => indices_by_type.set(unit_id, [...(indices_by_type.get(unit_id) ?? []), i]));
  const by_type = [...indices_by_type.entries()].map(([unit_id, indices]) => group(unit_id, indices));
  return by_type.length <= capacity ? by_type.map((g) => [g]) : [by_type];
}

function drawMercenaryGhosts(
  ctx: CanvasRenderingContext2D,
  risq: DwgRisq,
  slots: UnitByTypeData[][],
  positions: Point2D[],
  hex_r: number,
  rotation: number
) {
  const unit_r = UNIT_SLOT_CIRCLE_RADIUS_MULTIPLIER * hex_r;
  ctx.globalAlpha = GHOST_ALPHA;
  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  for (const [i, slot] of slots.entries()) {
    ctx.save();
    ctx.translate(positions[i].x, positions[i].y);
    ctx.rotate(-rotation);
    const total = slot.reduce((sum, t) => sum + t.units.size, 0);
    drawUnitTypeCluster(ctx, risq, slot, { x: unit_r, y: unit_r }, total, 'white', 'rgba(210, 210, 210, 0.4)');
    ctx.restore();
  }
  ctx.globalAlpha = 1;
}

/** Board overlays for the local player's orders: arrows, move paths, gather point, and pending mercenary ghosts */
export class RisqOrderOverlays {
  constructor(
    private risq: DwgRisq,
    private session: RisqSession,
    private viewport: RisqViewport,
    private orders_model: RisqOrdersModel,
    private planning: RisqOrderPlanning,
    private selection: RisqSelection
  ) {}

  draw(ctx: CanvasRenderingContext2D) {
    this.drawUnitOrders(ctx);
    this.drawBuildingOrders(ctx);
    this.drawGatherPointOrder(ctx);
    this.drawPendingMercenaries(ctx);
  }

  private drawUnitOrders(ctx: CanvasRenderingContext2D) {
    const player = this.session.getPlayer();
    if (!player || !this.viewport.contentDrawn()) {
      return;
    }
    const selected = this.selection.selectedUnitIds();
    for (const unit of player.units.values()) {
      if (!unitVisibleInViewMode(unit.unit_type, this.viewport.viewMode())) {
        continue;
      }
      this.drawOrdersForUnit(ctx, unit, selected.has(unit.internal_id));
    }
  }

  private drawBuildingOrders(ctx: CanvasRenderingContext2D) {
    const player = this.session.getPlayer();
    if (!player || !this.viewport.contentDrawn()) {
      return;
    }
    ctx.setLineDash([8, 5]);
    for (const building of player.buildings.values()) {
      this.drawOrdersForBuilding(ctx, building, this.selection.isBuildingSelected(building.internal_id));
    }
    ctx.setLineDash([]);
    ctx.globalAlpha = 1;
  }

  private drawOrdersForBuilding(ctx: CanvasRenderingContext2D, building: RisqBuilding, selected: boolean) {
    const zone_view = this.viewport.zoneView();
    const building_offset = zoneCenterOffset(building.zone_coordinate, this.viewport.hexR());
    const from = this.viewport.orderPoint(building.space_coordinate, building_offset, zone_view);
    ctx.lineWidth = selected ? 2 : 1;
    ctx.globalAlpha = selected ? 1 : 0.35;
    for (const order of this.orders_model.effectiveForSubject(building.internal_id, 'building')) {
      const to = this.orderTargetPoint(order, zone_view, from);
      if (!to || equalsPoint2D(from, to)) {
        continue;
      }
      const color = orderArrowColor(order.order_type);
      ctx.strokeStyle = color;
      ctx.fillStyle = color;
      drawArrow(ctx, from, to, selected ? 10 : 6);
    }
  }

  private remainingMovePath(unit: RisqUnit): RisqMovePathStep[] {
    const path = unit.move_path ?? [];
    const location = this.session.unitLocation(unit);
    const current_index = path.findIndex(
      (step) =>
        equalsPoint2D(step.space, location?.space_coordinate) && equalsPoint2D(step.zone, location?.zone_coordinate)
    );
    return path.slice(current_index + 1);
  }

  private drawOrdersForUnit(ctx: CanvasRenderingContext2D, unit: RisqUnit, selected: boolean) {
    const location = this.session.unitLocation(unit);
    const orders = this.orders_model.effectiveForSubject(unit.internal_id, 'unit');
    if (!location || !orders.length) {
      return;
    }
    const zone_view = this.viewport.zoneView();
    let from = this.viewport.orderPoint(location.space_coordinate, this.viewport.unitAnchorOffset(unit), zone_view);
    ctx.lineWidth = selected ? 2 : 1;
    ctx.globalAlpha = selected ? 1 : 0.35;
    ctx.setLineDash([8, 5]);
    for (const [i, order] of orders.entries()) {
      if (
        i === 0 &&
        order.internal_id !== undefined &&
        order.internal_id === unit.active_orders[0]?.internal_id &&
        unit.move_path?.length
      ) {
        from = this.drawMovePath(
          ctx,
          this.remainingMovePath(unit),
          from,
          zone_view,
          selected ? 10 : 6,
          order.order_type
        );
        continue;
      }
      const to = this.orderTargetPoint(order, zone_view, from);
      if (!to || equalsPoint2D(from, to)) {
        continue;
      }
      const color = orderArrowColor(order.order_type);
      ctx.strokeStyle = color;
      ctx.fillStyle = color;
      drawArrow(ctx, from, to, selected ? 10 : 6);
      from = to;
    }
    ctx.setLineDash([]);
    ctx.globalAlpha = 1;
  }

  private drawMovePath(
    ctx: CanvasRenderingContext2D,
    path: RisqMovePathStep[],
    from: Point2D,
    zone_view: boolean,
    arrow_size: number,
    order_type: RisqOrderType
  ): Point2D {
    const color = orderArrowColor(order_type);
    ctx.strokeStyle = color;
    ctx.fillStyle = color;
    let current = from;
    for (const [i, step] of path.entries()) {
      const to = this.viewport.orderPoint(step.space, zoneCenterOffset(step.zone, this.viewport.hexR()), zone_view);
      if (equalsPoint2D(current, to)) {
        continue;
      }
      if (i === path.length - 1) {
        drawArrow(ctx, current, to, arrow_size);
      } else {
        drawLine(ctx, current, to);
      }
      current = to;
    }
    return current;
  }

  private orderTargetPoint(order: RisqFrontendOrder, zone_view: boolean, from: Point2D): Point2D | undefined {
    if (!this.session.getGame()) {
      return undefined;
    }
    const hex_r = this.viewport.hexR();
    let target_space: Point2D;
    let target_offset: Point2D | undefined;
    switch (order.order_type) {
      case RisqOrderType.OrderType_UnitMoveSpace:
      case RisqOrderType.OrderType_UnitAttackSpace:
        target_space = invertPair(order.target_id);
        break;
      case RisqOrderType.OrderType_UnitMoveZone:
      case RisqOrderType.OrderType_UnitAttackZone: {
        const decoded = invertZoneKey(order.target_id);
        target_space = decoded.space;
        const space_canvas = this.viewport.coordinateToCanvas(target_space);
        target_offset = zoneApproachPoint(decoded.zone, hex_r, subtractPoint2D(from, space_canvas));
        break;
      }
      case RisqOrderType.OrderType_UnitGather: {
        const decoded = invertZoneKey(order.target_id);
        target_space = decoded.space;
        target_offset = zoneCenterOffset(decoded.zone, hex_r);
        break;
      }
      case RisqOrderType.OrderType_UnitBuild: {
        const decoded = invertBuildKey(order.target_id);
        target_space = decoded.space;
        target_offset = zoneCenterOffset(decoded.zone, hex_r);
        break;
      }
      case RisqOrderType.OrderType_UnitRepair:
      case RisqOrderType.OrderType_UnitRenew:
      case RisqOrderType.OrderType_UnitAttackBuilding:
      case RisqOrderType.OrderType_UnitAutoAttackBuilding:
      case RisqOrderType.OrderType_BuildingAttackBuilding:
      case RisqOrderType.OrderType_BuildingAutoAttackBuilding:
      case RisqOrderType.OrderType_UnitGarrison: {
        const building = this.session.findBuildingById(order.target_id);
        if (!building) {
          return undefined;
        }
        target_space = building.space_coordinate;
        target_offset = zoneCenterOffset(building.zone_coordinate, hex_r);
        break;
      }
      case RisqOrderType.OrderType_UnitAttackUnit:
      case RisqOrderType.OrderType_UnitAutoAttackUnit:
      case RisqOrderType.OrderType_BuildingAttackUnit:
      case RisqOrderType.OrderType_BuildingAutoAttackUnit: {
        const target_unit = this.session.findUnitById(order.target_id);
        const target_location = target_unit ? this.session.unitLocation(target_unit) : undefined;
        if (!target_unit || !target_location) {
          return undefined;
        }
        target_space = target_location.space_coordinate;
        target_offset = this.viewport.unitAnchorOffset(target_unit);
        break;
      }
      default:
        return undefined;
    }
    return this.viewport.orderPoint(target_space, target_offset, zone_view);
  }

  /** Reuses orderTargetPoint's exact placement logic by building the equivalent synthetic order */
  private gatherPointTargetPoint(
    gather_point: RisqGatherPoint,
    zone_view: boolean,
    from: Point2D
  ): Point2D | undefined {
    let order_type: RisqOrderType;
    let target_id: number;
    switch (gather_point.object_type) {
      case RisqGatherObjectType.BUILDING:
        order_type = RisqOrderType.OrderType_UnitAttackBuilding;
        target_id = gather_point.object_id;
        break;
      case RisqGatherObjectType.UNIT:
        order_type = RisqOrderType.OrderType_UnitAttackUnit;
        target_id = gather_point.object_id;
        break;
      case RisqGatherObjectType.RESOURCE:
        order_type = RisqOrderType.OrderType_UnitGather;
        target_id = gather_point.location_id;
        break;
      default:
        order_type =
          gather_point.location_kind === RisqGatherPointLocationKind.SPACE
            ? RisqOrderType.OrderType_UnitMoveSpace
            : RisqOrderType.OrderType_UnitMoveZone;
        target_id = gather_point.location_id;
        break;
    }
    const player_id = this.session.getPlayerId();
    return this.orderTargetPoint({ player_id, order_type, target_id, subjects: [] }, zone_view, from);
  }

  private drawGatherPointOrder(ctx: CanvasRenderingContext2D) {
    const building = this.selection.selectedBuilding();
    const gather_point = building?.gather_point;
    if (!building || !gather_point) {
      return;
    }
    const zone_view = this.viewport.zoneView();
    const building_offset = zoneCenterOffset(building.zone_coordinate, this.viewport.hexR());
    const from = this.viewport.orderPoint(building.space_coordinate, building_offset, zone_view);
    const to = this.gatherPointTargetPoint(gather_point, zone_view, from);
    if (!to || equalsPoint2D(from, to)) {
      return;
    }
    ctx.lineWidth = 2;
    ctx.globalAlpha = 1;
    ctx.setLineDash([8, 5]);
    ctx.strokeStyle = 'white';
    ctx.fillStyle = 'white';
    drawArrow(ctx, from, to, 10);
    ctx.setLineDash([]);
    const flag_icon = this.risq.getPlayerColoredIcon('risq/icons/garrison_flag', new ColorRGB(255, 255, 255));
    const flag_size = Math.max(16, 0.15 * this.viewport.hexR());
    ctx.drawImage(flag_icon, to.x, to.y - flag_size, flag_size, flag_size);
  }

  private drawPendingMercenaries(ctx: CanvasRenderingContext2D) {
    const zone_view = this.viewport.zoneView();
    const hex_r = this.viewport.hexR();
    const groups = new Map<number, { positions: Point2D[]; unit_ids: number[] }>();
    for (const order of this.planning.pendingMercenaryOrders()) {
      const { x: unit_id, y: zone_key } = invertPair(order.target_id);
      const { space, zone } = invertZoneKey(zone_key);
      const key = zone_view ? zone_key : cantorPair(space.x, space.y);
      const space_center = this.viewport.coordinateToCanvas(space);
      const group = groups.get(key) ?? {
        positions: zoneMercenarySlotOffsets(zone_view ? zone : { x: 0, y: 0 }, hex_r).map((offset) =>
          addPoint2D(space_center, offset)
        ),
        unit_ids: [],
      };
      group.unit_ids.push(unit_id);
      groups.set(key, group);
    }
    const rotation = this.viewport.lastTransform().rotation;
    for (const { positions, unit_ids } of groups.values()) {
      const slots = mercenaryGhostSlots(this.session.getPlayerId(), unit_ids, positions.length);
      drawMercenaryGhosts(ctx, this.risq, slots, positions, hex_r, rotation);
    }
  }
}

import type { BoardTransformData } from '../../../../util/canvas_board/canvas_board';
import { defaultTransform, screenToCanvas } from '../../../../util/canvas_board/canvas_board';
import type { Point2D } from '../../../../util/objects2d';
import { addPoint2D } from '../../../../util/objects2d';
import type { RisqSession } from '../../application/session';
import { invertPair } from '../../model/coordinates';
import type { RisqRegion, RisqSpace, RisqUnit } from '../../model/types';
import { DrawRisqSpaceDetail } from '../space';
import { RisqViewMode, nextViewMode } from '../terrain';
import { getRisqZone, zoneCenterOffset } from '../zones/geometry';
import { unitSlotWorldPosition } from '../zones/slots';

const DEFAULT_HEXAGON_RADIUS = 60;
const ZOOM_REFERENCE_BOARD_SIZE = 4;
const MAX_ZOOM_CANVAS_FRACTION = 0.65;
const MIN_ZOOM_REFERENCE_POWER = 2.2;
const ZONE_DETAIL_THRESHOLD = 0.45;
const OWNERSHIP_DETAIL_THRESHOLD = 0.4;

export declare interface CanvasBounds {
  min: Point2D;
  max: Point2D;
}

/** Owns the board's hex size, canvas size, last transform, and level of detail, and converts between their frames */
export class RisqViewport {
  private hex_r = DEFAULT_HEXAGON_RADIUS;
  private hex_a = 0.5 * 1.732 * DEFAULT_HEXAGON_RADIUS;
  private canvas_center: Point2D = { x: 0, y: 0 };
  private canvas_size: DOMRect = DOMRect.fromRect();
  private transform: BoardTransformData = defaultTransform();
  private draw_detail: DrawRisqSpaceDetail = DrawRisqSpaceDetail.SPACE_DETAILS;
  private view_mode: RisqViewMode = RisqViewMode.ALL;

  constructor(
    private session: RisqSession,
    private on_view_mode_change?: () => void
  ) {}

  hexR(): number {
    return this.hex_r;
  }

  hexA(): number {
    return this.hex_a;
  }

  canvasSize(): DOMRect {
    return this.canvas_size;
  }

  lastTransform(): BoardTransformData {
    return this.transform;
  }

  setTransform(transform: BoardTransformData) {
    this.transform = transform;
  }

  drawDetail(): DrawRisqSpaceDetail {
    return this.draw_detail;
  }

  zoneView(): boolean {
    return this.draw_detail === DrawRisqSpaceDetail.ZONE_DETAILS;
  }

  viewMode(): RisqViewMode {
    return this.view_mode;
  }

  setViewMode(mode: RisqViewMode): void {
    this.view_mode = mode;
    this.on_view_mode_change?.();
  }

  cycleViewMode(): void {
    this.setViewMode(nextViewMode(this.view_mode));
  }

  /** Whether units, buildings, and their orders are drawn at the current detail and view mode */
  contentDrawn(): boolean {
    return this.view_mode !== RisqViewMode.REGION && this.draw_detail !== DrawRisqSpaceDetail.OWNERSHIP;
  }

  // Regions are hoverable/selectable in the dedicated REGION view mode (any zoom), or fully zoomed out in any other non-military view mode
  regionInteractionEnabled(): boolean {
    return (
      this.view_mode === RisqViewMode.REGION ||
      (this.draw_detail === DrawRisqSpaceDetail.OWNERSHIP && this.view_mode !== RisqViewMode.MILITARY)
    );
  }

  zoomLimits(board_width: number): { min: number; max: number } {
    const reference_radius = board_width / (1.732 * (2 * ZOOM_REFERENCE_BOARD_SIZE + 1));
    const reference_max = (MAX_ZOOM_CANVAS_FRACTION * this.canvas_size.height) / reference_radius;
    const max = (MAX_ZOOM_CANVAS_FRACTION * this.canvas_size.height) / this.hex_r;
    return { min: max / reference_max ** MIN_ZOOM_REFERENCE_POWER, max };
  }

  updateDrawDetail(scale: number, max_scale: number) {
    const board_size = this.session.getGame()?.board_size ?? ZOOM_REFERENCE_BOARD_SIZE;
    const reference_scale = (2 * ZOOM_REFERENCE_BOARD_SIZE + 1) / (2 * board_size + 1);
    scale *= reference_scale;
    max_scale *= reference_scale;
    if (scale > ZONE_DETAIL_THRESHOLD * (max_scale - 1) + 1) {
      this.draw_detail = DrawRisqSpaceDetail.ZONE_DETAILS;
    } else if (scale < 1 / (OWNERSHIP_DETAIL_THRESHOLD * (max_scale - 1) + 1)) {
      this.draw_detail = DrawRisqSpaceDetail.OWNERSHIP;
    } else {
      this.draw_detail = DrawRisqSpaceDetail.SPACE_DETAILS;
    }
  }

  /** Board size in canvas pixels at the current hex radius */
  boardSize(board_size: number): Point2D {
    return {
      x: 1.732 * this.hex_r * (2 * board_size + 1),
      y: 1.5 * this.hex_r * (2 * board_size + 1) + 0.5 * this.hex_r,
    };
  }

  resize(board_size: Point2D, canvas_size: DOMRect, game_board_size: number): { ratio: number; center: Point2D } {
    const new_center_x = 0.5 * Math.min(board_size.x, canvas_size.width);
    const ratio = this.canvas_center.x === 0 ? 1 : new_center_x / this.canvas_center.x;
    this.canvas_center = {
      x: new_center_x,
      y: 0.5 * Math.min(board_size.y, canvas_size.height),
    };
    this.canvas_size = canvas_size;
    this.hex_r = board_size.x / (1.732 * (2 * game_board_size + 1));
    this.hex_a = 0.5 * 1.732 * this.hex_r;
    return { ratio, center: this.canvas_center };
  }

  canvasToCoordinate(canvas: Point2D, board_size: number): Point2D {
    const cy = (canvas.y - 0.25 * this.hex_r) / (1.5 * this.hex_r) - board_size - 0.5;
    return {
      x: canvas.x / (1.732 * this.hex_r) - 0.5 * cy - board_size - 0.5,
      y: cy,
    };
  }

  coordinateToCanvas(coordinate: Point2D): Point2D {
    const game = this.session.getGame();
    if (!game) {
      return { x: 0, y: 0 };
    }
    return {
      x: 1.732 * (coordinate.x + 0.5 * coordinate.y + game.board_size + 0.5) * this.hex_r,
      y: 1.5 * (coordinate.y + game.board_size + 0.5) * this.hex_r + 0.25 * this.hex_r,
    };
  }

  /** Space/zone-view-aware canvas point for an order endpoint; offset is ignored (space-to-space) outside zone view */
  orderPoint(space: Point2D, offset: Point2D | undefined, zone_view: boolean): Point2D {
    const p = this.coordinateToCanvas(space);
    return zone_view && offset ? addPoint2D(p, offset) : p;
  }

  /** Offset (relative to its space's center) of the specific unit-slot circle a unit currently occupies */
  unitAnchorOffset(unit: RisqUnit): Point2D | undefined {
    if (!this.session.getGame()) {
      return undefined;
    }
    if (unit.garrisoned_in !== undefined) {
      const building = this.session.findBuildingById(unit.garrisoned_in);
      return building ? zoneCenterOffset(building.zone_coordinate, this.hex_r) : undefined;
    }
    const zone = getRisqZone(this.session.spaceAt(unit.space_coordinate), unit.zone_coordinate);
    if (!zone) {
      return zoneCenterOffset(unit.zone_coordinate, this.hex_r);
    }
    return (
      unitSlotWorldPosition(zone, unit.zone_coordinate, this.hex_r, this.session.getPlayerId(), unit.internal_id) ??
      zoneCenterOffset(unit.zone_coordinate, this.hex_r)
    );
  }

  /** Canvas position of a region's label: the centroid of its (explored) member spaces */
  regionLabelPosition(region: RisqRegion): Point2D {
    let sx = 0;
    let sy = 0;
    for (const key of region.spaces) {
      const c = invertPair(key);
      sx += c.x;
      sy += c.y;
    }
    const n = region.spaces.length || 1;
    return this.coordinateToCanvas({ x: sx / n, y: sy / n });
  }

  visibleCanvasBounds(): CanvasBounds {
    const { width, height } = this.canvas_size;
    const corners = [
      screenToCanvas({ x: 0, y: 0 }, this.transform),
      screenToCanvas({ x: width, y: 0 }, this.transform),
      screenToCanvas({ x: 0, y: height }, this.transform),
      screenToCanvas({ x: width, y: height }, this.transform),
    ];
    return {
      min: { x: Math.min(...corners.map((c) => c.x)), y: Math.min(...corners.map((c) => c.y)) },
      max: { x: Math.max(...corners.map((c) => c.x)), y: Math.max(...corners.map((c) => c.y)) },
    };
  }

  isSpaceOnScreen(space: RisqSpace, bounds: CanvasBounds): boolean {
    const { min, max } = bounds;
    return !(
      space.center.x + this.hex_a < min.x ||
      space.center.x - this.hex_a > max.x ||
      space.center.y + this.hex_r < min.y ||
      space.center.y - this.hex_r > max.y
    );
  }

  isCircleOnScreen(c: Point2D, radius: number, bounds: CanvasBounds): boolean {
    const { min, max } = bounds;
    const closest_x = Math.min(Math.max(c.x, min.x), max.x);
    const closest_y = Math.min(Math.max(c.y, min.y), max.y);
    const dx = c.x - closest_x;
    const dy = c.y - closest_y;
    return dx * dx + dy * dy <= radius * radius;
  }
}

import type { DwgRisq } from '../risq';
import { buildingImage } from './assets/buildings';
import { RisqOrderType } from '../model/types';
import { unitImage } from './assets/unit';

export const DEFAULT_CURSOR_IMAGE = 'cursor';

const ORDER_CURSOR_IMAGES: Partial<Record<RisqOrderType, string>> = {
  [RisqOrderType.OrderType_UnitMoveSpace]: 'move',
  [RisqOrderType.OrderType_UnitMoveZone]: 'move',
  [RisqOrderType.OrderType_UnitGather]: 'gather',
  [RisqOrderType.OrderType_UnitBuild]: 'build',
  [RisqOrderType.OrderType_UnitRepair]: 'repair',
  [RisqOrderType.OrderType_UnitRenew]: 'renew',
  [RisqOrderType.OrderType_UnitAttackSpace]: 'attack',
  [RisqOrderType.OrderType_UnitAttackZone]: 'attack',
  [RisqOrderType.OrderType_UnitAttackUnit]: 'attack',
  [RisqOrderType.OrderType_UnitAttackBuilding]: 'attack',
  [RisqOrderType.OrderType_BuildingAttackUnit]: 'attack',
  [RisqOrderType.OrderType_BuildingAttackBuilding]: 'attack',
  [RisqOrderType.OrderType_UnitGarrison]: 'garrison',
};

const INVALID_TARGET_CURSOR_ALPHA = 0.5;

export function armedCursorAlpha(valid: boolean): number {
  return valid ? 1 : INVALID_TARGET_CURSOR_ALPHA;
}

/** Returns the bare cursor name for the given order type (relative to the cursors/ folder), falling back to the default cursor */
export function cursorImageForOrderType(order_type: RisqOrderType): string {
  return ORDER_CURSOR_IMAGES[order_type] ?? DEFAULT_CURSOR_IMAGE;
}

export const BUILD_CURSOR_SIZE = 48;
export const BUILD_CURSOR_ICON_SIZE = 24;
export const BUILD_PREVIEW_ALPHA_DEFAULT = 0.6;
export const BUILD_PREVIEW_ALPHA_VALID = 1;

export function buildOrderCursorKey(building_id: number, valid: boolean): string {
  return `build_${building_id}${valid ? '_valid' : ''}`;
}

export function resolveBuildCursorUrl(
  risq: DwgRisq,
  armed_building: { id: number; display_name: string },
  valid: boolean
): string | undefined {
  const building_icon = risq.getIcon(buildingImage(armed_building.id, false, true));
  const build_icon = risq.getIcon(`cursors/${cursorImageForOrderType(RisqOrderType.OrderType_UnitBuild)}`);
  return risq
    .getImageCache()
    .getCursorUrl(
      buildOrderCursorKey(armed_building.id, valid),
      BUILD_CURSOR_SIZE,
      [building_icon, build_icon],
      (ctx) => drawBuildOrderCursor(ctx, build_icon, building_icon, valid)
    );
}

export function resolveMercenaryCursorUrl(risq: DwgRisq, unit_id: number, valid: boolean): string | undefined {
  const unit_icon = risq.getIcon(unitImage(unit_id, true));
  const pointer_icon = risq.getIcon(`cursors/${DEFAULT_CURSOR_IMAGE}`);
  return risq
    .getImageCache()
    .getCursorUrl(`mercenary_${unit_id}${valid ? '_valid' : ''}`, BUILD_CURSOR_SIZE, [unit_icon, pointer_icon], (ctx) =>
      drawBuildOrderCursor(ctx, pointer_icon, unit_icon, valid)
    );
}

export function drawBuildOrderCursor(
  ctx: CanvasRenderingContext2D,
  build_icon: HTMLImageElement,
  building_icon: HTMLImageElement,
  valid: boolean
) {
  ctx.globalAlpha = valid ? BUILD_PREVIEW_ALPHA_VALID : BUILD_PREVIEW_ALPHA_DEFAULT;
  ctx.drawImage(building_icon, 0, 0, BUILD_CURSOR_SIZE, BUILD_CURSOR_SIZE);
  ctx.globalAlpha = 1;
  ctx.drawImage(build_icon, 0, 0, BUILD_CURSOR_ICON_SIZE, BUILD_CURSOR_ICON_SIZE);
}

