interface HoldingKeysData {
  arrow_up: boolean;
  arrow_down: boolean;
  arrow_left: boolean;
  arrow_right: boolean;
}

/** Modifier key state */
export declare interface ModifierKeys {
  ctrl: boolean;
  shift: boolean;
  alt: boolean;
}

const EXTRA_MOUSE_BUTTON_EVENTS = ['mousedown', 'mouseup', 'auxclick'] as const;

function modifiersFrom(e: MouseEvent | KeyboardEvent): ModifierKeys {
  return { ctrl: e.ctrlKey, shift: e.shiftKey, alt: e.altKey };
}

/** Data describing how the canvas should be initialized */
export declare interface CanvasBoardInitializationData {
  board_size: Point2D;
  max_scale: number;
  min_scale?: number;
  fill_space?: boolean;
  allow_side_move?: boolean;
  draw: (ctx: CanvasRenderingContext2D, transform: BoardTransformData) => void;
  // returns whether something was scrolled
  scroll?: (dy: number, mode: number, dx?: number) => boolean;
  mousemove: (canvas: Point2D, screen: Point2D, transform: BoardTransformData, modifiers: ModifierKeys) => void;
  draggingCallback?: () => void;
  mouseleave: () => void;
  cancelInput?: () => void;
  // returns whether something was clicked
  mousedown: (e: MouseEvent) => boolean;
  mouseup: (e: MouseEvent) => void;
  // press/release of a mouse button past left/right/middle (browser back/forward), anywhere on the page
  extraMouseButton?: (e: MouseEvent) => void;
  zoom_config: ZoomConfig;
}

/** Data describing the size of a the board */
export declare interface CanvasBoardSize {
  board_size: Point2D;
  el_size: DOMRect;
}

/** Data how the board is transformed */
export declare interface BoardTransformData {
  scale: number;
  view: Point2D;
  offset: Point2D;
  rotation: number;
}

/** Returns a default board transform data object */
export function defaultTransform(): BoardTransformData {
  return {
    scale: 1,
    view: { x: 0, y: 0 },
    offset: { x: 0, y: 0 },
    rotation: 0,
  };
}

export function canvasToScreen(canvas: Point2D, transform: BoardTransformData): Point2D {
  const scaled = rotatePoint(
    {
      x: canvas.x * transform.scale - transform.view.x,
      y: canvas.y * transform.scale - transform.view.y,
    },
    transform.rotation
  );
  return {
    x: scaled.x + transform.offset.x,
    y: scaled.y + transform.offset.y,
  };
}

export function screenToCanvas(screen: Point2D, transform: BoardTransformData): Point2D {
  const unrotated = rotatePoint(
    {
      x: screen.x - transform.offset.x,
      y: screen.y - transform.offset.y,
    },
    -transform.rotation
  );
  return {
    x: (unrotated.x + transform.view.x) / transform.scale,
    y: (unrotated.y + transform.view.y) / transform.scale,
  };
}

/** Data describing how zoom can operate */
export declare interface ZoomConfig {
  zoom_constant: number;
  max_zoom?: number;
  min_zoom?: number;
}

export class DwgCanvasBoard extends DwgElement {
  private canvas!: HTMLCanvasElement;

  private initialized_successfully = false;
  private initialization_controller = new AbortController();
  private ctx!: CanvasRenderingContext2D;
  private data!: CanvasBoardInitializationData;
  private orig_size!: Point2D;
  private transform: BoardTransformData = defaultTransform();
  private zoom_config!: ZoomConfig;

  private hovered = false;
  private modifiers: ModifierKeys = { ctrl: false, shift: false, alt: false };
  private holding_keys: HoldingKeysData = {
    arrow_up: false,
    arrow_down: false,
    arrow_left: false,
    arrow_right: false,
  };
  private cursor_move_threshold = 5;
  // TODO: replace edge_arm_threshold/sticky_pan with document-level mouse tracking, so edge-pan is a
  // speed-independent viewport-boundary check instead of a threshold the cursor can jump past
  private edge_arm_threshold = 100;
  private sticky_pan = { up: false, down: false, left: false, right: false };
  private pan_suppressed = { x: false, y: false };
  private draw_interval?: ReturnType<typeof setInterval>;
  private dragging = false;
  private drag_button = 0;
  private dragged = false;
  private mouse: Point2D = { x: 0, y: 0 };
  private cursor_images = new Map<string, HTMLImageElement>();
  private cursor_image?: HTMLImageElement;
  private cursor_alpha = 1;

  private bounding_rect!: DOMRect;
  private resize_observer = new ResizeObserver(async (els) => {
    const signal = this.initialization_controller.signal;
    for (const el of els) {
      if (!(await this.updateSize(this.data, el.contentRect, signal)) || signal.aborted) {
        return;
      }
      this.dispatchEvent(
        new CustomEvent<CanvasBoardSize>('canvas_resize', {
          detail: {
            board_size: this.data.board_size,
            el_size: this.bounding_rect,
          },
          bubbles: true,
        })
      );
    }
  });

  constructor() {
    super();
    this.html_string = html;
    this.configureElement('canvas');
  }

  getBoundingRect(): DOMRect {
    return this.bounding_rect;
  }

  isInitialized(): boolean {
    return this.initialized_successfully;
  }

  getModifiers(): ModifierKeys {
    return { ...this.modifiers };
  }

  async initialize(data: CanvasBoardInitializationData): Promise<CanvasBoardSize | undefined> {
    this.initialization_controller.abort();
    this.initialization_controller = new AbortController();
    const signal = this.initialization_controller.signal;
    data.allow_side_move = data.allow_side_move ?? true;
    this.zoom_config = Object.assign({}, data.zoom_config);
    this.orig_size = {
      x: data.board_size.x,
      y: data.board_size.y,
    };
    const success = await this.updateSize(data, undefined, signal);
    if (!success || signal.aborted) {
      return undefined;
    }
    await until(() => !!this.canvas.getBoundingClientRect()?.width, 50, signal);
    if (signal.aborted) {
      return undefined;
    }
    this.setCursor('cursor');
    this.addEventListeners();
    this.resize_observer.observe(this);
    this.draw_interval = setInterval(() => {
      this.tick();
      // If ever made async everything after tick() needs to run at same time (just skip until last finished)
      this.ctx.resetTransform();
      this.ctx.fillStyle = 'black';
      this.ctx.fillRect(0, 0, this.data.board_size.x, this.data.board_size.y);
      this.ctx.translate(this.transform.offset.x, this.transform.offset.y);
      this.ctx.rotate(this.transform.rotation);
      this.ctx.translate(-this.transform.view.x, -this.transform.view.y);
      this.ctx.scale(this.transform.scale, this.transform.scale);
      setTooltipCursor(this.mouse);
      this.data.draw(this.ctx, this.transform);
      flushTooltipQueue();
      this.drawCursor();
    }, 20);
    this.initialized_successfully = true;
    return {
      board_size: this.data.board_size,
      el_size: this.bounding_rect,
    };
  }

  async updateSize(
    data: CanvasBoardInitializationData,
    override_rect?: DOMRect,
    signal: AbortSignal = this.initialization_controller.signal
  ): Promise<boolean> {
    if (!data || this.orig_size.x < 1 || this.orig_size.y < 1) {
      console.error('Size must be at least 1px in each direction');
      return false;
    }
    if (!data.max_scale || data.max_scale < 1) {
      console.error(`Max scale of ${data.max_scale} is invalid`);
      return false;
    }
    this.data = data;
    await until(() => this.fully_parsed, 50, signal);
    if (signal.aborted) {
      return false;
    }
    if (!this.canvas.getContext) {
      console.error('Browser does not support canvas; cannot draw board');
      return false;
    }
    await this.setSize(override_rect, signal);
    if (signal.aborted || !this.ctx) {
      return false;
    }
    return true;
  }

  private async setSize(rect?: DOMRect, signal: AbortSignal = this.initialization_controller.signal): Promise<void> {
    const data = this.data;
    if (!!rect) {
      this.bounding_rect = rect;
    } else {
      await until(
        () => {
          this.bounding_rect = this.getBoundingClientRect();
          return !!this.bounding_rect?.width;
        },
        50,
        signal
      );
      rect = this.bounding_rect;
    }
    if (signal.aborted) {
      return;
    }
    if (data.fill_space) {
      const aspect_ratio = this.orig_size.x / this.orig_size.y;
      data.board_size.x = Math.max(this.orig_size.x, rect.width);
      data.board_size.y = Math.max(this.orig_size.y, rect.height);
      const new_ratio = data.board_size.x / data.board_size.y;
      if (new_ratio > aspect_ratio) {
        data.board_size.y = data.board_size.x / aspect_ratio;
      } else {
        data.board_size.x = data.board_size.y * aspect_ratio;
      }
    }
    this.ctx = this.canvas.getContext('2d')!;
    this.canvas.style.setProperty('--w', `${data.board_size.x.toString()}px`);
    this.canvas.style.setProperty('--h', `${data.board_size.y.toString()}px`);
    this.canvas.width = data.board_size.x;
    this.canvas.height = data.board_size.y;
  }

  private mouseCanvasPoint(): Point2D {
    return screenToCanvas(this.mouse, this.transform);
  }

  private addEventListeners() {
    this.addEventListener('wheel', (e: WheelEvent) => {
      this.modifiers = modifiersFrom(e);
      if (this.data.scroll) {
        if (this.data.scroll(e.deltaY, e.deltaMode, e.deltaX)) {
          return;
        }
      }
      let zoom = 1 + e.deltaY / this.zoom_config.zoom_constant;
      if (!!this.zoom_config.max_zoom && this.zoom_config.max_zoom < zoom) {
        zoom = this.zoom_config.max_zoom;
      }
      if (!!this.zoom_config.min_zoom && this.zoom_config.min_zoom > zoom) {
        zoom = this.zoom_config.min_zoom;
      }
      this.zoomTowardPoint(this.transform.scale / zoom, this.mouse);
      this.data.mousemove(this.mouseCanvasPoint(), this.mouse, this.transform, modifiersFrom(e));
    });
    this.addEventListener('mousemove', (e: MouseEvent) => {
      this.modifiers = modifiersFrom(e);
      this.hovered = true;
      const rect = this.canvas.getBoundingClientRect();
      const new_mouse = {
        x: e.clientX - rect.left,
        y: e.clientY - rect.top,
      };
      const old_mouse = this.mouse;
      const dif_mouse = subtractPoint2D(new_mouse, old_mouse);
      this.mouse = new_mouse;
      if (this.dragging && isDialogOpen()) {
        this.dragging = false;
      } else if (this.dragging) {
        if (this.drag_button === 2) {
          const pivot = this.transform.offset;
          const prev_angle = Math.atan2(old_mouse.y - pivot.y, old_mouse.x - pivot.x);
          const new_angle = Math.atan2(new_mouse.y - pivot.y, new_mouse.x - pivot.x);
          this.setRotation(this.transform.rotation + (new_angle - prev_angle));
        } else {
          this.setView(subtractPoint2D(this.transform.view, rotatePoint(dif_mouse, -this.transform.rotation)));
        }
        if (this.data.draggingCallback) {
          this.data.draggingCallback();
        }
        this.dragged = true;
      } else {
        this.data.mousemove(this.mouseCanvasPoint(), this.mouse, this.transform, modifiersFrom(e));
      }
    });
    this.addEventListener('mousedown', (e: MouseEvent) => {
      this.modifiers = modifiersFrom(e);
      e.stopImmediatePropagation();
      if (isDialogOpen() || e.button > 2) {
        return;
      }
      if (this.data.mousedown(e)) {
        return;
      }
      if (e.button === 2 && e.detail >= 2) {
        this.setRotation(0);
        return;
      }
      this.dragging = true;
      this.drag_button = e.button;
    });
    this.addEventListener('mouseup', (e: MouseEvent) => {
      this.modifiers = modifiersFrom(e);
      e.stopImmediatePropagation();
      if (e.button > 2) {
        return;
      }
      this.dragging = false;
      if (this.dragged) {
        this.data.mousemove(this.mouseCanvasPoint(), this.mouse, this.transform, modifiersFrom(e));
        this.dragged = false;
      } else {
        this.data.mouseup(e);
      }
    });
    this.addEventListener('mouseenter', () => {
      this.hovered = true;
      this.sticky_pan = { up: false, down: false, left: false, right: false };
    });
    this.addEventListener('mouseleave', () => {
      this.hovered = false;
      if (this.data.allow_side_move && !this.dragging) {
        this.sticky_pan = {
          up: this.mouse.y < this.edge_arm_threshold,
          down: this.mouse.y > this.bounding_rect.height - this.edge_arm_threshold,
          left: this.mouse.x < this.edge_arm_threshold,
          right: this.mouse.x > this.bounding_rect.width - this.edge_arm_threshold,
        };
      }
      this.data.mouseleave();
    });
    this.addEventListener(
      'contextmenu',
      (e) => {
        e.preventDefault();
      },
      false
    );
    document.body.addEventListener('keydown', this.handleKeydown);
    document.body.addEventListener('keyup', this.handleKeyup);
    document.addEventListener('mousemove', this.handleDocumentMouseMove);
    document.addEventListener('mouseup', this.handleDocumentMouseUp);
    window.addEventListener('blur', this.handleBlur);
    for (const type of EXTRA_MOUSE_BUTTON_EVENTS) {
      window.addEventListener(type, this.handleExtraMouseButton, true);
    }
  }

  // swallowed while the board is mounted so they never trigger browser back/forward navigation
  private handleExtraMouseButton = (e: MouseEvent) => {
    this.modifiers = modifiersFrom(e);
    if (e.button <= 2) {
      return;
    }
    e.preventDefault();
    if (e.type !== 'auxclick') {
      this.data.extraMouseButton?.(e);
    }
  };

  private handleDocumentMouseMove = (e: MouseEvent) => {
    this.modifiers = modifiersFrom(e);
    const rect = this.canvas.getBoundingClientRect();
    this.mouse = { x: e.clientX - rect.left, y: e.clientY - rect.top };
  };

  private handleDocumentMouseUp = (e: MouseEvent): void => {
    if (e.button === this.drag_button) {
      this.dragging = false;
      this.dragged = false;
    }
  };

  private handleBlur = (): void => {
    this.modifiers = { ctrl: false, shift: false, alt: false };
    this.sticky_pan = { up: false, down: false, left: false, right: false };
    this.holding_keys = { arrow_up: false, arrow_down: false, arrow_left: false, arrow_right: false };
    this.dragging = false;
    this.dragged = false;
    this.hovered = false;
    this.data?.cancelInput?.();
  };

  private handleKeydown = (e: KeyboardEvent) => {
    this.modifiers = modifiersFrom(e);
    if (!this.hovered || isTypingInInput() || isDialogOpen()) {
      return;
    }
    switch (e.key) {
      case 'ArrowUp':
        this.holding_keys.arrow_up = true;
        break;
      case 'ArrowDown':
        this.holding_keys.arrow_down = true;
        break;
      case 'ArrowLeft':
        this.holding_keys.arrow_left = true;
        break;
      case 'ArrowRight':
        this.holding_keys.arrow_right = true;
        break;
      default:
        break;
    }
  };

  private handleKeyup = (e: KeyboardEvent) => {
    this.modifiers = modifiersFrom(e);
    switch (e.key) {
      case 'ArrowUp':
        this.holding_keys.arrow_up = false;
        break;
      case 'ArrowDown':
        this.holding_keys.arrow_down = false;
        break;
      case 'ArrowLeft':
        this.holding_keys.arrow_left = false;
        break;
      case 'ArrowRight':
        this.holding_keys.arrow_right = false;
        break;
      default:
        break;
    }
  };

  override disconnectedCallback(): void {
    this.initialization_controller.abort();
    this.initialized_successfully = false;
    super.disconnectedCallback();
    clearInterval(this.draw_interval);
    this.handleBlur();
    this.resize_observer.disconnect();
    document.body.removeEventListener('keydown', this.handleKeydown);
    document.body.removeEventListener('keyup', this.handleKeyup);
    document.removeEventListener('mousemove', this.handleDocumentMouseMove);
    document.removeEventListener('mouseup', this.handleDocumentMouseUp);
    window.removeEventListener('blur', this.handleBlur);
    for (const type of EXTRA_MOUSE_BUTTON_EVENTS) {
      window.removeEventListener(type, this.handleExtraMouseButton, true);
    }
  }

  private tick() {
    if (isDialogOpen()) {
      return;
    }
    const d_view = { x: 0, y: 0 };
    const arrow_key_speed = 20;
    let moved = false;
    const rect = this.bounding_rect;
    if (this.holding_keys.arrow_up) {
      d_view.y -= arrow_key_speed;
      moved = true;
    }
    if (this.holding_keys.arrow_down) {
      d_view.y += arrow_key_speed;
      moved = true;
    }
    if (this.holding_keys.arrow_left) {
      d_view.x -= arrow_key_speed;
      moved = true;
    }
    if (this.holding_keys.arrow_right) {
      d_view.x += arrow_key_speed;
      moved = true;
    }
    if (!this.dragging && this.data.allow_side_move && this.hovered && document.hasFocus()) {
      if (!this.pan_suppressed.y && this.mouse.y < this.cursor_move_threshold) {
        d_view.y -= arrow_key_speed;
        moved = true;
      }
      if (!this.pan_suppressed.y && this.mouse.y > rect.height - this.cursor_move_threshold) {
        d_view.y += arrow_key_speed;
        moved = true;
      }
      if (!this.pan_suppressed.x && this.mouse.x < this.cursor_move_threshold) {
        d_view.x -= arrow_key_speed;
        moved = true;
      }
      if (!this.pan_suppressed.x && this.mouse.x > rect.width - this.cursor_move_threshold) {
        d_view.x += arrow_key_speed;
        moved = true;
      }
    } else if (!this.dragging && this.data.allow_side_move && !this.hovered && document.hasFocus()) {
      if (this.sticky_pan.up) {
        d_view.y -= arrow_key_speed;
        moved = true;
      }
      if (this.sticky_pan.down) {
        d_view.y += arrow_key_speed;
        moved = true;
      }
      if (this.sticky_pan.left) {
        d_view.x -= arrow_key_speed;
        moved = true;
      }
      if (this.sticky_pan.right) {
        d_view.x += arrow_key_speed;
        moved = true;
      }
    }
    if (moved) {
      const rotated = rotatePoint(d_view, -this.transform.rotation);
      this.setView({
        x: this.transform.view.x + rotated.x,
        y: this.transform.view.y + rotated.y,
      });
      this.data.mousemove(this.mouseCanvasPoint(), this.mouse, this.transform, this.getModifiers());
    }
  }

  setCursor(image_path: string, alpha = 1) {
    this.setCursorUrl(`/images/cursors/${image_path}.png`, alpha);
  }

  setCursorUrl(url: string, alpha = 1) {
    this.cursor_alpha = alpha;
    let img = this.cursor_images.get(url);
    if (!img) {
      img = createImage(url);
      this.cursor_images.set(url, img);
    }
    this.cursor_image = img;
  }

  private drawCursor() {
    if (this.hovered && !isDialogOpen() && this.cursor_image && isImageReady(this.cursor_image)) {
      this.canvas.style.cursor = 'none';
      configDraw(
        this.ctx,
        this.transform,
        { fill_style: 'transparent', stroke_width: 0, fixed_position: true },
        false,
        false,
        () => {
          const img = this.cursor_image!;
          this.ctx.globalAlpha = this.cursor_alpha;
          this.ctx.drawImage(img, this.mouse.x, this.mouse.y, img.naturalWidth, img.naturalHeight);
          this.ctx.globalAlpha = 1;
        }
      );
    } else {
      this.canvas.style.cursor = 'auto';
    }
  }

  scaleView(scale: number) {
    this.setView({
      x: this.transform.view.x * scale,
      y: this.transform.view.y * scale,
    });
  }

  setOffset(offset: Point2D) {
    this.transform.offset = offset;
  }

  /** Suppresses edge-of-screen panning along the given axes */
  setPanSuppressed(x: boolean, y: boolean) {
    this.pan_suppressed = { x, y };
  }

  setRotation(rotation: number) {
    this.transform.rotation = rotation;
  }

  setView(view: Point2D) {
    if (isNaN(view.x) || isNaN(view.y)) {
      return;
    }
    if (view.x < 0) {
      view.x = 0;
    } else if (view.x > this.data.board_size.x * this.transform.scale) {
      view.x = this.data.board_size.x * this.transform.scale;
    }
    if (view.y < 0) {
      view.y = 0;
    } else if (view.y > this.data.board_size.y * this.transform.scale) {
      view.y = this.data.board_size.y * this.transform.scale;
    }
    this.transform.view = view;
  }

  getMaxScale(): number {
    return this.data.max_scale;
  }

  setMaxScale(max_scale: number, min_scale?: number): void {
    if (!max_scale || max_scale < 1) {
      return;
    }
    const scale_ratio = max_scale / this.data.max_scale;
    const preserve_scale = min_scale !== undefined && this.data.min_scale !== undefined;
    this.data.max_scale = max_scale;
    this.data.min_scale = min_scale;
    const scale = this.transform.scale;
    const next_scale = preserve_scale || scale > 1 ? scale * scale_ratio : scale < 1 ? scale / scale_ratio : scale;
    this.setScale(next_scale);
  }

  setScale(scale: number): number {
    scale = this.clampScale(scale);
    if (!scale) {
      return this.transform.scale;
    }
    this.transform.view.x *= scale / this.transform.scale;
    this.transform.view.y *= scale / this.transform.scale;
    this.transform.scale = scale;
    return scale;
  }

  zoomTowardPoint(scale: number, anchor: Point2D): number {
    scale = this.clampScale(scale);
    if (!scale) {
      return this.transform.scale;
    }
    const factor = scale / this.transform.scale;
    this.transform.scale = scale;
    const a = rotatePoint(
      { x: anchor.x - this.transform.offset.x, y: anchor.y - this.transform.offset.y },
      -this.transform.rotation
    );
    this.setView({
      x: factor * this.transform.view.x + (factor - 1) * a.x,
      y: factor * this.transform.view.y + (factor - 1) * a.y,
    });
    return scale;
  }

  private clampScale(scale: number): number {
    if (!scale) {
      return 0;
    }
    const min_scale = this.data.min_scale ?? 1 / this.data.max_scale;
    if (scale < min_scale) {
      return min_scale;
    } else if (scale > this.data.max_scale) {
      return this.data.max_scale;
    }
    return scale;
  }
}

customElements.define('dwg-canvas-board', DwgCanvasBoard);

declare global {
  interface HTMLElementTagNameMap {
    'dwg-canvas-board': DwgCanvasBoard;
  }
}

import { defaultTransform, type BoardTransformData } from '../../canvas_board/canvas_board';
import type { Point2D } from '../../objects2d';
import type { CanvasComponent } from '../canvas_component';
import { ClickSource, mouseEventToClickSource, type ButtonConfig } from './button_config';

export abstract class DwgButton implements CanvasComponent {
  private hovering = false;
  private clicking = false;
  private click_hold_timer = 0;
  private hold_clicks = 0;
  private disabled: boolean;
  private last_canvas: Point2D = { x: 0, y: 0 };
  private last_screen: Point2D = { x: 0, y: 0 };
  private last_transform: BoardTransformData = defaultTransform();

  private config: ButtonConfig;

  constructor(config: ButtonConfig) {
    if (config.hold_config) {
      if (config.hold_config.hold_click_time < 1) {
        config.hold_config = undefined;
        console.error('Must set hold click time for hold click buttons');
      } else if (config.hold_config.hold_click_delay < 1) {
        config.hold_config.hold_click_delay = config.hold_config.hold_click_time;
      }
    }
    this.disabled = !!config.start_disabled;
    this.config = config;
  }

  isHovering() {
    return this.hovering;
  }

  setHovering(hovering: boolean) {
    this.hovering = hovering;
  }

  isClicking() {
    return this.clicking;
  }

  setClicking(clicking: boolean) {
    this.clicking = clicking;
  }

  isPressed() {
    return this.clicking;
  }

  isDisabled(): boolean {
    return this.disabled;
  }

  disable() {
    this.disabled = true;
    this.hovering = false;
    this.clicking = false;
  }

  enable() {
    this.disabled = false;
    this.mousemove(this.last_canvas, this.last_screen, this.last_transform);
  }

  draw(ctx: CanvasRenderingContext2D, transform: BoardTransformData, dt: number): void {
    this.last_transform = transform;
    if (this.clicking && this.config.hold_config && !this.disabled) {
      this.click_hold_timer -= dt;
      if (this.click_hold_timer < 0) {
        this.click_hold_timer += this.config.hold_config.hold_click_time;
        this.hold_clicks++;
        this.clicked(ClickSource.HOLD_CLICK);
      }
    }
    this._draw(ctx, transform, dt);
  }

  mousemove(canvas: Point2D, screen: Point2D, _transform: BoardTransformData): boolean {
    this.last_canvas = canvas;
    this.last_screen = screen;
    if (this.disabled) {
      this.hovering = false;
      false;
    }
    const previous_hovered = this.hovering;
    this.hovering = this.mouseOver(canvas, screen);
    if (!previous_hovered && this.hovering) {
      this.hovered();
    } else if (previous_hovered && !this.hovering) {
      this.unhovered();
      if (this.clicking && this.config.hold_config?.hold_click_hover) {
        this.clicking = false;
        this.released(ClickSource.HOLD_CLICK);
      }
    }
    return this.hovering;
  }

  /** Returns whether this mousedown event triggered a click event on the button */
  mousedown(e: MouseEvent): boolean {
    if (this.disabled) {
      return false;
    }
    const source = mouseEventToClickSource(e);
    if (source === ClickSource.UNKNOWN) {
      return false;
    }
    if (!this.config.allow_nonleft_clicks && source !== ClickSource.LEFT_MOUSE) {
      return false;
    }
    if (this.hovering && !this.clicking) {
      this.clicking = true;
      this.hold_clicks = 0;
      if (this.config.hold_config) {
        this.click_hold_timer = this.config.hold_config.hold_click_delay;
      }
      this.clicked(source);
      return true;
    }
    return false;
  }

  /** Returns whether this mouseup event triggered a release event on the button */
  mouseup(e: MouseEvent) {
    if (this.disabled) {
      return;
    }
    const source = mouseEventToClickSource(e);
    if (source === ClickSource.UNKNOWN) {
      return;
    }
    if (this.clicking) {
      this.clicking = false;
      this.released(source);
    }
  }

  protected abstract _draw(ctx: CanvasRenderingContext2D, transform: BoardTransformData, t: number): void;
  abstract mouseOver(canvas: Point2D, screen: Point2D): boolean;

  protected abstract hovered(): void;
  protected abstract unhovered(): void;
  protected abstract clicked(source: ClickSource): void;
  protected abstract released(source: ClickSource): void;

  abstract xi(): number;
  abstract xf(): number;
  abstract yi(): number;
  abstract yf(): number;
  abstract w(): number;
  abstract h(): number;
}

import type { BoardTransformData } from '../../canvas_board/canvas_board';
import type { DrawTextConfig } from '../../canvas_util';
import { drawRect, drawText } from '../../canvas_util';
import type { Point2D } from '../../objects2d';
import { addPoint2D, equalsPoint2D, multiplyPoint2D } from '../../objects2d';
import type { DrawConfig, Rotation } from '../canvas_component';
import { configDraw } from '../canvas_component';
import type { ButtonConfig } from './button_config';
import { DwgButton } from './button';
import type { WithRequired } from '../../../../../scripts/types';
import { createImage, resolveImage } from '../../../../../scripts/image';

type RectButtonTextConfig = WithRequired<Omit<DrawTextConfig, 'p' | 'w'>, 'align' | 'baseline' | 'font'>;

/** Config data for a rect button */
export declare interface RectButtonConfig {
  button_config: ButtonConfig;
  p: Point2D;
  w: number;
  h: number;
  draw_config: DrawConfig;
  move_animation_speed?: number;
  rotate_animation_speed?: number;
  image_path?: string;
  /** If true, the image draws on top of the fill instead of behind it*/
  image_on_top?: boolean;
  rotation?: number;
  text?: {
    text: string;
    config: RectButtonTextConfig;
    padding?: number;
  };
  r?: number;
}

export abstract class DwgRectButton extends DwgButton {
  private rect_config!: RectButtonConfig;
  private center_p!: Point2D;
  private radius_p!: Point2D;
  private speed_p?: Point2D;
  private target_p?: Point2D;
  private target_callback?: () => void;
  private reached_target = { x: false, y: false };
  private rotate_target?: Rotation;
  private rotate_speed?: number;
  private rotate_reached?: boolean;
  private rotate_callback?: () => void;
  private img?: CanvasImageSource;
  private text_align_p?: Point2D;

  constructor(config: RectButtonConfig) {
    super(config.button_config);
    config.move_animation_speed = config.move_animation_speed ?? 0;
    config.rotate_animation_speed = config.rotate_animation_speed ?? 0;
    if (!!config.image_path) {
      this.img = createImage(`/images/${config.image_path}.png`);
    }
    config.rotation = config.rotation ?? 0;
    this.rect_config = config;
    this.refreshPositionDependencies();
  }

  protected setImage(img: CanvasImageSource): void {
    this.img = img;
  }

  setPosition(p: Point2D, callback?: () => void, no_animation = false) {
    const animation_speed = this.rect_config.move_animation_speed;
    if (!!animation_speed && animation_speed > 0 && !equalsPoint2D(p, this.rect_config.p) && !no_animation) {
      this.target_p = { ...p };
      this.speed_p = {
        x: (p.x - this.rect_config.p.x) / animation_speed,
        y: (p.y - this.rect_config.p.y) / animation_speed,
      };
      this.reached_target = { x: false, y: false };
      this.target_callback = callback;
    } else {
      this.rect_config.p = { ...p };
      this.refreshPositionDependencies();
      if (!!callback) {
        callback();
      }
    }
  }

  setW(w: number) {
    this.rect_config.w = w;
    this.refreshPositionDependencies();
  }

  setH(h: number) {
    this.rect_config.h = h;
    this.refreshPositionDependencies();
  }

  setSize(w: number, h: number) {
    this.rect_config.w = w;
    this.rect_config.h = h;
    this.refreshPositionDependencies();
  }

  setText(s: string) {
    if (!this.rect_config.text) {
      return;
    }
    this.rect_config.text.text = s;
  }

  setRotation(rotation: Rotation, callback?: () => void, no_animation = false) {
    const animation_speed = this.rect_config.rotate_animation_speed ?? this.rect_config.move_animation_speed;
    if (
      animation_speed !== undefined &&
      this.rect_config.rotation !== undefined &&
      animation_speed > 0 &&
      rotation.angle !== this.rect_config.rotation &&
      !no_animation
    ) {
      this.rotate_target = rotation;
      let rotation_needed = (rotation.angle - this.rect_config.rotation) % (2 * Math.PI);
      if (rotation.direction && rotation_needed < 0) {
        rotation_needed += 2 * Math.PI;
      } else if (!rotation.direction && rotation_needed > 0) {
        rotation_needed -= 2 * Math.PI;
      }
      this.rotate_speed = rotation_needed / animation_speed;
      this.rotate_reached = false;
      this.rotate_callback = callback;
    } else {
      this.rect_config.rotation = rotation.angle;
      if (!!callback) {
        callback();
      }
    }
  }

  private refreshPositionDependencies() {
    this.radius_p = {
      x: 0.5 * this.rect_config.w,
      y: 0.5 * this.rect_config.h,
    };
    this.center_p = addPoint2D(this.rect_config.p, this.radius_p);
    if (!!this.rect_config.text) {
      this.text_align_p = { x: 0, y: 0 };
      const padding = this.rect_config.text.padding ?? 0;
      switch (this.rect_config.text.config.align) {
        case 'center':
          this.text_align_p.x = 0;
          break;
        case 'left':
        case 'start':
          this.text_align_p.x = padding - 0.5 * this.w();
          break;
        case 'right':
        case 'end':
          this.text_align_p.y = 0.5 * this.w() - padding;
          break;
      }
      switch (this.rect_config.text.config.baseline) {
        case 'alphabetic':
        case 'hanging':
        case 'middle':
          this.text_align_p.y = 0;
          break;
        case 'top':
          this.text_align_p.y = padding - 0.5 * this.h();
          break;
        case 'ideographic':
        case 'bottom':
          this.text_align_p.y = 0.5 * this.h() - padding;
          break;
      }
    }
  }

  xi(): number {
    return this.rect_config.p.x;
  }
  yi(): number {
    return this.rect_config.p.y;
  }
  xf(): number {
    return this.rect_config.p.x + this.rect_config.w;
  }
  yf(): number {
    return this.rect_config.p.y + this.rect_config.h;
  }
  xc(): number {
    return this.center_p.x;
  }
  yc(): number {
    return this.center_p.y;
  }
  w(): number {
    return this.rect_config.w;
  }
  h(): number {
    return this.rect_config.h;
  }

  protected override _draw(ctx: CanvasRenderingContext2D, transform: BoardTransformData, dt: number): void {
    if (this.img instanceof HTMLImageElement) {
      resolveImage(this.img);
    }
    // translate animation
    if (!!this.target_p && !!this.speed_p) {
      if (this.reached_target.x && this.reached_target.y) {
        this.rect_config.p = { ...this.target_p };
        this.target_p = undefined;
        this.speed_p = undefined;
        if (!!this.target_callback) {
          this.target_callback();
        }
      } else {
        if (!this.reached_target.x) {
          const dx = this.speed_p.x * dt;
          if (Math.abs(this.rect_config.p.x - this.target_p.x) <= Math.abs(dx)) {
            this.reached_target.x = true;
            this.rect_config.p.x = this.target_p.x;
          } else {
            this.rect_config.p.x += dx;
            if (Math.abs(this.rect_config.p.x - this.target_p.x) <= Math.abs(dx)) {
              this.reached_target.x = true;
            }
          }
        }
        if (!this.reached_target.y) {
          const dy = this.speed_p.y * dt;
          if (Math.abs(this.rect_config.p.y - this.target_p.y) <= Math.abs(dy)) {
            this.reached_target.y = true;
            this.rect_config.p.y = this.target_p.y;
          } else {
            this.rect_config.p.y += dy;
            if (Math.abs(this.rect_config.p.y - this.target_p.y) <= Math.abs(dy)) {
              this.reached_target.y = true;
            }
          }
        }
      }
      this.refreshPositionDependencies();
    }
    // rotate animation
    if (
      this.rotate_target !== undefined &&
      this.rotate_speed !== undefined &&
      this.rect_config.rotation !== undefined
    ) {
      const da = this.rotate_speed * dt;
      if (this.rotate_reached || Math.abs(this.rect_config.rotation - this.rotate_target.angle) <= Math.abs(da)) {
        this.rect_config.rotation = this.rotate_target.angle;
        this.rotate_target = undefined;
        this.rotate_speed = undefined;
        if (!!this.rotate_callback) {
          this.rotate_callback();
        }
      } else {
        this.rect_config.rotation += da;
        if (Math.abs(this.rect_config.rotation - this.rotate_target.angle) <= Math.abs(da)) {
          this.rotate_reached = true;
        }
      }
    }
    // actual draw
    configDraw(ctx, transform, this.rect_config.draw_config, this.isHovering(), this.isClicking(), () => {
      ctx.beginPath();
      ctx.translate(this.center_p.x, this.center_p.y);
      if (!!this.rect_config.rotation) {
        ctx.rotate(this.rect_config.rotation);
      }
      if (!!this.img && !this.rect_config.image_on_top) {
        ctx.drawImage(this.img, -this.radius_p.x, -this.radius_p.y, this.rect_config.w, this.rect_config.h);
      }
      drawRect(ctx, multiplyPoint2D(-1, this.radius_p), this.rect_config.w, this.rect_config.h, this.rect_config.r);
      if (!!this.img && this.rect_config.image_on_top) {
        ctx.drawImage(this.img, -this.radius_p.x, -this.radius_p.y, this.rect_config.w, this.rect_config.h);
      }
      if (!!this.rect_config.text && !!this.text_align_p) {
        drawText(ctx, this.rect_config.text.text, {
          ...this.rect_config.text.config,
          p: this.text_align_p,
          w: this.w() - 2 * (this.rect_config.text.padding ?? 0),
        });
      }
      if (!!this.rect_config.rotation) {
        ctx.rotate(-this.rect_config.rotation);
      }
      ctx.translate(-this.center_p.x, -this.center_p.y);
    });
  }

  override mouseOver(canvas: Point2D, screen: Point2D): boolean {
    const m = this.rect_config.draw_config.fixed_position ? screen : canvas;
    if (m.x < this.xi() || m.y < this.yi() || m.x > this.xf() || m.y > this.yf()) {
      return false;
    }
    return true;
  }
}

import type { BoardTransformData } from '../canvas_board/canvas_board';
import type { Point2D } from '../objects2d';

/** Data a canvas component must have */
export declare interface CanvasComponent {
  isHovering: () => boolean;
  setHovering: (hovering: boolean) => void;
  isClicking: () => boolean;
  setClicking: (clicking: boolean) => void;
  draw: (ctx: CanvasRenderingContext2D, transform: BoardTransformData, dt: number) => void;
  // should return true if scroll had an effect on the component
  scroll?: (dy: number, mode: number, dx?: number) => boolean;
  // should return true if the component is hovered
  mousemove: (canvas: Point2D, screen: Point2D, transform: BoardTransformData) => boolean;
  // should return true if mousedown had an effect on the component
  mousedown: (e: MouseEvent) => boolean;
  mouseup: (e: MouseEvent) => void;
  xi: () => number;
  xf: () => number;
  yi: () => number;
  yf: () => number;
  w: () => number;
  h: () => number;
}

/** Default xc function for all canvas components */
export function xc(cc: CanvasComponent): number {
  return cc.xi() + 0.5 * cc.w();
}

/** Default yc function for all canvas components */
export function yc(cc: CanvasComponent): number {
  return cc.yi() + 0.5 * cc.h();
}

/** Config for drawing */
export declare interface DrawConfig {
  /** sets canvas fillStyle */
  fill_style: string;
  /** sets canvas strokeStyle */
  stroke_style?: string;
  /** sets canvas lineWidth */
  stroke_width: number;
  /** sets canvas fillStyle when hovered */
  hover_fill_style?: string;
  /** sets canvas strokeStyle when hovered */
  hover_stroke_style?: string;
  /** sets canvas lineWidth when hovered */
  hover_stroke_width?: number;
  /** sets canvas fillStyle when clicked */
  click_fill_style?: string;
  /** sets canvas strokeStyle when clicked */
  click_stroke_style?: string;
  /** sets canvas lineWidth when clicked */
  click_stroke_width?: number;
  /** draw with clicked config when clicked and not hovered */
  draw_clicked_when_unhovered?: boolean;
  /** forces draw to ignore transformations */
  fixed_position?: boolean;
  /** ignore all stroke styles and just match them to the fill style */
  stroke_matches_fill_style?: boolean;
}

const default_stroke_style = 'transparent';

/** Applies input draw config to the input canvas */
export function configDraw(
  ctx: CanvasRenderingContext2D,
  transform: BoardTransformData,
  config: DrawConfig,
  hovering: boolean,
  clicking: boolean,
  draw: () => void
) {
  if (clicking) {
    if (hovering) {
      ctx.fillStyle = config.click_fill_style ?? config.hover_fill_style ?? config.fill_style;
      ctx.strokeStyle =
        config.click_stroke_style ?? config.hover_stroke_style ?? config.stroke_style ?? default_stroke_style;
      ctx.lineWidth = config.click_stroke_width ?? config.hover_stroke_width ?? config.stroke_width;
    } else if (config.draw_clicked_when_unhovered) {
      ctx.fillStyle = config.click_fill_style ?? config.fill_style;
      ctx.strokeStyle = config.click_stroke_style ?? config.stroke_style ?? default_stroke_style;
      ctx.lineWidth = config.click_stroke_width ?? config.stroke_width;
    } else {
      ctx.fillStyle = config.fill_style;
      ctx.strokeStyle = config.stroke_style ?? default_stroke_style;
      ctx.lineWidth = config.stroke_width;
    }
  } else if (hovering) {
    ctx.fillStyle = config.hover_fill_style ?? config.fill_style;
    ctx.strokeStyle = config.hover_stroke_style ?? config.stroke_style ?? default_stroke_style;
    ctx.lineWidth = config.hover_stroke_width ?? config.stroke_width;
  } else {
    ctx.fillStyle = config.fill_style;
    ctx.strokeStyle = config.stroke_style ?? default_stroke_style;
    ctx.lineWidth = config.stroke_width;
  }
  if (config.stroke_matches_fill_style) {
    ctx.strokeStyle = ctx.fillStyle;
  }
  if (config.fixed_position) {
    ctx.scale(1 / transform.scale, 1 / transform.scale);
    ctx.translate(transform.view.x, transform.view.y);
    ctx.rotate(-transform.rotation);
    ctx.translate(-transform.offset.x, -transform.offset.y);
  }
  ctx.beginPath();
  draw();
  if (config.fixed_position) {
    ctx.translate(transform.offset.x, transform.offset.y);
    ctx.rotate(transform.rotation);
    ctx.translate(-transform.view.x, -transform.view.y);
    ctx.scale(transform.scale, transform.scale);
  }
}

/** Data describing a rotation */
export declare interface Rotation {
  /** should be true for counterclockwise */
  direction: boolean;
  /** can represent an angle move or a target angle */
  angle: number;
}

import type { BoardTransformData } from '../../canvas_board/canvas_board';
import type { Point2D } from '../../objects2d';
import type { CanvasComponent } from '../canvas_component';

export declare interface DropdownOption {
  value: string;
  label: string;
}

export declare interface DropdownConfig {
  options: DropdownOption[];
  selected?: string;
  start_disabled?: boolean;
}

type DropdownPress = 'button' | number;

export abstract class DwgDropdown implements CanvasComponent {
  private hovering = false;
  private over_popover = false;
  private hover_option?: number;
  private pressed?: DropdownPress;
  private open = false;
  private disabled: boolean;
  private option_list: DropdownOption[];
  private selected?: string;

  constructor(config: DropdownConfig) {
    this.option_list = config.options;
    this.selected = config.selected;
    this.disabled = !!config.start_disabled;
  }

  options(): DropdownOption[] {
    return this.option_list;
  }

  setOptions(options: DropdownOption[]) {
    this.option_list = options;
    if (!options.some((option) => option.value === this.selected)) {
      this.selected = undefined;
    }
    this.close();
  }

  value(): string | undefined {
    return this.selected;
  }

  setValue(value: string | undefined) {
    this.selected = this.option_list.some((option) => option.value === value) ? value : undefined;
  }

  selectedOption(): DropdownOption | undefined {
    return this.option_list.find((option) => option.value === this.selected);
  }

  isOpen(): boolean {
    return this.open;
  }

  close() {
    this.open = false;
    this.over_popover = false;
    this.hover_option = undefined;
    this.pressed = undefined;
  }

  protected hoveredOption(): number | undefined {
    return this.hover_option;
  }

  protected isButtonHovered(): boolean {
    return this.hovering;
  }

  isHovering() {
    return this.hovering || this.over_popover;
  }

  setHovering(hovering: boolean) {
    if (!hovering) {
      this.hovering = false;
      this.over_popover = false;
      this.hover_option = undefined;
    }
  }

  isClicking() {
    return this.pressed !== undefined;
  }

  setClicking(clicking: boolean) {
    if (!clicking) {
      this.pressed = undefined;
    }
  }

  isDisabled(): boolean {
    return this.disabled;
  }

  disable() {
    this.disabled = true;
    this.setHovering(false);
    this.close();
  }

  enable() {
    this.disabled = false;
  }

  draw(ctx: CanvasRenderingContext2D, transform: BoardTransformData, dt: number): void {
    this._draw(ctx, transform, dt);
  }

  mousemove(canvas: Point2D, screen: Point2D, _transform: BoardTransformData): boolean {
    if (this.disabled) {
      this.setHovering(false);
      return false;
    }
    this.hovering = this.mouseOver(canvas, screen);
    this.over_popover = this.open && this.overPopover(canvas, screen);
    this.hover_option = this.over_popover ? this.optionAt(canvas, screen) : undefined;
    return this.isHovering();
  }

  scroll(dy: number): boolean {
    return this.over_popover && this.scrolled(dy);
  }

  mousedown(e: MouseEvent): boolean {
    if (this.disabled || e.button !== 0) {
      return false;
    }
    if (this.hovering) {
      this.pressed = 'button';
      return true;
    }
    if (this.hover_option !== undefined) {
      this.pressed = this.hover_option;
      return true;
    }
    if (this.over_popover) {
      return true;
    }
    const was_open = this.open;
    this.close();
    return was_open;
  }

  mouseup(e: MouseEvent) {
    const target = this.pressed;
    this.pressed = undefined;
    if (e.button !== 0 || target === undefined) {
      return;
    }
    if (target === 'button' && this.hovering) {
      this.toggle();
    } else if (target === this.hover_option && typeof target === 'number') {
      this.choose(target);
    }
  }

  private toggle() {
    if (this.open) {
      this.close();
      return;
    }
    this.open = true;
    this.opened();
  }

  private choose(index: number) {
    const option = this.option_list[index];
    this.close();
    if (option.value !== this.selected) {
      this.selected = option.value;
      this.changed(option);
    }
  }

  protected abstract _draw(ctx: CanvasRenderingContext2D, transform: BoardTransformData, dt: number): void;
  abstract mouseOver(canvas: Point2D, screen: Point2D): boolean;
  protected abstract overPopover(canvas: Point2D, screen: Point2D): boolean;
  protected abstract optionAt(canvas: Point2D, screen: Point2D): number | undefined;
  protected abstract scrolled(dy: number): boolean;

  protected abstract opened(): void;
  protected abstract changed(option: DropdownOption): void;

  abstract xi(): number;
  abstract xf(): number;
  abstract yi(): number;
  abstract yf(): number;
  abstract w(): number;
  abstract h(): number;
}

import { clampNumber } from '../../../../../scripts/math';
import type { BoardTransformData } from '../../canvas_board/canvas_board';
import { drawRect, drawText } from '../../canvas_util';
import type { Point2D } from '../../objects2d';
import type { CanvasComponent } from '../canvas_component';
import { configDraw } from '../canvas_component';
import type { RectScrollbarConfig } from '../scrollbar/rect_scrollbar';
import { DwgRectScrollbar } from '../scrollbar/rect_scrollbar';
import { queueTooltipDraw } from '../tooltip';

export declare interface MultiSelectOption {
  id: number;
  label: string;
  icon?: string;
}

export declare interface DropdownBounds {
  x: number;
  y: number;
  w: number;
  h: number;
}

export declare interface MultiSelectDropdownConfig {
  title: string;
  options: MultiSelectOption[];
  /** Edited in place; onChange fires after every edit */
  selected: Set<number>;
  onChange: () => void;
  getIcon: (path: string) => HTMLImageElement;
  /** The popover stays inside this rect, scrolling its option rows if they don't fit */
  bounds: () => DropdownBounds;
}

/** The button, its clear badge, or an option by index */
type DropdownTarget = 'button' | 'clear' | number;

type PopoverRect = DropdownBounds;

const ROW_H = 18;
const POPOVER_W = 200;
const POPOVER_OVERLAP = 8;
const MIN_POPOVER_ROWS = 1.5;
const CLEAR_BADGE = 12;
const PADDING = 4;
const CHECKBOX = 12;
const ICON = 14;
const SCROLLBAR_W = 10;

function popoverScrollbarConfig(value: number, max_scroll: number): RectScrollbarConfig {
  const fill = (alpha: number) => ({ fill_style: `rgba(59, 36, 19, ${alpha})`, stroke_width: 0, fixed_position: true });
  return {
    scrollbar_config: {
      value: { value, value_min: 0, value_max: max_scroll },
      step_size: ROW_H,
      scroll_pixel_constant: 1,
    },
    p: { x: 0, y: 0 },
    w: SCROLLBAR_W,
    h: 0,
    scrollbar_size: SCROLLBAR_W,
    vertical: true,
    draw_config: { ...fill(0.55), hover_fill_style: fill(0.75).fill_style, click_fill_style: fill(0.9).fill_style },
    space_draw_config: { ...fill(0.12), stroke_matches_fill_style: true },
    background_color: 'rgba(59, 36, 19, 0.08)',
    min_bar_size: 12,
    arrow_scroll_amount: ROW_H,
    space_scroll_amount: 3 * ROW_H,
  };
}

class PopoverScrollbar extends DwgRectScrollbar {
  constructor(value: number, max_scroll: number) {
    super(popoverScrollbarConfig(value, max_scroll));
  }

  scrollCallback(_value: number): void {}
}

export class DwgMultiSelectDropdown implements CanvasComponent {
  private p: Point2D = { x: 0, y: 0 };
  private size: Point2D = { x: 0, y: 0 };
  private open = false;
  private hover?: DropdownTarget;
  private pressed?: DropdownTarget;
  private over_popover = false;
  private scrollbar?: PopoverScrollbar;

  constructor(private config: MultiSelectDropdownConfig) {}

  setPosition(p: Point2D): void {
    this.p = p;
  }

  setSize(w: number, h: number): void {
    this.size = { x: w, y: h };
  }

  isOpen(): boolean {
    return this.open;
  }

  close(): void {
    this.open = false;
    this.hover = undefined;
    this.pressed = undefined;
    this.over_popover = false;
    this.scrollbar = undefined;
  }

  private popoverRect(): PopoverRect {
    const bounds = this.config.bounds();
    const w = Math.min(POPOVER_W, bounds.w);
    const y = this.yf() - POPOVER_OVERLAP;
    const full_h = this.config.options.length * ROW_H;
    const room_h = Math.max(MIN_POPOVER_ROWS * ROW_H, bounds.y + bounds.h - y);
    return { x: clampNumber(this.xi(), bounds.x, bounds.x + bounds.w - w), y, w, h: Math.min(full_h, room_h) };
  }

  private scrollOffset(): number {
    return this.scrollbar?.value() ?? 0;
  }

  private syncScrollbar(): void {
    const pop = this.popoverRect();
    const max_scroll = Math.max(0, this.config.options.length * ROW_H - pop.h);
    if (max_scroll === 0) {
      this.scrollbar = undefined;
      return;
    }
    if (this.scrollbar?.maxValue() !== max_scroll) {
      this.scrollbar = new PopoverScrollbar(Math.min(this.scrollOffset(), max_scroll), max_scroll);
    }
    this.scrollbar.setAllSizes(SCROLLBAR_W, { x: pop.x + pop.w - SCROLLBAR_W - 2, y: pop.y }, SCROLLBAR_W, pop.h);
  }

  private overPopover(m: Point2D): boolean {
    const pop = this.popoverRect();
    return this.open && m.x >= pop.x && m.x <= pop.x + pop.w && m.y >= pop.y && m.y <= pop.y + pop.h;
  }

  private overButton(m: Point2D): boolean {
    return m.x >= this.xi() && m.x <= this.xf() && m.y >= this.yi() && m.y <= this.yf();
  }

  private hitTarget(m: Point2D): DropdownTarget | undefined {
    if (!this.overPopover(m)) {
      if (this.overClearBadge(m)) {
        return 'clear';
      }
      return this.overButton(m) ? 'button' : undefined;
    }
    const pop = this.popoverRect();
    const index = Math.floor((m.y - pop.y + this.scrollOffset()) / ROW_H);
    const over_scrollbar = !!this.scrollbar && m.x >= pop.x + pop.w - SCROLLBAR_W - 2;
    return !over_scrollbar && index < this.config.options.length ? index : undefined;
  }

  private clearBadgePosition(): Point2D {
    return { x: this.xf() - CLEAR_BADGE - 2, y: this.yi() + 2 };
  }

  private overClearBadge(m: Point2D): boolean {
    const p = this.clearBadgePosition();
    const inside = m.x >= p.x && m.x <= p.x + CLEAR_BADGE && m.y >= p.y && m.y <= p.y + CLEAR_BADGE;
    return this.config.selected.size > 0 && inside;
  }

  mousemove(canvas: Point2D, screen: Point2D, transform: BoardTransformData): boolean {
    this.syncScrollbar();
    this.scrollbar?.mousemove(canvas, screen, transform);
    this.hover = this.hitTarget(screen);
    this.over_popover = this.overPopover(screen);
    return this.hover !== undefined || this.over_popover;
  }

  scroll(dy: number): boolean {
    if (this.over_popover) {
      this.scrollbar?._scroll(Math.sign(dy) * 2 * ROW_H);
    }
    return this.over_popover;
  }

  mousedown(e: MouseEvent): boolean {
    if (e.button !== 0) {
      return false;
    }
    if (this.scrollbar?.mousedown(e)) {
      return true;
    }
    if (this.hover !== undefined) {
      this.pressed = this.hover;
      return true;
    }
    if (this.over_popover) {
      return true;
    }
    const captured = this.open;
    this.close();
    return captured;
  }

  mouseup(e: MouseEvent): void {
    this.scrollbar?.mouseup(e);
    const target = this.pressed;
    this.pressed = undefined;
    if (e.button !== 0 || target === undefined || target !== this.hover) {
      return;
    }
    if (target === 'button') {
      this.toggleOpen();
    } else if (target === 'clear') {
      this.config.selected.clear();
      this.config.onChange();
    } else {
      this.toggle(this.config.options[target].id);
    }
  }

  private toggleOpen(): void {
    if (this.open) {
      this.close();
    } else {
      this.open = true;
    }
  }

  private label(): string {
    const count = this.config.selected.size;
    return count > 0 ? `${this.config.title} (${count})` : this.config.title;
  }

  private drawButton(ctx: CanvasRenderingContext2D, transform: BoardTransformData): void {
    const fill_style = this.config.selected.size > 0 ? 'rgb(255, 232, 160)' : 'rgb(241, 226, 196)';
    const draw_config = { fill_style, stroke_style: 'rgb(59, 36, 19)', stroke_width: 0.6, fixed_position: true };
    configDraw(ctx, transform, draw_config, this.hover === 'button', this.pressed === 'button', () => {
      drawRect(ctx, { x: this.xi(), y: this.yi() }, this.w(), this.h(), 3);
      drawText(ctx, this.label(), {
        p: { x: this.xi() + PADDING + 2, y: this.yc() },
        w: this.w() - 2 * PADDING - 14,
        fill_style: 'rgb(59, 36, 19)',
        baseline: 'middle',
        font: 'bold 11px serif',
      });
      this.drawCaret(ctx);
      this.drawClearBadge(ctx);
    });
  }

  private drawCaret(ctx: CanvasRenderingContext2D): void {
    const x = this.xf() - PADDING - 6;
    const y = this.config.selected.size > 0 ? this.yi() + 17 : this.yc();
    const dy = this.open ? -2 : 2;
    ctx.beginPath();
    ctx.moveTo(x - 4, y - dy);
    ctx.lineTo(x + 4, y - dy);
    ctx.lineTo(x, y + dy);
    ctx.closePath();
    ctx.fill();
  }

  private drawClearBadge(ctx: CanvasRenderingContext2D): void {
    if (this.config.selected.size === 0) {
      return;
    }
    const p = this.clearBadgePosition();
    const hovered = this.hover === 'clear';
    const inset = 3;
    ctx.strokeStyle = hovered ? 'rgb(122, 46, 27)' : 'rgba(59, 36, 19, 0.6)';
    ctx.lineWidth = hovered ? 2 : 1.5;
    ctx.beginPath();
    ctx.moveTo(p.x + inset, p.y + inset);
    ctx.lineTo(p.x + CLEAR_BADGE - inset, p.y + CLEAR_BADGE - inset);
    ctx.moveTo(p.x + CLEAR_BADGE - inset, p.y + inset);
    ctx.lineTo(p.x + inset, p.y + CLEAR_BADGE - inset);
    ctx.stroke();
  }

  draw(ctx: CanvasRenderingContext2D, transform: BoardTransformData, dt: number): void {
    this.drawButton(ctx, transform);
    if (this.open) {
      queueTooltipDraw(() => this.drawPopover(ctx, transform, dt));
    }
  }

  private drawPopover(ctx: CanvasRenderingContext2D, transform: BoardTransformData, dt: number): void {
    this.syncScrollbar();
    const pop = this.popoverRect();
    const draw_config = {
      fill_style: 'rgb(241, 226, 196)',
      stroke_style: 'rgb(59, 36, 19)',
      stroke_width: 1,
      fixed_position: true,
    };
    configDraw(ctx, transform, draw_config, false, false, () => {
      drawRect(ctx, { x: pop.x, y: pop.y }, pop.w, pop.h, 3);
      ctx.save();
      ctx.beginPath();
      ctx.rect(pop.x, pop.y, pop.w, pop.h);
      ctx.clip();
      for (let i = 0; i < this.config.options.length; i++) {
        this.drawOptionRow(ctx, pop, i, pop.y + i * ROW_H - this.scrollOffset());
      }
      ctx.restore();
    });
    this.scrollbar?.draw(ctx, transform, dt);
  }

  private drawRowHighlight(ctx: CanvasRenderingContext2D, pop: PopoverRect, y: number, hovered: boolean): void {
    if (hovered) {
      ctx.fillStyle = this.pressed === undefined ? 'rgba(59, 36, 19, 0.12)' : 'rgba(59, 36, 19, 0.22)';
      ctx.strokeStyle = 'transparent';
      drawRect(ctx, { x: pop.x + 2, y }, pop.w - 4, ROW_H, 2);
    }
  }

  private drawCheckbox(ctx: CanvasRenderingContext2D, p: Point2D, checked: boolean): void {
    ctx.fillStyle = 'transparent';
    ctx.strokeStyle = 'rgb(59, 36, 19)';
    ctx.lineWidth = 1;
    drawRect(ctx, p, CHECKBOX, CHECKBOX, 2);
    if (checked) {
      ctx.fillStyle = 'rgb(59, 36, 19)';
      ctx.strokeStyle = 'transparent';
      drawRect(ctx, { x: p.x + 3, y: p.y + 3 }, CHECKBOX - 6, CHECKBOX - 6, 1);
    }
  }

  private drawOptionRow(ctx: CanvasRenderingContext2D, pop: PopoverRect, index: number, y: number): void {
    const option = this.config.options[index];
    this.drawRowHighlight(ctx, pop, y, this.hover === index);
    const checkbox_p = { x: pop.x + PADDING + 4, y: y + 0.5 * (ROW_H - CHECKBOX) };
    this.drawCheckbox(ctx, checkbox_p, this.config.selected.has(option.id));
    let x = checkbox_p.x + CHECKBOX + 6;
    if (option.icon) {
      ctx.drawImage(this.config.getIcon(option.icon), x, y + 0.5 * (ROW_H - ICON), ICON, ICON);
      x += ICON + 6;
    }
    drawText(ctx, option.label, {
      p: { x, y: y + 0.5 * ROW_H },
      w: pop.x + pop.w - PADDING - (this.scrollbar ? SCROLLBAR_W + 2 : 0) - x,
      fill_style: 'rgb(59, 36, 19)',
      baseline: 'middle',
      font: '11px serif',
    });
  }

  private toggle(id: number): void {
    if (!this.config.selected.delete(id)) {
      this.config.selected.add(id);
    }
    this.config.onChange();
  }

  isHovering(): boolean {
    return this.hover !== undefined || this.over_popover;
  }

  setHovering(hovering: boolean): void {
    if (!hovering) {
      this.hover = undefined;
      this.over_popover = false;
    }
  }

  isClicking(): boolean {
    return this.pressed !== undefined;
  }

  setClicking(clicking: boolean): void {
    if (!clicking) {
      this.pressed = undefined;
    }
  }

  xi(): number {
    return this.p.x;
  }
  yi(): number {
    return this.p.y;
  }
  xf(): number {
    return this.p.x + this.size.x;
  }
  yf(): number {
    return this.p.y + this.size.y;
  }
  yc(): number {
    return this.p.y + 0.5 * this.size.y;
  }
  w(): number {
    return this.size.x;
  }
  h(): number {
    return this.size.y;
  }
}

import type { BoardTransformData } from '../../canvas_board/canvas_board';
import type { DrawTextConfig } from '../../canvas_util';
import { drawRect, drawText } from '../../canvas_util';
import type { Point2D } from '../../objects2d';
import type { DrawConfig } from '../canvas_component';
import { configDraw } from '../canvas_component';
import { queueTooltipDraw } from '../tooltip';
import type { DropdownConfig } from './dropdown';
import { DwgDropdown } from './dropdown';
import type { WithRequired } from '../../../../../scripts/types';

type RectDropdownTextConfig = WithRequired<
  Omit<DrawTextConfig, 'p' | 'w' | 'align' | 'baseline'>,
  'font' | 'fill_style'
>;

export declare interface RectDropdownConfig {
  dropdown_config: DropdownConfig;
  p: Point2D;
  w: number;
  h: number;
  draw_config: DrawConfig;
  popover_draw_config: DrawConfig;
  text_config: RectDropdownTextConfig;
  option_hover_fill_style: string;
  placeholder?: string;
  popover_w?: number;
  row_h?: number;
  max_rows?: number;
  padding?: number;
  r?: number;
}

const DEFAULT_ROW_H = 20;
const DEFAULT_MAX_ROWS = 10;
const DEFAULT_PADDING = 4;
const CARET_HALF_W = 4;
const CARET_HALF_H = 2;
const THUMB_W = 3;
const WHEEL_ROWS = 2;

interface Rect {
  x: number;
  y: number;
  w: number;
  h: number;
}

export abstract class DwgRectDropdown extends DwgDropdown {
  private rect_config: RectDropdownConfig;
  private scroll_offset = 0;

  constructor(config: RectDropdownConfig) {
    super(config.dropdown_config);
    this.rect_config = config;
  }

  setPosition(p: Point2D) {
    this.rect_config.p = { ...p };
  }

  setSize(w: number, h: number) {
    this.rect_config.w = w;
    this.rect_config.h = h;
  }

  xi(): number {
    return this.rect_config.p.x;
  }
  yi(): number {
    return this.rect_config.p.y;
  }
  xf(): number {
    return this.rect_config.p.x + this.rect_config.w;
  }
  yf(): number {
    return this.rect_config.p.y + this.rect_config.h;
  }
  xc(): number {
    return this.xi() + 0.5 * this.rect_config.w;
  }
  yc(): number {
    return this.yi() + 0.5 * this.rect_config.h;
  }
  w(): number {
    return this.rect_config.w;
  }
  h(): number {
    return this.rect_config.h;
  }

  private rowH(): number {
    return this.rect_config.row_h ?? DEFAULT_ROW_H;
  }

  private padding(): number {
    return this.rect_config.padding ?? DEFAULT_PADDING;
  }

  private contentH(): number {
    return this.options().length * this.rowH();
  }

  private popoverRect(): Rect {
    const rows = Math.min(this.options().length, this.rect_config.max_rows ?? DEFAULT_MAX_ROWS);
    return { x: this.xi(), y: this.yf(), w: this.rect_config.popover_w ?? this.rect_config.w, h: rows * this.rowH() };
  }

  private maxScroll(): number {
    return Math.max(0, this.contentH() - this.popoverRect().h);
  }

  private mousePoint(canvas: Point2D, screen: Point2D): Point2D {
    return this.rect_config.draw_config.fixed_position ? screen : canvas;
  }

  override mouseOver(canvas: Point2D, screen: Point2D): boolean {
    const m = this.mousePoint(canvas, screen);
    return m.x >= this.xi() && m.x <= this.xf() && m.y >= this.yi() && m.y <= this.yf();
  }

  protected override overPopover(canvas: Point2D, screen: Point2D): boolean {
    const m = this.mousePoint(canvas, screen);
    const pop = this.popoverRect();
    return m.x >= pop.x && m.x <= pop.x + pop.w && m.y >= pop.y && m.y <= pop.y + pop.h;
  }

  protected override optionAt(canvas: Point2D, screen: Point2D): number | undefined {
    const m = this.mousePoint(canvas, screen);
    const index = Math.floor((m.y - this.popoverRect().y + this.scroll_offset) / this.rowH());
    return index >= 0 && index < this.options().length ? index : undefined;
  }

  protected override scrolled(dy: number): boolean {
    const max_scroll = this.maxScroll();
    this.scroll_offset = Math.min(
      Math.max(this.scroll_offset + Math.sign(dy) * WHEEL_ROWS * this.rowH(), 0),
      max_scroll
    );
    return max_scroll > 0;
  }

  protected override opened(): void {
    const selected = this.options().findIndex((option) => option.value === this.value());
    this.scroll_offset = Math.min(Math.max(selected, 0) * this.rowH(), this.maxScroll());
  }

  protected override _draw(ctx: CanvasRenderingContext2D, transform: BoardTransformData, _dt: number): void {
    const config = this.rect_config;
    configDraw(ctx, transform, config.draw_config, this.isButtonHovered(), this.isOpen(), () => {
      drawRect(ctx, config.p, config.w, config.h, config.r);
      this.drawLabel(ctx);
      this.drawCaret(ctx);
    });
    if (this.isOpen()) {
      queueTooltipDraw(() => this.drawPopover(ctx, transform));
    }
  }

  private drawLabel(ctx: CanvasRenderingContext2D): void {
    const padding = this.padding();
    drawText(ctx, this.selectedOption()?.label ?? this.rect_config.placeholder ?? '', {
      ...this.rect_config.text_config,
      p: { x: this.xi() + padding, y: this.yc() },
      w: this.rect_config.w - 3 * padding - 2 * CARET_HALF_W,
      align: 'left',
      baseline: 'middle',
    });
  }

  private drawCaret(ctx: CanvasRenderingContext2D): void {
    const x = this.xf() - this.padding() - CARET_HALF_W;
    const dy = this.isOpen() ? -CARET_HALF_H : CARET_HALF_H;
    ctx.fillStyle = this.rect_config.text_config.fill_style;
    ctx.beginPath();
    ctx.moveTo(x - CARET_HALF_W, this.yc() - dy);
    ctx.lineTo(x + CARET_HALF_W, this.yc() - dy);
    ctx.lineTo(x, this.yc() + dy);
    ctx.closePath();
    ctx.fill();
  }

  private drawPopover(ctx: CanvasRenderingContext2D, transform: BoardTransformData): void {
    const pop = this.popoverRect();
    configDraw(ctx, transform, this.rect_config.popover_draw_config, false, false, () => {
      drawRect(ctx, pop, pop.w, pop.h, this.rect_config.r);
      ctx.save();
      ctx.beginPath();
      ctx.rect(pop.x, pop.y, pop.w, pop.h);
      ctx.clip();
      this.options().forEach((option, i) => this.drawRow(ctx, pop, i, option.label));
      ctx.restore();
      this.drawThumb(ctx, pop);
    });
  }

  private drawRow(ctx: CanvasRenderingContext2D, pop: Rect, index: number, label: string): void {
    const y = pop.y + index * this.rowH() - this.scroll_offset;
    if (this.hoveredOption() === index) {
      ctx.fillStyle = this.rect_config.option_hover_fill_style;
      ctx.strokeStyle = 'transparent';
      drawRect(ctx, { x: pop.x, y }, pop.w, this.rowH());
    }
    drawText(ctx, label, {
      ...this.rect_config.text_config,
      p: { x: pop.x + this.padding(), y: y + 0.5 * this.rowH() },
      w: pop.w - 2 * this.padding() - THUMB_W,
      align: 'left',
      baseline: 'middle',
    });
  }

  private drawThumb(ctx: CanvasRenderingContext2D, pop: Rect): void {
    const max_scroll = this.maxScroll();
    if (max_scroll === 0) {
      return;
    }
    const thumb_h = (pop.h * pop.h) / this.contentH();
    ctx.globalAlpha = 0.4;
    ctx.fillStyle = this.rect_config.text_config.fill_style;
    ctx.fillRect(
      pop.x + pop.w - THUMB_W - 1,
      pop.y + (this.scroll_offset / max_scroll) * (pop.h - thumb_h),
      THUMB_W,
      thumb_h
    );
    ctx.globalAlpha = 1;
  }
}

import type { BoardTransformData } from '../../canvas_board/canvas_board';
import type { Point2D } from '../../objects2d';
import type { CanvasComponent } from '../canvas_component';

const CARET_BLINK_MS = 530;

export declare interface InputConfig {
  value?: string;
  max_length?: number;
  allowed_chars?: RegExp;
  start_disabled?: boolean;
}

export abstract class DwgInput implements CanvasComponent {
  private hovering = false;
  private clicking = false;
  private focused = false;
  private disabled: boolean;
  private text: string;
  private caret: number;
  private caret_timer = 0;
  private config: InputConfig;

  constructor(config: InputConfig) {
    this.config = config;
    this.disabled = !!config.start_disabled;
    this.text = this.sanitize(config.value ?? '');
    this.caret = this.text.length;
  }

  value(): string {
    return this.text;
  }

  setValue(value: string) {
    this.text = this.sanitize(value);
    this.caret = this.text.length;
  }

  protected caretIndex(): number {
    return this.caret;
  }

  protected caretVisible(): boolean {
    return this.focused && this.caret_timer < CARET_BLINK_MS;
  }

  isFocused(): boolean {
    return this.focused;
  }

  focus() {
    if (this.focused || this.disabled) {
      return;
    }
    this.focused = true;
    this.caret_timer = 0;
    document.addEventListener('keydown', this.handleKeydown, true);
    document.addEventListener('paste', this.handlePaste, true);
  }

  blur() {
    if (!this.focused) {
      return;
    }
    this.focused = false;
    document.removeEventListener('keydown', this.handleKeydown, true);
    document.removeEventListener('paste', this.handlePaste, true);
  }

  isHovering() {
    return this.hovering;
  }

  setHovering(hovering: boolean) {
    this.hovering = hovering;
  }

  isClicking() {
    return this.clicking;
  }

  setClicking(clicking: boolean) {
    this.clicking = clicking;
  }

  isDisabled(): boolean {
    return this.disabled;
  }

  disable() {
    this.disabled = true;
    this.hovering = false;
    this.clicking = false;
    this.blur();
  }

  enable() {
    this.disabled = false;
  }

  draw(ctx: CanvasRenderingContext2D, transform: BoardTransformData, dt: number): void {
    this.caret_timer = (this.caret_timer + dt) % (2 * CARET_BLINK_MS);
    this._draw(ctx, transform, dt);
  }

  mousemove(canvas: Point2D, screen: Point2D, _transform: BoardTransformData): boolean {
    this.hovering = !this.disabled && this.mouseOver(canvas, screen);
    return this.hovering;
  }

  mousedown(e: MouseEvent): boolean {
    if (!this.disabled && e.button === 0 && this.hovering) {
      this.clicking = true;
      this.focus();
      this.moveCaret(this.text.length);
      return true;
    }
    this.blur();
    return false;
  }

  mouseup(_e: MouseEvent) {
    this.clicking = false;
  }

  private sanitize(s: string): string {
    const allowed = this.config.allowed_chars;
    const filtered = [...s].filter((c) => !allowed || allowed.test(c)).join('');
    return filtered.slice(0, this.config.max_length ?? filtered.length);
  }

  private insert(s: string) {
    const room = (this.config.max_length ?? Infinity) - this.text.length;
    const added = this.sanitize(s).slice(0, Math.max(0, room));
    if (!added) {
      return;
    }
    this.text = this.text.slice(0, this.caret) + added + this.text.slice(this.caret);
    this.moveCaret(this.caret + added.length);
    this.changed(this.text);
  }

  private removeAt(index: number) {
    if (index < 0 || index >= this.text.length) {
      return;
    }
    this.text = this.text.slice(0, index) + this.text.slice(index + 1);
    this.moveCaret(Math.min(this.caret, index));
    this.changed(this.text);
  }

  private moveCaret(index: number) {
    this.caret = Math.min(Math.max(index, 0), this.text.length);
    this.caret_timer = 0;
  }

  private applyKey(key: string): boolean {
    switch (key) {
      case 'Enter':
        this.submitted(this.text);
        this.blur();
        return true;
      case 'Escape':
        this.blur();
        return true;
      case 'Backspace':
        this.removeAt(this.caret - 1);
        return true;
      case 'Delete':
        this.removeAt(this.caret);
        return true;
      case 'ArrowLeft':
        this.moveCaret(this.caret - 1);
        return true;
      case 'ArrowRight':
        this.moveCaret(this.caret + 1);
        return true;
      case 'Home':
        this.moveCaret(0);
        return true;
      case 'End':
        this.moveCaret(this.text.length);
        return true;
      default:
        if (key.length !== 1) {
          return false;
        }
        this.insert(key);
        return true;
    }
  }

  private handleKeydown = (e: KeyboardEvent): void => {
    if (e.ctrlKey || e.metaKey || e.altKey || !this.applyKey(e.key)) {
      return;
    }
    e.preventDefault();
    e.stopImmediatePropagation();
  };

  private handlePaste = (e: ClipboardEvent): void => {
    this.insert(e.clipboardData?.getData('text') ?? '');
    e.preventDefault();
    e.stopImmediatePropagation();
  };

  protected abstract _draw(ctx: CanvasRenderingContext2D, transform: BoardTransformData, dt: number): void;
  abstract mouseOver(canvas: Point2D, screen: Point2D): boolean;

  protected abstract changed(value: string): void;
  protected abstract submitted(value: string): void;

  abstract xi(): number;
  abstract xf(): number;
  abstract yi(): number;
  abstract yf(): number;
  abstract w(): number;
  abstract h(): number;
}

import type { BoardTransformData } from '../../canvas_board/canvas_board';
import type { DrawTextConfig } from '../../canvas_util';
import { drawRect, drawText } from '../../canvas_util';
import type { Point2D } from '../../objects2d';
import type { DrawConfig } from '../canvas_component';
import { configDraw } from '../canvas_component';
import type { InputConfig } from './input';
import { DwgInput } from './input';
import type { WithRequired } from '../../../../../scripts/types';

type RectInputTextConfig = WithRequired<Omit<DrawTextConfig, 'p' | 'w' | 'align' | 'baseline'>, 'font' | 'fill_style'>;

export declare interface RectInputConfig {
  input_config: InputConfig;
  p: Point2D;
  w: number;
  h: number;
  draw_config: DrawConfig;
  text_config: RectInputTextConfig;
  placeholder?: string;
  placeholder_fill_style?: string;
  padding?: number;
  r?: number;
}

const DEFAULT_PADDING = 4;

export abstract class DwgRectInput extends DwgInput {
  private rect_config: RectInputConfig;

  constructor(config: RectInputConfig) {
    super(config.input_config);
    this.rect_config = config;
  }

  setPosition(p: Point2D) {
    this.rect_config.p = { ...p };
  }

  setSize(w: number, h: number) {
    this.rect_config.w = w;
    this.rect_config.h = h;
  }

  xi(): number {
    return this.rect_config.p.x;
  }
  yi(): number {
    return this.rect_config.p.y;
  }
  xf(): number {
    return this.rect_config.p.x + this.rect_config.w;
  }
  yf(): number {
    return this.rect_config.p.y + this.rect_config.h;
  }
  xc(): number {
    return this.xi() + 0.5 * this.rect_config.w;
  }
  yc(): number {
    return this.yi() + 0.5 * this.rect_config.h;
  }
  w(): number {
    return this.rect_config.w;
  }
  h(): number {
    return this.rect_config.h;
  }

  protected override _draw(ctx: CanvasRenderingContext2D, transform: BoardTransformData, _dt: number): void {
    const config = this.rect_config;
    configDraw(ctx, transform, config.draw_config, this.isHovering(), this.isFocused(), () => {
      drawRect(ctx, config.p, config.w, config.h, config.r);
      this.drawContent(ctx);
    });
  }

  private drawContent(ctx: CanvasRenderingContext2D): void {
    const config = this.rect_config;
    const padding = config.padding ?? DEFAULT_PADDING;
    const placeholder_shown = this.value() === '' && !this.isFocused();
    drawText(ctx, placeholder_shown ? (config.placeholder ?? '') : this.value(), {
      ...config.text_config,
      fill_style: placeholder_shown
        ? (config.placeholder_fill_style ?? config.text_config.fill_style)
        : config.text_config.fill_style,
      p: { x: this.xi() + padding, y: this.yc() },
      w: config.w - 2 * padding,
      align: 'left',
      baseline: 'middle',
    });
    if (this.caretVisible()) {
      const caret_x = this.xi() + padding + ctx.measureText(this.value().slice(0, this.caretIndex())).width;
      ctx.fillStyle = config.text_config.fill_style;
      ctx.fillRect(caret_x, this.yi() + padding, 1, config.h - 2 * padding);
    }
  }

  override mouseOver(canvas: Point2D, screen: Point2D): boolean {
    const m = this.rect_config.draw_config.fixed_position ? screen : canvas;
    return m.x >= this.xi() && m.x <= this.xf() && m.y >= this.yi() && m.y <= this.yf();
  }
}

import type { BoardTransformData } from '../../canvas_board/canvas_board';
import { drawRect, drawText } from '../../canvas_util';
import type { Point2D } from '../../objects2d';
import { subtractPoint2D } from '../../objects2d';
import { configDraw, xc, type CanvasComponent, type DrawConfig } from '../canvas_component';
import type { DwgRectScrollbar } from './rect_scrollbar';

/** Data describing a listbox config */
export declare interface ListboxConfig<T extends CanvasComponent, R extends DwgRectScrollbar = DwgRectScrollbar> {
  list: T[];
  scrollbar: R;
  draw_config: DrawConfig;
  gap?: number;
  padding?: number;
  title?: {
    text: string;
    size: number;
    font_color: string;
  };
}

export class DwgListbox<
  T extends CanvasComponent = CanvasComponent,
  R extends DwgRectScrollbar = DwgRectScrollbar,
> implements CanvasComponent {
  protected config: ListboxConfig<T, R>;
  // Index of the first list item shown
  private draw_start = 0;
  // Index of the last list item shown
  private draw_end = 0;
  // Time between scrollbar adjustments
  static SCROLLBAR_ADJUST_TIME = 100;
  private scrollbar_adjust_time = DwgListbox.SCROLLBAR_ADJUST_TIME;
  // Maintain a list of coordinates for mouse move events
  private list_coordinates: Point2D[] = [];
  private check_mousemove_on_next_draw = false;
  private disabled = false;

  constructor(config: ListboxConfig<T, R>) {
    config.scrollbar.setValue({ value: 0, value_min: 0, value_max: 0 });
    const scroll_callback = config.scrollbar.scrollCallback;
    config.scrollbar.scrollCallback = (value: number) => {
      if (scroll_callback) {
        scroll_callback(value);
      }
      this.check_mousemove_on_next_draw = true;
    };
    this.config = config;
    this.setList(config.list);
  }

  setList(list: T[]) {
    this.config.list = list;
    this.list_coordinates = [];
    for (const _ of this.config.list) {
      this.list_coordinates.push({
        x: 0,
        y: 0,
      });
    }
  }

  protected getList(): T[] {
    return this.config.list;
  }

  isHovering() {
    if (this.disabled) {
      return false;
    }
    return this.config.scrollbar.isHovering();
  }

  setHovering(hovering: boolean) {
    this.config.scrollbar.setHovering(hovering);
  }

  isClicking() {
    if (this.disabled) {
      return false;
    }
    return this.config.scrollbar.isClicking();
  }

  setClicking(clicking: boolean): void {
    this.config.scrollbar.setClicking(clicking);
    if (!clicking) {
      for (const item of this.config.list) {
        item.setClicking(false);
        item.setHovering(false);
      }
    }
  }

  setAllSizes(size: number, p: Point2D, w: number, h: number) {
    const title_size = this.config.title?.size ?? 0;
    this.config.scrollbar.setAllSizes(size, { x: p.x, y: p.y + title_size }, w, h - title_size);
  }

  getPadding(): number {
    return this.config.padding ?? 0;
  }

  getGap(): number {
    return this.config.gap ?? 0;
  }

  disable() {
    this.disabled = true;
    this.config.scrollbar.disable();
  }

  enable() {
    this.disabled = false;
    this.config.scrollbar.enable();
  }

  draw(ctx: CanvasRenderingContext2D, transform: BoardTransformData, dt: number): void {
    configDraw(ctx, transform, this.config.draw_config, this.isHovering(), this.isClicking(), () => {
      drawRect(ctx, { x: this.xi(), y: this.yi() }, this.w(), this.h());
      if (this.config.title) {
        drawRect(ctx, { x: this.xi(), y: this.yi() }, this.w(), this.config.title.size);
        drawText(ctx, this.config.title.text, {
          p: { x: xc(this), y: this.yi() + this.config.title.size - this.getPadding() },
          w: this.w() - 2 * this.getPadding(),
          font: `${this.config.title.size - 2 * this.getPadding()}px serif`,
          fill_style: this.config.title.font_color,
          align: 'center',
          baseline: 'ideographic',
        });
      }
      let [xi, yi, value, padding] = [
        this.xi(),
        this.config.scrollbar.yi(),
        this.config.scrollbar.value(),
        this.getPadding(),
      ];
      ctx.save();
      ctx.beginPath();
      ctx.rect(
        this.xi() + padding,
        this.config.scrollbar.yi() + padding,
        this.w() - padding * 2,
        this.config.scrollbar.h() - padding * 2
      );
      ctx.clip();
      yi += padding - value;
      ctx.translate(xi + padding, yi);
      let found_start = false;
      let found_end = false;
      const initial_yi = yi;
      for (const [i, el] of this.config.list.entries()) {
        let draw_el = true;
        if (!found_start) {
          if (yi + el.h() >= this.config.scrollbar.yi() + padding) {
            this.draw_start = i;
            found_start = true;
          } else {
            draw_el = false;
          }
        } else if (!found_end) {
          if (yi + el.h() >= this.config.scrollbar.yf() - padding) {
            this.draw_end = i;
            found_end = true;
          }
        } else {
          draw_el = false;
        }
        if (draw_el) {
          el.draw(ctx, transform, dt);
          this.list_coordinates[i] = { x: xi + padding, y: yi };
        }
        const yi_adjust = el.h() + (i + 1 < this.config.list.length ? this.getGap() : 0);
        yi += yi_adjust;
        ctx.translate(0, yi_adjust);
      }
      if (!found_end) {
        this.draw_end = this.config.list.length - 1;
      }
      ctx.translate(-xi - padding, -yi);
      ctx.restore();
      this.scrollbar_adjust_time -= dt;
      if (this.scrollbar_adjust_time < 0) {
        this.scrollbar_adjust_time = DwgListbox.SCROLLBAR_ADJUST_TIME;
        this.config.scrollbar.setValue({
          value,
          value_min: 0,
          value_max: yi >= this.yf() - padding ? yi - initial_yi - this.config.scrollbar.h() + 2 * padding : 0,
        });
      }
    });
    this.config.scrollbar.draw(ctx, transform, dt);
    if (this.check_mousemove_on_next_draw) {
      const last_canvas = this.config.scrollbar.getLastMousemoveCanvas();
      const last_screen = this.config.scrollbar.getLastMousemoveScreen();
      const last_transform = this.config.scrollbar.getLastMousemoveTransform();
      if (!!last_canvas && !!last_screen && !!last_transform) {
        this.mousemove(last_canvas, last_screen, last_transform);
      }
    }
    if (this.disabled) {
      configDraw(
        ctx,
        transform,
        {
          ...this.config.draw_config,
          fill_style: 'rgba(255, 255, 255, 0.4)',
        },
        false,
        false,
        () => {
          drawRect(ctx, { x: this.xi(), y: this.yi() }, this.w(), this.h());
        }
      );
    }
  }

  scroll(dy: number, mode: number, _dx?: number): boolean {
    return this.config.scrollbar.scroll(dy, mode, _dx);
  }

  mousemove(canvas: Point2D, screen: Point2D, transform: BoardTransformData): boolean {
    this.config.scrollbar.mousemove(canvas, screen, transform);
    const is_hovering = this.isHovering();
    const point = this.config.draw_config.fixed_position ? screen : canvas;
    for (const [i, el] of this.config.list.entries()) {
      if (this.disabled || !is_hovering || i < this.draw_start || i > this.draw_end) {
        el.setHovering(false);
      } else {
        const local = subtractPoint2D(point, this.list_coordinates[i]);
        el.mousemove(local, local, transform);
      }
    }
    return is_hovering;
  }

  mousedown(e: MouseEvent): boolean {
    this.config.scrollbar.mousedown(e);
    for (const [i, el] of this.config.list.entries()) {
      if (this.disabled || i < this.draw_start || i > this.draw_end) {
        continue;
      } else {
        el.mousedown(e);
      }
    }
    return this.isClicking();
  }

  mouseup(e: MouseEvent): void {
    for (const [i, el] of this.config.list.entries()) {
      if (this.disabled || i < this.draw_start || i > this.draw_end) {
        el.setClicking(false);
      } else {
        el.mouseup(e);
      }
    }
    this.config.scrollbar.mouseup(e);
  }

  mouseOver(canvas: Point2D, screen: Point2D): boolean {
    return this.config.scrollbar.mouseOver(canvas, screen);
  }

  xi(): number {
    return this.config.scrollbar.xi();
  }

  xf(): number {
    return this.config.scrollbar.xf();
  }

  yi(): number {
    const yi = this.config.scrollbar.yi();
    if (this.config.title) {
      return yi - this.config.title.size;
    }
    return yi;
  }

  yf(): number {
    return this.config.scrollbar.yf();
  }

  w(): number {
    return this.config.scrollbar.w();
  }

  h(): number {
    const h = this.config.scrollbar.h();
    if (this.config.title) {
      return h + this.config.title.size;
    }
    return h;
  }
}

import type { PartialBy } from '../../../../../scripts/types';
import type { BoardTransformData } from '../../canvas_board/canvas_board';
import { drawRect } from '../../canvas_util';
import type { Point2D } from '../../objects2d';
import type { RectButtonConfig } from '../button/rect_button';
import { DwgRectButton } from '../button/rect_button';
import { configDraw, type DrawConfig } from '../canvas_component';
import type { ScrollbarConfig } from './scrollbar';
import { DwgScrollbar } from './scrollbar';

abstract class DwgRectScrollbarButton extends DwgRectButton {
  protected scrollbar: DwgRectScrollbar;

  constructor(scrollbar: DwgRectScrollbar, config: RectButtonConfig) {
    super(config);
    this.scrollbar = scrollbar;
  }

  updateHovering(canvas: Point2D, screen: Point2D) {
    this.setHovering(this.mouseOver(canvas, screen));
  }

  protected hovered(): void {}
  protected unhovered(): void {}
  protected released(): void {}
}

interface RectScrollbarArrowButtonConfig {
  increase: boolean;
  /** scroll amount per click; defaults to 1 */
  amount?: number;
  rect_button_config: PartialBy<RectButtonConfig, 'button_config'>;
}

class DwgRectScrollbarArrowButton extends DwgRectScrollbarButton {
  private scrollbar_arrow_config: RectScrollbarArrowButtonConfig;
  private scroll_amount = 1;

  constructor(scrollbar: DwgRectScrollbar, config: RectScrollbarArrowButtonConfig) {
    super(scrollbar, {
      button_config: {
        hold_config: {
          hold_click_delay: 600,
          hold_click_time: 20,
          hold_click_hover: false,
        },
        allow_nonleft_clicks: false,
      },
      ...config.rect_button_config,
    });
    if (config.amount) {
      this.scroll_amount = Math.abs(config.amount);
    }
    if (!config.increase) {
      this.scroll_amount = -1 * this.scroll_amount;
    }
    this.scrollbar_arrow_config = config;
  }

  protected clicked(): void {
    this.scrollbar._scroll(this.scroll_amount);
  }
}

class DwgRectScrollbarSpaceButton extends DwgRectScrollbarButton {
  private scrollbar_arrow_config: RectScrollbarArrowButtonConfig;
  private scroll_amount = 10;

  constructor(scrollbar: DwgRectScrollbar, config: RectScrollbarArrowButtonConfig) {
    super(scrollbar, {
      button_config: {
        hold_config: {
          hold_click_delay: 600,
          hold_click_time: 50,
          hold_click_hover: true,
        },
        allow_nonleft_clicks: false,
      },
      ...config.rect_button_config,
    });
    if (config.amount) {
      this.scroll_amount = Math.abs(config.amount);
    }
    if (!config.increase) {
      this.scroll_amount = -1 * this.scroll_amount;
    }
    this.scrollbar_arrow_config = config;
  }

  protected clicked(): void {
    this.scrollbar._scroll(this.scroll_amount);
  }
}

interface RectScrollbarBarButtonConfig {
  /** minimum size of the bar button */
  min_bar_size: number;
  /** bar dif size per value of scrolling that is possible */
  bar_dif_size: number;
  rect_button_config: PartialBy<RectButtonConfig, 'button_config'>;
}

class DwgRectScrollbarBarButton extends DwgRectScrollbarButton {
  private scrollbar_bar_config: RectScrollbarBarButtonConfig;
  private click_m = 0;
  private click_v = 0;

  constructor(scrollbar: DwgRectScrollbar, config: RectScrollbarBarButtonConfig) {
    super(scrollbar, {
      button_config: {
        allow_nonleft_clicks: false,
      },
      ...config.rect_button_config,
    });
    this.scrollbar_bar_config = config;
  }

  override mousemove(canvas: Point2D, screen: Point2D, transform: BoardTransformData): boolean {
    super.mousemove(canvas, screen, transform);
    const m = this.scrollbar.isFixedPosition() ? screen : canvas;
    if (this.isClicking() && this.click_m && this.scrollbar.getBarDifSize()) {
      const mp = this.scrollbar.isVertical() ? m.y : m.x;
      this.scrollbar.scrollTo(this.click_v + (mp - this.click_m) / this.scrollbar.getBarDifSize());
    } else {
      this.click_m = this.scrollbar.isVertical() ? m.y : m.x;
      this.click_v = this.scrollbar.value();
    }
    return this.isHovering();
  }

  protected clicked(): void {}
}

/** Config data for a rect scrollbar */
export declare interface RectScrollbarConfig {
  scrollbar_config: ScrollbarConfig;
  // Top left point of the scrollbar area
  p: Point2D;
  // width of the scrollbar area
  w: number;
  // height of the scrollbar area
  h: number;
  // width (or height for a horizontal scrollbar) of the actual scrollbar
  scrollbar_size: number;
  vertical: boolean;
  draw_config: DrawConfig;
  space_draw_config: DrawConfig;
  background_color: string;
  min_bar_size?: number;
  bar_dif_size?: number;
  // Amount the arrow buttons should scroll per click event
  arrow_scroll_amount?: number;
  // Amount the space buttons should scroll per click event
  space_scroll_amount?: number;
}

export abstract class DwgRectScrollbar extends DwgScrollbar<DwgRectScrollbarButton> {
  private rect_config: RectScrollbarConfig;
  private background_config: DrawConfig;
  private scrollbar_p: Point2D = { x: 0, y: 0 };
  private scrollbar_w = 0;
  private scrollbar_h = 0;
  private max_bar_dif_size = 10;
  private bar_dif_size = 0;
  private bar_button: DwgRectScrollbarBarButton;

  constructor(config: RectScrollbarConfig) {
    super(config.scrollbar_config);
    this.rect_config = config;
    this.max_bar_dif_size = config.bar_dif_size ?? this.max_bar_dif_size;
    this.background_config = {
      fill_style: config.background_color,
      stroke_style: 'transparent',
      stroke_width: 0,
      hover_fill_style: config.background_color,
      click_fill_style: config.background_color,
      fixed_position: config.draw_config.fixed_position,
    };
    const arrow_button_config = {
      p: { x: 0, y: 0 },
      w: 0,
      h: 0,
      draw_config: config.draw_config,
    };
    this.addButton(
      new DwgRectScrollbarArrowButton(this, {
        increase: false,
        amount: config.arrow_scroll_amount,
        rect_button_config: {
          ...arrow_button_config,
        },
      })
    );
    this.addButton(
      new DwgRectScrollbarArrowButton(this, {
        increase: true,
        amount: config.arrow_scroll_amount,
        rect_button_config: {
          ...arrow_button_config,
        },
      })
    );
    this.bar_button = new DwgRectScrollbarBarButton(this, {
      min_bar_size: this.getMinBarSize(),
      bar_dif_size: this.bar_dif_size,
      rect_button_config: {
        ...arrow_button_config,
      },
    });
    this.addButton(this.bar_button);
    this.addButton(
      new DwgRectScrollbarSpaceButton(this, {
        increase: false,
        amount: config.space_scroll_amount,
        rect_button_config: {
          ...arrow_button_config,
          draw_config: config.space_draw_config,
        },
      })
    );
    this.addButton(
      new DwgRectScrollbarSpaceButton(this, {
        increase: true,
        amount: config.space_scroll_amount,
        rect_button_config: {
          ...arrow_button_config,
          draw_config: config.space_draw_config,
        },
      })
    );
    this.updateButtonPositions();
  }

  private getMinBarSize(): number {
    return this.rect_config.min_bar_size ?? 0.5 * this.rect_config.scrollbar_size;
  }

  getBarDifSize(): number {
    return this.bar_dif_size;
  }

  protected updateButtonPositions() {
    const size = this.rect_config.scrollbar_size;
    const vertical = this.rect_config.vertical;
    const p: Point2D = {
      x: vertical ? this.xf() - size : this.xi(),
      y: vertical ? this.yi() : this.yf() - size,
    };
    this.buttons[0].setPosition({ ...p });
    this.buttons[0].setSize(size, size);
    this.buttons[1].setPosition({
      x: this.xf() - size,
      y: this.yf() - size,
    });
    this.buttons[1].setSize(size, size);
    this.scrollbar_p = p;
    this.scrollbar_w = vertical ? size : this.w();
    this.scrollbar_h = vertical ? this.h() : size;
    const total_bar_area_size = (vertical ? this.h() : this.w()) - 2 * this.rect_config.scrollbar_size;
    const total_steps = this.totalSteps();
    const bar_size = Math.max(total_bar_area_size - this.max_bar_dif_size * total_steps, this.getMinBarSize());
    if (total_bar_area_size <= 0 || bar_size <= 0) {
      this.bar_dif_size = 0;
      this.buttons[2].setSize(0, 0);
      this.buttons[3].setSize(0, 0);
      this.buttons[4].setSize(0, 0);
      return;
    }
    this.bar_dif_size = total_steps < 1 ? 0 : (total_bar_area_size - bar_size) / total_steps;
    const bar_area_offset = this.step() * this.bar_dif_size;
    const bar_offset = this.rect_config.scrollbar_size + bar_area_offset;
    this.buttons[2].setPosition({
      x: p.x + (vertical ? 0 : bar_offset),
      y: p.y + (vertical ? bar_offset : 0),
    });
    this.buttons[2].setSize(vertical ? this.scrollbar_w : bar_size, vertical ? bar_size : this.scrollbar_h);
    this.buttons[3].setPosition({
      x: p.x + (vertical ? 0 : this.rect_config.scrollbar_size),
      y: p.y + (vertical ? this.rect_config.scrollbar_size : 0),
    });
    this.buttons[3].setSize(
      vertical ? this.scrollbar_w : bar_area_offset,
      vertical ? bar_area_offset : this.scrollbar_h
    );
    this.buttons[4].setPosition({
      x: p.x + (vertical ? 0 : bar_offset + bar_size),
      y: p.y + (vertical ? bar_offset + bar_size : 0),
    });
    this.buttons[4].setSize(
      vertical ? this.scrollbar_w : total_bar_area_size - bar_area_offset - bar_size,
      vertical ? total_bar_area_size - bar_area_offset - bar_size : this.scrollbar_h
    );
  }

  protected override setScroll(v: number): void {
    super.setScroll(v);
    this.updateButtonPositions();
    if (!this.last_mousemove_canvas || !this.last_mousemove_screen) {
      return;
    }
    this.buttons[2].updateHovering(this.last_mousemove_canvas, this.last_mousemove_screen);
    this.buttons[3].updateHovering(this.last_mousemove_canvas, this.last_mousemove_screen);
    this.buttons[4].updateHovering(this.last_mousemove_canvas, this.last_mousemove_screen);
  }

  isFixedPosition(): boolean {
    return this.rect_config.draw_config.fixed_position ?? false;
  }

  isVertical(): boolean {
    return this.rect_config.vertical;
  }

  setScrollbarSize(size: number) {
    this.rect_config.scrollbar_size = size;
    this.updateButtonPositions();
  }

  getScrollbarSize(): number {
    return this.rect_config.scrollbar_size;
  }

  setPosition(p: Point2D) {
    this.rect_config.p = { ...p };
    this.updateButtonPositions();
  }

  setW(w: number) {
    this.rect_config.w = w;
    this.updateButtonPositions();
  }

  setH(h: number) {
    this.rect_config.h = h;
    this.updateButtonPositions();
  }

  setSize(w: number, h: number) {
    this.rect_config.w = w;
    this.rect_config.h = h;
    this.updateButtonPositions();
  }

  setAllSizes(size: number, p: Point2D, w: number, h: number) {
    this.rect_config.scrollbar_size = size;
    this.rect_config.p = { ...p };
    this.rect_config.w = w;
    this.rect_config.h = h;
    this.updateButtonPositions();
  }

  override draw(ctx: CanvasRenderingContext2D, transform: BoardTransformData, dt: number): void {
    configDraw(ctx, transform, this.background_config, false, false, () => {
      drawRect(ctx, { ...this.scrollbar_p }, this.scrollbar_w, this.scrollbar_h);
    });
    super.draw(ctx, transform, dt);
  }

  mouseOver(canvas: Point2D, screen: Point2D): boolean {
    const m = this.rect_config.draw_config.fixed_position ? screen : canvas;
    if (m.x < this.xi() || m.y < this.yi() || m.x > this.xf() || m.y > this.yf()) {
      return false;
    }
    return true;
  }

  xi(): number {
    return this.rect_config.p.x;
  }
  xf(): number {
    return this.rect_config.p.x + this.rect_config.w;
  }
  yi(): number {
    return this.rect_config.p.y;
  }
  yf(): number {
    return this.rect_config.p.y + this.rect_config.h;
  }
  w(): number {
    return this.rect_config.w;
  }
  h(): number {
    return this.rect_config.h;
  }
}

import type { BoundedNumber } from '../../../../../scripts/math';
import { setBoundedNumber, validateBoundedNumber } from '../../../../../scripts/math';
import type { BoardTransformData } from '../../canvas_board/canvas_board';
import type { Point2D } from '../../objects2d';
import type { DwgButton } from '../button/button';
import type { CanvasComponent } from '../canvas_component';

/** Data describing a scrollbar config */
export declare interface ScrollbarConfig {
  value: BoundedNumber;
  step_size: number;
  // will divide the scroll by this in pixel mode
  scroll_pixel_constant?: number;
  // how many lines a 'page' is for a page scroll event
  scroll_pages?: number;
}

export abstract class DwgScrollbar<T extends DwgButton = DwgButton> implements CanvasComponent {
  private config!: ScrollbarConfig;
  protected buttons: T[] = [];
  private hovering = false;
  private clicking = false;
  protected last_mousemove_canvas?: Point2D;
  protected last_mousemove_screen?: Point2D;
  protected last_mousemove_transform?: BoardTransformData;
  private scroll_pixel_constant = 80;
  private scroll_pages = 20;

  constructor(config: ScrollbarConfig) {
    this.setConfig(config);
  }

  protected addButton(button: T) {
    this.buttons.push(button);
  }

  setConfig(config: ScrollbarConfig) {
    config.value = validateBoundedNumber(config.value);
    if (config.step_size === 0) {
      config.step_size = 1;
    }
    config.step_size = Math.min(config.step_size, config.value.value_max - config.value.value_min);
    if (config.step_size < 0) {
      config.step_size = -1 * config.step_size;
    }
    if (config.scroll_pixel_constant && config.scroll_pixel_constant > 0) {
      this.scroll_pixel_constant = config.scroll_pixel_constant;
    }
    if (config.scroll_pages && config.scroll_pages > 0) {
      this.scroll_pages = config.scroll_pages;
    }
    this.config = config;
  }

  value(): number {
    return this.config.value.value;
  }

  minValue(): number {
    return this.config.value.value_min;
  }

  maxValue(): number {
    return this.config.value.value_max;
  }

  setValue(value: BoundedNumber) {
    this.config.value = value;
    this.setConfig(this.config);
    this.updateButtonPositions();
  }

  // returns how many steps the scrollbar can be scrolled
  totalSteps(): number {
    if (!this.config.step_size) {
      return 0;
    }
    const value_dif = this.maxValue() - this.minValue();
    return value_dif / this.config.step_size;
  }

  step(): number {
    if (!this.config.step_size) {
      return 0;
    }
    return (this.value() - this.minValue()) / this.config.step_size;
  }

  /** Returns the actual dif from this operation */
  _scroll(dif: number): number {
    const prev = this.value();
    this.setScroll(prev + dif);
    return this.value() - prev;
  }

  // Returns the dif that was scrolled
  scrollTo(value: number): number {
    const prev = this.value();
    this.setScroll(value);
    return this.value() - prev;
  }

  protected setScroll(v: number) {
    setBoundedNumber(this.config.value, v);
    this.scrollCallback(this.config.value.value);
  }

  isHovering() {
    return this.hovering;
  }

  setHovering(hovering: boolean) {
    this.hovering = hovering;
  }

  isClicking() {
    return this.clicking;
  }

  setClicking(clicking: boolean): void {
    this.clicking = clicking;
    if (!clicking) {
      for (const button of this.buttons) {
        button.setClicking(false);
        button.setHovering(false);
      }
    }
  }

  getLastMousemoveCanvas(): Point2D | undefined {
    return this.last_mousemove_canvas;
  }

  getLastMousemoveScreen(): Point2D | undefined {
    return this.last_mousemove_screen;
  }

  getLastMousemoveTransform(): BoardTransformData | undefined {
    return this.last_mousemove_transform;
  }

  disable() {
    for (const button of this.buttons) {
      button.disable();
    }
  }

  enable() {
    for (const button of this.buttons) {
      button.enable();
    }
  }

  draw(ctx: CanvasRenderingContext2D, transform: BoardTransformData, dt: number) {
    for (const button of this.buttons) {
      button.draw(ctx, transform, dt);
    }
  }

  scroll(dy: number, mode: number, _dx?: number): boolean {
    if (this.hovering) {
      if (mode === 0) {
        this._scroll((dy * this.config.step_size) / this.scroll_pixel_constant);
      } else if (mode === 1) {
        this._scroll(dy);
      } else if (mode === 2) {
        this._scroll(dy * this.scroll_pages);
      } else {
        console.error('Unknown scroll mode', mode);
        return false;
      }
      return true;
    }
    return false;
  }

  mousemove(canvas: Point2D, screen: Point2D, transform: BoardTransformData): boolean {
    this.last_mousemove_canvas = canvas;
    this.last_mousemove_screen = screen;
    this.last_mousemove_transform = transform;
    const button_hovering: boolean[] = [];
    for (const button of this.buttons) {
      button_hovering.push(button.mousemove(canvas, screen, transform));
    }
    this.hovering = button_hovering.some((v) => !!v) || this.mouseOver(canvas, screen);
    return this.hovering;
  }

  mousedown(e: MouseEvent): boolean {
    const button_clicking: boolean[] = [];
    for (const button of this.buttons) {
      button_clicking.push(button.mousedown(e));
    }
    this.clicking = button_clicking.some((v) => !!v);
    return this.clicking;
  }

  mouseup(e: MouseEvent): void {
    for (const button of this.buttons) {
      button.mouseup(e);
    }
  }

  protected abstract updateButtonPositions(): void;
  abstract mouseOver(canvas: Point2D, screen: Point2D): boolean;
  abstract scrollCallback(value: number): void;
  abstract xi(): number;
  abstract xf(): number;
  abstract yi(): number;
  abstract yf(): number;
  abstract w(): number;
  abstract h(): number;
}

import type { BoardTransformData } from '../canvas_board/canvas_board';
import { drawRect, drawText } from '../canvas_util';
import type { Point2D } from '../objects2d';
import { configDraw } from './canvas_component';

export interface CanvasSize {
  width: number;
  height: number;
}

export type TooltipDraw<T> = (
  ctx: CanvasRenderingContext2D,
  transform: BoardTransformData,
  canvas_size: CanvasSize,
  p: Point2D,
  data: T
) => void;

export interface TooltipConfig<T> {
  delay_ms: number;
  draw: TooltipDraw<T>;
}

export const DEFAULT_TOOLTIP_CONFIG: TooltipConfig<string> = {
  delay_ms: 250,
  draw: defaultTooltipDraw,
};

const MAX_TOOLTIP_TEXT_WIDTH = 220;

export function wrapText(ctx: CanvasRenderingContext2D, text: string, max_width: number): string[] {
  const words = text.split(' ');
  const lines: string[] = [];
  let current = '';
  for (const word of words) {
    const attempt = current ? `${current} ${word}` : word;
    if (current && ctx.measureText(attempt).width > max_width) {
      lines.push(current);
      current = word;
    } else {
      current = attempt;
    }
  }
  if (current) {
    lines.push(current);
  }
  return lines;
}

const TOOLTIP_GAP = 2;

// anchors the box on whichever side of p has more room on both axes, then clamps it fully on screen
export function anchorTooltipBox(p: Point2D, w: number, h: number, canvas_size: CanvasSize): Point2D {
  const x = p.x > canvas_size.width / 2 ? p.x - w : p.x;
  const y = p.y > canvas_size.height / 2 ? p.y - TOOLTIP_GAP - h : p.y + TOOLTIP_GAP;
  return {
    x: Math.max(0, Math.min(x, canvas_size.width - w)),
    y: Math.max(0, Math.min(y, canvas_size.height - h)),
  };
}

export function defaultTooltipDraw(
  ctx: CanvasRenderingContext2D,
  transform: BoardTransformData,
  canvas_size: CanvasSize,
  p: Point2D,
  text: string
) {
  const padding = 4;
  const row_height = 16;
  configDraw(ctx, transform, { fill_style: 'transparent', stroke_width: 0, fixed_position: true }, false, false, () => {
    ctx.font = '12px serif';
    const lines = wrapText(ctx, text, MAX_TOOLTIP_TEXT_WIDTH);
    const w =
      Math.min(MAX_TOOLTIP_TEXT_WIDTH, Math.max(...lines.map((line) => ctx.measureText(line).width))) + 2 * padding;
    const h = lines.length * row_height + 2 * padding;
    const box_p = anchorTooltipBox(p, w, h, canvas_size);
    ctx.fillStyle = 'rgba(0, 0, 0, 0.85)';
    ctx.strokeStyle = 'rgba(250, 250, 250, 0.9)';
    ctx.lineWidth = 1;
    drawRect(ctx, box_p, w, h, 3);
    lines.forEach((line, i) => {
      drawText(ctx, line, {
        p: { x: box_p.x + padding, y: box_p.y + padding + (i + 0.5) * row_height },
        w: w - 2 * padding,
        fill_style: 'white',
        align: 'left',
        baseline: 'middle',
        font: '12px serif',
      });
    });
  });
}

export interface TooltipState<T = string> {
  hover_ms: number;
  config: TooltipConfig<T>;
}

export function createTooltipState<T = string>(config?: Partial<TooltipConfig<T>>): TooltipState<T> {
  return { hover_ms: 0, config: { ...(DEFAULT_TOOLTIP_CONFIG as unknown as TooltipConfig<T>), ...config } };
}

// Once any tooltip has shown, hovering a new target within this window skips its own delay
const GLOBAL_TOOLTIP_COOLDOWN_MS = 100;
let last_tooltip_shown_at = -Infinity;

export function shouldShowTooltip(
  state: { hover_ms: number; config: { delay_ms: number } },
  hovering: boolean,
  clicked: boolean,
  dt: number
): boolean {
  if (!hovering) {
    state.hover_ms = 0;
    return false;
  }
  const was_showing = state.hover_ms >= state.config.delay_ms;
  const now = performance.now();
  if (state.hover_ms === 0 && !clicked && now - last_tooltip_shown_at <= GLOBAL_TOOLTIP_COOLDOWN_MS) {
    state.hover_ms = state.config.delay_ms;
  }
  state.hover_ms = clicked ? state.config.delay_ms : state.hover_ms + dt;
  const show = state.hover_ms >= state.config.delay_ms;
  if (show && !was_showing) {
    last_tooltip_shown_at = now;
  }
  return show;
}

let queued_tooltip_draws: Array<() => void> = [];

export function queueTooltipDraw(draw: () => void) {
  queued_tooltip_draws.push(draw);
}

export function flushTooltipQueue() {
  const draws = queued_tooltip_draws;
  queued_tooltip_draws = [];
  for (const draw of draws) {
    draw();
  }
}

let cursor_screen: Point2D = { x: 0, y: 0 };

export function setTooltipCursor(p: Point2D) {
  cursor_screen = p;
}

export function drawTooltip<T>(
  state: TooltipState<T>,
  ctx: CanvasRenderingContext2D,
  transform: BoardTransformData,
  canvas_size: CanvasSize,
  data: T
) {
  queueTooltipDraw(() => state.config.draw(ctx, transform, canvas_size, cursor_screen, data));
}

import type { Point2D } from './objects2d';

/** Draws a hexagon on the canvas */
export function drawHexagon(ctx: CanvasRenderingContext2D, c: Point2D, r: number, o = Math.PI / 6) {
  drawNgon(ctx, 6, c, r, o);
}

/** Draws a circle on the canvas */
export function drawCircle(ctx: CanvasRenderingContext2D, c: Point2D, r: number) {
  ctx.beginPath();
  ctx.ellipse(c.x, c.y, r, r, 0, 0, 2 * Math.PI);
  ctx.closePath();
  ctx.fill();
  ctx.stroke();
}

/** Draws a ellipse on the canvas */
export function drawEllipse(ctx: CanvasRenderingContext2D, c: Point2D, r: Point2D) {
  ctx.beginPath();
  ctx.ellipse(c.x, c.y, r.x, r.y, 0, 0, 2 * Math.PI);
  ctx.closePath();
  ctx.fill();
  ctx.stroke();
}

/** Draws a rectangle on the canvas */
export function drawRect(ctx: CanvasRenderingContext2D, pi: Point2D, w: number, h: number, r = 0) {
  ctx.beginPath();
  ctx.roundRect(pi.x, pi.y, w, h, r);
  ctx.closePath();
  ctx.fill();
  ctx.stroke();
}

/** Draws a regular n-gon on the canvas */
export function drawNgon(ctx: CanvasRenderingContext2D, n: number, c: Point2D, r: number, o = 0) {
  if (n < 3) {
    console.error('n must be 3+');
  }
  const a = (2 * Math.PI) / n;
  ctx.beginPath();
  for (let i = 0; i < n; i++) {
    ctx.lineTo(c.x + r * Math.cos(a * i + o), c.y + r * Math.sin(a * i + o));
  }
  ctx.closePath();
  ctx.fill();
  ctx.stroke();
}

/** Draws a line */
export function drawLine(ctx: CanvasRenderingContext2D, pi: Point2D, pf: Point2D) {
  ctx.beginPath();
  ctx.lineTo(pi.x, pi.y);
  ctx.lineTo(pf.x, pf.y);
  ctx.stroke();
}

export function drawArrow(ctx: CanvasRenderingContext2D, pi: Point2D, pf: Point2D, head_size: number) {
  const angle = Math.atan2(pf.y - pi.y, pf.x - pi.x);
  const base = { x: pf.x - head_size * Math.cos(angle), y: pf.y - head_size * Math.sin(angle) };
  drawLine(ctx, pi, base);
  ctx.beginPath();
  ctx.moveTo(pf.x, pf.y);
  ctx.lineTo(pf.x - head_size * Math.cos(angle - Math.PI / 6), pf.y - head_size * Math.sin(angle - Math.PI / 6));
  ctx.lineTo(pf.x - head_size * Math.cos(angle + Math.PI / 6), pf.y - head_size * Math.sin(angle + Math.PI / 6));
  ctx.closePath();
  ctx.fill();
}

/** Config data for drawing text */
export declare interface DrawTextConfig {
  p: Point2D;
  w: number;
  fill_style?: string;
  stroke_style?: string;
  stroke_width?: number;
  font?: string;
  min_font_size?: number;
  align?: CanvasTextAlign;
  baseline?: CanvasTextBaseline;
  direction?: CanvasDirection;
}

/** Draws text from config */
export function drawText(ctx: CanvasRenderingContext2D, s: string, config: DrawTextConfig) {
  ctx.beginPath();
  if (!!config.font) {
    ctx.font = getFittedFont(ctx, s, config.font, config.w, config.min_font_size ?? 8);
  }
  ctx.textAlign = config.align ?? 'left';
  ctx.textBaseline = config.baseline ?? 'top';
  ctx.direction = config.direction ?? 'ltr';
  if (!!config.stroke_style && !!config.stroke_width) {
    ctx.strokeStyle = config.stroke_style;
    ctx.lineWidth = config.stroke_width;
    ctx.strokeText(s, config.p.x, config.p.y, config.w);
  }
  if (!!config.fill_style) {
    ctx.fillStyle = config.fill_style;
    ctx.fillText(s, config.p.x, config.p.y, config.w);
  }
}

/** Returns the font with a lower font size if necessary based on max width */
export function getFittedFont(
  ctx: CanvasRenderingContext2D,
  text: string,
  font: string,
  max_width: number,
  min_size: number
): string {
  const match = font.match(/^(.*?)(\d*\.?\d+)px(.*)$/);
  if (!match || match.length < 4) {
    return font;
  }
  const prefix = match[1];
  const font_size = parseFloat(match[2]);
  const suffix = match[3];
  if (!font_size || font_size < 1) {
    return font;
  }
  ctx.font = `${prefix}1px${suffix}`;
  const one_px_width = ctx.measureText(text).width;
  const max_size = Math.floor(max_width / one_px_width);
  const final_size = Math.max(Math.min(font_size, max_size), min_size);
  return `${prefix}${final_size.toFixed(0)}px${suffix}`;
}

import { DwgElement } from '../../../dwg_element';
import type { StandardCard } from '../card_util';
import { cardToIcon, cardToImagePath, sortStandardCards } from '../card_util';
import { createLock, until } from '../../../../scripts/util';
import type { Point2D } from '../objects2d';
import { MultiMap } from '../../../../scripts/multi_map';

import html from './card_hand.html';

import './card_hand.scss';

interface CardData {
  card: StandardCard;
  i: number; // actual card index in hand
  i_dom: number; // displayed card index
  el?: HTMLDivElement;
}

interface CardDraggingData {
  dragging: boolean;
  index: number;
  touch_identifier: number;
  start: Point2D;
  start_rect: DOMRect;
  hovering_play_drop: boolean;
}

export class DwgCardHand extends DwgElement {
  private cards_container!: HTMLDivElement;
  private play_drop!: HTMLDivElement;
  private cancel_drop!: HTMLDivElement;

  can_play = false; // flag to specify whether a card can be played
  private cards = new MultiMap<number, CardData>(['i', 'i_dom']);
  private dragging_data: CardDraggingData = {
    dragging: false,
    index: -1,
    touch_identifier: -1,
    start: { x: 0, y: 0 },
    start_rect: new DOMRect(0, 0, 0, 0),
    hovering_play_drop: false,
  };

  private dragging_lock = createLock();

  private resize_observer = new ResizeObserver(() => this.resizeCallback());

  // bound so they can be removed again in disconnectedCallback
  private on_mouse_up = this.handleMouseUp.bind(this);
  private on_touch_end = this.handleTouchEnd.bind(this);
  private on_mouse_move = this.handleMouseMove.bind(this);
  private on_document_mouse_enter = this.handleDocumentMouseEnter.bind(this);
  private on_touch_move = this.handleTouchMove.bind(this);

  constructor() {
    super();
    this.classList.add('hidden');
    this.html_string = html;
    this.configureElements('cards_container', 'play_drop', 'cancel_drop');
  }

  protected override async parsedCallback(): Promise<void> {
    await until(() => !!this.clientHeight);
    this.resizeCallback();
    this.setEventListeners();
    this.resize_observer.observe(this);
    this.classList.remove('hidden');
  }

  override disconnectedCallback(): void {
    super.disconnectedCallback();
    this.resize_observer.disconnect();
    document.body.removeEventListener('mouseup', this.on_mouse_up);
    document.body.removeEventListener('touchend', this.on_touch_end);
    document.body.removeEventListener('mousemove', this.on_mouse_move);
    document.documentElement.removeEventListener('mouseenter', this.on_document_mouse_enter);
    document.body.removeEventListener('touchmove', this.on_touch_move);
  }

  private resizeCallback() {
    const rect = this.getBoundingClientRect();
    this.style.setProperty('--height', `${rect.height.toString()}px`);
    this.style.setProperty('--width', `${rect.width.toString()}px`);
    const play_drop_margin = 0.4 * rect.height;
    this.style.setProperty('--play-drop-margin', `${play_drop_margin.toString()}px`);
  }

  private setEventListeners() {
    document.body.addEventListener('mouseup', this.on_mouse_up);
    document.body.addEventListener('touchend', this.on_touch_end);
    document.body.addEventListener('mousemove', this.on_mouse_move);
    document.documentElement.addEventListener('mouseenter', this.on_document_mouse_enter);
    document.body.addEventListener('touchmove', this.on_touch_move);
  }

  private handleMouseUp(e: MouseEvent) {
    if (e.button !== 0) {
      return;
    }
    if (!this.dragging_data.dragging) {
      return;
    }
    const card = this.cards.get('i', this.dragging_data.index);
    if (!card) {
      this.stopDragging();
      return;
    }
    e.stopImmediatePropagation();
    card.el?.classList.remove('hovering');
    this.stopDraggingCard(card);
  }

  private handleTouchEnd(e: TouchEvent) {
    if (!this.dragging_data.dragging) {
      return;
    }
    e.stopImmediatePropagation();
    const card = this.cards.get('i', this.dragging_data.index);
    if (!card) {
      this.stopDragging();
      return;
    }
    if (e.touches.length === 0) {
      this.stopDraggingCard(card);
      return;
    }
    const touch = e.touches[0];
    if (touch.identifier !== this.dragging_data.touch_identifier) {
      return;
    }
    this.stopDraggingCard(card);
  }

  private handleMouseMove(e: MouseEvent) {
    if (!this.dragging_data.dragging) {
      return;
    }
    const card = this.cards.get('i', this.dragging_data.index);
    if (!card) {
      this.stopDragging();
      return;
    }
    e.stopImmediatePropagation();
    this.dragCard(e, card);
  }

  private handleDocumentMouseEnter(e: MouseEvent) {
    if (!this.dragging_data.dragging || e.buttons % 2 === 1) {
      return;
    }
    const card = this.cards.get('i', this.dragging_data.index);
    if (!card) {
      this.stopDragging();
      return;
    }
    this.stopDraggingCard(card, true);
  }

  private handleTouchMove(e: TouchEvent) {
    if (!this.dragging_data.dragging) {
      return;
    }
    e.stopImmediatePropagation();
    const card = this.cards.get('i', this.dragging_data.index);
    if (!card) {
      this.stopDragging();
      return;
    }
    if (e.touches.length === 0) {
      return;
    }
    const touch = e.touches[0];
    if (touch.identifier !== this.dragging_data.touch_identifier) {
      return;
    }
    this.dragCard({ x: touch.clientX, y: touch.clientY }, card);
  }

  setCards(cards: StandardCard[], cards_played: number[] = [], animation_time = 0) {
    this.cards_container.replaceChildren();
    this.cards.clear();
    const card_data: CardData[] = cards
      .map((card, i) => {
        return { i, card, i_dom: -1 } satisfies CardData;
      })
      .sort((a, b) => {
        return sortStandardCards(a.card, b.card);
      });
    let cards_skipped = 0;
    for (const [i_dom, data] of card_data.entries()) {
      if (cards_played.some((i) => i === data.i)) {
        cards_skipped++;
        continue;
      }
      data.i_dom = i_dom - cards_skipped;
      this.createCardEl(data, animation_time);
    }
  }

  private createCardEl(data: CardData, animation_time = 0) {
    const el = document.createElement('div');
    const img = document.createElement('img');
    img.src = cardToImagePath(data.card);
    img.draggable = false;
    img.alt = cardToIcon(data.card);
    el.appendChild(img);
    el.classList.add('card');
    el.style.setProperty('--i', data.i_dom.toString());
    data.el = el;
    setTimeout(
      () => {
        // TODO: add card dealt sound effect
        this.cards.set([data.i, data.i_dom], data);
        this.cards_container.style.setProperty('--num-cards', this.cards.size().toString());
        this.cards_container.appendChild(el);

        el.addEventListener('dblclick', () => {
          if (this.can_play) {
            this.dispatchEvent(new CustomEvent<number>('play_card', { detail: data.i }));
          }
        });

        el.addEventListener('mousedown', (e) => {
          if (e.button !== 0) {
            return;
          }
          e.stopImmediatePropagation();
          this.startDraggingCard({ x: e.x, y: e.y }, data);
        });

        el.addEventListener('mouseenter', (e) => {
          e.stopImmediatePropagation();
          if (this.dragging_data.dragging) {
            return;
          }
          el.classList.add('hovering');
        });

        el.addEventListener('mouseleave', (e) => {
          e.stopImmediatePropagation();
          el.classList.remove('hovering');
        });

        el.addEventListener('touchstart', (e) => {
          e.stopImmediatePropagation();
          if (e.touches.length === 0) {
            return;
          }
          const touch = e.touches[0];
          this.startDraggingCard({ x: touch.clientX, y: touch.clientY }, data, touch.identifier);
        });
      },
      (1 + data.i_dom) * animation_time
    );
  }

  private startDraggingCard(p: Point2D, card: CardData, touch_identifier = 0) {
    this.dragging_lock(async () => {
      if (!card.el) {
        console.error('Cannot start dragging card without dom element');
        return;
      }
      if (this.dragging_data.dragging) {
        const previous_card = this.cards.get('i', this.dragging_data.index);
        if (!!previous_card) {
          this.stopDraggingCard(previous_card);
        }
      }
      this.dragging_data.dragging = true;
      this.dragging_data.index = card.i;
      this.dragging_data.touch_identifier = touch_identifier;
      this.dragging_data.start = p;
      this.dragging_data.start_rect = card.el.getBoundingClientRect();
      card.el.style.setProperty('--x', '0px');
      card.el.style.setProperty('--y', '0px');
      this.play_drop.classList.remove('hovering');
      this.cancel_drop.classList.add('hovering');
      this.dragging_data.hovering_play_drop = false;
      card.el.classList.add('dragging');
      this.classList.add('dragging');
      if (this.can_play) {
        this.classList.add('dragging-playing');
      }
    });
  }

  private dragCard(p: Point2D, card: CardData) {
    this.dragging_lock(async () => {
      if (!this.dragging_data.dragging) {
        return;
      }
      if (!card.el) {
        console.error('Cannot drag card without dom element');
        return;
      }
      const rect = card.el.getBoundingClientRect();
      if (p.x < this.dragging_data.start.x && card.i_dom > 0) {
        const left_card = this.cards.get('i_dom', card.i_dom - 1);
        const left_rect = left_card?.el?.getBoundingClientRect();
        if (!!left_card?.el && !!left_rect?.x && rect.x < left_rect.x) {
          const dif = this.dragging_data.start_rect.x - left_rect.x;
          this.dragging_data.start_rect.x -= dif;
          this.dragging_data.start.x -= dif;
          card.i_dom--;
          left_card.i_dom++;
          card.el.style.setProperty('--i', card.i_dom.toString());
          left_card.el.style.setProperty('--i', left_card.i_dom.toString());
          this.cards.set([card.i, card.i_dom], card);
          this.cards.set([left_card.i, left_card.i_dom], left_card);
        }
      } else if (p.x > this.dragging_data.start.x && card.i_dom < this.cards.size() - 1) {
        const right_card = this.cards.get('i_dom', card.i_dom + 1);
        const right_rect = right_card?.el?.getBoundingClientRect();
        if (!!right_card?.el && !!right_rect?.x && rect.x > right_rect?.x) {
          const dif = right_rect.x - this.dragging_data.start_rect.x;
          this.dragging_data.start_rect.x += dif;
          this.dragging_data.start.x += dif;
          card.i_dom++;
          right_card.i_dom--;
          card.el.style.setProperty('--i', card.i_dom.toString());
          right_card.el.style.setProperty('--i', right_card.i_dom.toString());
          this.cards.set([card.i, card.i_dom], card);
          this.cards.set([right_card.i, right_card.i_dom], right_card);
        }
      }
      card.el.style.setProperty('--x', `${(p.x - this.dragging_data.start.x).toString()}px`);
      card.el.style.setProperty('--y', `${(p.y - this.dragging_data.start.y).toString()}px`);
      if (p.y < this.cancel_drop.getBoundingClientRect()?.top) {
        this.play_drop.classList.add('hovering');
        this.cancel_drop.classList.remove('hovering');
        this.dragging_data.hovering_play_drop = true;
      } else {
        this.play_drop.classList.remove('hovering');
        this.cancel_drop.classList.add('hovering');
        this.dragging_data.hovering_play_drop = false;
      }
    });
  }

  private stopDragging() {
    this.dragging_data.dragging = false;
    this.classList.remove('dragging');
    this.classList.remove('dragging-playing');
  }

  private stopDraggingCard(card: CardData, returning_to_screen = false) {
    this.dragging_lock(async () => {
      if (!card.el) {
        console.error('Cannot stop dragging card without dom element');
        return;
      }
      this.stopDragging();
      card.el.classList.remove('dragging');
      if (!returning_to_screen && this.can_play) {
        if (this.dragging_data.hovering_play_drop) {
          this.dispatchEvent(new CustomEvent<number>('play_card', { detail: card.i }));
        }
      }
    });
  }

  playCard(index: number) {
    const card = this.cards.get('i', index);
    if (!card?.el) {
      console.error('Trying to play card that does not exist or does not have an element');
      return;
    }
    card.el.remove();
    this.cards.delete([index, card.i_dom]);
    this.dragging_lock(async () => {
      this.cards_container.style.setProperty('--num-cards', this.cards.size().toString());
      const shifted = [...this.cards.values()].filter((c) => c.i_dom > card.i_dom);
      for (const other_card of shifted) {
        this.cards.delete([other_card.i, other_card.i_dom]);
      }
      for (const other_card of shifted) {
        other_card.i_dom--;
        this.cards.set([other_card.i, other_card.i_dom], other_card);
        other_card.el?.style.setProperty('--i', other_card.i_dom.toString());
      }
    });
  }

  substituteCard(index: number, new_card: StandardCard) {
    const card = this.cards.get('i', index);
    if (!card) {
      console.error('Trying to substitute card that does not exist');
      return;
    }
    card.el?.remove();
    card.el = undefined;
    card.card = new_card;
    this.createCardEl(card);
  }

  removeCards() {
    this.cards.clear();
    this.cards_container.replaceChildren();
    this.can_play = false;
  }
}

