import { DwgElement } from '../dwg_element';
import { clickButton } from '../../scripts/util';
import type { ChatMessage, DwgChatbox } from '../chatbox/chatbox';
import { SERVER_CHAT_NAME } from '../chatbox/chatbox';
import { getUrlParam, removeUrlParam, setUrlParam } from '../../scripts/url';

import type { DwgLobbyUsers } from './lobby_users/lobby_users';
import type { DwgLobbyRooms } from './lobby_rooms/lobby_rooms';
import type { DwgLobbyRoom } from './lobby_room/lobby_room';
import type { ConnectionMetadata, ServerMessage, LobbyRoom } from './data_models';
import { createMessage } from './data_models';
import { handleMessage } from './message_handler';
import html from './lobby.html';

import './lobby.scss';
import '../chatbox/chatbox';
import './lobby_users/lobby_users';
import './lobby_rooms/lobby_rooms';
import './lobby_room/lobby_room';
import '../dialog_box/message_dialog/message_dialog';
import '../dialog_box/confirm_dialog/confirm_dialog';

const LOBBY_PING_TIME = 3500; // time between lobby refreshes

const URL_PARAM_ROOM = 'room_id';

export class DwgLobby extends DwgElement {
  private name_container!: HTMLSpanElement;
  private ping_container!: HTMLSpanElement;
  private refresh_lobby_button!: HTMLButtonElement;
  private create_room_button!: HTMLButtonElement;
  private lobby_rooms!: DwgLobbyRooms;
  private chatbox!: DwgChatbox;
  private lobby_users!: DwgLobbyUsers;
  private lobby_room_wrapper!: HTMLDivElement;
  private lobby_room!: DwgLobbyRoom;
  private lobby_users_button!: HTMLButtonElement;
  private lobby_users_backdrop!: HTMLDivElement;

  private socket?: WebSocket;
  private connection_metadata: ConnectionMetadata = {
    nickname: 'Anonymous',
    ping: 0,
  };
  private entered_game = false;
  private exited_game = false;
  private ping_interval?: NodeJS.Timeout;

  constructor() {
    super();
    this.html_string = html;
    this.configureElements(
      'name_container',
      'ping_container',
      'refresh_lobby_button',
      'create_room_button',
      'lobby_rooms',
      'chatbox',
      'lobby_users',
      'lobby_room_wrapper',
      'lobby_room',
      'lobby_users_button',
      'lobby_users_backdrop'
    );
  }

  getLobbyRoom(): DwgLobbyRoom {
    return this.lobby_room;
  }

  getLobbyRooms(): DwgLobbyRooms {
    return this.lobby_rooms;
  }

  getLobbyUsers(): DwgLobbyUsers {
    return this.lobby_users;
  }

  protected override parsedCallback(): void {
    this.chatbox.setPlaceholder('Chat with entire lobby');
    clickButton(this.refresh_lobby_button, async () => {
      await this.refreshLobbyRooms(false, true);
    });
    clickButton(
      this.create_room_button,
      async () => {
        this.socket?.send(createMessage(`client-${this.connection_metadata.client_id}`, 'room-create'));
      },
      { loading_text: 'Creating Room ...', re_enable_button: false }
    );
    this.lobby_rooms.addEventListener('join_room', async (e) => {
      this.socket?.send(
        createMessage(
          `client-${this.connection_metadata.client_id}`,
          e.detail.join_as_player ? 'room-join-player' : 'room-join-viewer',
          '',
          e.detail.room_id.toString()
        )
      );
    });
    this.chatbox.addEventListener('chat_sent', (e) => {
      this.sendChatMessage(
        this.chatbox,
        'lobby-chat',
        {
          ...e.detail,
          sender: `client-${this.connection_metadata.client_id}`,
        },
        this.connection_metadata.nickname
      );
    });
    this.lobby_room.addEventListener('chat_sent', (e) => {
      const message = e.detail;
      if (message.message.startsWith('\\l')) {
        message.message = message.message.slice(2).trim();
        this.sendChatMessage(
          this.chatbox,
          'lobby-chat',
          {
            ...e.detail,
            sender: `client-${this.connection_metadata.client_id}`,
          },
          this.connection_metadata.nickname
        );
      } else if (message.message.startsWith('\\u')) {
        message.message = message.message.slice(2).trim(); // TODO: implement
      } else if (message.message.startsWith('\\g')) {
        message.message = message.message.slice(2).trim();
        const room = this.lobby_room.getRoom();
        if (!!room?.game_id) {
          this.socket?.send(
            createMessage(
              message.sender ?? `game-${this.connection_metadata.client_id}`,
              'game-chat',
              message.message,
              message.color
            )
          );
        } else {
          this.lobby_room.getChatbox().addChat(
            {
              message: 'Cannot send message to unlaunched game',
              color: 'gray',
            },
            true
          );
        }
      } else {
        if (message.message.startsWith('\\r')) {
          message.message = message.message.slice(2).trim();
        }
        const server_message = message.sender === SERVER_CHAT_NAME;
        const display_sender = server_message ? message.sender : this.connection_metadata.nickname;
        const sender = `room-${this.connection_metadata.room_id}-${this.connection_metadata.client_id}`;
        message.sender = server_message ? `${sender}-${message.sender}` : sender;
        this.sendChatMessage(this.lobby_room.getChatbox(), 'room-chat', message, display_sender ?? '');
      }
    });
    this.lobby_room.addEventListener('leave_room', async () => {
      this.socket?.send(
        createMessage(
          `client-${this.connection_metadata.client_id}`,
          'room-leave',
          '',
          this.connection_metadata.room_id?.toString()
        )
      );
    });
    this.lobby_room.addEventListener('rename_room', (e) => {
      this.socket?.send(
        createMessage(
          `client-${this.connection_metadata.client_id}`,
          'room-rename',
          e.detail,
          this.connection_metadata.room_id?.toString()
        )
      );
    });
    this.lobby_room.addEventListener('kick_player', (e) => {
      this.socket?.send(
        createMessage(
          `client-${this.connection_metadata.client_id}`,
          'room-kick',
          e.detail.toString(),
          this.connection_metadata.room_id?.toString()
        )
      );
    });
    this.lobby_room.addEventListener('viewer_player', (e) => {
      this.socket?.send(
        createMessage(
          `client-${this.connection_metadata.client_id}`,
          'room-set-viewer',
          e.detail.toString(),
          this.connection_metadata.room_id?.toString()
        )
      );
    });
    this.lobby_room.addEventListener('player_player', (e) => {
      this.socket?.send(
        createMessage(
          `client-${this.connection_metadata.client_id}`,
          'room-set-player',
          e.detail.toString(),
          this.connection_metadata.room_id?.toString()
        )
      );
    });
    this.lobby_room.addEventListener('promote_player', (e) => {
      this.socket?.send(
        createMessage(
          `client-${this.connection_metadata.client_id}`,
          'room-promote',
          e.detail.toString(),
          this.connection_metadata.room_id?.toString()
        )
      );
    });
    this.lobby_room.addEventListener('save_settings', (e) => {
      this.socket?.send(e.detail);
    });
    this.lobby_room.addEventListener('launch_game', () => {
      this.socket?.send(
        createMessage(
          `client-${this.connection_metadata.client_id}`,
          'room-launch',
          '',
          this.connection_metadata.room_id?.toString()
        )
      );
    });
    this.lobby_room.addEventListener('rejoin_game', () => {
      this.dispatchEvent(new CustomEvent('rejoin_game', { detail: this.lobby_room.getRoom() }));
    });
    this.lobby_users_button.addEventListener('click', () => {
      this.lobby_users.classList.toggle('show');
      this.lobby_users_backdrop.classList.toggle('show');
    });
    this.lobby_users_backdrop.addEventListener('click', () => {
      this.lobby_users.classList.remove('show');
      this.lobby_users_backdrop.classList.remove('show');
    });
    this.refreshLobbyRooms();
    this.lobby_users.refreshUsers();
    clearInterval(this.ping_interval);
    this.ping_interval = setInterval(() => {
      this.pingServer();
      this.ping_container.innerText = `ping: ${Math.round(this.connection_metadata.ping)}`;
    }, LOBBY_PING_TIME);
  }

  getChatbox(): DwgChatbox {
    return this.chatbox;
  }

  getCreateRoomButton(): HTMLButtonElement {
    return this.create_room_button;
  }

  getSocket(): WebSocket | undefined {
    return this.socket;
  }

  getConnectionMetadata(): ConnectionMetadata {
    return this.connection_metadata;
  }

  connect(nickname: string, new_socket: WebSocket) {
    this.classList.remove('connector-open');
    this.setNickname(nickname);
    this.setPing(0);
    this.setSocket(new_socket);
    this.classList.remove('hide');
  }

  setSocket(new_socket: WebSocket) {
    if (!!this.socket) {
      this.socket.close(3000, 'opening new connection');
    }
    this.waiting_on_connection_times = DwgLobby.DEFAULT_CONNECTION_TIMES;
    this.socket = new_socket;
    this.socket.addEventListener('message', (m) => {
      try {
        const message = JSON.parse(m.data) as ServerMessage;
        handleMessage(this, message);
      } catch (e) {
        console.error('Error parsing message: ', m, e);
      }
    });
  }

  userLeftRoom(room_id: number, client_id: number, left_text: string) {
    if (room_id === this.connection_metadata.room_id) {
      this.lobby_room.leaveRoom(client_id, left_text);
      if (client_id === this.connection_metadata.client_id) {
        this.leaveRoom();
      }
    }
    this.lobby_users.leaveRoom(client_id);
    this.lobby_rooms.clientLeavesRoom(room_id, client_id);
  }

  socketActive() {
    return !!this.socket && this.socket.readyState === WebSocket.OPEN;
  }

  closeSocket(code: number, message: string) {
    if (!!this.socket) {
      this.socket.close(code, message);
    }
    this.socket = undefined;
  }

  setNickname(nickname: string) {
    this.connection_metadata.nickname = nickname;
    this.name_container.innerText = nickname;
  }

  setPing(ping: number) {
    this.waiting_on_connection_times = DwgLobby.DEFAULT_CONNECTION_TIMES;
    this.connection_metadata.ping = ping;
  }

  async refreshLobbyRooms(check_url = false, show_load_message = false) {
    const current_room = await this.lobby_rooms.refreshRooms(
      this.connection_metadata.client_id ?? -1,
      show_load_message
    );
    if (check_url) {
      const url_room_id = parseInt(getUrlParam(URL_PARAM_ROOM));
      const room = this.lobby_rooms.getRoom(url_room_id)?.data;
      if (!!room && current_room?.room_id !== room.room_id) {
        this.socket?.send(
          createMessage(`client-${this.connection_metadata.client_id}`, 'room-join', '', url_room_id.toString())
        );
        return;
      } else {
        removeUrlParam(URL_PARAM_ROOM);
      }
    }
    if (!!current_room && current_room.room_id !== this.lobby_room.getRoom()?.room_id) {
      this.enterRoom(current_room, current_room.host.client_id === (this.connection_metadata.client_id ?? -1));
    } else if (!current_room) {
      this.leaveRoom();
    } else if (!this.exited_game) {
      this.dispatchEvent(
        new CustomEvent('refresh_game_lobby', {
          detail: current_room,
          bubbles: true,
        })
      );
    }
  }

  enterRoom(room: LobbyRoom, is_host: boolean) {
    if (!this.connection_metadata.client_id) {
      return;
    }
    this.connection_metadata.room_id = room.room_id;
    this.lobby_room.setRoom(room, is_host, this.connection_metadata.client_id);
    this.lobby_room_wrapper.classList.add('show');
    setUrlParam(URL_PARAM_ROOM, room.room_id.toString());
    if (!room.game_id) {
      // reset when entering new room
      this.exited_game = false;
      this.entered_game = false;
    }
  }

  leaveRoom() {
    this.connection_metadata.room_id = undefined;
    this.lobby_room_wrapper.classList.remove('show');
    this.create_room_button.disabled = false;
    this.create_room_button.innerText = 'Create Room';
    if (this.lobby_room.inRoom()) {
      this.lobby_room.clearRoom();
      removeUrlParam(URL_PARAM_ROOM);
    }
  }

  sendChatMessage(chatbox: DwgChatbox, message_kind: string, message: ChatMessage, display_sender: string) {
    let message_sent = false;
    message.message = message.message.trim();
    try {
      if (this.socketActive()) {
        this.socket?.send(createMessage(message.sender ?? '', message_kind, message.message, message.color));
        message_sent = true;
      }
      if (message_sent) {
        chatbox.addChat({ ...message, sender: display_sender }, true);
      } else {
        chatbox.addChat(
          {
            message: `Message unable to be sent: "${message.message}"`,
            color: 'gray',
          },
          true
        );
      }
    } catch (_e) {
      // TODO: implement
      chatbox.addChat(
        {
          message: 'Error trying to send message',
          color: 'gray',
        },
        true
      );
    }
  }

  canAutoLaunchRoom(): boolean {
    return !this.exited_game && !this.entered_game;
  }

  enterGame() {
    this.classList.add('hide');
    this.entered_game = true;
  }

  exitGame() {
    this.classList.remove('hide');
    this.exited_game = true;
  }

  private static DEFAULT_CONNECTION_TIMES = 3;
  private waiting_on_connection_times = 0;

  pingServer() {
    if (this.classList.contains('connector-open') || this.classList.contains('hide')) {
      return;
    }
    if (!this.socketActive()) {
      this.dispatchEvent(new Event('connection_lost'));
      return;
    }
    if (!this.classList.contains('connected')) {
      this.dispatchEvent(new Event('connection_lost'));
      return;
    }
    this.waiting_on_connection_times--;
    if (this.waiting_on_connection_times < 1) {
      this.dispatchEvent(new Event('connection_lost'));
      return;
    }
    this.lobby_users.refreshUsers();
    this.refreshLobbyRooms();
    if (this.lobby_room_wrapper.classList.contains('show')) {
      this.socket?.send(
        createMessage(
          `client-${this.connection_metadata.client_id}`,
          'room-refresh',
          '',
          (this.lobby_room.getRoom()?.room_id ?? 0).toString()
        )
      );
    }
  }
}

