import { DwgElement } from '../../dwg_element';
import { clickButton } from '../../../scripts/util';
import { SERVER_CHAT_NAME } from '../../chatbox/chatbox';
import type { ConnectionMetadata } from '../data_models';
import { apiGet } from '../../../scripts/api';
import { getUrlParam } from '../../../scripts/url';
import { getSettings } from '../../../scripts/settings_store';

import html from './lobby_connector.html';
import './lobby_connector.scss';

/** Connection Data */
export declare interface ConnectData {
  nickname: string;
  try_reconnect: boolean;
  client_id?: number; // defined if try_reconnect is true
}

/** A 'nickname' that causes a default to previous nickname from server */
export const PREVIOUS_NICKNAME = '!!previous!!';

export class DwgLobbyConnector extends DwgElement {
  private reconnect_wrapper!: HTMLDivElement;
  private previous_nickname!: HTMLDivElement;
  private reconnect_button!: HTMLButtonElement;
  private new_connection_button!: HTMLButtonElement;
  private connect_wrapper!: HTMLDivElement;
  private nickname!: HTMLInputElement;
  private connect_button!: HTMLButtonElement;
  private status_message!: HTMLDivElement;

  private reconnect_data: ConnectData = {
    nickname: '',
    try_reconnect: true,
    client_id: 0,
  };

  constructor() {
    super();
    this.html_string = html;
    this.configureElements(
      'reconnect_wrapper',
      'previous_nickname',
      'reconnect_button',
      'new_connection_button',
      'connect_wrapper',
      'nickname',
      'connect_button',
      'status_message'
    );
  }

  protected override async parsedCallback(): Promise<void> {
    this.connect_button.disabled = true;
    this.nickname.value = getSettings().last_nickname;
    let try_reconnect = false;
    // check url param
    const url_client_id = parseInt(getUrlParam('client_id'));
    if (!!url_client_id && url_client_id > 0) {
      this.previous_nickname.innerHTML = `<em>Client ${url_client_id}</em>`;
      this.reconnect_data = {
        nickname: PREVIOUS_NICKNAME,
        try_reconnect: true,
        client_id: url_client_id,
      };
      try_reconnect = true;
    } else {
      const { client_id, client_id_time, last_nickname: previous_nickname } = getSettings();
      if (!!previous_nickname) {
        const previous_name_valid = this.validateName(previous_nickname);
        if (
          previous_name_valid &&
          !!client_id &&
          !!client_id_time &&
          Date.now() - client_id_time < 1000 * 60 * 60 * 24
        ) {
          this.previous_nickname.innerText = previous_nickname;
          this.reconnect_data = {
            nickname: PREVIOUS_NICKNAME,
            try_reconnect: true,
            client_id,
          };
          try_reconnect = true;
        }
      }
    }
    if (try_reconnect) {
      this.reconnect_wrapper.classList.add('show');
    } else {
      this.connect_wrapper.classList.add('show');
    }
    const pong = await apiGet<string>('ping');
    if (!pong.success) {
      this.status_message.innerHTML = 'Cannot connect to server at this time; you can try refreshing the page';
      return;
    }
    this.nickname.addEventListener('keyup', (e) => {
      const valid_name = this.validateInputName();
      if (valid_name && e.key === 'Enter') {
        this.connect({ nickname: this.nickname.value, try_reconnect: false });
      }
    });
    clickButton(
      this.connect_button,
      () => {
        if (!this.validateInputName()) {
          return;
        }
        this.connect({ nickname: this.nickname.value, try_reconnect: false });
        return 'Connecting ...';
      },
      { re_enable_button: false }
    );
    clickButton(
      this.reconnect_button,
      () => {
        this.connect(this.reconnect_data);
        return 'Reconnecting ...';
      },
      { re_enable_button: false }
    );
    clickButton(this.new_connection_button, () => {
      this.reconnect_wrapper.classList.remove('show');
      this.connect_wrapper.classList.add('show');
    });
  }

  tryReconnecting(message: string, connection_metadata: ConnectionMetadata) {
    this.status_message.innerText = message;
    this.reconnect_button.disabled = false;
    this.reconnect_button.innerText = 'Reconnect to Lobby';
    this.connect_button.disabled = false;
    this.connect_button.innerText = 'Reconnect to Lobby';
    this.reconnect_data.nickname = connection_metadata.nickname;
    this.reconnect_data.client_id = connection_metadata.client_id;
    if (this.validateName(this.reconnect_data.nickname) && !!this.reconnect_data.client_id) {
      this.reconnect_wrapper.classList.add('show');
      this.connect_wrapper.classList.remove('show');
    } else {
      this.reconnect_wrapper.classList.remove('show');
      this.connect_wrapper.classList.add('show');
    }
    this.classList.remove('hide');
  }

  connect(connect_data: ConnectData) {
    this.dispatchEvent(new CustomEvent<ConnectData>('connect', { detail: connect_data }));
  }

  invalid_names = [SERVER_CHAT_NAME];

  private validateInputName(): boolean {
    const valid = this.validateName(this.nickname.value);
    this.connect_button.disabled = !valid;
    return valid;
  }

  private validateName(name: string): boolean {
    if (this.invalid_names.includes(name)) {
      return false;
    }
    return name.length > 1 && name.length < 17;
  }
}

customElements.define('dwg-lobby-connector', DwgLobbyConnector);

import { DwgElement } from '../../../dwg_element';
import { GameType } from '../../data_models';
import type { AiPlayerFiddlesticks, AiPlayerRisq } from '../game_specific_data';
import { generateName } from './name_generator';

import html from './ai_selector.html';
import './ai_selector.scss';

/** Possible ai player types */
export type AiPlayerType = AiPlayerFiddlesticks | AiPlayerRisq;

/** Data needed to configure an ai selector */
export declare interface AiSelectorData {
  game_type: GameType;
  ai_players: AiPlayerType[]; // type depends on game type
}

export class DwgAiSelector extends DwgElement {
  private player_wrapper!: HTMLDivElement;
  private add_player_button!: HTMLButtonElement;

  private data!: AiSelectorData;
  private els: HTMLElement[] = [];

  constructor() {
    super();
    this.html_string = html;
    this.configureElements('player_wrapper', 'add_player_button');
  }

  protected override parsedCallback(): void {
    if (!this.data) {
      throw new Error('Must set ai selector data before adding to dom');
    }
    this.setPlayers(this.data.ai_players);
    this.add_player_button.addEventListener('click', () => {
      switch (this.data.game_type) {
        case GameType.FIDDLESTICKS:
        case GameType.RISQ:
          const el = document.createElement('div');
          const nickname = generateName();
          el.innerText = nickname;

          let p: AiPlayerType;
          if (this.data.game_type === GameType.RISQ) {
            p = {
              nickname,
              config: 'default',
            } satisfies AiPlayerRisq;
          } else {
            p = {
              nickname,
            } satisfies AiPlayerFiddlesticks;
          }

          this.data.ai_players.push(p);
          this.player_wrapper.appendChild(this.addPlayer(el, p));
          break;
        default:
          throw new Error('Unknown game type in ai selector');
      }
    });
  }

  setData(data: AiSelectorData) {
    if (this.fully_parsed) {
      throw new Error('Cannot set data when already added to dom');
    }
    this.data = data;
    this.els = [];
  }

  setPlayers(ai_players: AiPlayerType[]) {
    this.data.ai_players = ai_players;
    this.els = [];
    switch (this.data.game_type) {
      case GameType.FIDDLESTICKS:
      case GameType.RISQ:
        const players: AiPlayerType[] = ai_players;
        const player_els = players.map((p) => {
          const el = document.createElement('div');
          el.innerText = p.nickname;
          return this.addPlayer(el, p);
        });
        this.player_wrapper.replaceChildren(...player_els);
        break;
      default:
        throw new Error('Unknown game type in ai selector');
    }
  }

  private addPlayer(el: HTMLElement, p: AiPlayerType): HTMLDivElement {
    const wrapper = document.createElement('div');
    wrapper.classList.add('player');
    wrapper.classList.add('set-h');
    const remove_button = document.createElement('button');
    remove_button.classList.add('remove-button');
    remove_button.classList.add('set-size');
    const remove_icon = document.createElement('img');
    remove_icon.classList.add('max-size');
    remove_icon.src = '/images/icons/close64.png';
    remove_icon.draggable = false;
    remove_button.appendChild(remove_icon);
    el.id = `player-${this.els.length}`;
    this.els.push(el);
    remove_button.addEventListener('click', () => {
      wrapper.remove();
      const index = parseInt(el.id.replace('player-', ''));
      console.log(this.data.ai_players, index);
      this.data.ai_players.splice(index, 1);
      console.log(this.data.ai_players);
      this.els.splice(index, 1);
      for (const [id, el] of this.els.entries()) {
        if (id < index) {
          continue;
        }
        el.id = `player-${id}`;
      }
      console.log(this.getPlayers().length);
    });
    wrapper.appendChild(el);

    if (this.data.game_type === GameType.RISQ) {
      const risq_player = p as AiPlayerRisq;
      const select = document.createElement('select');
      select.classList.add('ai-model-select');
      const models = ['default', 'only_blunt', 'only_pierce'];
      for (const m of models) {
        const option = document.createElement('option');
        option.value = m;
        option.innerText = m;
        if ((risq_player.config || 'default') === m) {
          option.selected = true;
        }
        select.appendChild(option);
      }
      select.addEventListener('change', () => {
        risq_player.config = select.value;
      });
      wrapper.appendChild(select);
    }

    wrapper.appendChild(remove_button);
    return wrapper;
  }

  getPlayers(): AiPlayerType[] {
    switch (this.data.game_type) {
      case GameType.FIDDLESTICKS:
      case GameType.RISQ:
        return this.data.ai_players;
      default:
        throw new Error('Unknown game type in ai selector');
    }
  }
}

