import { DEV } from './util';

interface ApiSuccessResponse<T> {
  success: true;
  result: T;
  error_message?: never;
}

interface ApiErrorResponse {
  success: false;
  result?: never;
  error_message: string;
}

/** Data structure for all returns to get requests */
export type ApiResponse<T> = ApiSuccessResponse<T> | ApiErrorResponse;

/** Returns websocket path */
export function websocketPath() {
  const scheme = window.location.protocol === 'https:' ? 'wss://' : 'ws://';
  return DEV
    ? `ws://${location.hostname}:6807/api/lobby`
    : `${scheme}${location.hostname}${location.port ? ':' + location.port : ''}/api/lobby`;
}

/** Converts string api to actual api url */
function apiToUrl(api: string) {
  return `/api/${api}/`;
}

/** Calls and returns the input get api */
export async function apiGet<T>(api: string, signal?: AbortSignal): Promise<ApiResponse<T>> {
  try {
    const response = await fetch(apiToUrl(api), {
      method: 'GET',
      signal,
      headers: {
        'Content-Type': 'application/json',
      },
    });
    return (await response.json()) as ApiResponse<T>;
  } catch (error) {
    if (!signal?.aborted) {
      console.log(error);
    }
  }
  return {
    success: false,
    error_message: 'Server error; please report this bug.',
  };
}

/** Calls and returns the input post api */
export async function apiPost<T>(api: string, data: unknown): Promise<ApiResponse<T>> {
  const is_file = data instanceof File;
  const content_type = is_file ? data.type : 'application/json';
  const filename = is_file ? data.name : undefined;
  const body = is_file ? data : JSON.stringify(data);
  try {
    const custom_headers = new Headers();
    custom_headers.append('Content-Type', content_type);
    custom_headers.append('X-File-Name', filename ?? '');
    const response = await fetch(apiToUrl(api), {
      method: 'POST',
      headers: custom_headers,
      body,
    });
    return (await response.json()) as ApiResponse<T>;
  } catch (error) {
    console.log(error);
  }
  return {
    success: false,
    error_message: 'Server error; please report this bug.',
  };
}

import { clampNumber } from './math';

declare interface ColorRGBData {
  r: number;
  g: number;
  b: number;
  a: number;
}

/** Class describing an RGB color */
export class ColorRGB {
  private data: ColorRGBData = { r: 0, g: 0, b: 0, a: 0 };

  constructor(r: number, g: number, b: number, a?: number) {
    this.setColor(r, g, b, a);
  }

  copy(): ColorRGB {
    return new ColorRGB(this.data.r, this.data.g, this.data.b, this.data.a);
  }

  setColor(r: number, g: number, b: number, a?: number) {
    this.data = this.cleanInput(r, g, b, a);
  }

  getString(): string {
    return `rgb(${this.data.r}, ${this.data.g}, ${this.data.b}, ${this.data.a})`;
  }

  getR(): number {
    return this.data.r;
  }

  getG(): number {
    return this.data.g;
  }

  getB(): number {
    return this.data.b;
  }

  getAlpha(): number {
    return this.data.a;
  }

  addColor(r: number, g: number, b: number, a?: number): ColorRGB {
    const input = this.cleanInput(r, g, b, a);
    const new_a = this.data.a + input.a;
    if (new_a === 0) {
      this.data.a = 0;
      return this;
    }
    const new_r = (this.data.a * this.data.r + input.a * input.r) / new_a;
    const new_g = (this.data.a * this.data.g + input.a * input.g) / new_a;
    const new_b = (this.data.a * this.data.b + input.a * input.b) / new_a;
    this.data = this.cleanInput(new_r, new_g, new_b, new_a);
    return this;
  }

  dAlpha(da: number): ColorRGB {
    this.data.a += da;
    this.cleanData();
    return this;
  }

  // The input db should be in [-1,1] and should represent the % brightness change
  dBrightness(db: number): ColorRGB {
    const change = db * 255;
    this.data.r += change;
    this.data.g += change;
    this.data.b += change;
    this.cleanData();
    return this;
  }

  // Returns brightness as a percent value from [0,1]
  getBrightness(): number {
    return (this.data.r + this.data.g + this.data.b) / (3 * 255);
  }

  private cleanInput(r: number, g: number, b: number, a?: number): ColorRGBData {
    r = clampNumber(r, 0, 255);
    g = clampNumber(g, 0, 255);
    b = clampNumber(b, 0, 255);
    a = clampNumber(a ?? 1, 0, 1, false);
    return { r, g, b, a };
  }

  private cleanData() {
    this.data = this.cleanInput(this.data.r, this.data.g, this.data.b, this.data.a);
  }
}

/** Class giving functionality of a map but with multiple keys */
export class MultiMap<K, V> {
  private keynames: string[] = [];
  private maps = new Map<string, Map<K, V>>();
  private _size = 0;

  constructor(keynames: string[]) {
    this.keynames = keynames;
    for (const keyname of keynames) {
      this.maps.set(keyname, new Map<K, V>());
    }
  }

  public get(keyname: string, key: K): V | undefined {
    return this.maps.get(keyname)?.get(key);
  }

  /** Returns whether the value was successfully set on the multikey map */
  public set(keys: K[], value: V): boolean {
    if (keys.length !== this.keynames.length || keys.length === 0) {
      return false;
    }
    for (const [i, keyname] of this.keynames.entries()) {
      this.maps.get(keyname)?.set(keys[i], value); // TODO: what if doesn't exist
    }
    this._size = this.maps.get(this.keynames[0])!.size; // TODO: what if doesn't exist
    return true;
  }

  /** Returns whether the object was successfully deleted */
  public delete(keys: K[]): boolean {
    if (keys.length !== this.keynames.length || keys.length === 0) {
      return false;
    }
    let deleted = true;
    for (const [i, keyname] of this.keynames.entries()) {
      if (!this.maps.get(keyname)?.delete(keys[i])) {
        // TODO: what if doesn't exist
        deleted = false;
      }
    }
    this._size = this.maps.get(this.keynames[0])!.size; // TODO: what if doesn't exist
    return deleted;
  }

  public clear() {
    for (const [_, keyname] of this.keynames.entries()) {
      this.maps.get(keyname)?.clear(); // TODO: what if doesn't exist
    }
    this._size = 0;
  }

  public size(): number {
    return this._size;
  }

  public keys(keyname: string): IterableIterator<K> {
    if (!this.maps.has(keyname)) {
      return [].values();
    }
    return this.maps.get(keyname)!.keys(); // TODO: what if doesn't exist
  }

  public values(): IterableIterator<V> {
    if (this._size === 0) {
      return [].values();
    }
    return this.maps.get(this.keynames[0])!.values(); // TODO: what if doesn't exist
  }
}

