/** Loop helper function */
export function loop(times: number, callback: (i?: number) => void): void {
  for (let i = 0; i < times; i++) {
    callback(i);
  }
}

/** Async loop helper function */
export async function asyncLoop(times: number, callback: Function): Promise<void> {
  return new Promise<void>(async (resolve) => {
    for (let i = 0; i < times; i++) {
      await callback(i);
    }
    resolve();
  });
}

/** Resolves when the condition becomes true or the signal is aborted */
export function until(condition: () => boolean, poll_timer = 50, signal?: AbortSignal): Promise<void> {
  const poll = (resolve: () => void): void => {
    if (signal?.aborted || condition()) {
      resolve();
    } else {
      setTimeout(() => poll(resolve), poll_timer);
    }
  };
  return new Promise<void>(poll);
}

/** Awaits a specific amount of time */
export async function untilTimer(timer: number): Promise<void> {
  await new Promise((resolve) => setTimeout(resolve, timer));
}

/** Capitalizes each word in string */
export function capitalize(str: string, word_split = ' '): string {
  const str_split = str.trim().split(word_split);
  return str_split
    .map((str) => {
      const lower = str.toLowerCase();
      return str.charAt(0).toUpperCase() + lower.slice(1);
    })
    .join(word_split);
}

