/** Whether the currently focused element is a text input, so global hotkeys should be suppressed */
export function isTypingInInput(): boolean {
  const el = document.activeElement;
  return el instanceof HTMLInputElement || el instanceof HTMLTextAreaElement;
}

export function isDialogOpen(): boolean {
  return !!document.querySelector('.dwg-dialog-box');
}

/** Copies input text to clipboard */
export async function copyToClipboard(text: string): Promise<boolean> {
  if (!navigator.clipboard) {
    return false;
  }
  try {
    await navigator.clipboard.writeText(text);
    return true;
  } catch (_e) {
    return false;
  }
}

export class Sounds {
  private static instance: Sounds = new Sounds();

  private sounds: Map<string, HTMLAudioElement> = new Map<string, HTMLAudioElement>();

  private constructor() {}

  public static async play(s: string) {
    try {
      let sound = Sounds.instance.sounds.get(s);
      if (!sound) {
        sound = new Audio(`sounds/${s}.mp3`);
        Sounds.instance.sounds.set(s, sound);
      }
      await sound.play();
    } catch (e) {
      console.error(e);
    }
  }
}
